import re
import time
from collections import Counter

CONF = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
        '6': '50', '7': '12', '8': '30', '9': '43'}
L2D = {'O': '0', 'o': '0', 'Q': '0', 'D': '0', 'l': '1', 'I': '1', 'i': '1',
       'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6'}
D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
DIGITS = '0123456789'
SPLIT_RE = re.compile(r"\s*\|\s*|;|\t| {3,}")
DIGITISH = "0-9OoQDlIiSsBZzG"
CODE_RE = re.compile(r"[A-Z0-9]{2}[" + DIGITISH + r"]{3,7}")
NUM_RE = re.compile(r"[" + DIGITISH + r".,']{1,16}")
QTY_RE = re.compile(r"[" + DIGITISH + r"]{1,4}")
MONEY_RE = re.compile(r"[" + DIGITISH + r".,']{2,16}")


def sub_inv():
    inv = {}
    for t, obs in CONF.items():
        for o in obs:
            inv.setdefault(o, []).append(t)
    return inv


SUB_INV = sub_inv()


def strip_pcs(f):
    f = f.strip()
    m = re.match(r"^(.*?)\s*pcs\.?$", f)
    if m:
        return m.group(1)
    return f


def norm_num(s):
    return ''.join(L2D.get(c, c) for c in strip_pcs(s).replace(' ', ''))


def fmt_money(c, mark, grouped):
    ip = str(c // 100)
    if grouped:
        g = []
        while len(ip) > 3:
            g.insert(0, ip[-3:])
            ip = ip[:-3]
        g.insert(0, ip)
        ip = "'".join(g)
    return ip + mark + '%02d' % (c % 100)


def parse_money(s, mark, grouped):
    if s.count(mark) != 1:
        return None
    ip, dp = s.split(mark)
    if not re.fullmatch(r"[0-9]{2}", dp):
        return None
    if grouped:
        if not re.fullmatch(r"[0-9]{1,3}('[0-9]{3})*", ip):
            return None
    else:
        if not re.fullmatch(r"[0-9]+", ip):
            return None
    d = ip.replace("'", "")
    if len(d) > 1 and d[0] == '0':
        return None
    return int(d) * 100 + int(dp)


def parse_qty(s):
    if re.fullmatch(r"[1-9][0-9]{0,2}", s):
        v = int(s)
        if v <= 500:
            return v
    return None


def edits1(s, mark=None):
    out = []
    n = len(s)
    for i, ch in enumerate(s):
        for t in SUB_INV.get(ch, ()):
            out.append(s[:i] + t + s[i + 1:])
        if ch in DIGITS and i > 0 and s[i - 1] == ch:
            out.append(s[:i] + s[i + 1:])
    for i in range(n + 1):
        a, b = s[:i], s[i:]
        for d in DIGITS:
            out.append(a + d + b)
    if mark is not None and mark not in s and n >= 3:
        out.append(s[:-2] + mark + s[-2:])
    return out


def money_cands(s, mark, grouped):
    res = {}
    v = parse_money(s, mark, grouped)
    if v is not None:
        res[v] = 0
    for e in edits1(s, mark):
        v = parse_money(e, mark, grouped)
        if v is not None and v not in res:
            res[v] = 1
    if mark not in s and len(s) >= 2:
        base = [s[:-2] + mark + s[-2:]] if len(s) >= 3 else []
        for i in range(max(0, len(s) - 3), len(s) + 1):
            for d in DIGITS:
                t = s[:i] + d + s[i:]
                base.append(t[:-2] + mark + t[-2:])
        for bs in base:
            for e in edits1(bs):
                v = parse_money(e, mark, grouped)
                if v is not None and v not in res:
                    res[v] = 2
            v = parse_money(bs, mark, grouped)
            if v is not None and v not in res:
                res[v] = 2
    return res


def qty_cands(s):
    res = {}
    v = parse_qty(s)
    if v is not None:
        res[v] = 0
    for e in edits1(s):
        v = parse_qty(e)
        if v is not None and v not in res:
            res[v] = 1
    return res


def wdist(t, o):
    n, m = len(t), len(o)
    prev = [0.0] * (m + 1)
    for j in range(1, m + 1):
        c = 1.0 if (o[j - 1] in DIGITS and j > 1 and o[j - 2] == o[j - 1]) else 3.0
        prev[j] = prev[j - 1] + c
    for i in range(1, n + 1):
        tc = t[i - 1]
        dc = 2.5 if tc == "'" else 1.0
        cur = [prev[0] + dc] + [0.0] * m
        for j in range(1, m + 1):
            oc = o[j - 1]
            if tc == oc:
                best = prev[j - 1]
            elif tc in DIGITS and oc in CONF[tc]:
                best = prev[j - 1] + 1.0
            else:
                best = prev[j - 1] + 3.0
            x = prev[j] + dc
            if x < best:
                best = x
            ic = 1.0 if (oc in DIGITS and j > 1 and o[j - 2] == oc) else 3.0
            x = cur[j - 1] + ic
            if x < best:
                best = x
            cur[j] = best
        prev = cur
    return prev[m]


def code_ok(L, D):
    if not re.fullmatch(r"[0-9]{5}", D):
        return False
    d = [int(c) for c in D]
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + ord(L[0]) - 64 + ord(L[1]) - 64) % 10 == d[4]


def code_solve(s, seen):
    s = s.strip().replace(' ', '')
    if len(s) < 2:
        return 'AA00000'
    L = ''.join(D2L.get(c, c) for c in s[:2]).upper()
    D = ''.join(L2D.get(c, c) for c in s[2:])
    if not re.fullmatch(r"[A-Z]{2}", L):
        L = ''.join(c if 'A' <= c <= 'Z' else 'A' for c in L)
    if code_ok(L, D):
        return L + D
    c1 = []
    for e in edits1(D):
        if code_ok(L, e) and e not in c1:
            c1.append(e)
    if not c1:
        for e in edits1(D):
            if not (4 <= len(e) <= 6):
                continue
            for e2 in edits1(e):
                if code_ok(L, e2) and e2 not in c1:
                    c1.append(e2)
    if not c1:
        dd = D[:4] if len(D) >= 4 else (D + '0000')[:4]
        dd = ''.join(c if c in DIGITS else '0' for c in dd)
        d = [int(c) for c in dd]
        ck = (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + ord(L[0]) - 64 + ord(L[1]) - 64) % 10
        return L + dd + str(ck)
    for e in c1:
        if seen.get(L + e, 0) > 0:
            return L + e
    c1.sort(key=lambda e: wdist(e, D))
    return L + c1[0]


def solve_row(qs, us, as_, mark, grouped):
    Q = qty_cands(qs)
    U = money_cands(us, mark, grouped)
    A = money_cands(as_, mark, grouped)
    cands = {}

    def add(q, u, c):
        k = (q, u)
        if k not in cands or c < cands[k]:
            cands[k] = c

    for q, cq in Q.items():
        for u, cu in U.items():
            ca = A.get(q * u)
            if ca is not None:
                add(q, u, cq + cu + ca)
    for q, cq in Q.items():
        for a, ca in A.items():
            if cq + ca > 1 or a % q:
                continue
            u = a // q
            if u <= 0 or (q, u) in cands:
                continue
            add(q, u, cq + ca + min(6.0, wdist(fmt_money(u, mark, grouped), us)))
    for u, cu in U.items():
        if u <= 0:
            continue
        for a, ca in A.items():
            if cu + ca > 1 or a % u:
                continue
            q = a // u
            if q < 1 or q > 500 or (q, u) in cands:
                continue
            add(q, u, cu + ca + min(6.0, wdist(str(q), qs)))
    q0 = [q for q, c in Q.items() if c == 0]
    u0 = [u for u, c in U.items() if c == 0]
    for q in q0:
        for u in u0:
            if (q, u) not in cands:
                add(q, u, min(6.0, wdist(fmt_money(q * u, mark, grouped), as_)))
    best = min(cands.values()) if cands else 99
    if best >= 2:
        qq = q0 if q0 else [q for q in Q if Q[q] <= 1][:40]
        uu = u0 if u0 else [u for u in U if U[u] <= 1][:120]
        if len(qq) * len(uu) <= 400:
            for q in qq:
                for u in uu:
                    if (q, u) not in cands:
                        add(q, u, Q[q] + U[u] + min(6.0, wdist(fmt_money(q * u, mark, grouped), as_)))
    if not cands:
        qv = q0[0] if q0 else (min(Q, key=lambda x: Q[x]) if Q else None)
        uv = u0[0] if u0 else (min(U, key=lambda x: U[x]) if U else None)
        av = min(A, key=lambda x: A[x]) if A else None
        if qv is None:
            qv = 1
            digs = re.sub(r"[^0-9]", "", qs)
            if digs:
                qv = max(1, min(500, int(digs[:3])))
        if uv is None:
            if av is not None and qv:
                uv = max(1, av // qv)
            else:
                digs = re.sub(r"[^0-9]", "", us)
                uv = int(digs[:9]) if digs else 0
        add(qv, uv, 12.0)
    lst = sorted(((c, q, u) for (q, u), c in cands.items()), key=lambda x: (x[0], x[1], x[2]))
    return [[c, q, u, q * u] for c, q, u in lst[:8]]


def choose_section(rowcands, sub_cost):
    n = len(rowcands)
    base_cost = sum(rc[0][0] for rc in rowcands)
    base_sum = sum(rc[0][3] for rc in rowcands)
    best_cost = base_cost + sub_cost(base_sum, True)
    best_choice = [0] * n
    alts = []
    for i, rc in enumerate(rowcands):
        for j in range(1, len(rc)):
            alts.append((i, j, rc[j][0] - rc[0][0], rc[j][3] - rc[0][3]))
    for (i, j, dc, ds) in alts:
        if base_cost + dc >= best_cost:
            continue
        c = base_cost + dc + sub_cost(base_sum + ds, True)
        if c < best_cost - 1e-9:
            best_cost = c
            best_choice = [0] * n
            best_choice[i] = j
    if len(alts) <= 700:
        for x in range(len(alts)):
            i1, j1, dc1, ds1 = alts[x]
            if base_cost + dc1 >= best_cost:
                continue
            for y in range(x + 1, len(alts)):
                i2, j2, dc2, ds2 = alts[y]
                if i2 == i1:
                    continue
                c0 = base_cost + dc1 + dc2
                if c0 >= best_cost:
                    continue
                sc = sub_cost(base_sum + ds1 + ds2, False)
                if sc is None:
                    continue
                if c0 + sc < best_cost - 1e-9:
                    best_cost = c0 + sc
                    best_choice = [0] * n
                    best_choice[i1] = j1
                    best_choice[i2] = j2
    return best_cost, best_choice


def make_sub_cost(cands, obs, mark, grouped):
    def f(total, allow_dist):
        if obs is None:
            return 0.0 if allow_dist else None
        c = cands.get(total)
        if c is not None:
            return float(c)
        if not allow_dist:
            return None
        return min(6.0, wdist(fmt_money(total, mark, grouped), obs))
    return f


def field_type_cost(f, col):
    if col == 'CODE':
        return 0 if CODE_RE.fullmatch(f.replace(' ', '')) else 2
    if col == 'QTY':
        return 0 if QTY_RE.fullmatch(strip_pcs(f)) else 2
    g = f.replace(' ', '')
    if MONEY_RE.fullmatch(g) and (('.' in g or ',' in g) or len(g) >= 3):
        return 0
    return 2


def group_fields(fields, cols):
    n = len(fields)
    if n % 4 == 0:
        return [fields[i:i + 4] for i in range(0, n, 4)]
    INF = 1e9
    dp = [[INF] * 4 for _ in range(n + 1)]
    bp = [[None] * 4 for _ in range(n + 1)]
    dp[0][0] = 0
    for i in range(n):
        for k in range(4):
            if dp[i][k] >= INF:
                continue
            c = dp[i][k] + 1.5
            if c < dp[i + 1][k]:
                dp[i + 1][k] = c
                bp[i + 1][k] = (k, 'skip')
            c = dp[i][k] + field_type_cost(fields[i], cols[k])
            if c < dp[i + 1][(k + 1) % 4]:
                dp[i + 1][(k + 1) % 4] = c
                bp[i + 1][(k + 1) % 4] = (k, 'take')
    endk = min(range(4), key=lambda k: dp[n][k] + (0 if k == 0 else 3 * (4 - k)))
    seq = []
    i, k = n, endk
    while i > 0:
        pk, act = bp[i][k]
        if act == 'take':
            seq.append((i - 1, pk))
        i -= 1
        k = pk
    seq.reverse()
    rows = []
    cur = None
    for idx, col in seq:
        if col == 0 or cur is None:
            cur = ['', '', '', '']
            rows.append(cur)
        cur[col] = fields[idx]
    return rows


def parse_doc(text):
    cols = None
    sections = []
    cur = None
    total_s = None
    items_s = None
    for raw in text.split('\n'):
        line = raw.strip()
        if not line or line.startswith('MANIFEST'):
            continue
        if line.startswith('COLUMNS'):
            names = re.findall(r"CODE|QTY|UNIT|AMOUNT", line)
            if len(names) == 4 and len(set(names)) == 4:
                cols = names
            continue
        m = re.match(r"^=+\s*SECTION\b(.*?)=*$", line)
        if m:
            cur = {'name': m.group(1).strip(), 'fields': [], 'sub': None}
            sections.append(cur)
            continue
        m = re.match(r"^SUBTOTAL\s*(\S+)", line)
        if m:
            if cur is None:
                cur = {'name': '', 'fields': [], 'sub': None}
                sections.append(cur)
            cur['sub'] = m.group(1)
            cur = None
            continue
        m = re.match(r"^TOTAL\s*(\S+)(?:\s+ITEMS\s*(\S+))?", line)
        if m:
            total_s = m.group(1)
            items_s = m.group(2)
            cur = None
            continue
        parts = [p.strip() for p in SPLIT_RE.split(line)]
        parts = [p for p in parts if p]
        if not parts:
            continue
        ok = True
        for p in parts:
            g = strip_pcs(p).replace(' ', '') if 'pcs' in p else p
            if ' ' in g or not (CODE_RE.fullmatch(g) or NUM_RE.fullmatch(g)):
                ok = False
                break
        if not ok:
            continue
        if cur is None:
            if sections and sections[-1]['sub'] is None:
                cur = sections[-1]
            else:
                cur = {'name': '', 'fields': [], 'sub': None}
                sections.append(cur)
        cur['fields'].extend(parts)
    if cols is None:
        cols = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    return cols, sections, total_s, items_s


def solve(state, params):
    t0 = time.process_time()
    text = (state.get('input') or {}).get('text', '') or ''
    cols, sections, total_s, items_s = parse_doc(text)
    money_str = []
    for sec in sections:
        rows = group_fields(sec['fields'], cols)
        sec['rows'] = rows
        for r in rows:
            money_str.append(r[cols.index('UNIT')])
            money_str.append(r[cols.index('AMOUNT')])
        if sec['sub']:
            money_str.append(sec['sub'])
    if total_s:
        money_str.append(total_s)
    joined = ''.join(money_str)
    mark = '.' if joined.count('.') >= joined.count(',') else ','
    grouped = "'" in joined
    ci, qi, ui, ai = (cols.index('CODE'), cols.index('QTY'),
                      cols.index('UNIT'), cols.index('AMOUNT'))
    seen = Counter()
    for sec in sections:
        for r in sec['rows']:
            s = r[ci].strip()
            if re.fullmatch(r"[A-Z]{2}[0-9]{5}", s) and code_ok(s[:2], s[2:]):
                seen[s] += 1
    sec_results = []
    for sec in sections:
        rowcands = []
        codes = []
        for r in sec['rows']:
            codes.append(code_solve(r[ci], seen) if r[ci] else 'AA00000')
            rowcands.append(solve_row(norm_num(r[qi]), norm_num(r[ui]), norm_num(r[ai]),
                                      mark, grouped))
        sub_obs = norm_num(sec['sub']) if sec['sub'] else None
        S = money_cands(sub_obs, mark, grouped) if sub_obs else {}
        if rowcands:
            cost, choice = choose_section(rowcands, make_sub_cost(S, sub_obs, mark, grouped))
        else:
            cost, choice = 0.0, []
        sec_results.append({'codes': codes, 'rc': rowcands, 'choice': choice, 'cost': cost,
                            'sum': sum(rc[c][3] for rc, c in zip(rowcands, choice)),
                            'subS': S, 'sub_obs': sub_obs})
    if total_s and len(sec_results) > 1 and time.process_time() - t0 < 0.6:
        tobs = norm_num(total_s)
        T = money_cands(tobs, mark, grouped)
        grand = sum(r['sum'] for r in sec_results)
        if grand not in T:
            for res in sec_results:
                if not res['rc']:
                    continue
                others = grand - res['sum']
                tgt = {}
                for tv, tc in T.items():
                    if tv - others > 0:
                        tgt[tv - others] = tc
                if not tgt:
                    continue
                f = make_sub_cost(tgt, '', mark, grouped)

                def f2(total, allow, f=f, res=res):
                    c = f(total, False)
                    if c is None:
                        if not allow:
                            return None
                        return 4.0 + (0 if res['sub_obs'] is None else
                                      min(6.0, wdist(fmt_money(total, mark, grouped),
                                                     res['sub_obs'])))
                    sc = res['subS'].get(total)
                    if sc is None and res['sub_obs'] is not None:
                        sc = min(6.0, wdist(fmt_money(total, mark, grouped), res['sub_obs']))
                    return c + (sc or 0.0)

                old = res['cost'] + 3.0
                cost, choice = choose_section(res['rc'], f2)
                if cost < old - 1e-9 and choice != res['choice']:
                    res['choice'] = choice
                    res['cost'] = cost
                    res['sum'] = sum(rc[c][3] for rc, c in zip(res['rc'], choice))
                    grand = sum(r['sum'] for r in sec_results)
                    if grand in T:
                        break
    items = []
    for res in sec_results:
        for code, rc, c in zip(res['codes'], res['rc'], res['choice']):
            items.append({'code': code, 'qty': int(rc[c][1]), 'unit_cents': int(rc[c][2])})
    state['output'] = {'items': items}
    return state

import re
import time
import itertools

MISREAD = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
           '6': '50', '7': '12', '8': '30', '9': '43'}
LOOK_D = {'O': '0', 'o': '0', 'Q': '0', 'D': '0', 'l': '1', 'I': '1', 'i': '1', '|': '1',
          'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6', 'b': '6'}
DIG_TO_LET = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G',
              '3': 'B', '4': 'A', '7': 'T', '9': 'G'}
RE_CODE = re.compile(r"^[A-Za-z0-9]{2}[0-9OlISBZG]{3,7}$")
RE_CODE_LOOSE = re.compile(r"^[A-Za-z0-9]{5,10}$")
RE_QTY = re.compile(r"^[0-9OlISBZG]{1,4}$")
RE_MONEY = re.compile(r"^[0-9OlISBZG']+[.,][0-9OlISBZG]{1,3}$")
RE_DIGITISH = re.compile(r"^[0-9OlISBZG']{1,12}$")
RE_PCS = re.compile(r"\s*pcs\s*$", re.I)


def _rev_misread():
    r = {}
    for y, xs in MISREAD.items():
        for x in xs:
            r.setdefault(x, []).append((y, 1.0 + 0.1 * (len(xs) - 1)))
    return r


REV = _rev_misread()


def mdist(t, s):
    if s is None:
        return 3.0
    m = len(s)
    prev = [j * 2.5 for j in range(m + 1)]
    for i in range(1, len(t) + 1):
        tc = t[i - 1]
        mis = MISREAD.get(tc, '')
        cur = [prev[0] + 1.0] + [0.0] * m
        for j in range(1, m + 1):
            sc = s[j - 1]
            best = cur[j - 1] + 2.5
            v = prev[j] + 1.0
            if v < best:
                best = v
            if sc == tc:
                v = prev[j - 1]
            elif sc in mis:
                v = prev[j - 1] + 1.0
            elif sc.isdigit() and tc.isdigit():
                v = prev[j - 1] + 2.5
            else:
                v = prev[j - 1] + 3.0
            if v < best:
                best = v
            if j >= 2 and sc == tc and s[j - 2] == tc:
                v = prev[j - 2] + 1.0
                if v < best:
                    best = v
            cur[j] = best
        prev = cur
    return prev[m]


def fmt_money(c):
    return "%d.%02d" % (c // 100, c % 100)


def norm_digits(s):
    return ''.join(LOOK_D.get(ch, ch) for ch in s)


def norm_money(s):
    if s is None:
        return None
    s = s.replace("'", "").replace(" ", "").replace("`", "")
    s = norm_digits(s).replace(',', '.')
    s = ''.join(ch for ch in s if ch.isdigit() or ch == '.')
    if s.count('.') > 1:
        k = s.rfind('.')
        s = s[:k].replace('.', '') + s[k:]
    return s


def norm_qty(s):
    if s is None:
        return None
    s = RE_PCS.sub('', s).replace(' ', '')
    s = norm_digits(s)
    return ''.join(ch for ch in s if ch.isdigit())


def edits1(s):
    out = []
    n = len(s)
    for i in range(n):
        ch = s[i]
        if ch == '.':
            continue
        for y, c in REV.get(ch, ()):
            out.append((s[:i] + y + s[i + 1:], c))
        if i > 0 and s[i - 1] == ch:
            out.append((s[:i] + s[i + 1:], 1.0))
    for i in range(n + 1):
        for d in '0123456789':
            out.append((s[:i] + d + s[i:], 1.05))
    return out


def money_val(s):
    if not s:
        return None
    if '.' in s:
        parts = s.split('.')
        if len(parts) != 2:
            return None
        a, b = parts
        if len(b) != 2 or not a:
            return None
        if len(a) > 1 and a[0] == '0':
            return None
        v = int(a) * 100 + int(b)
        return (v, 0.0) if v > 0 else None
    if len(s) < 3:
        return None
    a = s[:-2]
    if len(a) > 1 and a[0] == '0':
        return None
    v = int(s)
    return (v, 1.0) if v > 0 else None


def money_cands(s):
    res = {}
    if s is None or s == '':
        return res
    mv = money_val(s)
    if mv:
        res[mv[0]] = mv[1]
    for t, c in edits1(s):
        mv = money_val(t)
        if mv:
            cc = c + mv[1]
            if cc < res.get(mv[0], 99):
                res[mv[0]] = cc
    return res


def qty_val(s):
    if not s or (len(s) > 1 and s[0] == '0'):
        return None
    v = int(s)
    if 1 <= v <= 500:
        return v
    return None


def qty_cands(s):
    res = {}
    if s is None or s == '':
        return res
    v = qty_val(s)
    if v is not None:
        res[v] = 0.0
    for t, c in edits1(s):
        v = qty_val(t)
        if v is not None and c < res.get(v, 99):
            res[v] = c
    return res


def qdist(s, q):
    if s is None or s == '':
        return 3.0
    return mdist(str(q), s)


def adist(s, c):
    if s is None or s == '':
        return 3.0
    return mdist(fmt_money(c), s)


def code_ok(letters, ds):
    if len(ds) != 5 or len(letters) != 2:
        return False
    p1 = ord(letters[0]) - 64
    p2 = ord(letters[1]) - 64
    d = [int(x) for x in ds]
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p1 + p2) % 10 == d[4]


def fix_code(tok):
    t = tok.replace(' ', '')
    pre = t[:2]
    rest = t[2:]
    letters = ''
    for ch in pre:
        if ch.isdigit():
            letters += DIG_TO_LET.get(ch, 'A')
        elif ch.isalpha():
            letters += ch.upper() if ch != 'l' else 'I'
        else:
            letters += 'A'
    letters = ''.join(ch if 'A' <= ch <= 'Z' else 'A' for ch in letters)
    while len(letters) < 2:
        letters += 'A'
    ds = ''.join(ch for ch in norm_digits(rest) if ch.isdigit())
    if code_ok(letters, ds):
        return letters + ds
    best = None
    lvl1 = edits1(ds)
    for s, c in lvl1:
        if code_ok(letters, s) and (best is None or c < best[0]):
            best = (c, s)
    if best is None and len(ds) <= 7:
        seen = set()
        for s, c in lvl1:
            if s in seen:
                continue
            seen.add(s)
            for s2, c2 in edits1(s):
                if code_ok(letters, s2) and (best is None or c + c2 < best[0]):
                    best = (c + c2, s2)
    if best is not None:
        return letters + best[1]
    ds = (ds + '00000')[:5]
    p1 = ord(letters[0]) - 64
    p2 = ord(letters[1]) - 64
    d = [int(x) for x in ds]
    chk = (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p1 + p2) % 10
    return letters + ds[:4] + str(chk)


def type_costs(tok, pcs_style):
    t = tok.strip()
    if RE_CODE.match(t):
        cc = 0.0
    elif RE_CODE_LOOSE.match(t) and any(ch.isalpha() for ch in t[:2]):
        cc = 1.5
    else:
        cc = 4.0
    has_pcs = bool(RE_PCS.search(t))
    core = RE_PCS.sub('', t)
    if RE_QTY.match(core):
        qc = 0.0 if len(core) <= 3 else 0.8
        if pcs_style is not None and has_pcs != pcs_style:
            qc += 1.0
    elif RE_DIGITISH.match(core):
        qc = 2.0
    elif RE_MONEY.match(core):
        qc = 3.0
    else:
        qc = 4.0
    if has_pcs:
        mc = 4.0
    elif RE_MONEY.match(t):
        mc = 0.0
    elif RE_DIGITISH.match(t):
        mc = 0.7 if len(t) >= 3 else 1.5
    else:
        mc = 4.0
    return cc, qc, mc


def split_line(line, sepkind):
    if sepkind == 'pipe':
        parts = re.split(r"\s*\|\s*", line)
    elif sepkind == 'semi':
        parts = re.split(r"\s*;\s*", line)
    elif sepkind == 'tab':
        parts = re.split(r"\s*\t\s*", line)
    else:
        parts = re.split(r"\s{2,}|\t", line)
    return [p.strip() for p in parts if p.strip() != '']


def segment(tokens, colkind, pcs_style):
    n = len(tokens)
    INF = 1e18
    tc = [type_costs(t, pcs_style) for t in tokens]

    def cost_for(i, k):
        kind = colkind[k]
        c = tc[i]
        if kind == 'CODE':
            return c[0]
        if kind == 'QTY':
            return c[1]
        return c[2]
    dp = [[INF] * 4 for _ in range(n + 1)]
    bk = [[None] * 4 for _ in range(n + 1)]
    dp[0][0] = 0.0
    SKIP_TOK = 3.5
    SKIP_SLOT = 5.0
    for i in range(n + 1):
        for _ in range(2):
            for k in range(4):
                if dp[i][k] >= INF:
                    continue
                nk = (k + 1) % 4
                v = dp[i][k] + SKIP_SLOT
                if v < dp[i][nk] - 1e-12:
                    dp[i][nk] = v
                    bk[i][nk] = ('slot', i, k)
        if i == n:
            break
        for k in range(4):
            if dp[i][k] >= INF:
                continue
            nk = (k + 1) % 4
            v = dp[i][k] + cost_for(i, k)
            if v < dp[i + 1][nk]:
                dp[i + 1][nk] = v
                bk[i + 1][nk] = ('tok', i, k)
            v = dp[i][k] + SKIP_TOK
            if v < dp[i + 1][k]:
                dp[i + 1][k] = v
                bk[i + 1][k] = ('skip', i, k)
    seq = []
    i, k = n, 0
    guard = 0
    while not (i == 0 and k == 0) and guard < 10 * (n + 10):
        guard += 1
        b = bk[i][k]
        if b is None:
            break
        typ, pi, pk = b
        if typ == 'tok':
            seq.append((pk, tokens[pi]))
        elif typ == 'slot':
            seq.append((pk, None))
        i, k = pi, pk
    seq.reverse()
    rows = []
    cur = [None] * 4
    filled = False
    for k, tok in seq:
        cur[k] = tok
        filled = filled or tok is not None
        if k == 3:
            if filled:
                rows.append(cur)
            cur = [None] * 4
            filled = False
    return rows


def solve_row(row, deadline):
    qs, us, ams = row['qs'], row['us'], row['as']
    q0 = qty_val(qs) if qs else None
    u0 = money_val(us) if us else None
    a0 = money_val(ams) if ams else None
    if q0 is not None and u0 is not None and a0 is not None and u0[1] == 0 and a0[1] == 0 \
            and q0 * u0[0] == a0[0]:
        row['opts'] = [[0.0, q0, u0[0], a0[0]]]
        row['certain'] = True
        return
    row['certain'] = False
    Q = qty_cands(qs)
    U = money_cands(us)
    A = money_cands(ams)
    row['Q'] = Q
    row['U'] = U
    row['A'] = A
    opts = {}

    def add(c, q, u, a):
        key = (q, u)
        if key not in opts or c < opts[key][0]:
            opts[key] = [c, q, u, a]
    for q, cq in Q.items():
        for u, cu in U.items():
            a = q * u
            ca = A.get(a)
            if ca is not None:
                add(cq + cu + ca, q, u, a)
    best = min([o[0] for o in opts.values()] + [99])
    if best > 1.6 and time.perf_counter() < deadline:
        Ql = sorted(Q.items(), key=lambda x: x[1])
        Ul = sorted(U.items(), key=lambda x: x[1])
        Al = sorted(A.items(), key=lambda x: x[1])
        Q0 = [x for x in Ql if x[1] <= 0.01] or Ql[:3]
        U0 = [x for x in Ul if x[1] <= 1.01] or Ul[:3]
        A0 = [x for x in Al if x[1] <= 1.01] or Al[:3]
        Q0 = Q0[:5]
        U0 = U0[:6]
        A0 = A0[:6]
        Qw = Ql[:40]
        Uw = Ul[:60]
        Aw = Al[:60]
        pairs = set()
        for q, cq in Q0:
            for u, cu in Uw:
                pairs.add((q, cq, u, cu))
        for q, cq in Qw:
            for u, cu in U0:
                pairs.add((q, cq, u, cu))
        for (q, cq, u, cu) in pairs:
            if cq + cu > 2.2:
                continue
            a = q * u
            add(cq + cu + adist(ams, a), q, u, a)
        for q, cq in (Q0 + Qw[:15]):
            for a, ca in (A0 + Aw[:30]):
                if cq + ca > 2.2 or a % q:
                    continue
                u = a // q
                if u <= 0:
                    continue
                add(cq + ca + adist(us, u), q, u, a)
        for u, cu in (U0 + Uw[:30]):
            for a, ca in (A0 + Aw[:30]):
                if cu + ca > 2.2 or u <= 0 or a % u:
                    continue
                q = a // u
                if 1 <= q <= 500:
                    add(cu + ca + qdist(qs, q), q, u, a)
    if not opts:
        q = q0 if q0 is not None else (min(Q, key=Q.get) if Q else 1)
        if u0:
            u = u0[0]
        elif U:
            u = min(U, key=U.get)
        elif a0 and q:
            u = max(1, a0[0] // q)
        else:
            u = 100
        opts[(q, u)] = [9.0, q, u, q * u]
    ol = sorted(opts.values(), key=lambda o: (o[0], o[1], o[2]))
    row['opts'] = ol[:8]


def need_options(row, need):
    res = []
    if need <= 0 or row.get('certain'):
        return res
    Q, U = row.get('Q', {}), row.get('U', {})
    ca = adist(row['as'], need)
    seen = set()
    for q, cq in Q.items():
        if need % q == 0:
            u = need // q
            cu = U.get(u)
            if cu is None:
                if cq > 0.01:
                    continue
                cu = adist(row['us'], u)
            if (q, u) not in seen:
                seen.add((q, u))
                res.append([cq + cu + ca, q, u, need])
    for u, cu in U.items():
        if need % u == 0:
            q = need // u
            if 1 <= q <= 500 and (q, u) not in seen:
                cq = Q.get(q)
                if cq is None:
                    if cu > 0.01:
                        continue
                    cq = qdist(row['qs'], q)
                seen.add((q, u))
                res.append([cq + cu + ca, q, u, need])
    return res


def section_alts(sec, extra_targets, deadline):
    rows = sec['rows']
    subs = sec['sub']
    if not rows:
        return [[(adist(subs, 0) if subs else 0.0), 0, {}]]

    def subcost(x):
        if subs is None:
            return 1.5
        if x <= 0:
            return 6.0
        return adist(subs, x)
    base = [r['opts'][0] for r in rows]
    bc = sum(o[0] for o in base)
    S = sum(o[3] for o in base)
    alts = {}

    def add(cost, total, ch):
        if total not in alts or cost < alts[total][0]:
            alts[total] = [cost, total, ch]
    sc0 = subcost(S)
    add(bc + sc0, S, {})
    unc = [i for i, r in enumerate(rows) if not r.get('certain')]
    if sc0 > 0.01 or extra_targets:
        for i in unc:
            for o in rows[i]['opts'][1:6]:
                nS = S - base[i][3] + o[3]
                add(bc - base[i][0] + o[0] + subcost(nS), nS, {i: o})
        if len(unc) <= 8:
            for i, j in itertools.combinations(unc, 2):
                for oi in rows[i]['opts'][:4]:
                    for oj in rows[j]['opts'][:4]:
                        if oi is rows[i]['opts'][0] and oj is rows[j]['opts'][0]:
                            continue
                        nS = S - base[i][3] - base[j][3] + oi[3] + oj[3]
                        add(bc - base[i][0] - base[j][0] + oi[0] + oj[0] + subcost(nS), nS,
                            {i: oi, j: oj})
        targets = {}
        if subs:
            for t, c in money_cands(subs).items():
                targets[t] = c
        for t in extra_targets:
            if t > 0 and t not in targets:
                targets[t] = subcost(t)
        tl = sorted(targets.items(), key=lambda x: x[1])[:150]
        for i in unc:
            if time.perf_counter() > deadline:
                break
            rest = S - base[i][3]
            for T, tcost in tl:
                need = T - rest
                for o in need_options(rows[i], need):
                    add(bc - base[i][0] + o[0] + tcost, T, {i: o})
    al = sorted(alts.values(), key=lambda a: a[0])
    return al[:4]


def parse_doc(text):
    lines = text.split('\n')
    colorder = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    sepkind = None
    for ln in lines:
        if 'COLUMNS' in ln:
            rest = ln.split('COLUMNS', 1)[1]
            if rest.startswith(':'):
                rest = rest[1:]
            ms = list(re.finditer(r"CODE|QTY|UNIT|AMOUNT", rest))
            if len(ms) >= 2:
                order = [m.group(0) for m in ms]
                if sorted(order) == sorted(colorder):
                    colorder = order
                sep = rest[ms[0].end():ms[1].start()]
                if '|' in sep:
                    sepkind = 'pipe'
                elif ';' in sep:
                    sepkind = 'semi'
                elif '\t' in sep:
                    sepkind = 'tab'
                else:
                    sepkind = 'space'
            break
    if sepkind is None:
        cnt = {'pipe': text.count('|'), 'semi': text.count(';'), 'tab': text.count('\t'),
               'space': text.count('   ')}
        sepkind = max(cnt, key=cnt.get)
    sections = []
    cur = None
    total_s = None
    items_s = None
    pcs_count = 0
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if '== SECTION' in s or s.startswith('=='):
            cur = {'tokens': [], 'sub': None}
            sections.append(cur)
            continue
        if s.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'tokens': [], 'sub': None}
                sections.append(cur)
            cur['sub'] = norm_money(s[len('SUBTOTAL'):].strip())
            cur = None
            continue
        if s.startswith('TOTAL'):
            m = re.match(r"TOTAL\s+(.*?)\s*ITEMS\s*(.*)$", s)
            if m:
                total_s = norm_money(m.group(1))
                items_s = m.group(2)
            else:
                total_s = norm_money(s[5:])
            continue
        toks = split_line(s, sepkind)
        if not toks:
            continue
        ok = True
        for t in toks:
            if min(type_costs(t, None)) > 1.0:
                ok = False
                break
        if not ok:
            continue
        if cur is None:
            if sections and sections[-1]['sub'] is None:
                cur = sections[-1]
            else:
                cur = {'tokens': [], 'sub': None}
                sections.append(cur)
        for t in toks:
            if RE_PCS.search(t):
                pcs_count += 1
        cur['tokens'].extend(toks)
    return colorder, sepkind, sections, total_s, items_s, pcs_count


def solve(state, params):
    t0 = time.perf_counter()
    deadline = t0 + 0.7
    text = state.get('input', {}).get('text', '') or ''
    try:
        colorder, sepkind, sections, total_s, items_s, pcs_count = parse_doc(text)
        ntok = sum(len(s['tokens']) for s in sections)
        pcs_style = None
        if ntok:
            pcs_style = pcs_count * 2 >= max(1, ntok // 4)
        idx = {c: i for i, c in enumerate(colorder)}
        secs = []
        for sec in sections:
            rows_tok = segment(sec['tokens'], colorder, pcs_style)
            rows = []
            for rt in rows_tok:
                ct = rt[idx['CODE']]
                qt = rt[idx['QTY']]
                ut = rt[idx['UNIT']]
                at = rt[idx['AMOUNT']]
                row = {'ct': ct, 'qs': norm_qty(qt), 'us': norm_money(ut), 'as': norm_money(at)}
                for key in ('qs', 'us', 'as'):
                    if row[key] == '':
                        row[key] = None
                solve_row(row, deadline - 0.25)
                rows.append(row)
            secs.append({'rows': rows, 'sub': sec['sub']})
        sec_alts = [section_alts(s, [], deadline) for s in secs]

        def global_pick(sa):
            best = None
            lists = [a[:3] for a in sa]
            ncomb = 1
            for l in lists:
                ncomb *= max(1, len(l))
            if ncomb > 3000:
                lists = [a[:2] for a in sa]
            for combo in itertools.product(*lists):
                c = sum(x[0] for x in combo)
                tot = sum(x[1] for x in combo)
                if total_s:
                    c += adist(total_s, tot) if tot > 0 else 6.0
                if best is None or c < best[0]:
                    best = (c, combo)
            return best
        best = global_pick(sec_alts) if secs else None
        if best is not None and total_s and time.perf_counter() < deadline:
            tot = sum(x[1] for x in best[1])
            if adist(total_s, tot) > 0.01 or any(
                    s['sub'] is not None and adist(s['sub'], x[1]) > 0.01
                    for s, x in zip(secs, best[1])):
                tcands = money_cands(total_s)
                tl = sorted(tcands.items(), key=lambda x: x[1])[:40]
                new_alts = []
                for k, s in enumerate(secs):
                    others = tot - best[1][k][1]
                    ext = [T - others for T, c in tl if T - others > 0]
                    if time.perf_counter() > deadline:
                        new_alts.append(sec_alts[k])
                        continue
                    al = section_alts(s, ext, deadline)
                    merged = {}
                    for a in sec_alts[k] + al:
                        if a[1] not in merged or a[0] < merged[a[1]][0]:
                            merged[a[1]] = a
                    new_alts.append(sorted(merged.values(), key=lambda a: a[0])[:4])
                b2 = global_pick(new_alts)
                if b2 is not None and b2[0] < best[0]:
                    best = b2
        items = []
        for k, s in enumerate(secs):
            ch = best[1][k][2] if best is not None else {}
            for i, r in enumerate(s['rows']):
                o = ch.get(i, r['opts'][0])
                code = fix_code(r['ct']) if r['ct'] else 'AA00000'
                items.append({'code': code, 'qty': int(o[1]), 'unit_cents': int(o[2])})
        state['output'] = {'items': items}
    except Exception as e:
        state['output'] = {'items': []}
        state['error'] = str(e)
    return state

import re
import time

L2D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6'}
D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63', '6': '50', '7': '12', '8': '30', '9': '43'}
REV = {}
for _t, _ss in MIS.items():
    for _s in _ss:
        REV.setdefault(_s, []).append(_t)


def _edits1(s):
    out = {}
    n = len(s)
    for i in range(n):
        for t in REV.get(s[i], []):
            out.setdefault(s[:i] + t + s[i + 1:], 1)
    for i in range(1, n):
        if s[i] == s[i - 1]:
            out.setdefault(s[:i] + s[i + 1:], 1)
    for i in range(n + 1):
        for d in '0123456789':
            out.setdefault(s[:i] + d + s[i:], 1)
    out.pop(s, None)
    return out


def _dist(t, o, memo):
    key = (t, o)
    if key in memo:
        return memo[key]
    if t == o:
        memo[key] = 0
        return 0
    n, m = len(t), len(o)
    prev = [0.0] * (m + 1)
    for j in range(1, m + 1):
        prev[j] = prev[j - 1] + (1.5 if o[j - 1] == "'" else 2.5)
    for i in range(1, n + 1):
        ti = t[i - 1]
        cur = [0.0] * (m + 1)
        cur[0] = prev[0] + (1.5 if ti == "'" else 1.0)
        for j in range(1, m + 1):
            oj = o[j - 1]
            if ti == oj:
                c = prev[j - 1]
            elif ti == "'" or oj == "'":
                c = prev[j - 1] + 3.0
            elif oj in MIS.get(ti, ''):
                c = prev[j - 1] + 1.0
            else:
                c = prev[j - 1] + 2.0
            d = prev[j] + (1.5 if ti == "'" else 1.0)
            if d < c:
                c = d
            if oj == "'":
                ins = cur[j - 1] + 1.5
            elif oj == ti:
                ins = cur[j - 1] + 1.0
            else:
                ins = cur[j - 1] + 2.5
            if ins < c:
                c = ins
            cur[j] = c
        prev = cur
    memo[key] = prev[m]
    return prev[m]


def _map_digits(s):
    return ''.join(L2D.get(ch, ch) for ch in s)


def _parse_money(tok):
    if tok is None:
        return None
    s = _map_digits(tok.strip())
    s = re.sub(r"[^0-9.,']", '', s)
    k = max(s.rfind('.'), s.rfind(','))
    if k >= 0:
        ip = s[:k].replace('.', '').replace(',', '')
        fp = s[k + 1:].replace('.', '').replace(',', '').replace("'", '')
        return (ip, fp)
    if not re.search(r'\d', s):
        return None
    return (s, None)


def _fmt_int(n, grp):
    return "{:,}".format(n).replace(',', "'") if grp else str(n)


def _money_cands(mo):
    if mo is None:
        return {}, {}
    ip, fp = mo
    x = ip.replace("'", '') + (fp if fp is not None else '')
    base = {}
    if x and (fp is None or len(fp) == 2):
        base[int(x)] = 0
    c1 = {}
    if x:
        for s, c in _edits1(x).items():
            if s and len(s) <= 11:
                v = int(s)
                if v > 0 and v not in base:
                    c1.setdefault(v, c)
        if fp is not None and len(fp) != 2:
            v = int(x)
            if v > 0 and v not in base:
                c1.setdefault(v, 1)
    return base, c1


def _qty_cands(qo):
    if not qo:
        return {}, {}
    base = {}
    v = int(qo)
    if 1 <= v <= 500:
        base[v] = 0
    c1 = {}
    for s, c in _edits1(qo).items():
        if s and len(s) <= 3:
            v = int(s)
            if 1 <= v <= 500 and v not in base:
                c1.setdefault(v, c)
    return base, c1


def _check_ok(code):
    d = [ord(ch) - 48 for ch in code[2:]]
    p = ord(code[0]) - 64 + ord(code[1]) - 64
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p) % 10 == d[4]


def _decode_code(tok):
    if tok is None:
        return 'AA00000'
    t = re.sub(r'[^A-Za-z0-9]', '', tok.strip())
    if len(t) < 2:
        t = (t + 'AA')[:2]
    lp = ''
    for ch in t[:2]:
        if ch.isdigit():
            lp += D2L.get(ch, 'A')
        else:
            u = ch.upper()
            if ch == 'l':
                u = 'I'
            lp += u if 'A' <= u <= 'Z' else 'A'
    dg = ''.join(L2D.get(ch, ch) for ch in t[2:])
    dg = re.sub(r'[^0-9]', '', dg)

    def ok(s):
        return len(s) == 5 and _check_ok(lp + s)
    if ok(dg):
        return lp + dg
    lv1 = _edits1(dg)
    for s in lv1:
        if ok(s):
            return lp + s
    for s in list(lv1.keys()):
        if abs(len(s) - 5) > 1:
            continue
        for s2 in _edits1(s):
            if ok(s2):
                return lp + s2
    if len(dg) == 5:
        for i in range(4, -1, -1):
            for d in '0123456789':
                s = dg[:i] + d + dg[i + 1:]
                if ok(s):
                    return lp + s
    s = (dg + '00000')[:5]
    d = [int(c) for c in s]
    p = ord(lp[0]) - 64 + ord(lp[1]) - 64
    s = s[:4] + str((d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p) % 10)
    return lp + s


def solve(state, params):
    t0 = time.process_time()
    text = (state.get('input', {}) or {}).get('text', '') or ''
    lines = text.split('\n')
    sep = None
    order = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    for ln in lines:
        if ln.lstrip().startswith('COLUMNS'):
            rest = ln.split('COLUMNS', 1)[1]
            rest = rest[1:] if rest.startswith(':') else rest
            names = re.findall(r'CODE|QTY|UNIT|AMOUNT', rest)
            if len(names) == 4 and len(set(names)) == 4:
                order = names
            body = rest.strip(' ')
            if '|' in body:
                sep = '|'
            elif '\t' in body:
                sep = '\t'
            elif ';' in body:
                sep = ';'
            else:
                sep = '   '
            break
    if sep is None:
        if ' | ' in text:
            sep = '|'
        elif '\t' in text:
            sep = '\t'
        elif ';' in text:
            sep = ';'
        else:
            sep = '   '

    tokpat = re.compile(r"^[A-Z0-9lOSBZGIoiz.,']+( ?pcs)?$")

    def split_line(ln):
        s = ln.strip()
        if sep == '   ':
            parts = s.split('   ')
        else:
            parts = s.split(sep)
        parts = [p.strip() for p in parts]
        while parts and parts[-1] == '':
            parts.pop()
        while parts and parts[0] == '':
            parts.pop(0)
        return parts

    sections = []
    cur = {'tokens': [], 'sub': None}
    total_tok = None
    grp = False
    pcs_count = 0
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if re.match(r'^==\s*SECTION', s):
            if cur['tokens'] or cur['sub'] is not None:
                sections.append(cur)
            cur = {'tokens': [], 'sub': None}
            continue
        if s.startswith('SUBTOTAL'):
            cur['sub'] = s[len('SUBTOTAL'):].strip()
            sections.append(cur)
            cur = {'tokens': [], 'sub': None}
            continue
        if s.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s+(.*?)\s+ITEMS\b.*$', s)
            total_tok = m.group(1).strip() if m else s[len('TOTAL'):].strip()
            continue
        parts = split_line(s)
        if not parts:
            continue
        if not all(p == '' or tokpat.match(p) for p in parts):
            continue
        for p in parts:
            if "'" in p:
                grp = True
            if 'pcs' in p:
                pcs_count += 1
        cur['tokens'].extend(parts)
    if cur['tokens'] or cur['sub'] is not None:
        sections.append(cur)

    code_re = re.compile(r'^[A-Z0-9lI]{2}[0-9OlSBZGI]{3,7}$')
    qty_re = re.compile(r'^[0-9OlSBZGI]{0,4}( ?pcs)?$')
    money_re = re.compile(r"^[0-9OlSBZGI']+([.,][0-9OlSBZGI]{0,4})?$")

    def fit(tok, role):
        if role == 'CODE':
            if code_re.match(tok):
                return 0.0 if re.search(r'[A-Z]', tok[:2]) else 1.0
            return 3.0
        if role == 'QTY':
            if 'pcs' in tok:
                return 0.0
            if tok and qty_re.match(tok):
                return 0.0 if pcs_count == 0 else 1.0
            return 3.0
        if 'pcs' in tok:
            return 3.0
        if money_re.match(tok):
            if re.search(r'[.,]', tok):
                return 0.0
            return 0.5 if len(tok) >= 3 else 1.0
        return 3.0

    def align(tokens):
        n = len(tokens)
        INF = 1e18
        SK = 4.0
        dp = [[INF] * 4 for _ in range(n + 1)]
        bk = [[None] * 4 for _ in range(n + 1)]
        dp[0][0] = 0.0
        for i in range(n + 1):
            for _ in range(2):
                for k in range(3):
                    if dp[i][k] + SK < dp[i][k + 1]:
                        dp[i][k + 1] = dp[i][k] + SK
                        bk[i][k + 1] = ('miss', i, k)
            if i == n:
                break
            tok = tokens[i]
            for k in range(4):
                if dp[i][k] >= INF:
                    continue
                c = dp[i][k] + fit(tok, order[k])
                nk = (k + 1) % 4
                if c < dp[i + 1][nk]:
                    dp[i + 1][nk] = c
                    bk[i + 1][nk] = ('take', i, k)
                c = dp[i][k] + SK
                if c < dp[i + 1][k]:
                    dp[i + 1][k] = c
                    bk[i + 1][k] = ('skip', i, k)
        if dp[n][0] >= INF:
            return []
        ops = []
        i, k = n, 0
        while not (i == 0 and k == 0):
            b = bk[i][k]
            if b is None:
                break
            ops.append(b)
            i, k = b[1], b[2]
        ops.reverse()
        rows = []
        cr = None
        for op, i, k in ops:
            if op == 'skip':
                continue
            if k == 0 or cr is None:
                cr = [None] * 4
            if op == 'take':
                cr[k] = tokens[i]
            if k == 3:
                rows.append(cr)
                cr = None
        return rows

    memo = {}

    def dmoney(c, mo):
        if mo is None:
            return 1.5
        ip, fp = mo
        ti = _fmt_int(c // 100, grp)
        tf = '%02d' % (c % 100)
        if not grp:
            ip = ip.replace("'", '')
        if fp is not None:
            return _dist(ti, ip, memo) + _dist(tf, fp, memo)
        return _dist(ti + tf, ip, memo)

    def dqty(q, qo):
        if not qo:
            return 1.5
        return _dist(str(q), qo, memo)

    def decode_row(row):
        f = dict(zip(order, row))
        code = _decode_code(f['CODE'])
        qt = f['QTY']
        qo = None
        if qt is not None:
            qo = re.sub(r'[^0-9]', '', _map_digits(qt.replace('pcs', '')))
        uo = _parse_money(f['UNIT'])
        ao = _parse_money(f['AMOUNT'])
        Q0, Q1 = _qty_cands(qo)
        U0, U1 = _money_cands(uo)
        A0, A1 = _money_cands(ao)
        res = {}

        def add(q, u, a, cost):
            key = (q, u)
            if key not in res or res[key][0] > cost:
                res[key] = (cost, q, u, a)

        def full(q, u, a):
            c1 = Q0.get(q)
            if c1 is None:
                c1 = Q1.get(q)
            if c1 is None:
                c1 = dqty(q, qo)
            c2 = U0.get(u)
            if c2 is None:
                c2 = U1.get(u)
            if c2 is None:
                c2 = dmoney(u, uo)
            c3 = A0.get(a)
            if c3 is None:
                c3 = A1.get(a)
            if c3 is None:
                c3 = dmoney(a, ao)
            return c1 + c2 + c3

        def look(v, d0, d1):
            if v in d0:
                return d0[v]
            if v in d1:
                return d1[v]
            return 3.0

        def gen(Qs, Us, As, exact):
            for q in Qs:
                for u in Us:
                    a = q * u
                    add(q, u, a, full(q, u, a) if exact else Qs[q] + Us[u] + look(a, A0, A1))
                for a in As:
                    if a % q == 0:
                        u = a // q
                        if u > 0:
                            add(q, u, a, full(q, u, a) if exact else Qs[q] + As[a] + look(u, U0, U1))
            for u in Us:
                for a in As:
                    if a % u == 0:
                        q = a // u
                        if 1 <= q <= 500:
                            add(q, u, a, full(q, u, a) if exact else Us[u] + As[a] + look(q, Q0, Q1))

        gen(Q0, U0, A0, True)
        best = min((v[0] for v in res.values()), default=99)
        if best > 0 and time.process_time() - t0 < 0.6:
            gen(Q0, U1, {}, False)
            gen(Q1, U0, {}, False)
            gen(Q0, {}, A1, False)
            gen(Q1, {}, A0, False)
            gen({}, U0, A1, False)
            gen({}, U1, A0, False)
        alts = sorted(res.values())
        if alts:
            alts = [a for a in alts if a[0] <= alts[0][0] + 3][:8]
        else:
            q = next(iter(Q0), None) or next(iter(Q1), 1)
            u = next(iter(U0), None) or next(iter(U1), 0)
            alts = [(9.0, q, u, q * u)]
        return code, alts

    sec_data = []
    for sec in sections:
        rows = align(sec['tokens']) if sec['tokens'] else []
        dec = [decode_row(r) for r in rows]
        subo = _parse_money(sec['sub']) if sec['sub'] is not None else None
        sec_data.append((dec, subo))

    sec_sols = []
    for dec, subo in sec_data:
        base_cost = sum(d[1][0][0] for d in dec)
        base_sum = sum(d[1][0][3] for d in dec)

        def sc(s, subo=subo):
            return dmoney(s, subo) if subo is not None else 0.0
        sols = [(base_cost + sc(base_sum), base_sum, -1, 0)]
        if subo is not None:
            for i, d in enumerate(dec):
                for k in range(1, len(d[1])):
                    a = d[1][k]
                    s = base_sum - d[1][0][3] + a[3]
                    c = base_cost - d[1][0][0] + a[0] + sc(s)
                    sols.append((c, s, i, k))
        sols.sort()
        sec_sols.append(sols[:6])

    toto = _parse_money(total_tok) if total_tok is not None else None
    choice = [0] * len(sec_sols)
    if toto is not None and sec_sols:
        bsum = sum(s[0][1] for s in sec_sols)
        bcost = sum(s[0][0] for s in sec_sols)
        best = (bcost + dmoney(bsum, toto), -1, 0)
        for j, ss in enumerate(sec_sols):
            for k in range(1, len(ss)):
                s = bsum - ss[0][1] + ss[k][1]
                c = bcost - ss[0][0] + ss[k][0] + dmoney(s, toto)
                if c < best[0] - 1e-9:
                    best = (c, j, k)
        if best[1] >= 0:
            choice[best[1]] = best[2]

    items = []
    for j, (dec, subo) in enumerate(sec_data):
        sol = sec_sols[j][choice[j]]
        for i, (code, alts) in enumerate(dec):
            k = sol[3] if sol[2] == i else 0
            a = alts[k]
            items.append({'code': code, 'qty': int(a[1]), 'unit_cents': int(a[2])})
    state['output'] = {'items': items}
    return state

import re
import time

LOOK_D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6', 'D': '0', 'Q': '0'}
LOOK_L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G', '4': 'A', '7': 'T', '3': 'E'}
MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63', '6': '50', '7': '12', '8': '30', '9': '43'}


def _rev():
    r = {}
    for o, shown in MIS.items():
        for s in shown:
            r.setdefault(s, []).append(o)
    return r


REV = _rev()


def to_digits(s):
    out = []
    for ch in s:
        if ch.isdigit():
            out.append(ch)
        elif ch in LOOK_D:
            out.append(LOOK_D[ch])
    return ''.join(out)


def code_check(letters, d):
    p1 = ord(letters[0]) - 64
    p2 = ord(letters[1]) - 64
    return (int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p1 + p2) % 10


def code_valid(letters, d):
    return len(d) == 5 and d.isdigit() and code_check(letters, d) == int(d[4])


def fix_code(tok):
    t = re.sub(r'\s+', '', tok)
    letters = ''
    i = 0
    while len(letters) < 2 and i < len(t):
        ch = t[i]
        if ch.isalpha():
            letters += ch.upper()
        elif ch in LOOK_L:
            letters += LOOK_L[ch]
        i += 1
    while len(letters) < 2:
        letters += 'A'
    if not ('A' <= letters[0] <= 'Z' and 'A' <= letters[1] <= 'Z'):
        letters = 'AA'
    d = to_digits(t[i:])
    if len(d) == 5 and code_valid(letters, d):
        return letters + d
    cands = []
    if len(d) == 5:
        for k in range(5):
            for r in REV.get(d[k], []):
                nd = d[:k] + r + d[k + 1:]
                if code_valid(letters, nd):
                    cands.append(nd)
        if cands:
            return letters + cands[0]
        return letters + d[:4] + str(code_check(letters, d[:4]))
    if len(d) == 6:
        for k in range(6):
            if (k > 0 and d[k] == d[k - 1]) or (k < 5 and d[k] == d[k + 1]):
                nd = d[:k] + d[k + 1:]
                if code_valid(letters, nd) and nd not in cands:
                    cands.append(nd)
        if not cands:
            for k in range(6):
                nd = d[:k] + d[k + 1:]
                if code_valid(letters, nd):
                    cands.append(nd)
        if cands:
            return letters + cands[0]
        nd = d[:5]
        return letters + nd[:4] + str(code_check(letters, nd[:4]))
    if len(d) == 4:
        for k in range(5):
            for c in '0123456789':
                nd = d[:k] + c + d[k:]
                if code_valid(letters, nd):
                    cands.append(nd)
        if cands:
            return letters + cands[0]
        return letters + d + str(code_check(letters, d))
    if len(d) > 6:
        d = d[:5]
        return letters + d[:4] + str(code_check(letters, d[:4]))
    d = (d + '0000')[:4]
    return letters + d + str(code_check(letters, d))


def edits(ds, ins_lo, ins_hi, del_lo, del_hi):
    yield ds, 0.0
    n = len(ds)
    for k in range(n):
        for r in REV.get(ds[k], []):
            yield ds[:k] + r + ds[k + 1:], 1.0
    for k in range(max(0, del_lo), min(n, del_hi)):
        if (k > 0 and ds[k] == ds[k - 1]) or (k < n - 1 and ds[k] == ds[k + 1]):
            yield ds[:k] + ds[k + 1:], 1.0
    for k in range(max(0, ins_lo), min(n, ins_hi) + 1):
        for c in '0123456789':
            yield ds[:k] + c + ds[k:], 1.05


def money_cands(tok):
    s = tok.strip()
    s2 = ''
    for ch in s:
        if ch.isdigit() or ch in '.,':
            s2 += ch
        elif ch in LOOK_D:
            s2 += LOOK_D[ch]
    m = re.match(r'^(\d*)[.,](\d*)$', s2)
    if m:
        ip, fp = m.group(1), m.group(2)
        ds = ip + fp
        ni = len(ip)
        if len(fp) == 2:
            il, ih, dl, dh = 0, ni, 0, ni
        elif len(fp) == 1:
            il, ih, dl, dh = ni, len(ds), 0, 0
        elif len(fp) == 3:
            il, ih, dl, dh = 0, -1, ni, len(ds)
        else:
            il, ih, dl, dh = 0, len(ds), 0, len(ds)
    else:
        ds = re.sub(r'\D', '', s2)
        il, ih, dl, dh = 0, len(ds), 0, len(ds)
    out = {}
    for cand, c in edits(ds, il, ih, dl, dh):
        if not cand:
            continue
        v = int(cand)
        if v <= 0:
            continue
        if v not in out or out[v] > c:
            out[v] = c
    return out


def qty_cands(tok):
    s = re.sub(r'(?i)p\s*c\s*s', '', tok).strip()
    ds = to_digits(s)
    out = {}
    if not ds:
        for v in range(1, 10):
            out[v] = 1.0
        return out
    for cand, c in edits(ds, 0, len(ds), 0, len(ds)):
        if not cand:
            continue
        v = int(cand)
        if 1 <= v <= 500 and (v not in out or out[v] > c):
            out[v] = c
    if not out:
        out[max(1, min(500, int(ds[:3])))] = 2.0
    return out


def tok_type_cost(tok, col):
    t = tok.strip()
    if col == 'CODE':
        if re.match(r'^[A-Z0-9]{2}[0-9OlSBZGI]{4,6}$', t):
            return 0.0
        if re.match(r'^[A-Za-z0-9]{6,9}$', t):
            return 1.0
        return 3.0
    if col == 'QTY':
        if re.match(r'^[0-9OlSBZG]{0,4}( ?pcs)?$', t):
            return 0.0 if '.' not in t and ',' not in t else 2.0
        return 3.0
    if re.match(r"^[0-9OlSBZG']*[.,][0-9OlSBZG]{1,3}$", t):
        return 0.0
    if re.match(r"^[0-9OlSBZG']{2,}$", t):
        if re.match(r'^[A-Z]{2}', t):
            return 3.0
        return 0.6
    return 3.0


def looks_value(tok):
    t = tok.strip()
    if t == '':
        return True
    t = re.sub(r'\s*pcs$', '', t)
    if not re.match(r"^[A-Za-z0-9.,']+$", t):
        return False
    if len(t) > 14:
        return False
    good = sum(1 for ch in t if ch.isdigit() or ch in LOOK_D or ch in ".,'")
    return good >= len(t) - 2 and good >= 1


def split_line(line, sep):
    if sep == '|':
        parts = line.split('|')
    elif sep == ';':
        parts = line.split(';')
    elif sep == '\t':
        parts = line.split('\t')
    else:
        parts = re.split(r' {3}', line.rstrip('\n'))
    parts = [p.strip() for p in parts]
    while parts and parts[-1] == '':
        parts.pop()
    while parts and parts[0] == '':
        parts.pop(0)
    return parts


def parse_doc(state, params):
    text = state.get('input', {}).get('text', '') or ''
    lines = text.split('\n')
    cols = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    sep = ';'
    for ln in lines:
        if 'COLUMNS' in ln:
            body = ln.split('COLUMNS', 1)[1]
            body = body[1:] if body.startswith(':') else body
            pos = []
            for c in ['CODE', 'QTY', 'UNIT', 'AMOUNT']:
                pos.append((body.find(c), c))
            if all(p >= 0 for p, _ in pos):
                cols = [c for _, c in sorted(pos)]
            inner = body.strip()
            if '|' in inner:
                sep = '|'
            elif ';' in inner:
                sep = ';'
            elif '\t' in inner:
                sep = '\t'
            else:
                sep = '   '
            break
    sections = []
    cur = None
    total = None
    items_n = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if re.match(r'^=+\s*SECTION', s):
            cur = {'tokens': [], 'subtotal': None}
            sections.append(cur)
            continue
        if s.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'tokens': [], 'subtotal': None}
                sections.append(cur)
            cur['subtotal'] = s[len('SUBTOTAL'):].strip()
            continue
        if s.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s+(.*?)\s+ITEMS\s*(.*)$', s)
            if m:
                total = m.group(1)
                items_n = m.group(2)
            continue
        parts = split_line(ln.replace('\r', ''), sep)
        if not parts:
            continue
        if not all(looks_value(p) for p in parts):
            continue
        if cur is None:
            cur = {'tokens': [], 'subtotal': None}
            sections.append(cur)
        cur['tokens'].extend(parts)
    state['doc'] = {'cols': cols, 'sections': sections, 'total': total, 'items_n': items_n}
    return state


def align(tokens, cols):
    n = len(tokens)
    INF = float('inf')
    best = [INF] * (n + 1)
    back = [None] * (n + 1)
    best[0] = 0.0
    tc = [[tok_type_cost(t, c) for c in cols] for t in tokens]
    for i in range(n):
        if best[i] == INF:
            continue
        b = best[i]
        if b + 4.0 < best[i + 1]:
            best[i + 1] = b + 4.0
            back[i + 1] = ('skip', i)
        if i + 4 <= n:
            c = b + sum(tc[i + k][k] for k in range(4))
            if c < best[i + 4]:
                best[i + 4] = c
                back[i + 4] = ('row', i, -1)
        if i + 3 <= n:
            for miss in range(4):
                c = b + 3.5
                k2 = 0
                for k in range(4):
                    if k == miss:
                        continue
                    c += tc[i + k2][k]
                    k2 += 1
                if c < best[i + 3]:
                    best[i + 3] = c
                    back[i + 3] = ('row3', i, miss)
    rows = []
    j = n
    while j > 0:
        bk = back[j]
        if bk is None:
            break
        if bk[0] == 'skip':
            j = bk[1]
            continue
        i = bk[1]
        if bk[0] == 'row':
            rows.append(tokens[i:i + 4])
        else:
            seg = list(tokens[i:i + 3])
            seg.insert(bk[2], '')
            rows.append(seg)
        j = i
    rows.reverse()
    return rows


def solve_row(fields, cols):
    d = dict(zip(cols, fields))
    qc = qty_cands(d['QTY'])
    uc = money_cands(d['UNIT'])
    ac = money_cands(d['AMOUNT'])
    q0 = min(qc, key=lambda v: qc[v]) if qc else 1
    u0 = min(uc, key=lambda v: uc[v]) if uc else 0
    if qc.get(q0) == 0 and uc.get(u0) == 0 and ac.get(q0 * u0) == 0:
        return [(0.0, q0, u0, q0 * u0)]
    opts = []
    for q, cq in qc.items():
        for u, cu in uc.items():
            c = cq + cu
            if c > 2.2:
                continue
            a = q * u
            ca = ac.get(a)
            if ca is None:
                ca = 3.0
            opts.append((c + ca, q, u, a))
    bestc = min([o[0] for o in opts]) if opts else 99.0
    if bestc >= 2.0:
        for q, cq in qc.items():
            if cq > 1.1:
                continue
            for a, ca in ac.items():
                if ca > 1.1 or a % q:
                    continue
                u = a // q
                if u > 0:
                    opts.append((cq + ca + 2.5, q, u, a))
        for u, cu in uc.items():
            if cu > 1.1:
                continue
            for a, ca in ac.items():
                if ca > 1.1 or a % u:
                    continue
                q = a // u
                if 1 <= q <= 500:
                    opts.append((cu + ca + 2.5, q, u, a))
    if not opts:
        return [(9.0, q0, u0, q0 * u0)]
    opts.sort(key=lambda o: o[0])
    bc = opts[0][0]
    res = []
    seen = set()
    for o in opts:
        if o[0] > bc + 2.1:
            break
        key = (o[1], o[2])
        if key in seen:
            continue
        seen.add(key)
        res.append(o)
        if len(res) >= 25:
            break
    return res


def solve(state, params):
    t0 = time.process_time()
    doc = state.get('doc', {})
    cols = doc.get('cols', ['CODE', 'QTY', 'UNIT', 'AMOUNT'])
    items = []
    for sec in doc.get('sections', []):
        rows = align(sec['tokens'], cols)
        sec_items = []
        sec_opts = []
        for r in rows:
            d = dict(zip(cols, r))
            code = fix_code(d['CODE'])
            if time.process_time() - t0 > 0.7:
                qc = qty_cands(d['QTY'])
                uc = money_cands(d['UNIT'])
                q = min(qc, key=lambda v: qc[v])
                u = min(uc, key=lambda v: uc[v]) if uc else 0
                opts = [(0.0, q, u, q * u)]
            else:
                opts = solve_row(r, cols)
            sec_items.append(code)
            sec_opts.append(opts)
        choice = [0] * len(sec_opts)
        if sec.get('subtotal') and sec_opts:
            sc = money_cands(sec['subtotal'])
            base = sum(o[0][3] for o in sec_opts)
            cur_cost = sc.get(base, 2.5)
            bestimp = (cur_cost, -1, 0)
            if cur_cost > 0:
                for ri, opts in enumerate(sec_opts):
                    for oi in range(1, len(opts)):
                        ns = base - opts[0][3] + opts[oi][3]
                        if ns in sc:
                            c = sc[ns] + (opts[oi][0] - opts[0][0])
                            if c < bestimp[0] - 1e-9:
                                bestimp = (c, ri, oi)
                if bestimp[1] >= 0:
                    choice[bestimp[1]] = bestimp[2]
        for code, opts, ci in zip(sec_items, sec_opts, choice):
            o = opts[ci]
            items.append({'code': code, 'qty': int(o[1]), 'unit_cents': int(o[2])})
    state['output'] = {'items': items}
    return state

import re
import time

LOOK_D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6', 'D': '0', 'Q': '0'}
LOOK_L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G', '4': 'A', '7': 'T', '3': 'E'}
MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63', '6': '50', '7': '12', '8': '30', '9': '43'}
INF = float('inf')


def _rev():
    r = {}
    for o, shown in MIS.items():
        for s in shown:
            r.setdefault(s, []).append(o)
    return r


REV = _rev()


def to_digits(s):
    out = []
    for ch in s:
        if ch.isdigit():
            out.append(ch)
        elif ch in LOOK_D:
            out.append(LOOK_D[ch])
    return ''.join(out)


def code_check(letters, d):
    p1 = ord(letters[0]) - 64
    p2 = ord(letters[1]) - 64
    return (int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p1 + p2) % 10


def code_valid(letters, d):
    return len(d) == 5 and d.isdigit() and code_check(letters, d) == int(d[4])


def fix_code(tok):
    t = re.sub(r'\s+', '', tok)
    letters = ''
    i = 0
    while len(letters) < 2 and i < len(t):
        ch = t[i]
        if ch.isalpha():
            letters += ch.upper()
        elif ch in LOOK_L:
            letters += LOOK_L[ch]
        i += 1
    while len(letters) < 2:
        letters += 'A'
    if not ('A' <= letters[0] <= 'Z' and 'A' <= letters[1] <= 'Z'):
        letters = 'AA'
    d = to_digits(t[i:])
    if len(d) == 5 and code_valid(letters, d):
        return letters + d
    cands = []
    if len(d) == 5:
        for k in range(5):
            for r in REV.get(d[k], []):
                nd = d[:k] + r + d[k + 1:]
                if code_valid(letters, nd):
                    cands.append(nd)
        if cands:
            return letters + cands[0]
        return letters + d[:4] + str(code_check(letters, d[:4]))
    if len(d) == 6:
        for k in range(6):
            if (k > 0 and d[k] == d[k - 1]) or (k < 5 and d[k] == d[k + 1]):
                nd = d[:k] + d[k + 1:]
                if code_valid(letters, nd) and nd not in cands:
                    cands.append(nd)
        if not cands:
            for k in range(6):
                nd = d[:k] + d[k + 1:]
                if code_valid(letters, nd):
                    cands.append(nd)
        if cands:
            return letters + cands[0]
        nd = d[:5]
        return letters + nd[:4] + str(code_check(letters, nd[:4]))
    if len(d) == 4:
        for k in range(5):
            for c in '0123456789':
                nd = d[:k] + c + d[k:]
                if code_valid(letters, nd):
                    cands.append(nd)
        if cands:
            return letters + cands[0]
        return letters + d + str(code_check(letters, d))
    if len(d) > 6:
        d = d[:5]
        return letters + d[:4] + str(code_check(letters, d[:4]))
    d = (d + '0000')[:4]
    return letters + d + str(code_check(letters, d))


def edits(ds, ins_lo, ins_hi, del_lo, del_hi):
    yield ds, 0.0
    n = len(ds)
    for k in range(n):
        for r in REV.get(ds[k], []):
            yield ds[:k] + r + ds[k + 1:], 1.0
    for k in range(max(0, del_lo), min(n, del_hi)):
        if (k > 0 and ds[k] == ds[k - 1]) or (k < n - 1 and ds[k] == ds[k + 1]):
            yield ds[:k] + ds[k + 1:], 1.0
    for k in range(max(0, ins_lo), min(n, ins_hi) + 1):
        for c in '0123456789':
            yield ds[:k] + c + ds[k:], 1.05


def money_cands(tok):
    s = (tok or '').strip()
    s2 = ''
    for ch in s:
        if ch.isdigit() or ch in '.,':
            s2 += ch
        elif ch in LOOK_D:
            s2 += LOOK_D[ch]
    m = re.match(r'^(\d*)[.,](\d*)$', s2)
    if m:
        ip, fp = m.group(1), m.group(2)
        ds = ip + fp
        ni = len(ip)
        if len(fp) == 2:
            il, ih, dl, dh = 0, ni, 0, ni
        elif len(fp) == 1:
            il, ih, dl, dh = ni, len(ds), 0, 0
        elif len(fp) == 3:
            il, ih, dl, dh = 0, -1, ni, len(ds)
        else:
            il, ih, dl, dh = 0, len(ds), 0, len(ds)
    else:
        ds = re.sub(r'\D', '', s2)
        il, ih, dl, dh = 0, len(ds), 0, len(ds)
    out = {}
    for cand, c in edits(ds, il, ih, dl, dh):
        if not cand:
            continue
        v = int(cand)
        if v <= 0:
            continue
        if v not in out or out[v] > c:
            out[v] = c
    return out


def qty_cands(tok):
    s = re.sub(r'(?i)p\s*c\s*s', '', tok or '').strip()
    ds = to_digits(s)
    out = {}
    if not ds:
        for v in range(1, 10):
            out[v] = 1.0
        return out
    for cand, c in edits(ds, 0, len(ds), 0, len(ds)):
        if not cand:
            continue
        v = int(cand)
        if 1 <= v <= 500 and (v not in out or out[v] > c):
            out[v] = c
    if not out:
        out[max(1, min(500, int(ds[:3])))] = 2.0
    return out


def tok_type_cost(tok, col):
    t = tok.strip()
    if col == 'CODE':
        if re.match(r'^[A-Z0-9]{2}[0-9OlSBZGI]{4,6}$', t):
            return 0.0
        if re.match(r'^[A-Za-z0-9]{6,9}$', t):
            return 1.0
        if re.match(r'^[A-Za-z0-9]{4,5}$', t) and re.match(r'^[A-Z]', t):
            return 1.5
        return 3.0
    if col == 'QTY':
        if re.match(r'^[0-9OlSBZG]{0,4}( ?pcs)?$', t):
            return 0.0 if '.' not in t and ',' not in t else 2.0
        return 3.0
    if re.match(r"^[0-9OlSBZG']*[.,][0-9OlSBZG]{1,3}$", t):
        return 0.0
    if re.match(r"^[0-9OlSBZG']{2,}$", t):
        if re.match(r'^[A-Z]{2}', t):
            return 3.0
        return 0.6
    return 3.0


def looks_value(tok):
    t = tok.strip()
    if t == '':
        return True
    t = re.sub(r'\s*pcs$', '', t)
    if t == '':
        return True
    if not re.match(r"^[A-Za-z0-9.,']+$", t):
        return False
    if len(t) > 14:
        return False
    good = sum(1 for ch in t if ch.isdigit() or ch in LOOK_D or ch in ".,'")
    return good >= len(t) - 2 and good >= 1


def split_line(line, sep):
    if sep == '|':
        parts = line.split('|')
    elif sep == ';':
        parts = line.split(';')
    elif sep == '\t':
        parts = line.split('\t')
    else:
        parts = re.split(r' {3}', line.rstrip('\n'))
    parts = [p.strip() for p in parts]
    while parts and parts[-1] == '':
        parts.pop()
    while parts and parts[0] == '':
        parts.pop(0)
    return parts


def parse_doc(state, params):
    text = state.get('input', {}).get('text', '') or ''
    lines = text.split('\n')
    cols = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    sep = ';'
    for ln in lines:
        if 'COLUMNS' in ln:
            body = ln.split('COLUMNS', 1)[1]
            body = body[1:] if body.startswith(':') else body
            pos = []
            for c in ['CODE', 'QTY', 'UNIT', 'AMOUNT']:
                pos.append((body.find(c), c))
            if all(p >= 0 for p, _ in pos):
                cols = [c for _, c in sorted(pos)]
            inner = body.strip()
            if '|' in inner:
                sep = '|'
            elif ';' in inner:
                sep = ';'
            elif '\t' in inner:
                sep = '\t'
            else:
                sep = '   '
            break
    sections = []
    cur = None
    total = None
    items_n = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if re.match(r'^=+\s*SECTION', s):
            cur = {'tokens': [], 'subtotal': None}
            sections.append(cur)
            continue
        if s.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'tokens': [], 'subtotal': None}
                sections.append(cur)
            cur['subtotal'] = s[len('SUBTOTAL'):].strip()
            continue
        if s.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s+(.*?)\s+ITEMS\s*(.*)$', s)
            if m:
                total = m.group(1)
                items_n = m.group(2)
            continue
        parts = split_line(ln.replace('\r', ''), sep)
        if not parts:
            continue
        suspect = not all(looks_value(p) for p in parts)
        if cur is None:
            cur = {'tokens': [], 'subtotal': None}
            sections.append(cur)
        for p in parts:
            cur['tokens'].append([p, bool(suspect or not looks_value(p))])
    state['doc'] = {'cols': cols, 'sections': sections, 'total': total, 'items_n': items_n}
    return state


def align_dp(toks, cols):
    n = len(toks)
    R = n // 3 + 2
    tc = [[tok_type_cost(t, c) for c in cols] for t, _ in toks]
    sk = [0.3 if s else 4.0 for _, s in toks]
    r4 = [None] * n
    r3 = [None] * n
    for i in range(n):
        if i + 4 <= n:
            r4[i] = sum(tc[i + k][k] for k in range(4))
        if i + 3 <= n:
            bm = None
            for miss in range(4):
                c = 3.5
                k2 = 0
                for k in range(4):
                    if k == miss:
                        continue
                    c += tc[i + k2][k]
                    k2 += 1
                if bm is None or c < bm[0]:
                    bm = (c, miss)
            r3[i] = bm
    best = [[INF] * (R + 1) for _ in range(n + 1)]
    back = [[None] * (R + 1) for _ in range(n + 1)]
    best[0][0] = 0.0
    for i in range(n):
        bi = best[i]
        for r in range(R + 1):
            b = bi[r]
            if b == INF:
                continue
            c = b + sk[i]
            if c < best[i + 1][r]:
                best[i + 1][r] = c
                back[i + 1][r] = ('skip', i, -1)
            if r < R:
                if r4[i] is not None:
                    c = b + r4[i]
                    if c < best[i + 4][r + 1]:
                        best[i + 4][r + 1] = c
                        back[i + 4][r + 1] = ('row', i, -1)
                if r3[i] is not None:
                    c = b + r3[i][0]
                    if c < best[i + 3][r + 1]:
                        best[i + 3][r + 1] = c
                        back[i + 3][r + 1] = ('row3', i, r3[i][1])
    return best[n], back


def reconstruct(toks, back, n, r):
    rows = []
    j = n
    rr = r
    while j > 0:
        bk = back[j][rr]
        if bk is None:
            break
        i = bk[1]
        if bk[0] == 'skip':
            j = i
            continue
        if bk[0] == 'row':
            rows.append([t for t, _ in toks[i:i + 4]])
        else:
            seg = [t for t, _ in toks[i:i + 3]]
            seg.insert(bk[2], '')
            rows.append(seg)
        j = i
        rr -= 1
    rows.reverse()
    return rows


def items_cands(s):
    out = {}
    if not s:
        return None, out
    ds = to_digits(s.strip())
    if not ds:
        return None, out
    raw = int(ds) if re.match(r'^\d+$', s.strip()) else None
    for cand, c in edits(ds, 0, len(ds), 0, len(ds)):
        if not cand:
            continue
        v = int(cand)
        if 1 <= v <= 80:
            if v not in out or out[v] > c:
                out[v] = c
    if raw is None:
        v = int(ds)
        if 1 <= v <= 80:
            out[v] = 0.5
    return raw, out


def solve_row(fields, cols):
    d = dict(zip(cols, fields))
    qc = qty_cands(d['QTY'])
    uc = money_cands(d['UNIT'])
    ac = money_cands(d['AMOUNT'])
    q0 = min(qc, key=lambda v: qc[v]) if qc else 1
    u0 = min(uc, key=lambda v: uc[v]) if uc else 0
    if qc.get(q0) == 0 and uc.get(u0) == 0 and ac.get(q0 * u0) == 0:
        return [(0.0, q0, u0, q0 * u0)]
    opts = []
    for q, cq in qc.items():
        for u, cu in uc.items():
            c = cq + cu
            if c > 2.2:
                continue
            a = q * u
            ca = ac.get(a)
            if ca is None:
                ca = 3.0
            opts.append((c + ca, q, u, a))
    bestc = min([o[0] for o in opts]) if opts else 99.0
    if bestc >= 2.0:
        for q, cq in qc.items():
            if cq > 1.1:
                continue
            for a, ca in ac.items():
                if ca > 1.1 or a % q:
                    continue
                u = a // q
                if u > 0:
                    opts.append((cq + ca + 2.5, q, u, a))
        for u, cu in uc.items():
            if cu > 1.1:
                continue
            for a, ca in ac.items():
                if ca > 1.1 or a % u:
                    continue
                q = a // u
                if 1 <= q <= 500:
                    opts.append((cu + ca + 2.5, q, u, a))
    if not opts:
        return [(9.0, q0, u0, q0 * u0)]
    opts.sort(key=lambda o: o[0])
    bc = opts[0][0]
    res = []
    seen = set()
    for o in opts:
        if o[0] > bc + 2.1:
            break
        key = (o[1], o[2])
        if key in seen:
            continue
        seen.add(key)
        res.append(o)
        if len(res) >= 25:
            break
    return res


def subtotal_choice(sec_opts, sub):
    choice = [0] * len(sec_opts)
    if not sub or not sec_opts:
        return choice
    sc = money_cands(sub)
    if not sc:
        return choice
    base = sum(o[0][3] for o in sec_opts)
    cur_cost = sc.get(base, 2.5)
    if cur_cost == 0:
        return choice
    changes = []
    for ri, opts in enumerate(sec_opts):
        for oi in range(1, len(opts)):
            dc = opts[oi][0] - opts[0][0]
            if dc > 2.5:
                continue
            changes.append((opts[oi][3] - opts[0][3], dc, ri, oi))
    best = (cur_cost, [])
    by_delta = {}
    for ch in changes:
        dl = ch[0]
        if dl not in by_delta or by_delta[dl][1] > ch[1]:
            by_delta[dl] = ch
        ns = base + dl
        if ns in sc:
            c = sc[ns] + ch[1]
            if c < best[0] - 1e-9:
                best = (c, [ch])
    if len(changes) <= 3000:
        for target, tcst in sc.items():
            need = target - base
            for ch in changes:
                other = by_delta.get(need - ch[0])
                if other is None or other[2] == ch[2]:
                    continue
                c = tcst + ch[1] + other[1] + 0.5
                if c < best[0] - 1e-9:
                    best = (c, [ch, other])
    for ch in best[1]:
        choice[ch[2]] = ch[3]
    return choice


def solve(state, params):
    t0 = time.process_time()
    doc = state.get('doc', {})
    cols = doc.get('cols', ['CODE', 'QTY', 'UNIT', 'AMOUNT'])
    secs = doc.get('sections', [])
    dps = []
    for sec in secs:
        costs, back = align_dp(sec['tokens'], cols)
        dps.append((costs, back))
    # knapsack over sections: total rows -> (cost, choices)
    tot = {0: (0.0, [])}
    for costs, _ in dps:
        nt = {}
        for k, (c, ch) in tot.items():
            for r, cr in enumerate(costs):
                if cr == INF:
                    continue
                v = c + cr
                kk = k + r
                if kk not in nt or nt[kk][0] > v:
                    nt[kk] = (v, ch + [r])
        tot = nt
    raw, ic = items_cands(doc.get('items_n'))
    bestk = None
    bests = INF
    for k, (c, ch) in tot.items():
        if raw is not None and k == raw:
            pen = 0.0
        elif k in ic:
            pen = 2.5 + ic[k] * 0.0
        else:
            pen = 6.0
        s = c + pen
        if s < bests - 1e-9:
            bests = s
            bestk = k
    if bestk is None:
        rcounts = [0] * len(secs)
    else:
        rcounts = tot[bestk][1]
    items = []
    for si, sec in enumerate(secs):
        toks = sec['tokens']
        rows = reconstruct(toks, dps[si][1], len(toks), rcounts[si]) if rcounts else []
        sec_codes = []
        sec_opts = []
        for r in rows:
            d = dict(zip(cols, r))
            code = fix_code(d['CODE'])
            if time.process_time() - t0 > 0.7:
                qc = qty_cands(d['QTY'])
                uc = money_cands(d['UNIT'])
                q = min(qc, key=lambda v: qc[v])
                u = min(uc, key=lambda v: uc[v]) if uc else 0
                opts = [(0.0, q, u, q * u)]
            else:
                opts = solve_row(r, cols)
            sec_codes.append(code)
            sec_opts.append(opts)
        if time.process_time() - t0 < 0.8:
            choice = subtotal_choice(sec_opts, sec.get('subtotal'))
        else:
            choice = [0] * len(sec_opts)
        for code, opts, ci in zip(sec_codes, sec_opts, choice):
            o = opts[ci]
            items.append({'code': code, 'qty': int(o[1]), 'unit_cents': int(o[2])})
    state['output'] = {'items': items}
    return state

import re
import time

LOOK_D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6', 'D': '0', 'Q': '0'}
LOOK_L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G', '4': 'A', '7': 'T', '3': 'E'}
MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63', '6': '50', '7': '12', '8': '30', '9': '43'}
INF = float('inf')


def _rev():
    r = {}
    for o, shown in MIS.items():
        for s in shown:
            r.setdefault(s, []).append(o)
    return r


REV = _rev()


def to_digits(s):
    out = []
    for ch in s:
        if ch.isdigit():
            out.append(ch)
        elif ch in LOOK_D:
            out.append(LOOK_D[ch])
    return ''.join(out)


def code_check(letters, d):
    p1 = ord(letters[0]) - 64
    p2 = ord(letters[1]) - 64
    return (int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p1 + p2) % 10


def code_valid(letters, d):
    return len(d) == 5 and d.isdigit() and code_check(letters, d) == int(d[4])


def _best(res):
    if not res:
        return None
    return max(res, key=lambda k: res[k])


def _misread_cands(letters, d, res, w=1.0):
    for k in range(len(d)):
        for o in REV.get(d[k], []):
            nd = d[:k] + o + d[k + 1:]
            if code_valid(letters, nd):
                res[nd] = res.get(nd, 0.0) + w / len(MIS[o])
    return res


def _dup_dels(d):
    out = []
    for k in range(1, len(d)):
        if d[k] == d[k - 1]:
            nd = d[:k] + d[k + 1:]
            if nd not in out:
                out.append(nd)
    return out


def _ins_cands(letters, d, res, w=1.0):
    for k in range(len(d) + 1):
        for c in '0123456789':
            nd = d[:k] + c + d[k:]
            if code_valid(letters, nd):
                res[nd] = res.get(nd, 0.0) + w
    return res


def _fallback(letters, d):
    d = (d + '0000')[:4]
    return letters + d + str(code_check(letters, d))


def fix_code(tok):
    t = re.sub(r'\s+', '', tok or '')
    letters = ''
    i = 0
    while len(letters) < 2 and i < len(t):
        ch = t[i]
        if ch.isalpha():
            letters += ch.upper()
        elif ch in LOOK_L:
            letters += LOOK_L[ch]
        i += 1
    while len(letters) < 2:
        letters += 'A'
    if not ('A' <= letters[0] <= 'Z' and 'A' <= letters[1] <= 'Z'):
        letters = 'AA'
    d = to_digits(t[i:])
    n = len(d)
    if n == 5:
        if code_valid(letters, d):
            return letters + d
        b = _best(_misread_cands(letters, d, {}))
        if b:
            return letters + b
        return _fallback(letters, d)
    if n == 6:
        res = {}
        for nd in _dup_dels(d):
            if code_valid(letters, nd):
                res[nd] = res.get(nd, 0.0) + 1.0
        b = _best(res)
        if b:
            return letters + b
        res = {}
        for nd in _dup_dels(d):
            _misread_cands(letters, nd, res, 0.3)
        for k in range(6):
            nd = d[:k] + d[k + 1:]
            if code_valid(letters, nd):
                res[nd] = res.get(nd, 0.0) + 0.2
        b = _best(res)
        if b:
            return letters + b
        return _fallback(letters, d[:5])
    if n == 4:
        b = _best(_ins_cands(letters, d, {}))
        if b:
            return letters + b
        return _fallback(letters, d)
    if n == 7:
        res = {}
        for a in _dup_dels(d):
            for nd in _dup_dels(a):
                if code_valid(letters, nd):
                    res[nd] = res.get(nd, 0.0) + 1.0
        b = _best(res)
        if b:
            return letters + b
        return _fallback(letters, d[:5])
    if n == 3:
        res = {}
        for k in range(4):
            for c in '0123456789':
                _ins_cands(letters, d[:k] + c + d[k:], res)
        b = _best(res)
        if b:
            return letters + b
        return _fallback(letters, d)
    if n > 7:
        return _fallback(letters, d[:5])
    return _fallback(letters, d)


def edits(ds, ins_lo, ins_hi, del_lo, del_hi):
    yield ds, 0.0
    n = len(ds)
    for k in range(n):
        for r in REV.get(ds[k], []):
            yield ds[:k] + r + ds[k + 1:], 1.0 + 0.02 * (len(MIS[r]) - 1)
    for k in range(max(0, del_lo), min(n, del_hi)):
        if (k > 0 and ds[k] == ds[k - 1]) or (k < n - 1 and ds[k] == ds[k + 1]):
            yield ds[:k] + ds[k + 1:], 1.0
    for k in range(max(0, ins_lo), min(n, ins_hi) + 1):
        for c in '0123456789':
            yield ds[:k] + c + ds[k:], 1.05


def money_cands(tok):
    s = (tok or '').strip()
    s2 = ''
    for ch in s:
        if ch.isdigit() or ch in '.,':
            s2 += ch
        elif ch in LOOK_D:
            s2 += LOOK_D[ch]
    m = re.match(r'^(\d*)[.,](\d*)$', s2)
    if m:
        ip, fp = m.group(1), m.group(2)
        ds = ip + fp
        ni = len(ip)
        if len(fp) == 2:
            il, ih, dl, dh = 0, ni, 0, ni
        elif len(fp) == 1:
            il, ih, dl, dh = ni, len(ds), 0, 0
        elif len(fp) == 3:
            il, ih, dl, dh = 0, -1, ni, len(ds)
        else:
            il, ih, dl, dh = 0, len(ds), 0, len(ds)
    else:
        ds = re.sub(r'\D', '', s2)
        il, ih, dl, dh = 0, len(ds), 0, len(ds)
    out = {}
    for cand, c in edits(ds, il, ih, dl, dh):
        if not cand:
            continue
        v = int(cand)
        if v <= 0:
            continue
        if v not in out or out[v] > c:
            out[v] = c
    return out


def qty_cands(tok):
    s = re.sub(r'(?i)p\s*c\s*s', '', tok or '').strip()
    ds = to_digits(s)
    out = {}
    if not ds:
        for v in range(1, 10):
            out[v] = 1.0
        return out
    for cand, c in edits(ds, 0, len(ds), 0, len(ds)):
        if not cand:
            continue
        v = int(cand)
        if 1 <= v <= 500 and (v not in out or out[v] > c):
            out[v] = c
    if not out:
        out[max(1, min(500, int(ds[:3])))] = 2.0
    return out


def tok_type_cost(tok, col):
    t = tok.strip()
    if col == 'CODE':
        if re.match(r'^[A-Z0-9]{2}[0-9OlSBZGI]{4,6}$', t):
            return 0.0
        if re.match(r'^[A-Za-z0-9]{6,9}$', t):
            return 1.0
        if re.match(r'^[A-Za-z0-9]{4,5}$', t) and re.match(r'^[A-Z]', t):
            return 1.5
        return 3.0
    if col == 'QTY':
        if re.match(r'^[0-9OlSBZG]{0,4}( ?pcs)?$', t):
            return 0.0 if '.' not in t and ',' not in t else 2.0
        return 3.0
    if re.match(r"^[0-9OlSBZG']*[.,][0-9OlSBZG]{1,3}$", t):
        return 0.0
    if re.match(r"^[0-9OlSBZG']{2,}$", t):
        if re.match(r'^[A-Z]{2}', t):
            return 3.0
        return 0.6
    return 3.0


def looks_value(tok):
    t = tok.strip()
    if t == '':
        return True
    t = re.sub(r'\s*pcs$', '', t)
    if t == '':
        return True
    if not re.match(r"^[A-Za-z0-9.,']+$", t):
        return False
    if len(t) > 14:
        return False
    good = sum(1 for ch in t if ch.isdigit() or ch in LOOK_D or ch in ".,'")
    return good >= len(t) - 2 and good >= 1


def split_line(line, sep):
    if sep == '|':
        parts = line.split('|')
    elif sep == ';':
        parts = line.split(';')
    elif sep == '\t':
        parts = line.split('\t')
    else:
        parts = re.split(r' {3}', line.rstrip('\n'))
    parts = [p.strip() for p in parts]
    while parts and parts[-1] == '':
        parts.pop()
    while parts and parts[0] == '':
        parts.pop(0)
    return parts


def parse_doc(state, params):
    text = state.get('input', {}).get('text', '') or ''
    lines = text.split('\n')
    cols = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    sep = ';'
    for ln in lines:
        if 'COLUMNS' in ln:
            body = ln.split('COLUMNS', 1)[1]
            body = body[1:] if body.startswith(':') else body
            pos = []
            for c in ['CODE', 'QTY', 'UNIT', 'AMOUNT']:
                pos.append((body.find(c), c))
            if all(p >= 0 for p, _ in pos):
                cols = [c for _, c in sorted(pos)]
            inner = body.strip()
            if '|' in inner:
                sep = '|'
            elif ';' in inner:
                sep = ';'
            elif '\t' in inner:
                sep = '\t'
            else:
                sep = '   '
            break
    sections = []
    cur = None
    total = None
    items_n = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if re.match(r'^=+\s*SECTION', s):
            cur = {'tokens': [], 'subtotal': None}
            sections.append(cur)
            continue
        if s.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'tokens': [], 'subtotal': None}
                sections.append(cur)
            cur['subtotal'] = s[len('SUBTOTAL'):].strip()
            continue
        if s.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s+(.*?)\s+ITEMS\s*(.*)$', s)
            if m:
                total = m.group(1)
                items_n = m.group(2)
            continue
        parts = split_line(ln.replace('\r', ''), sep)
        if not parts:
            continue
        suspect = not all(looks_value(p) for p in parts)
        if cur is None:
            cur = {'tokens': [], 'subtotal': None}
            sections.append(cur)
        for p in parts:
            cur['tokens'].append([p, bool(suspect or not looks_value(p))])
    state['doc'] = {'cols': cols, 'sections': sections, 'total': total, 'items_n': items_n}
    return state


def align_dp(toks, cols):
    n = len(toks)
    R = n // 3 + 2
    tc = [[tok_type_cost(t, c) for c in cols] for t, _ in toks]
    sk = [0.3 if s else 4.0 for _, s in toks]
    r4 = [None] * n
    r3 = [None] * n
    for i in range(n):
        if i + 4 <= n:
            r4[i] = sum(tc[i + k][k] for k in range(4))
        if i + 3 <= n:
            bm = None
            for miss in range(4):
                c = 3.5
                k2 = 0
                for k in range(4):
                    if k == miss:
                        continue
                    c += tc[i + k2][k]
                    k2 += 1
                if bm is None or c < bm[0]:
                    bm = (c, miss)
            r3[i] = bm
    best = [[INF] * (R + 1) for _ in range(n + 1)]
    back = [[None] * (R + 1) for _ in range(n + 1)]
    best[0][0] = 0.0
    for i in range(n):
        bi = best[i]
        for r in range(R + 1):
            b = bi[r]
            if b == INF:
                continue
            c = b + sk[i]
            if c < best[i + 1][r]:
                best[i + 1][r] = c
                back[i + 1][r] = ('skip', i, -1)
            if r < R:
                if r4[i] is not None:
                    c = b + r4[i]
                    if c < best[i + 4][r + 1]:
                        best[i + 4][r + 1] = c
                        back[i + 4][r + 1] = ('row', i, -1)
                if r3[i] is not None:
                    c = b + r3[i][0]
                    if c < best[i + 3][r + 1]:
                        best[i + 3][r + 1] = c
                        back[i + 3][r + 1] = ('row3', i, r3[i][1])
    return best[n], back


def reconstruct(toks, back, n, r):
    rows = []
    j = n
    rr = r
    while j > 0:
        bk = back[j][rr]
        if bk is None:
            break
        i = bk[1]
        if bk[0] == 'skip':
            j = i
            continue
        if bk[0] == 'row':
            rows.append([t for t, _ in toks[i:i + 4]])
        else:
            seg = [t for t, _ in toks[i:i + 3]]
            seg.insert(bk[2], '')
            rows.append(seg)
        j = i
        rr -= 1
    rows.reverse()
    return rows


def items_cands(s):
    out = {}
    if not s:
        return None, out
    ds = to_digits(s.strip())
    if not ds:
        return None, out
    raw = int(ds) if re.match(r'^\d+$', s.strip()) else None
    for cand, c in edits(ds, 0, len(ds), 0, len(ds)):
        if not cand:
            continue
        v = int(cand)
        if 1 <= v <= 80:
            if v not in out or out[v] > c:
                out[v] = c
    if raw is None:
        v = int(ds)
        if 1 <= v <= 80:
            out[v] = 0.5
    return raw, out


def solve_row(fields, cols):
    d = dict(zip(cols, fields))
    qc = qty_cands(d['QTY'])
    uc = money_cands(d['UNIT'])
    ac = money_cands(d['AMOUNT'])
    q0 = min(qc, key=lambda v: qc[v]) if qc else 1
    u0 = min(uc, key=lambda v: uc[v]) if uc else 0
    if qc.get(q0) == 0 and uc.get(u0) == 0 and ac.get(q0 * u0) == 0:
        return [(0.0, q0, u0, q0 * u0)]
    opts = []
    for q, cq in qc.items():
        for u, cu in uc.items():
            c = cq + cu
            if c > 2.2:
                continue
            a = q * u
            ca = ac.get(a)
            if ca is None:
                ca = 3.0
            opts.append((c + ca, q, u, a))
    bestc = min([o[0] for o in opts]) if opts else 99.0
    if bestc >= 2.0:
        for q, cq in qc.items():
            if cq > 1.1:
                continue
            for a, ca in ac.items():
                if ca > 1.1 or a % q:
                    continue
                u = a // q
                if u > 0:
                    opts.append((cq + ca + 2.5, q, u, a))
        for u, cu in uc.items():
            if cu > 1.1:
                continue
            for a, ca in ac.items():
                if ca > 1.1 or a % u:
                    continue
                q = a // u
                if 1 <= q <= 500:
                    opts.append((cu + ca + 2.5, q, u, a))
    if not opts:
        return [(9.0, q0, u0, q0 * u0)]
    opts.sort(key=lambda o: o[0])
    bc = opts[0][0]
    res = []
    seen = set()
    for o in opts:
        if o[0] > bc + 2.1:
            break
        key = (o[1], o[2])
        if key in seen:
            continue
        seen.add(key)
        res.append(o)
        if len(res) >= 25:
            break
    return res


def subtotal_choice(sec_opts, sc):
    choice = [0] * len(sec_opts)
    if not sc or not sec_opts:
        return choice
    base = sum(o[0][3] for o in sec_opts)
    cur_cost = sc.get(base, 2.5)
    if cur_cost == 0:
        return choice
    changes = []
    for ri, opts in enumerate(sec_opts):
        for oi in range(1, len(opts)):
            dc = opts[oi][0] - opts[0][0]
            if dc > 2.5:
                continue
            changes.append((opts[oi][3] - opts[0][3], dc, ri, oi))
    best = (cur_cost, [])
    by_delta = {}
    for ch in changes:
        dl = ch[0]
        if dl not in by_delta or by_delta[dl][1] > ch[1]:
            by_delta[dl] = ch
        ns = base + dl
        if ns in sc:
            c = sc[ns] + ch[1]
            if c < best[0] - 1e-9:
                best = (c, [ch])
    if len(changes) <= 3000:
        for target, tcst in sc.items():
            need = target - base
            for ch in changes:
                other = by_delta.get(need - ch[0])
                if other is None or other[2] == ch[2]:
                    continue
                c = tcst + ch[1] + other[1] + 0.5
                if c < best[0] - 1e-9:
                    best = (c, [ch, other])
    for ch in best[1]:
        choice[ch[2]] = ch[3]
    return choice


def solve(state, params):
    t0 = time.process_time()
    doc = state.get('doc', {})
    cols = doc.get('cols', ['CODE', 'QTY', 'UNIT', 'AMOUNT'])
    secs = doc.get('sections', [])
    dps = []
    for sec in secs:
        costs, back = align_dp(sec['tokens'], cols)
        dps.append((costs, back))
    tot = {0: (0.0, [])}
    for costs, _ in dps:
        nt = {}
        for k, (c, ch) in tot.items():
            for r, cr in enumerate(costs):
                if cr == INF:
                    continue
                v = c + cr
                kk = k + r
                if kk not in nt or nt[kk][0] > v:
                    nt[kk] = (v, ch + [r])
        tot = nt
    raw, ic = items_cands(doc.get('items_n'))
    bestk = None
    bests = INF
    for k, (c, ch) in tot.items():
        if raw is not None and k == raw:
            pen = 0.0
        elif k in ic:
            pen = 2.5
        else:
            pen = 6.0
        s = c + pen
        if s < bests - 1e-9:
            bests = s
            bestk = k
    if bestk is None:
        rcounts = [0] * len(secs)
    else:
        rcounts = tot[bestk][1]
    all_codes = []
    all_opts = []
    all_sc = []
    all_choice = []
    for si, sec in enumerate(secs):
        toks = sec['tokens']
        rc = rcounts[si] if si < len(rcounts) else 0
        rows = reconstruct(toks, dps[si][1], len(toks), rc)
        sec_codes = []
        sec_opts = []
        for r in rows:
            d = dict(zip(cols, r))
            code = fix_code(d['CODE'])
            if time.process_time() - t0 > 0.7:
                qc = qty_cands(d['QTY'])
                uc = money_cands(d['UNIT'])
                q = min(qc, key=lambda v: qc[v])
                u = min(uc, key=lambda v: uc[v]) if uc else 0
                opts = [(0.0, q, u, q * u)]
            else:
                opts = solve_row(r, cols)
            sec_codes.append(code)
            sec_opts.append(opts)
        sc = money_cands(sec.get('subtotal')) if sec.get('subtotal') else {}
        if time.process_time() - t0 < 0.8:
            choice = subtotal_choice(sec_opts, sc)
        else:
            choice = [0] * len(sec_opts)
        all_codes.append(sec_codes)
        all_opts.append(sec_opts)
        all_sc.append(sc)
        all_choice.append(choice)

    # TOTAL cross-check: repair a single section whose subtotal disagrees
    try:
        if doc.get('total') and len(secs) >= 1 and time.process_time() - t0 < 0.8:
            tcands = money_cands(doc.get('total'))
            sums = []
            okc = []
            for si in range(len(secs)):
                s = sum(o[ci][3] for o, ci in zip(all_opts[si], all_choice[si]))
                sums.append(s)
                c = all_sc[si].get(s)
                okc.append(c)
            bad = [si for si in range(len(secs)) if okc[si] is None or okc[si] > 0]
            if len(bad) == 1:
                si = bad[0]
                others_ok = all(okc[j] is not None and okc[j] <= 1.1 for j in range(len(secs)) if j != si)
                if others_ok and all_opts[si]:
                    rest = sum(sums[j] for j in range(len(secs)) if j != si)
                    aug = dict(all_sc[si])
                    for T, c in tcands.items():
                        v = T - rest
                        if v <= 0:
                            continue
                        cc = c + 0.8
                        if v not in aug or aug[v] > cc:
                            aug[v] = cc
                    all_choice[si] = subtotal_choice(all_opts[si], aug)
    except Exception:
        pass

    items = []
    for si in range(len(all_opts)):
        for code, opts, ci in zip(all_codes[si], all_opts[si], all_choice[si]):
            o = opts[ci]
            items.append({'code': code, 'qty': int(o[1]), 'unit_cents': int(o[2])})
    state['output'] = {'items': items}
    return state

import re
import time
import math

LOOK_D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6', 'D': '0', 'Q': '0'}
LOOK_L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
LOOK_L2 = {'4': 'A', '7': 'T', '3': 'E', '9': 'G'}
MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63', '6': '50', '7': '12', '8': '30', '9': '43'}

E_BASE = 3.0
C_MIS1 = E_BASE
C_MIS2 = E_BASE + 0.69
C_LOST = E_BASE
C_DBL = E_BASE
C_MARK = E_BASE - 0.3


def _rev():
    r = {}
    for o, shown in MIS.items():
        for s in shown:
            r.setdefault(s, []).append((o, C_MIS1 if len(shown) == 1 else C_MIS2))
    return r


REV = _rev()


def mis_cost(orig, shown):
    m = MIS.get(orig, '')
    if shown in m:
        return C_MIS1 if len(m) == 1 else C_MIS2
    return None


# ---------------------------------------------------------------- generic reverse-edit search
def neighbours(s, allow_mark):
    out = []
    n = len(s)
    for k in range(n):
        ch = s[k]
        if ch.isdigit():
            for o, c in REV.get(ch, []):
                out.append((s[:k] + o + s[k + 1:], c))
            if (k > 0 and s[k - 1] == ch) or (k < n - 1 and s[k + 1] == ch):
                out.append((s[:k] + s[k + 1:], C_DBL))
    for k in range(n + 1):
        for c in '0123456789':
            mult = 0
            if k > 0 and s[k - 1] == c:
                mult += 1
            if k < n and s[k] == c:
                mult += 1
            cost = C_LOST - (0.69 if mult >= 1 else 0.0)
            out.append((s[:k] + c + s[k:], cost))
        if allow_mark:
            out.append((s[:k] + '.' + s[k:], C_MARK))
    return out


def search(s, depth, valid_fn, allow_mark, budget_end):
    """returns dict normalized-string -> cost for valid strings within depth edits"""
    best = {s: 0.0}
    frontier = {s: 0.0}
    res = {}
    if valid_fn(s):
        res[s] = 0.0
    for d in range(depth):
        if time.process_time() > budget_end:
            break
        nf = {}
        for st, c0 in frontier.items():
            for ns, c in neighbours(st, allow_mark and '.' not in st):
                cc = c0 + c
                if ns in best and best[ns] <= cc:
                    continue
                best[ns] = cc
                nf[ns] = cc
        for ns, cc in nf.items():
            if valid_fn(ns):
                if ns not in res or res[ns] > cc:
                    res[ns] = cc
        frontier = nf
    return res


# ---------------------------------------------------------------- codes
def code_check(letters, d):
    p1 = ord(letters[0]) - 64
    p2 = ord(letters[1]) - 64
    return (int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p1 + p2) % 10


def fix_code(tok, budget_end):
    t = re.sub(r'\s+', '', tok)
    letters = ''
    i = 0
    while len(letters) < 2 and i < len(t):
        ch = t[i]
        if 'A' <= ch.upper() <= 'Z' and ch.isalpha():
            letters += ch.upper()
        elif ch in LOOK_L:
            letters += LOOK_L[ch]
        elif ch in LOOK_L2:
            letters += LOOK_L2[ch]
        i += 1
    while len(letters) < 2:
        letters += 'A'
    rest = t[i:]
    d = ''
    for ch in rest:
        if ch.isdigit():
            d += ch
        elif ch in LOOK_D:
            d += LOOK_D[ch]

    def valid(x):
        return len(x) == 5 and code_check(letters, x) == int(x[4])

    if valid(d):
        return letters + d
    depth = 1
    if abs(len(d) - 5) >= 2:
        depth = min(3, abs(len(d) - 5))
    res = search(d, depth, valid, False, budget_end)
    if not res and depth < 2:
        res = search(d, 2, valid, False, budget_end)
    if res:
        bestv = min(res.items(), key=lambda kv: (kv[1], kv[0]))
        return letters + bestv[0]
    dd = (d + '00000')[:4]
    return letters + dd + str(code_check(letters, dd))


# ---------------------------------------------------------------- money
def norm_money_obs(tok):
    out = ''
    for ch in tok.strip():
        if ch.isdigit():
            out += ch
        elif ch in '.,':
            out += '.'
        elif ch == "'":
            out += "'"
        elif ch in LOOK_D:
            out += LOOK_D[ch]
    return out


def make_money_valid(grouped):
    if grouped:
        rx = re.compile(r"^(0|[1-9]\d{0,2}('\d{3})*)\.\d\d$")
    else:
        rx = re.compile(r"^(0|[1-9]\d*)\.\d\d$")

    def f(s):
        return bool(rx.match(s)) and s != '0.00'
    return f


def money_str(v, grouped):
    ip = str(v // 100)
    fp = '%02d' % (v % 100)
    if grouped:
        parts = []
        while len(ip) > 3:
            parts.insert(0, ip[-3:])
            ip = ip[:-3]
        parts.insert(0, ip)
        ip = "'".join(parts)
    return ip + '.' + fp


def str_to_cents(s):
    s = s.replace("'", '')
    a, b = s.split('.')
    return int(a) * 100 + int(b)


def money_cands(obs, grouped, depth, budget_end):
    vf = make_money_valid(grouped)
    res = search(obs, depth, vf, True, budget_end)
    out = {}
    for s, c in res.items():
        v = str_to_cents(s)
        if v not in out or out[v] > c:
            out[v] = c
    return out


def channel_cost(orig, obs):
    """weighted alignment cost of producing obs from orig (both normalised)."""
    n = len(orig)
    m = len(obs)
    INF = 1e9
    dp = [[INF] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        row = dp[i]
        for j in range(m + 1):
            c = row[j]
            if c >= INF:
                continue
            if i < n:
                oc = orig[i]
                # lost
                lc = C_MARK if oc == '.' else (C_LOST if oc.isdigit() else 9.0)
                if c + lc < dp[i + 1][j]:
                    dp[i + 1][j] = c + lc
                if j < m:
                    sc = obs[j]
                    if sc == oc:
                        if c < dp[i + 1][j + 1]:
                            dp[i + 1][j + 1] = c
                    elif oc.isdigit() and sc.isdigit():
                        mc = mis_cost(oc, sc)
                        if mc is not None and c + mc < dp[i + 1][j + 1]:
                            dp[i + 1][j + 1] = c + mc
                    if oc.isdigit() and j + 1 < m and obs[j] == oc and obs[j + 1] == oc:
                        if c + C_DBL < dp[i + 1][j + 2]:
                            dp[i + 1][j + 2] = c + C_DBL
    return dp[n][m]


def money_cost_of(v, obs, grouped):
    if v <= 0:
        return 99.0
    s = money_str(v, grouped)
    return channel_cost(s, obs)


# ---------------------------------------------------------------- qty
def qty_obs(tok):
    s = re.sub(r'(?i)p\s*c\s*s', '', tok).strip()
    out = ''
    for ch in s:
        if ch.isdigit():
            out += ch
        elif ch in LOOK_D:
            out += LOOK_D[ch]
    return out


def qty_valid(s):
    return len(s) > 0 and s[0] != '0' and len(s) <= 3 and 1 <= int(s) <= 500


def qty_cands(obs, depth, budget_end):
    res = search(obs, depth, qty_valid, False, budget_end)
    out = {}
    for s, c in res.items():
        v = int(s)
        if v not in out or out[v] > c:
            out[v] = c
    return out


# ---------------------------------------------------------------- parsing
def tok_type_cost(tok, col):
    t = tok.strip()
    if col == 'CODE':
        if re.match(r'^[A-Z0-9]{2}[0-9OlSBZGI]{4,6}$', t):
            return 0.0
        if re.match(r'^[A-Za-z0-9]{5,10}$', t) and re.match(r'^[A-Za-z]', t):
            return 1.0
        if re.match(r'^[A-Za-z0-9]{5,10}$', t):
            return 2.0
        return 3.0
    if col == 'QTY':
        if re.match(r'^[0-9OlSBZG]{0,4}( ?pcs)?$', t):
            if t == '':
                return 1.0
            return 0.0 if '.' not in t and ',' not in t else 2.0
        return 3.0
    if t == '':
        return 3.0
    if re.match(r"^[0-9OlSBZG']*[.,][0-9OlSBZG]{1,3}$", t):
        return 0.0
    if re.match(r"^[0-9OlSBZG']{2,}$", t):
        if re.match(r'^[A-Z]{2}', t):
            return 3.0
        return 0.6
    return 3.0


def looks_value(tok):
    t = tok.strip()
    if t == '':
        return True
    t = re.sub(r'\s*pcs$', '', t)
    if t == '':
        return True
    if not re.match(r"^[A-Za-z0-9.,']+$", t):
        return False
    if len(t) > 14:
        return False
    good = sum(1 for ch in t if ch.isdigit() or ch in LOOK_D or ch in ".,'")
    return good >= len(t) - 2 and good >= 1


def split_line(line, sep):
    line = line.replace('\r', '')
    if sep == '|':
        parts = line.split('|')
    elif sep == ';':
        parts = line.split(';')
    elif sep == '\t':
        parts = line.split('\t')
    else:
        parts = re.split(r' {3}', line)
    parts = [p.strip() for p in parts]
    while parts and parts[-1] == '':
        parts.pop()
    if parts and all(p == '' for p in parts):
        return []
    return parts


def parse_doc(state, params):
    text = state.get('input', {}).get('text', '') or ''
    lines = text.split('\n')
    cols = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    sep = ';'
    for ln in lines:
        if 'COLUMNS' in ln:
            body = ln.split('COLUMNS', 1)[1]
            body = body[1:] if body.startswith(':') else body
            pos = []
            for c in ['CODE', 'QTY', 'UNIT', 'AMOUNT']:
                pos.append((body.find(c), c))
            if all(p >= 0 for p, _ in pos):
                cols = [c for _, c in sorted(pos)]
            inner = body.strip()
            if '|' in inner:
                sep = '|'
            elif ';' in inner:
                sep = ';'
            elif '\t' in inner:
                sep = '\t'
            else:
                sep = '   '
            break
    sections = []
    cur = None
    total = None
    items_n = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if re.match(r'^=+\s*SECTION', s):
            cur = {'tokens': [], 'subtotal': None}
            sections.append(cur)
            continue
        if s.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'tokens': [], 'subtotal': None}
                sections.append(cur)
            cur['subtotal'] = s[len('SUBTOTAL'):].strip()
            continue
        if s.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s+(.*?)\s+ITEMS\s*(.*)$', s)
            if m:
                total = m.group(1)
                items_n = m.group(2)
            continue
        parts = split_line(ln, sep)
        if not parts:
            continue
        if not all(looks_value(p) for p in parts):
            continue
        if cur is None:
            cur = {'tokens': [], 'subtotal': None}
            sections.append(cur)
        cur['tokens'].extend(parts)
    grouped = "'" in text
    state['doc'] = {'cols': cols, 'sections': sections, 'total': total,
                    'items_n': items_n, 'grouped': grouped}
    return state


# ---------------------------------------------------------------- alignment with row count
def align_counts(tokens, cols):
    n = len(tokens)
    INF = float('inf')
    tc = [[tok_type_cost(t, c) for c in cols] for t in tokens]
    maxr = n // 3 + 2
    best = [dict() for _ in range(n + 1)]
    best[0][0] = (0.0, None)
    for i in range(n):
        if not best[i]:
            continue
        for r, (b, _) in list(best[i].items()):
            # skip
            c = b + 4.0
            cur = best[i + 1].get(r)
            if cur is None or c < cur[0]:
                best[i + 1][r] = (c, ('skip', i, r))
            if i + 4 <= n and r + 1 <= maxr:
                c = b + tc[i][0] + tc[i + 1][1] + tc[i + 2][2] + tc[i + 3][3]
                cur = best[i + 4].get(r + 1)
                if cur is None or c < cur[0]:
                    best[i + 4][r + 1] = (c, ('row', i, r))
            if i + 3 <= n and r + 1 <= maxr:
                for miss in range(4):
                    c = b + 3.5
                    k2 = 0
                    for k in range(4):
                        if k == miss:
                            continue
                        c += tc[i + k2][k]
                        k2 += 1
                    cur = best[i + 3].get(r + 1)
                    if cur is None or c < cur[0]:
                        best[i + 3][r + 1] = (c, ('row3', i, r, miss))
    return best


def backtrack(best, tokens, r):
    n = len(tokens)
    rows = []
    j = n
    while j > 0:
        e = best[j].get(r)
        if e is None or e[1] is None:
            break
        bk = e[1]
        if bk[0] == 'skip':
            j = bk[1]
            r = bk[2]
            continue
        i = bk[1]
        if bk[0] == 'row':
            rows.append(list(tokens[i:i + 4]))
        else:
            seg = list(tokens[i:i + 3])
            seg.insert(bk[3], '')
            rows.append(seg)
        j = i
        r = bk[2]
    rows.reverse()
    return rows


# ---------------------------------------------------------------- row solving
def solve_row(d, grouped, budget_end, deep):
    qo = qty_obs(d['QTY'])
    uo = norm_money_obs(d['UNIT'])
    ao = norm_money_obs(d['AMOUNT'])
    Q = qty_cands(qo, 2, budget_end)
    U = money_cands(uo, grouped, 1, budget_end)
    A = money_cands(ao, grouped, 1, budget_end)
    opts = {}

    def add(c, q, u, a):
        key = (q, u)
        if key not in opts or opts[key][0] > c:
            opts[key] = (c, q, u, a)

    Ql = sorted(Q.items(), key=lambda kv: kv[1])
    Ul = sorted(U.items(), key=lambda kv: kv[1])
    Al = sorted(A.items(), key=lambda kv: kv[1])
    for q, cq in Ql:
        if cq > 2 * E_BASE + 1:
            continue
        for u, cu in Ul:
            a = q * u
            ca = A.get(a)
            if ca is not None:
                add(cq + cu + ca, q, u, a)
    for u, cu in Ul:
        for a, ca in Al:
            if a % u == 0:
                q = a // u
                cq = Q.get(q)
                if cq is not None:
                    add(cq + cu + ca, q, u, a)
    bestc = min([o[0] for o in opts.values()]) if opts else 99.0
    if bestc > 1.5 * E_BASE and deep and time.process_time() < budget_end:
        # deeper: u at depth 2 derived from q,a ; a at depth 2 via channel cost
        for q, cq in Ql:
            if cq > E_BASE + 1:
                continue
            for a, ca in Al:
                if a % q == 0:
                    u = a // q
                    if u not in U:
                        cu = money_cost_of(u, uo, grouped)
                        if cu < 2 * E_BASE + 2:
                            add(cq + cu + ca, q, u, a)
        for q, cq in Ql:
            if cq > E_BASE + 1:
                continue
            for u, cu in Ul:
                if cq + cu > E_BASE + 1:
                    continue
                a = q * u
                if a not in A:
                    ca = money_cost_of(a, ao, grouped)
                    if ca < 2 * E_BASE + 2:
                        add(cq + cu + ca, q, u, a)
        if time.process_time() < budget_end:
            U2 = money_cands(uo, grouped, 2, budget_end)
            for u, cu in U2.items():
                if cu < E_BASE * 1.5:
                    continue
                for q, cq in Ql:
                    if cq > E_BASE + 1:
                        continue
                    a = q * u
                    ca = A.get(a)
                    if ca is not None:
                        add(cq + cu + ca, q, u, a)
    olist = sorted(opts.values(), key=lambda o: (o[0], o[1], o[2]))
    if not olist:
        q0 = Ql[0][0] if Ql else 1
        u0 = Ul[0][0] if Ul else 100
        if Al and Ql:
            for q, cq in Ql:
                if Al[0][0] % q == 0:
                    pass
        olist = [(30.0, q0, u0, q0 * u0)]
    bc = olist[0][0]
    res = [o for o in olist if o[0] <= bc + 1.5 * E_BASE][:12]
    info = {'Q': Ql[:60], 'uo': uo, 'ao': ao}
    return res, info


def solve(state, params):
    t0 = time.process_time()
    hard_end = t0 + 0.85
    doc = state.get('doc', {})
    cols = doc.get('cols', ['CODE', 'QTY', 'UNIT', 'AMOUNT'])
    grouped = doc.get('grouped', False)
    sections = doc.get('sections', [])

    # ---------- alignment with item-count guidance
    tables = []
    for sec in sections:
        best = align_counts(sec['tokens'], cols)
        fin = best[len(sec['tokens'])]
        tables.append((best, fin))
    choice_r = []
    for best, fin in tables:
        if fin:
            choice_r.append(min(fin.items(), key=lambda kv: (kv[1][0], kv[0]))[0])
        else:
            choice_r.append(0)
    free_n = sum(choice_r)
    target = None
    istr = qty_obs(doc.get('items_n') or '')
    if istr:
        try:
            iv = int(istr)
        except Exception:
            iv = -1
        if iv != free_n and abs(iv - free_n) <= 2 and 6 <= iv <= 60:
            target = iv
    if target is not None and sections:
        # knapsack over sections for exact count
        dp = {0: (0.0, [])}
        for (best, fin) in tables:
            nd = {}
            for tot, (c, lst) in dp.items():
                for r, (cr, _) in fin.items():
                    nt = tot + r
                    if nt > target:
                        continue
                    cc = c + cr
                    if nt not in nd or nd[nt][0] > cc:
                        nd[nt] = (cc, lst + [r])
            dp = nd
        free_cost = sum(tables[i][1][choice_r[i]][0] for i in range(len(tables)) if tables[i][1])
        if target in dp and dp[target][0] - free_cost <= 3.5:
            choice_r = dp[target][1]

    items = []
    for si, sec in enumerate(sections):
        best, fin = tables[si]
        rows = backtrack(best, sec['tokens'], choice_r[si]) if fin else []
        nrows_left = sum(choice_r[si:]) + 1
        codes = []
        sec_opts = []
        infos = []
        for r in rows:
            d = dict(zip(cols, r))
            now = time.process_time()
            slack_end = min(hard_end, now + max(0.004, (hard_end - now) / max(1, nrows_left)) * 3)
            codes.append(fix_code(d['CODE'], slack_end))
            deep = now < t0 + 0.6
            opts, info = solve_row(d, grouped, slack_end, deep)
            sec_opts.append(opts)
            infos.append(info)
            nrows_left -= 1
        choice = [0] * len(sec_opts)
        sub_obs = norm_money_obs(sec.get('subtotal') or '')
        if sub_obs and sec_opts and time.process_time() < hard_end:
            SUBCAP = 2 * E_BASE + 1
            states = {0: (0.0, [])}
            for ri, opts in enumerate(sec_opts):
                ns = {}
                b0 = opts[0][0]
                for oi, o in enumerate(opts):
                    dc = o[0] - b0
                    for s, (c, path) in states.items():
                        nsum = s + o[3]
                        cc = c + dc
                        if nsum not in ns or ns[nsum][0] > cc:
                            ns[nsum] = (cc, path + [oi])
                if len(ns) > 150:
                    items_s = sorted(ns.items(), key=lambda kv: kv[1][0])[:150]
                    ns = dict(items_s)
                states = ns
            bestf = None
            for s, (c, path) in states.items():
                sc = min(SUBCAP, money_cost_of(s, sub_obs, grouped))
                tot = c + sc
                if bestf is None or tot < bestf[0] - 1e-9:
                    bestf = (tot, path, sc)
            if bestf is not None:
                choice = bestf[1]
                # residual repair for single unresolved row
                if bestf[2] >= SUBCAP and time.process_time() < hard_end:
                    bad = [i for i, o in enumerate(sec_opts) if o[0][0] > 2 * E_BASE + 0.5]
                    sc_cands = money_cands(sub_obs, grouped, 1, hard_end)
                    if len(bad) == 1 and sc_cands:
                        bi = bad[0]
                        others = sum(sec_opts[i][choice[i]][3] for i in range(len(sec_opts)) if i != bi)
                        bestres = None
                        for sv, scc in sorted(sc_cands.items(), key=lambda kv: kv[1])[:20]:
                            R = sv - others
                            if R <= 0:
                                continue
                            ca = money_cost_of(R, infos[bi]['ao'], grouped)
                            for q, cq in infos[bi]['Q']:
                                if R % q:
                                    continue
                                u = R // q
                                cu = money_cost_of(u, infos[bi]['uo'], grouped)
                                tot = scc + ca + cq + cu
                                if bestres is None or tot < bestres[0]:
                                    bestres = (tot, q, u, R)
                        if bestres is not None and bestres[0] < sec_opts[bi][0][0] + SUBCAP - 0.5:
                            sec_opts[bi] = [bestres] + sec_opts[bi]
                            choice[bi] = 0
        for code, opts, ci in zip(codes, sec_opts, choice):
            o = opts[ci] if ci < len(opts) else opts[0]
            items.append({'code': code, 'qty': int(o[1]), 'unit_cents': int(o[2])})
    state['output'] = {'items': items}
    return state

import re
import time

LOOK_D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6', 'D': '0', 'Q': '0'}
LOOK_L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
LOOK_L2 = {'4': 'A', '7': 'T', '3': 'E', '9': 'G'}
MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63', '6': '50', '7': '12', '8': '30', '9': '43'}
DIG = '0123456789'

E_BASE = 3.0
C_MIS1 = E_BASE
C_MIS2 = E_BASE + 0.69
C_LOST = E_BASE
C_DBL = E_BASE
C_MARK = E_BASE - 0.3
EMPTY_C = 4.0
UNK_C = EMPTY_C + 3.0
SUBCAP = 2 * E_BASE + 1
TOTCAP = 2 * E_BASE + 1
INF = float('inf')


def _rev():
    r = {}
    for o, shown in MIS.items():
        for s in shown:
            r.setdefault(s, []).append((o, C_MIS1 if len(shown) == 1 else C_MIS2))
    return r


REV = _rev()


def mis_cost(orig, shown):
    m = MIS.get(orig, '')
    if shown in m:
        return C_MIS1 if len(m) == 1 else C_MIS2
    return None


# ---------------------------------------------------------------- reverse-edit search
def neighbours(s, allow_mark):
    out = []
    n = len(s)
    for k in range(n):
        ch = s[k]
        if ch in DIG:
            for o, c in REV.get(ch, []):
                out.append((s[:k] + o + s[k + 1:], c))
            if (k > 0 and s[k - 1] == ch) or (k < n - 1 and s[k + 1] == ch):
                out.append((s[:k] + s[k + 1:], C_DBL))
    for k in range(n + 1):
        for c in DIG:
            mult = 0
            if k > 0 and s[k - 1] == c:
                mult += 1
            if k < n and s[k] == c:
                mult += 1
            cost = C_LOST - (0.69 if mult >= 1 else 0.0)
            out.append((s[:k] + c + s[k:], cost))
        if allow_mark:
            out.append((s[:k] + '.' + s[k:], C_MARK))
    return out


def search(s, depth, valid_fn, allow_mark, budget_end):
    best = {s: 0.0}
    frontier = {s: 0.0}
    res = {}
    if valid_fn(s):
        res[s] = 0.0
    for d in range(depth):
        if time.process_time() > budget_end:
            break
        nf = {}
        for st, c0 in frontier.items():
            for ns, c in neighbours(st, allow_mark and '.' not in st):
                cc = c0 + c
                if ns in best and best[ns] <= cc:
                    continue
                best[ns] = cc
                nf[ns] = cc
        for ns, cc in nf.items():
            if valid_fn(ns):
                if ns not in res or res[ns] > cc:
                    res[ns] = cc
        frontier = nf
    return res


# ---------------------------------------------------------------- codes
def code_check(letters, d):
    p1 = ord(letters[0]) - 64
    p2 = ord(letters[1]) - 64
    return (int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p1 + p2) % 10


def fix_code(tok, budget_end):
    t = re.sub(r'\s+', '', tok or '')
    letters = ''
    i = 0
    while len(letters) < 2 and i < len(t):
        ch = t[i]
        if ch.isalpha() and 'A' <= ch.upper() <= 'Z':
            letters += ch.upper()
        elif ch in LOOK_L:
            letters += LOOK_L[ch]
        elif ch in LOOK_L2:
            letters += LOOK_L2[ch]
        i += 1
    while len(letters) < 2:
        letters += 'A'
    d = ''
    for ch in t[i:]:
        if ch in DIG:
            d += ch
        elif ch in LOOK_D:
            d += LOOK_D[ch]

    def valid(x):
        return len(x) == 5 and all(c in DIG for c in x) and code_check(letters, x) == int(x[4])

    def fallback():
        dd = (d + '00000')[:4]
        return letters + dd + str(code_check(letters, dd))

    if valid(d):
        return letters + d
    if len(d) < 3 or len(d) > 8:
        return fallback()
    depth = 1
    if abs(len(d) - 5) >= 2:
        depth = min(3, abs(len(d) - 5))
    res = search(d, depth, valid, False, budget_end)
    if not res and depth < 2:
        res = search(d, 2, valid, False, budget_end)
    if res:
        bestv = min(res.items(), key=lambda kv: (kv[1], kv[0]))
        return letters + bestv[0]
    return fallback()


# ---------------------------------------------------------------- money
def norm_money_obs(tok):
    out = ''
    for ch in (tok or '').strip():
        if ch in DIG:
            out += ch
        elif ch in '.,':
            out += '.'
        elif ch == "'":
            out += "'"
        elif ch in LOOK_D:
            out += LOOK_D[ch]
    return out


def make_money_valid(grouped):
    if grouped:
        rx = re.compile(r"^(0|[1-9]\d{0,2}('\d{3})*)\.\d\d$")
    else:
        rx = re.compile(r"^(0|[1-9]\d*)\.\d\d$")

    def f(s):
        return bool(rx.match(s)) and s != '0.00'
    return f


def money_str(v, grouped):
    ip = str(v // 100)
    fp = '%02d' % (v % 100)
    if grouped:
        parts = []
        while len(ip) > 3:
            parts.insert(0, ip[-3:])
            ip = ip[:-3]
        parts.insert(0, ip)
        ip = "'".join(parts)
    return ip + '.' + fp


def str_to_cents(s):
    s = s.replace("'", '')
    a, b = s.split('.')
    return int(a) * 100 + int(b)


def money_cands(obs, grouped, depth, budget_end):
    if not obs:
        return {}
    vf = make_money_valid(grouped)
    res = search(obs, depth, vf, True, budget_end)
    out = {}
    for s, c in res.items():
        v = str_to_cents(s)
        if v not in out or out[v] > c:
            out[v] = c
    return out


def channel_cost(orig, obs):
    n = len(orig)
    m = len(obs)
    BIG = 1e9
    dp = [[BIG] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        row = dp[i]
        for j in range(m + 1):
            c = row[j]
            if c >= BIG:
                continue
            if i < n:
                oc = orig[i]
                lc = C_MARK if oc == '.' else (C_LOST if oc in DIG else 9.0)
                if c + lc < dp[i + 1][j]:
                    dp[i + 1][j] = c + lc
                if j < m:
                    sc = obs[j]
                    if sc == oc:
                        if c < dp[i + 1][j + 1]:
                            dp[i + 1][j + 1] = c
                    elif oc in DIG and sc in DIG:
                        mc = mis_cost(oc, sc)
                        if mc is not None and c + mc < dp[i + 1][j + 1]:
                            dp[i + 1][j + 1] = c + mc
                    if oc in DIG and j + 1 < m and obs[j] == oc and obs[j + 1] == oc:
                        if c + C_DBL < dp[i + 1][j + 2]:
                            dp[i + 1][j + 2] = c + C_DBL
    return dp[n][m]


def money_cost_of(v, obs, grouped):
    if v <= 0:
        return 99.0
    return channel_cost(money_str(v, grouped), obs)


# ---------------------------------------------------------------- qty
def qty_obs(tok):
    s = re.sub(r'(?i)p\s*c\s*s', '', tok or '').strip()
    out = ''
    for ch in s:
        if ch in DIG:
            out += ch
        elif ch in LOOK_D:
            out += LOOK_D[ch]
    return out


def qty_valid(s):
    return 0 < len(s) <= 3 and s[0] != '0' and all(c in DIG for c in s) and 1 <= int(s) <= 500


def qty_cands(obs, depth, budget_end):
    if not obs or len(obs) > 6:
        return {}
    res = search(obs, depth, qty_valid, False, budget_end)
    out = {}
    for s, c in res.items():
        v = int(s)
        if v not in out or out[v] > c:
            out[v] = c
    return out


# ---------------------------------------------------------------- parsing
def tok_type_cost(tok, col):
    t = tok.strip()
    if col == 'CODE':
        if re.match(r'^[A-Z0-9]{2}[0-9OlSBZGI]{4,6}$', t):
            return 0.0
        if re.match(r'^[A-Za-z0-9]{4,10}$', t) and re.match(r'^[A-Za-z]', t):
            return 1.0
        if re.match(r'^[A-Za-z0-9]{5,10}$', t):
            return 2.0
        return 3.0
    if col == 'QTY':
        if t == '':
            return 1.0
        if re.match(r'^[0-9OlSBZG]{0,4}( ?pcs)?$', t):
            return 0.0
        return 3.0
    if t == '':
        return 3.0
    if re.match(r"^[0-9OlSBZG']*[.,][0-9OlSBZG]{1,3}$", t):
        return 0.0
    if re.match(r"^[0-9OlSBZG']{2,}$", t):
        if re.match(r'^[A-Z]{2}', t):
            return 3.0
        return 0.6
    return 3.0


def looks_value(tok):
    t = tok.strip()
    if t == '':
        return True
    t = re.sub(r'\s*pcs$', '', t)
    if t == '':
        return True
    if not re.match(r"^[A-Za-z0-9.,']+$", t):
        return False
    if len(t) > 14:
        return False
    good = sum(1 for ch in t if ch in DIG or ch in LOOK_D or ch in ".,'")
    return good >= len(t) - 2 and good >= 1


def split_line(line, sep):
    if sep == '|':
        parts = line.split('|')
    elif sep == ';':
        parts = line.split(';')
    elif sep == '\t':
        parts = line.split('\t')
    else:
        parts = re.split(r' {3}', line)
    parts = [p.strip() for p in parts]
    while parts and parts[-1] == '':
        parts.pop()
    if not parts or all(p == '' for p in parts):
        return []
    return parts


def parse_doc(state, params):
    text = (state.get('input') or {}).get('text', '') or ''
    lines = text.split('\n')
    cols = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    sep = ';'
    for ln in lines:
        if 'COLUMNS' in ln:
            body = ln.split('COLUMNS', 1)[1]
            body = body[1:] if body.startswith(':') else body
            pos = [(body.find(c), c) for c in ['CODE', 'QTY', 'UNIT', 'AMOUNT']]
            if all(p >= 0 for p, _ in pos):
                cols = [c for _, c in sorted(pos)]
            inner = body.strip()
            if '|' in inner:
                sep = '|'
            elif ';' in inner:
                sep = ';'
            elif '\t' in inner:
                sep = '\t'
            else:
                sep = '   '
            break
    sections = []
    cur = None
    total = None
    items_n = None
    for ln in lines:
        ln = ln.replace('\r', '')
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if re.match(r'^=+\s*SECTION', s):
            cur = {'tokens': [], 'subtotal': None}
            sections.append(cur)
            continue
        if s.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'tokens': [], 'subtotal': None}
                sections.append(cur)
            cur['subtotal'] = s[len('SUBTOTAL'):].strip()
            continue
        if s.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s+(.*?)\s+ITEMS\s*(.*)$', s)
            if m:
                total = m.group(1)
                items_n = m.group(2)
            else:
                total = s[len('TOTAL'):].strip()
            continue
        parts = split_line(ln, sep)
        if not parts:
            continue
        suspect = not all(looks_value(p) for p in parts)
        if cur is None:
            cur = {'tokens': [], 'subtotal': None}
            sections.append(cur)
        for p in parts:
            cur['tokens'].append([p, bool(suspect or not looks_value(p))])
    grouped = bool(re.search(r"[0-9OlSBZG]'[0-9OlSBZG]", text))
    state['doc'] = {'cols': cols, 'sections': sections, 'total': total,
                    'items_n': items_n, 'grouped': grouped}
    return state


# ---------------------------------------------------------------- alignment
def align_dp(toks, cols):
    n = len(toks)
    R = n // 3 + 2
    tc = [[tok_type_cost(t, c) for c in cols] for t, _ in toks]
    sk = [0.3 if s else 4.0 for _, s in toks]
    r4 = [None] * n
    r3 = [None] * n
    for i in range(n):
        if i + 4 <= n:
            r4[i] = sum(tc[i + k][k] for k in range(4))
        if i + 3 <= n:
            bm = None
            for miss in range(4):
                c = 3.5
                k2 = 0
                for k in range(4):
                    if k == miss:
                        continue
                    c += tc[i + k2][k]
                    k2 += 1
                if bm is None or c < bm[0]:
                    bm = (c, miss)
            r3[i] = bm
    best = [[INF] * (R + 1) for _ in range(n + 1)]
    back = [[None] * (R + 1) for _ in range(n + 1)]
    best[0][0] = 0.0
    for i in range(n):
        bi = best[i]
        for r in range(R + 1):
            b = bi[r]
            if b == INF:
                continue
            c = b + sk[i]
            if c < best[i + 1][r]:
                best[i + 1][r] = c
                back[i + 1][r] = ('skip', i, -1)
            if r < R:
                if r4[i] is not None:
                    c = b + r4[i]
                    if c < best[i + 4][r + 1]:
                        best[i + 4][r + 1] = c
                        back[i + 4][r + 1] = ('row', i, -1)
                if r3[i] is not None:
                    c = b + r3[i][0]
                    if c < best[i + 3][r + 1]:
                        best[i + 3][r + 1] = c
                        back[i + 3][r + 1] = ('row3', i, r3[i][1])
    return best[n], back


def reconstruct(toks, back, n, r):
    rows = []
    j = n
    rr = r
    while j > 0:
        bk = back[j][rr]
        if bk is None:
            break
        i = bk[1]
        if bk[0] == 'skip':
            j = i
            continue
        if bk[0] == 'row':
            rows.append([t for t, _ in toks[i:i + 4]])
        else:
            seg = [t for t, _ in toks[i:i + 3]]
            seg.insert(bk[2], '')
            rows.append(seg)
        j = i
        rr -= 1
    rows.reverse()
    return rows


# ---------------------------------------------------------------- row solving
def solve_row(d, grouped, budget_end, deep):
    qo = qty_obs(d.get('QTY', ''))
    uo = norm_money_obs(d.get('UNIT', ''))
    ao = norm_money_obs(d.get('AMOUNT', ''))
    Q = qty_cands(qo, 2, budget_end) if qo else {}
    U = money_cands(uo, grouped, 1, budget_end) if uo else {}
    A = money_cands(ao, grouped, 1, budget_end) if ao else {}
    qunk = None if Q else (EMPTY_C if not qo else UNK_C)
    uunk = None if U else (EMPTY_C if not uo else UNK_C)
    aunk = None if A else (EMPTY_C if not ao else UNK_C)
    opts = {}

    def add(c, q, u, a):
        if q < 1 or q > 500 or u <= 0:
            return
        key = (q, u)
        if key not in opts or opts[key][0] > c:
            opts[key] = (c, q, u, a)

    Ql = sorted(Q.items(), key=lambda kv: (kv[1], kv[0]))
    Ul = sorted(U.items(), key=lambda kv: (kv[1], kv[0]))
    Al = sorted(A.items(), key=lambda kv: (kv[1], kv[0]))
    for q, cq in Ql:
        if cq > 2 * E_BASE + 1:
            continue
        for u, cu in Ul:
            ca = A.get(q * u)
            if ca is not None:
                add(cq + cu + ca, q, u, q * u)
    for u, cu in Ul:
        for a, ca in Al:
            if a % u == 0:
                cq = Q.get(a // u)
                if cq is not None:
                    add(cq + cu + ca, a // u, u, a)
    bestc = min([o[0] for o in opts.values()]) if opts else 99.0
    if bestc > 1.5 * E_BASE and deep and time.process_time() < budget_end:
        if uo:
            for q, cq in Ql:
                if cq > E_BASE + 1:
                    continue
                for a, ca in Al:
                    if a % q == 0:
                        u = a // q
                        if u not in U:
                            cu = money_cost_of(u, uo, grouped)
                            if cu < 2 * E_BASE + 2:
                                add(cq + cu + ca, q, u, a)
        if ao:
            for q, cq in Ql:
                if cq > E_BASE + 1:
                    continue
                for u, cu in Ul:
                    if cq + cu > E_BASE + 1:
                        continue
                    a = q * u
                    if a not in A:
                        ca = money_cost_of(a, ao, grouped)
                        if ca < 2 * E_BASE + 2:
                            add(cq + cu + ca, q, u, a)
        if uo and time.process_time() < budget_end:
            U2 = money_cands(uo, grouped, 2, budget_end)
            for u, cu in U2.items():
                if cu < E_BASE * 1.5:
                    continue
                for q, cq in Ql:
                    if cq > E_BASE + 1:
                        continue
                    ca = A.get(q * u)
                    if ca is not None:
                        add(cq + cu + ca, q, u, q * u)
    # unknown / empty field derivation
    if uunk is not None:
        for q, cq in Ql[:40]:
            for a, ca in Al[:40]:
                if a % q == 0:
                    add(cq + ca + uunk, q, a // q, a)
    if aunk is not None:
        for q, cq in Ql[:40]:
            for u, cu in Ul[:40]:
                add(cq + cu + aunk, q, u, q * u)
    if qunk is not None:
        for u, cu in Ul[:40]:
            for a, ca in Al[:40]:
                if a % u == 0 and 1 <= a // u <= 500:
                    add(cu + ca + qunk, a // u, u, a)
    olist = sorted(opts.values(), key=lambda o: (o[0], o[1], o[2]))
    if not olist:
        q0 = Ql[0][0] if Ql else 1
        if Ul:
            u0 = Ul[0][0]
        elif Al:
            u0 = max(1, Al[0][0] // q0)
        else:
            u0 = 100
        olist = [(30.0, q0, u0, q0 * u0)]
    bc = olist[0][0]
    res = [o for o in olist if o[0] <= bc + 1.5 * E_BASE][:12]
    info = {'Q': Ql[:60], 'qo': qo, 'uo': uo, 'ao': ao, 'qunk': qunk}
    return res, info


# ---------------------------------------------------------------- section beam
def beam_section(sec_opts):
    states = {0: 0.0}
    layers = []
    for opts in sec_opts:
        b0 = opts[0][0]
        ns = {}
        bk = {}
        for s, c in states.items():
            for oi, o in enumerate(opts):
                nsum = s + o[3]
                cc = c + o[0] - b0
                if nsum not in ns or ns[nsum] > cc:
                    ns[nsum] = cc
                    bk[nsum] = (s, oi)
        if len(ns) > 220:
            ns = dict(sorted(ns.items(), key=lambda kv: (kv[1], kv[0]))[:220])
        layers.append(bk)
        states = ns
    return states, layers


def path_of(layers, s):
    path = []
    for bk in reversed(layers):
        ps, oi = bk[s]
        path.append(oi)
        s = ps
    path.reverse()
    return path


def solve(state, params):
    t0 = time.process_time()
    hard_end = t0 + 0.85
    doc = state.get('doc') or {}
    cols = doc.get('cols') or ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    grouped = bool(doc.get('grouped'))
    secs = doc.get('sections') or []

    # ---- row counts: alignment DP + knapsack against ITEMS
    dps = [align_dp(sec.get('tokens', []), cols) for sec in secs]
    tot = {0: (0.0, [])}
    for costs, _ in dps:
        nt = {}
        for k, (c, ch) in tot.items():
            for r, cr in enumerate(costs):
                if cr == INF:
                    continue
                v = c + cr
                kk = k + r
                if kk not in nt or nt[kk][0] > v:
                    nt[kk] = (v, ch + [r])
        tot = nt
    io = qty_obs(doc.get('items_n') or '')
    bestk = None
    bests = INF
    for k, (c, ch) in sorted(tot.items()):
        pen = 0.0
        if io:
            pen = 0.0 if str(k) == io else min(6.0, 0.8 * channel_cost(str(k), io))
        if c + pen < bests - 1e-9:
            bests = c + pen
            bestk = k
    rcounts = tot[bestk][1] if bestk is not None else [0] * len(secs)

    # ---- decode rows
    total_rows = sum(rcounts)
    rows_left = total_rows
    sdata = []
    for si, sec in enumerate(secs):
        toks = sec.get('tokens', [])
        rc = rcounts[si] if si < len(rcounts) else 0
        rows = reconstruct(toks, dps[si][1], len(toks), rc) if toks else []
        codes, opts_l, infos = [], [], []
        for r in rows:
            d = dict(zip(cols, r))
            now = time.process_time()
            slack_end = min(hard_end, now + max(0.004, (hard_end - now) / max(1, rows_left)) * 3)
            codes.append(fix_code(d.get('CODE', ''), slack_end))
            o, inf = solve_row(d, grouped, slack_end, now < t0 + 0.6)
            opts_l.append(o)
            infos.append(inf)
            rows_left -= 1
        sdata.append({'codes': codes, 'opts': opts_l, 'infos': infos,
                      'sub_obs': norm_money_obs(sec.get('subtotal') or '')})

    # ---- per-section beams
    all_finals = []
    all_layers = []
    for sd in sdata:
        if sd['opts']:
            states, layers = beam_section(sd['opts'])
        else:
            states, layers = {0: 0.0}, []
        finals = []
        late = time.process_time() > hard_end
        for s, c in states.items():
            if sd['sub_obs'] and not late:
                sc = min(SUBCAP, money_cost_of(s, sd['sub_obs'], grouped))
            else:
                sc = 0.0
            finals.append((c + sc, s, sc))
        finals.sort()
        all_finals.append(finals[:25])
        all_layers.append(layers)

    # ---- cross-section DP against TOTAL
    tot_obs = norm_money_obs(doc.get('total') or '')
    cross = {0: (0.0, [])}
    for fl in all_finals:
        nc = {}
        for T, (c, lst) in cross.items():
            for fi, (scv, s, sc) in enumerate(fl):
                nt_ = T + s
                cc = c + scv
                if nt_ not in nc or nc[nt_][0] > cc:
                    nc[nt_] = (cc, lst + [fi])
        if len(nc) > 300:
            nc = dict(sorted(nc.items(), key=lambda kv: (kv[1][0], kv[0]))[:300])
        cross = nc
    bestx = None
    late = time.process_time() > hard_end
    for T, (c, lst) in cross.items():
        tc = min(TOTCAP, money_cost_of(T, tot_obs, grouped)) if (tot_obs and not late) else 0.0
        v = c + tc
        if bestx is None or v < bestx[0] - 1e-9:
            bestx = (v, lst, tc, T)

    choices = []
    sec_sums = []
    sec_subc = []
    for si, sd in enumerate(sdata):
        fi = bestx[1][si] if bestx is not None else 0
        fin = all_finals[si][fi]
        if sd['opts']:
            try:
                ch = path_of(all_layers[si], fin[1])
            except Exception:
                ch = [0] * len(sd['opts'])
        else:
            ch = []
        choices.append(ch)
        sec_sums.append(sum(sd['opts'][i][ch[i]][3] for i in range(len(ch))))
        sec_subc.append(fin[2])

    # ---- residual repair
    total_ok = bestx is not None and tot_obs and bestx[2] < TOTCAP
    tot_cands = {}
    if total_ok and time.process_time() < hard_end:
        try:
            tot_cands = money_cands(tot_obs, grouped, 1, hard_end)
        except Exception:
            tot_cands = {}
    for si, sd in enumerate(sdata):
        if time.process_time() > hard_end:
            break
        if not sd['opts'] or sec_subc[si] < SUBCAP - 1e-9:
            continue
        try:
            targets = {}
            if sd['sub_obs']:
                for v, c in money_cands(sd['sub_obs'], grouped, 1, hard_end).items():
                    targets[v] = c
            others_sec = sum(sec_sums) - sec_sums[si]
            for T, c in tot_cands.items():
                v = T - others_sec
                if v > 0:
                    cc = c + 1.0
                    if v not in targets or targets[v] > cc:
                        targets[v] = cc
            if not targets:
                continue
            tl = sorted(targets.items(), key=lambda kv: (kv[1], kv[0]))[:25]
            ch = choices[si]
            cur_sum = sec_sums[si]
            bestr = None
            for ri, opts in enumerate(sd['opts']):
                if time.process_time() > hard_end:
                    break
                o = opts[ch[ri]]
                inf = sd['infos'][ri]
                limit = o[0] + SUBCAP - 0.5
                others = cur_sum - o[3]
                if inf['Q']:
                    qlist = inf['Q']
                else:
                    qlist = [(q, inf['qunk'] if inf['qunk'] is not None else UNK_C) for q in range(1, 501)]
                for v, tcst in tl:
                    R = v - others
                    if R <= 0 or R == o[3]:
                        continue
                    if inf['ao']:
                        ca = money_cost_of(R, inf['ao'], grouped)
                    else:
                        ca = EMPTY_C
                    base = tcst + ca
                    if base >= limit:
                        continue
                    for q, cq in qlist:
                        if R % q or base + cq >= limit:
                            continue
                        u = R // q
                        cu = money_cost_of(u, inf['uo'], grouped) if inf['uo'] else EMPTY_C
                        totc = base + cq + cu
                        if totc < limit:
                            gain = limit - totc
                            if bestr is None or gain > bestr[0]:
                                bestr = (gain, ri, (totc, q, u, R))
            if bestr is not None:
                ri = bestr[1]
                sd['opts'][ri] = [bestr[2]] + sd['opts'][ri]
                choices[si][ri] = 0
        except Exception:
            pass

    items = []
    for si, sd in enumerate(sdata):
        for ri, code in enumerate(sd['codes']):
            opts = sd['opts'][ri]
            ci = choices[si][ri] if ri < len(choices[si]) else 0
            o = opts[ci] if ci < len(opts) else opts[0]
            items.append({'code': code, 'qty': int(o[1]), 'unit_cents': int(o[2])})
    state['output'] = {'items': items}
    return state

import re
import time
import math

LOOK_D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6', 'D': '0', 'Q': '0'}
LOOK_L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G', '4': 'A', '7': 'T', '3': 'E'}
MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63', '6': '50', '7': '12', '8': '30', '9': '43'}
INF = float('inf')


def _rev():
    r = {}
    for o, shown in MIS.items():
        for s in shown:
            r.setdefault(s, []).append(o)
    return r


REV = _rev()


def to_digits(s):
    out = []
    for ch in s:
        if ch.isdigit():
            out.append(ch)
        elif ch in LOOK_D:
            out.append(LOOK_D[ch])
    return ''.join(out)


def code_check(letters, d):
    p1 = ord(letters[0]) - 64
    p2 = ord(letters[1]) - 64
    return (int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p1 + p2) % 10


def code_valid(letters, d):
    return len(d) == 5 and d.isdigit() and code_check(letters, d) == int(d[4])


def rate_costs(R):
    def c(p):
        return min(2.0, max(0.5, -math.log(max(p, 1e-6)) / 3.2))
    cm = {}
    for o, sh in MIS.items():
        cm[o] = {s: c(R['pm'] / len(sh)) for s in sh}
    return {'cm': cm, 'cl': c(R['pl']), 'cd': c(R['pd'])}


DEFAULT_R = {'pm': 0.04, 'pl': 0.03, 'pd': 0.03}


def edits(ds, ins_lo, ins_hi, del_lo, del_hi, C):
    yield ds, 0.0
    n = len(ds)
    cm = C['cm']
    for k in range(n):
        for r in REV.get(ds[k], []):
            yield ds[:k] + r + ds[k + 1:], cm[r][ds[k]]
    for k in range(max(0, del_lo), min(n, del_hi)):
        if (k > 0 and ds[k] == ds[k - 1]) or (k < n - 1 and ds[k] == ds[k + 1]):
            yield ds[:k] + ds[k + 1:], C['cd']
    for k in range(max(0, ins_lo), min(n, ins_hi) + 1):
        for c in '0123456789':
            yield ds[:k] + c + ds[k:], C['cl']


def money_obs(tok):
    s = ''
    for ch in (tok or '').strip():
        if ch.isdigit():
            s += ch
        elif ch in '.,':
            s += '.'
        elif ch in LOOK_D:
            s += LOOK_D[ch]
    if s.count('.') > 1:
        k = s.rfind('.')
        s = s[:k].replace('.', '') + s[k:]
    return s


def fmt_money(v):
    return '%d.%02d' % (v // 100, v % 100)


def money_cands(tok, C):
    s2 = money_obs(tok)
    m = re.match(r'^(\d*)\.(\d*)$', s2)
    if m:
        ip, fp = m.group(1), m.group(2)
        ds = ip + fp
        ni = len(ip)
        if len(fp) == 2:
            il, ih, dl, dh = 0, ni, 0, ni
        elif len(fp) == 1:
            il, ih, dl, dh = ni, len(ds), 0, 0
        elif len(fp) == 3:
            il, ih, dl, dh = 0, -1, ni, len(ds)
        else:
            il, ih, dl, dh = 0, len(ds), 0, len(ds)
    else:
        ds = re.sub(r'\D', '', s2)
        il, ih, dl, dh = 0, len(ds), 0, len(ds)
    out = {}
    for cand, c in edits(ds, il, ih, dl, dh, C):
        if not cand:
            continue
        v = int(cand)
        if v <= 0:
            continue
        if v not in out or out[v] > c:
            out[v] = c
    return out


def qty_obs(tok):
    s = re.sub(r'(?i)p\s*c\s*s', '', tok or '').strip()
    return to_digits(s)


def qty_cands(tok, C):
    ds = qty_obs(tok)
    out = {}
    if not ds:
        for v in range(1, 10):
            out[v] = 1.0
        return out
    for cand, c in edits(ds, 0, len(ds), 0, len(ds), C):
        if not cand:
            continue
        v = int(cand)
        if 1 <= v <= 500 and (v not in out or out[v] > c):
            out[v] = c
    if not out:
        out[max(1, min(500, int(ds[:3])))] = 2.0
    return out


def wdist(o, c, C):
    n, m = len(c), len(o)
    if abs(n - m) > 3:
        return 9.0
    cm, cl, cd = C['cm'], C['cl'], C['cd']
    D = [[INF] * (m + 1) for _ in range(n + 1)]
    D[0][0] = 0.0
    for i in range(n + 1):
        Di = D[i]
        for j in range(m + 1):
            v = Di[j]
            if v == INF:
                continue
            if 0 < j < m and o[j] == o[j - 1] and o[j] != '.':
                if v + cd < Di[j + 1]:
                    Di[j + 1] = v + cd
            if i < n:
                ci = c[i]
                nv = v + (0.0 if ci == '.' else cl)
                Dn = D[i + 1]
                if nv < Dn[j]:
                    Dn[j] = nv
                if j < m:
                    oj = o[j]
                    if ci == oj:
                        w = 0.0
                    else:
                        w = cm.get(ci, {}).get(oj)
                    if w is not None and v + w < Dn[j + 1]:
                        Dn[j + 1] = v + w
    return D[n][m]


def tok_type_cost(tok, col):
    t = tok.strip()
    if col == 'CODE':
        if re.match(r'^[A-Z0-9]{2}[0-9OlSBZGI]{4,6}$', t):
            return 0.0
        if re.match(r'^[A-Za-z0-9]{6,9}$', t):
            return 1.0
        if re.match(r'^[A-Za-z0-9]{4,5}$', t) and re.match(r'^[A-Z]', t):
            return 1.5
        return 3.0
    if col == 'QTY':
        if re.match(r'^[0-9OlSBZG]{0,4}( ?pcs)?$', t):
            return 0.0 if '.' not in t and ',' not in t else 2.0
        return 3.0
    if re.match(r"^[0-9OlSBZG']*[.,][0-9OlSBZG]{1,3}$", t):
        return 0.0
    if re.match(r"^[0-9OlSBZG']{2,}$", t):
        if re.match(r'^[A-Z]{2}', t):
            return 3.0
        return 0.6
    return 3.0


def looks_value(tok):
    t = tok.strip()
    if t == '':
        return True
    t = re.sub(r'\s*pcs$', '', t)
    if t == '':
        return True
    if not re.match(r"^[A-Za-z0-9.,']+$", t):
        return False
    if len(t) > 14:
        return False
    good = sum(1 for ch in t if ch.isdigit() or ch in LOOK_D or ch in ".,'")
    return good >= len(t) - 2 and good >= 1


def split_line(line, sep):
    if sep == '|':
        parts = line.split('|')
    elif sep == ';':
        parts = line.split(';')
    elif sep == '\t':
        parts = line.split('\t')
    else:
        parts = re.split(r' {3}', line.rstrip('\n'))
    parts = [p.strip() for p in parts]
    while parts and parts[-1] == '':
        parts.pop()
    while parts and parts[0] == '':
        parts.pop(0)
    return parts


def parse_doc(state, params):
    text = state.get('input', {}).get('text', '') or ''
    lines = text.split('\n')
    cols = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    sep = ';'
    for ln in lines:
        if 'COLUMNS' in ln:
            body = ln.split('COLUMNS', 1)[1]
            body = body[1:] if body.startswith(':') else body
            pos = []
            for c in ['CODE', 'QTY', 'UNIT', 'AMOUNT']:
                pos.append((body.find(c), c))
            if all(p >= 0 for p, _ in pos):
                cols = [c for _, c in sorted(pos)]
            inner = body.strip()
            if '|' in inner:
                sep = '|'
            elif ';' in inner:
                sep = ';'
            elif '\t' in inner:
                sep = '\t'
            else:
                sep = '   '
            break
    sections = []
    cur = None
    total = None
    items_n = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if re.match(r'^=+\s*SECTION', s):
            cur = {'tokens': [], 'subtotal': None}
            sections.append(cur)
            continue
        if s.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'tokens': [], 'subtotal': None}
                sections.append(cur)
            cur['subtotal'] = s[len('SUBTOTAL'):].strip()
            continue
        if s.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s+(.*?)\s+ITEMS\s*(.*)$', s)
            if m:
                total = m.group(1)
                items_n = m.group(2)
            continue
        parts = split_line(ln.replace('\r', ''), sep)
        if not parts:
            continue
        suspect = not all(looks_value(p) for p in parts)
        if cur is None:
            cur = {'tokens': [], 'subtotal': None}
            sections.append(cur)
        for p in parts:
            cur['tokens'].append([p, bool(suspect or not looks_value(p))])
    state['doc'] = {'cols': cols, 'sections': sections, 'total': total, 'items_n': items_n}
    return state


def align_dp(toks, cols):
    n = len(toks)
    R = n // 3 + 2
    tc = [[tok_type_cost(t, c) for c in cols] for t, _ in toks]
    sk = [0.3 if s else 4.0 for _, s in toks]
    r4 = [None] * n
    r3 = [None] * n
    for i in range(n):
        if i + 4 <= n:
            r4[i] = sum(tc[i + k][k] for k in range(4))
        if i + 3 <= n:
            bm = None
            for miss in range(4):
                c = 3.5
                k2 = 0
                for k in range(4):
                    if k == miss:
                        continue
                    c += tc[i + k2][k]
                    k2 += 1
                if bm is None or c < bm[0]:
                    bm = (c, miss)
            r3[i] = bm
    best = [[INF] * (R + 1) for _ in range(n + 1)]
    back = [[None] * (R + 1) for _ in range(n + 1)]
    best[0][0] = 0.0
    for i in range(n):
        bi = best[i]
        for r in range(R + 1):
            b = bi[r]
            if b == INF:
                continue
            c = b + sk[i]
            if c < best[i + 1][r]:
                best[i + 1][r] = c
                back[i + 1][r] = ('skip', i, -1)
            if r < R:
                if r4[i] is not None:
                    c = b + r4[i]
                    if c < best[i + 4][r + 1]:
                        best[i + 4][r + 1] = c
                        back[i + 4][r + 1] = ('row', i, -1)
                if r3[i] is not None:
                    c = b + r3[i][0]
                    if c < best[i + 3][r + 1]:
                        best[i + 3][r + 1] = c
                        back[i + 3][r + 1] = ('row3', i, r3[i][1])
    return best[n], back


def reconstruct(toks, back, n, r):
    rows = []
    j = n
    rr = r
    while j > 0:
        bk = back[j][rr]
        if bk is None:
            break
        i = bk[1]
        if bk[0] == 'skip':
            j = i
            continue
        if bk[0] == 'row':
            rows.append([t for t, _ in toks[i:i + 4]])
        else:
            seg = [t for t, _ in toks[i:i + 3]]
            seg.insert(bk[2], '')
            rows.append(seg)
        j = i
        rr -= 1
    rows.reverse()
    return rows


def items_cands(s, C):
    out = {}
    if not s:
        return None, out
    ds = to_digits(s.strip())
    if not ds:
        return None, out
    raw = int(ds) if re.match(r'^\d+$', s.strip()) else None
    for cand, c in edits(ds, 0, len(ds), 0, len(ds), C):
        if not cand:
            continue
        v = int(cand)
        if 1 <= v <= 80:
            if v not in out or out[v] > c:
                out[v] = c
    if raw is None:
        v = int(ds)
        if 1 <= v <= 80:
            out[v] = 0.5
    return raw, out


def align_rows(state, params):
    doc = state.get('doc', {})
    cols = doc.get('cols', ['CODE', 'QTY', 'UNIT', 'AMOUNT'])
    secs = doc.get('sections', [])
    dps = []
    for sec in secs:
        dps.append(align_dp(sec['tokens'], cols))
    tot = {0: (0.0, [])}
    for costs, _ in dps:
        nt = {}
        for k, (c, ch) in tot.items():
            for r, cr in enumerate(costs):
                if cr == INF:
                    continue
                v = c + cr
                kk = k + r
                if kk not in nt or nt[kk][0] > v:
                    nt[kk] = (v, ch + [r])
        tot = nt
    raw, ic = items_cands(doc.get('items_n'), rate_costs(DEFAULT_R))
    bestk = None
    bests = INF
    for k, (c, ch) in tot.items():
        if raw is not None and k == raw:
            pen = 0.0
        elif k in ic:
            pen = 2.5
        else:
            pen = 6.0
        s = c + pen
        if s < bests - 1e-9:
            bests = s
            bestk = k
    rcounts = [0] * len(secs) if bestk is None else tot[bestk][1]
    out = []
    for si, sec in enumerate(secs):
        toks = sec['tokens']
        rc = rcounts[si] if si < len(rcounts) else 0
        rows = reconstruct(toks, dps[si][1], len(toks), rc)
        out.append({'rows': rows, 'subtotal': sec.get('subtotal')})
    state['aligned'] = {'cols': cols, 'sections': out, 'total': doc.get('total')}
    return state


def split_code(tok):
    t = re.sub(r'\s+', '', tok or '')
    letters = ''
    i = 0
    while len(letters) < 2 and i < len(t):
        ch = t[i]
        if ch.isalpha():
            letters += ch.upper()
        elif ch in LOOK_L:
            letters += LOOK_L[ch]
        i += 1
    while len(letters) < 2:
        letters += 'A'
    if not all('A' <= x <= 'Z' for x in letters[:2]):
        letters = 'AA'
    return letters[:2], to_digits(t[i:])


def estimate_rates(secs, cols):
    nc = c4 = c6 = m5 = 0
    nm = f1 = f3 = 0
    for sec in secs:
        for row in sec['rows']:
            d = dict(zip(cols, row))
            if d.get('CODE'):
                nc += 1
                letters, dg = split_code(d['CODE'])
                n = len(dg)
                if n < 5:
                    c4 += 5 - n
                elif n > 5:
                    c6 += n - 5
                elif not code_valid(letters, dg):
                    m5 += 1
            for col in ('UNIT', 'AMOUNT'):
                s = money_obs(d.get(col, ''))
                if '.' in s:
                    nm += 1
                    f = len(s) - s.rfind('.') - 1
                    if f < 2:
                        f1 += 2 - f
                    elif f > 2:
                        f3 += f - 2
    den = 5.0 * nc + 2.0 * nm + 20.0
    pl = (c4 + f1 + 0.4) / den
    pd = (c6 + f3 + 0.4) / den
    pm = (m5 + 0.4) / (5.0 * nc + 20.0)
    return {'pm': pm, 'pl': pl, 'pd': pd}


def code_search(letters, d, maxdep, R, deadline):
    res = {}
    pm, pl, pd = R['pm'], R['pl'], R['pd']
    cnt = [0]

    def rec(s, w, dep):
        cnt[0] += 1
        if (cnt[0] & 1023) == 0 and time.process_time() > deadline:
            return
        L = len(s)
        if dep > 0 and L == 5 and code_check(letters, s) == int(s[4]):
            res[s] = res.get(s, 0.0) + w
        if dep >= maxdep:
            return
        rem = maxdep - dep - 1
        if abs(L - 5) <= rem:
            for k in range(L):
                for o in REV.get(s[k], []):
                    rec(s[:k] + o + s[k + 1:], w * pm / len(MIS[o]), dep + 1)
        if abs(L - 6) <= rem:
            for k in range(1, L):
                if s[k] == s[k - 1]:
                    rec(s[:k] + s[k + 1:], w * pd, dep + 1)
        if abs(L - 4) <= rem:
            for k in range(L + 1):
                for c in '0123456789':
                    rec(s[:k] + c + s[k:], w * pl, dep + 1)

    rec(d, 1.0, 0)
    return res


def _fallback(letters, d):
    d = (d + '0000')[:4]
    return letters + d + str(code_check(letters, d))


def fix_code(tok, R, deadline):
    letters, d = split_code(tok)
    if len(d) == 5 and code_valid(letters, d):
        return letters + d
    res = {}
    if 3 <= len(d) <= 7 and time.process_time() < deadline:
        res = code_search(letters, d, 2, R, deadline)
        if not res and 4 <= len(d) <= 6 and time.process_time() < deadline - 0.1:
            res = code_search(letters, d, 3, R, deadline)
    if res:
        b = max(res.items(), key=lambda kv: (kv[1], kv[0]))[0]
        return letters + b
    if len(d) > 5:
        return _fallback(letters, d[:5])
    return _fallback(letters, d)


def _top(dct, k):
    return sorted(dct.items(), key=lambda x: (x[1], x[0]))[:k]


def solve_row(fields, cols, C):
    d = dict(zip(cols, fields))
    qc = qty_cands(d['QTY'], C)
    uc = money_cands(d['UNIT'], C)
    ac = money_cands(d['AMOUNT'], C)
    q0 = min(qc, key=lambda v: (qc[v], v)) if qc else 1
    u0 = min(uc, key=lambda v: (uc[v], v)) if uc else 0
    if qc.get(q0) == 0 and uc.get(u0) == 0 and ac.get(q0 * u0) == 0:
        return [(0.0, q0, u0, q0 * u0)]
    qo = qty_obs(d['QTY'])
    uo = money_obs(d['UNIT'])
    ao = money_obs(d['AMOUNT'])
    memo = {}

    def wd(o, c):
        k = (o, c)
        if k not in memo:
            memo[k] = min(3.0, wdist(o, c, C)) if o else 3.0
        return memo[k]

    opts = {}

    def add(c, q, u, a):
        k = (q, u)
        if k not in opts or opts[k][0] > c:
            opts[k] = (c, q, u, a)

    Ql = _top(qc, 30)
    Ul = _top(uc, 40)
    Al = _top(ac, 40)
    for q, cq in Ql:
        for u, cu in Ul:
            p = cq + cu
            if p > 2.4:
                continue
            a = q * u
            ca = ac.get(a)
            if ca is None:
                ca = wd(ao, fmt_money(a)) if p <= 1.3 else 3.0
            add(p + ca, q, u, a)
    for q, cq in Ql:
        if cq > 1.3:
            continue
        for a, ca in Al:
            p = cq + ca
            if p > 1.3 or a % q:
                continue
            u = a // q
            if u <= 0:
                continue
            cu = uc.get(u)
            if cu is None:
                cu = wd(uo, fmt_money(u))
            add(p + cu, q, u, a)
    for u, cu in Ul:
        if cu > 1.3:
            continue
        for a, ca in Al:
            p = cu + ca
            if p > 1.3 or a % u:
                continue
            q = a // u
            if not (1 <= q <= 500):
                continue
            cq = qc.get(q)
            if cq is None:
                cq = wd(qo, str(q))
            add(p + cq, q, u, a)
    if not opts:
        return [(9.0, q0, u0, q0 * u0)]
    ol = sorted(opts.values(), key=lambda o: (o[0], o[1], o[2]))
    bc = ol[0][0]
    res = []
    for o in ol:
        if o[0] > bc + 2.1:
            break
        res.append(o)
        if len(res) >= 25:
            break
    return res


def subtotal_choice(sec_opts, sc):
    choice = [0] * len(sec_opts)
    if not sc or not sec_opts:
        return choice
    base = sum(o[0][3] for o in sec_opts)
    cur_cost = sc.get(base, 2.5)
    if cur_cost == 0:
        return choice
    changes = []
    for ri, opts in enumerate(sec_opts):
        for oi in range(1, len(opts)):
            dc = opts[oi][0] - opts[0][0]
            if dc > 2.5:
                continue
            changes.append((opts[oi][3] - opts[0][3], dc, ri, oi))
    best = (cur_cost, [])
    by_delta = {}
    for ch in changes:
        dl = ch[0]
        if dl not in by_delta or by_delta[dl][1] > ch[1]:
            by_delta[dl] = ch
        ns = base + dl
        if ns in sc:
            c = sc[ns] + ch[1]
            if c < best[0] - 1e-9:
                best = (c, [ch])
    if len(changes) <= 3000:
        for target, tcst in sc.items():
            need = target - base
            for ch in changes:
                other = by_delta.get(need - ch[0])
                if other is None or other[2] == ch[2]:
                    continue
                c = tcst + ch[1] + other[1] + 0.5
                if c < best[0] - 1e-9:
                    best = (c, [ch, other])
    for ch in best[1]:
        choice[ch[2]] = ch[3]
    return choice


def decode(state, params):
    t0 = time.process_time()
    al = state.get('aligned', {})
    cols = al.get('cols', ['CODE', 'QTY', 'UNIT', 'AMOUNT'])
    secs = al.get('sections', [])
    try:
        R = estimate_rates(secs, cols)
    except Exception:
        R = dict(DEFAULT_R)
    state['profile'] = R
    C = rate_costs(R)
    deadline = t0 + 0.55
    all_codes, all_opts, all_sc, all_choice = [], [], [], []
    for sec in secs:
        sec_codes = []
        sec_opts = []
        for r in sec['rows']:
            d = dict(zip(cols, r))
            try:
                code = fix_code(d['CODE'], R, deadline)
            except Exception:
                lt, dg = split_code(d['CODE'])
                code = _fallback(lt, dg)
            if time.process_time() - t0 > 0.6:
                qc = qty_cands(d['QTY'], C)
                uc = money_cands(d['UNIT'], C)
                q = min(qc, key=lambda v: qc[v])
                u = min(uc, key=lambda v: uc[v]) if uc else 0
                opts = [(0.0, q, u, q * u)]
            else:
                opts = solve_row(r, cols, C)
            sec_codes.append(code)
            sec_opts.append(opts)
        sc = money_cands(sec.get('subtotal'), C) if sec.get('subtotal') else {}
        if time.process_time() - t0 < 0.75:
            choice = subtotal_choice(sec_opts, sc)
        else:
            choice = [0] * len(sec_opts)
        all_codes.append(sec_codes)
        all_opts.append(sec_opts)
        all_sc.append(sc)
        all_choice.append(choice)

    try:
        if al.get('total') and len(secs) >= 1 and time.process_time() - t0 < 0.75:
            tcands = money_cands(al.get('total'), C)
            sums = []
            okc = []
            for si in range(len(secs)):
                s = sum(o[ci][3] for o, ci in zip(all_opts[si], all_choice[si]))
                sums.append(s)
                okc.append(all_sc[si].get(s))
            bad = [si for si in range(len(secs)) if okc[si] is None or okc[si] > 0]
            if len(bad) == 1:
                si = bad[0]
                others_ok = all(okc[j] is not None and okc[j] <= 1.3 for j in range(len(secs)) if j != si)
                if others_ok and all_opts[si]:
                    rest = sum(sums[j] for j in range(len(secs)) if j != si)
                    aug = dict(all_sc[si])
                    for T, c in tcands.items():
                        v = T - rest
                        if v <= 0:
                            continue
                        cc = c + 0.8
                        if v not in aug or aug[v] > cc:
                            aug[v] = cc
                    all_choice[si] = subtotal_choice(all_opts[si], aug)
    except Exception:
        pass

    items = []
    for si in range(len(all_opts)):
        for code, opts, ci in zip(all_codes[si], all_opts[si], all_choice[si]):
            o = opts[ci]
            items.append({'code': code, 'qty': int(o[1]), 'unit_cents': int(o[2])})
    state['output'] = {'items': items}
    return state

import re
import time
import math

LOOK_D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6', 'D': '0', 'Q': '0'}
LOOK_L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G', '4': 'A', '7': 'T', '3': 'E'}
MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63', '6': '50', '7': '12', '8': '30', '9': '43'}
INF = float('inf')


def _rev():
    r = {}
    for o, shown in MIS.items():
        for s in shown:
            r.setdefault(s, []).append(o)
    return r


REV = _rev()


def to_digits(s):
    out = []
    for ch in s:
        if ch.isdigit():
            out.append(ch)
        elif ch in LOOK_D:
            out.append(LOOK_D[ch])
    return ''.join(out)


def wdist(o, c):
    n = len(o)
    m = len(c)
    prev = [j * 1.05 for j in range(m + 1)]
    for i in range(1, n + 1):
        oi = o[i - 1]
        ins = 1.0 if (i >= 2 and o[i - 2] == oi) else 2.5
        cur = [prev[0] + ins] + [0.0] * m
        for j in range(1, m + 1):
            cj = c[j - 1]
            if oi == cj:
                s = prev[j - 1]
            else:
                s = prev[j - 1] + (1.0 if oi in MIS[cj] else 2.5)
            a = cur[j - 1] + 1.05
            if a < s:
                s = a
            b = prev[j] + ins
            if b < s:
                s = b
            cur[j] = s
        prev = cur
    return prev[m]


def money_parse(tok):
    s = ''
    for ch in (tok or '').strip():
        if ch.isdigit() or ch in '.,':
            s += ch
        elif ch in LOOK_D:
            s += LOOK_D[ch]
    m = re.match(r'^(\d*)[.,](\d*)$', s)
    if m:
        return [m.group(1), m.group(2)]
    return [re.sub(r'\D', '', s), None]


def mdist(p, v):
    ip = str(v // 100)
    fp = '%02d' % (v % 100)
    if p[1] is None:
        return wdist(p[0], ip + fp)
    return wdist(p[0], ip) + wdist(p[1], fp)


def code_check(letters, d):
    p1 = ord(letters[0]) - 64
    p2 = ord(letters[1]) - 64
    return (int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p1 + p2) % 10


def code_valid(letters, d):
    return len(d) == 5 and d.isdigit() and code_check(letters, d) == int(d[4])


def _best(res):
    if not res:
        return None
    return max(sorted(res), key=lambda k: res[k])


def _misread_cands(letters, d, res, w=1.0):
    for k in range(len(d)):
        for o in REV.get(d[k], []):
            nd = d[:k] + o + d[k + 1:]
            if code_valid(letters, nd):
                res[nd] = res.get(nd, 0.0) + w / len(MIS[o])
    return res


def _dup_dels(d):
    out = []
    for k in range(1, len(d)):
        if d[k] == d[k - 1]:
            nd = d[:k] + d[k + 1:]
            if nd not in out:
                out.append(nd)
    return out


def _ins_cands(letters, d, res, w=1.0):
    for k in range(len(d) + 1):
        for c in '0123456789':
            nd = d[:k] + c + d[k:]
            if code_valid(letters, nd):
                res[nd] = res.get(nd, 0.0) + w
    return res


def _fallback(letters, d):
    d = (d + '0000')[:4]
    return letters + d + str(code_check(letters, d))


def edits(ds, ins_lo, ins_hi, del_lo, del_hi):
    yield ds, 0.0
    n = len(ds)
    for k in range(n):
        for r in REV.get(ds[k], []):
            yield ds[:k] + r + ds[k + 1:], 1.0 + 0.02 * (len(MIS[r]) - 1)
    for k in range(max(0, del_lo), min(n, del_hi)):
        if (k > 0 and ds[k] == ds[k - 1]) or (k < n - 1 and ds[k] == ds[k + 1]):
            yield ds[:k] + ds[k + 1:], 1.0
    for k in range(max(0, ins_lo), min(n, ins_hi) + 1):
        for c in '0123456789':
            yield ds[:k] + c + ds[k:], 1.05


def _two_edit(letters, d):
    res = {}
    seen1 = {}
    for e1, c1 in edits(d, 0, len(d), 0, len(d)):
        if e1 in seen1 and seen1[e1] <= c1:
            continue
        seen1[e1] = c1
        if abs(len(e1) - 5) > 1:
            continue
        for e2, c2 in edits(e1, 0, len(e1), 0, len(e1)):
            if len(e2) == 5 and code_valid(letters, e2):
                res[e2] = res.get(e2, 0.0) + math.exp(-3.0 * (c1 + c2))
    return _best(res)


def fix_code(tok, allow2=True):
    t = re.sub(r'\s+', '', tok or '')
    letters = ''
    i = 0
    while len(letters) < 2 and i < len(t):
        ch = t[i]
        if ch.isalpha():
            letters += ch.upper()
        elif ch in LOOK_L:
            letters += LOOK_L[ch]
        i += 1
    while len(letters) < 2:
        letters += 'A'
    if not ('A' <= letters[0] <= 'Z' and 'A' <= letters[1] <= 'Z'):
        letters = 'AA'
    d = to_digits(t[i:])
    n = len(d)
    if n == 5:
        if code_valid(letters, d):
            return letters + d
        b = _best(_misread_cands(letters, d, {}))
        if b:
            return letters + b
        if allow2:
            b = _two_edit(letters, d)
            if b:
                return letters + b
        return _fallback(letters, d)
    if n == 6:
        res = {}
        for nd in _dup_dels(d):
            if code_valid(letters, nd):
                res[nd] = res.get(nd, 0.0) + 1.0
        b = _best(res)
        if b:
            return letters + b
        res = {}
        for nd in _dup_dels(d):
            _misread_cands(letters, nd, res, 0.3)
        for k in range(6):
            nd = d[:k] + d[k + 1:]
            if code_valid(letters, nd):
                res[nd] = res.get(nd, 0.0) + 0.2
        b = _best(res)
        if b:
            return letters + b
        return _fallback(letters, d[:5])
    if n == 4:
        b = _best(_ins_cands(letters, d, {}))
        if b:
            return letters + b
        return _fallback(letters, d)
    if n == 7:
        res = {}
        for a in _dup_dels(d):
            for nd in _dup_dels(a):
                if code_valid(letters, nd):
                    res[nd] = res.get(nd, 0.0) + 1.0
        b = _best(res)
        if b:
            return letters + b
        return _fallback(letters, d[:5])
    if n == 3:
        res = {}
        for k in range(4):
            for c in '0123456789':
                _ins_cands(letters, d[:k] + c + d[k:], res)
        b = _best(res)
        if b:
            return letters + b
        return _fallback(letters, d)
    if n > 7:
        return _fallback(letters, d[:5])
    return _fallback(letters, d)


def money_cands(tok):
    s = (tok or '').strip()
    s2 = ''
    for ch in s:
        if ch.isdigit() or ch in '.,':
            s2 += ch
        elif ch in LOOK_D:
            s2 += LOOK_D[ch]
    m = re.match(r'^(\d*)[.,](\d*)$', s2)
    if m:
        ip, fp = m.group(1), m.group(2)
        ds = ip + fp
        ni = len(ip)
        if len(fp) == 2:
            il, ih, dl, dh = 0, ni, 0, ni
        elif len(fp) == 1:
            il, ih, dl, dh = ni, len(ds), 0, 0
        elif len(fp) == 3:
            il, ih, dl, dh = 0, -1, ni, len(ds)
        else:
            il, ih, dl, dh = 0, len(ds), 0, len(ds)
    else:
        ds = re.sub(r'\D', '', s2)
        il, ih, dl, dh = 0, len(ds), 0, len(ds)
    out = {}
    for cand, c in edits(ds, il, ih, dl, dh):
        if not cand:
            continue
        v = int(cand)
        if v <= 0:
            continue
        if v not in out or out[v] > c:
            out[v] = c
    return out


def qty_cands(tok):
    s = re.sub(r'(?i)p\s*c\s*s', '', tok or '').strip()
    ds = to_digits(s)
    out = {}
    if not ds:
        for v in range(1, 10):
            out[v] = 1.05
        return out
    for cand, c in edits(ds, 0, len(ds), 0, len(ds)):
        if not cand:
            continue
        v = int(cand)
        if 1 <= v <= 500 and (v not in out or out[v] > c):
            out[v] = c
    if not out:
        out[max(1, min(500, int(ds[:3])))] = 2.0
    return out


def tok_type_cost(tok, col):
    t = tok.strip()
    if col == 'CODE':
        if re.match(r'^[A-Z0-9]{2}[0-9OlSBZGI]{4,6}$', t):
            return 0.0
        if re.match(r'^[A-Za-z0-9]{6,9}$', t):
            return 1.0
        if re.match(r'^[A-Za-z0-9]{4,5}$', t) and re.match(r'^[A-Z]', t):
            return 1.5
        return 3.0
    if col == 'QTY':
        if re.match(r'^[0-9OlSBZG]{0,4}( ?pcs)?$', t):
            return 0.0 if '.' not in t and ',' not in t else 2.0
        return 3.0
    if re.match(r"^[0-9OlSBZG']*[.,][0-9OlSBZG]{1,3}$", t):
        return 0.0
    if re.match(r"^[0-9OlSBZG']{2,}$", t):
        if re.match(r'^[A-Z]{2}', t):
            return 3.0
        return 0.6
    return 3.0


def looks_value(tok):
    t = tok.strip()
    if t == '':
        return True
    t = re.sub(r'\s*pcs$', '', t)
    if t == '':
        return True
    if not re.match(r"^[A-Za-z0-9.,']+$", t):
        return False
    if len(t) > 14:
        return False
    good = sum(1 for ch in t if ch.isdigit() or ch in LOOK_D or ch in ".,'")
    return good >= len(t) - 2 and good >= 1


def split_line(line, sep):
    if sep == '|':
        parts = line.split('|')
    elif sep == ';':
        parts = line.split(';')
    elif sep == '\t':
        parts = line.split('\t')
    else:
        parts = re.split(r' {3}', line.rstrip('\n'))
    parts = [p.strip() for p in parts]
    while parts and parts[-1] == '':
        parts.pop()
    while parts and parts[0] == '':
        parts.pop(0)
    return parts


def parse_doc(state, params):
    state['t0'] = time.process_time()
    text = state.get('input', {}).get('text', '') or ''
    lines = text.split('\n')
    cols = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    sep = ';'
    for ln in lines:
        if 'COLUMNS' in ln:
            body = ln.split('COLUMNS', 1)[1]
            body = body[1:] if body.startswith(':') else body
            pos = []
            for c in ['CODE', 'QTY', 'UNIT', 'AMOUNT']:
                pos.append((body.find(c), c))
            if all(p >= 0 for p, _ in pos):
                cols = [c for _, c in sorted(pos)]
            inner = body.strip()
            if '|' in inner:
                sep = '|'
            elif ';' in inner:
                sep = ';'
            elif '\t' in inner:
                sep = '\t'
            else:
                sep = '   '
            break
    sections = []
    cur = None
    total = None
    items_n = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if re.match(r'^=+\s*SECTION', s):
            cur = {'tokens': [], 'subtotal': None}
            sections.append(cur)
            continue
        if s.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'tokens': [], 'subtotal': None}
                sections.append(cur)
            cur['subtotal'] = s[len('SUBTOTAL'):].strip()
            continue
        if s.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s+(.*?)\s+ITEMS\s*(.*)$', s)
            if m:
                total = m.group(1)
                items_n = m.group(2)
            continue
        parts = split_line(ln.replace('\r', ''), sep)
        if not parts:
            continue
        suspect = not all(looks_value(p) for p in parts)
        if cur is None:
            cur = {'tokens': [], 'subtotal': None}
            sections.append(cur)
        for p in parts:
            cur['tokens'].append([p, bool(suspect or not looks_value(p))])
    state['doc'] = {'cols': cols, 'sections': sections, 'total': total, 'items_n': items_n}
    return state


def align_dp(toks, cols):
    n = len(toks)
    R = n // 3 + 2
    tc = [[tok_type_cost(t, c) for c in cols] for t, _ in toks]
    sk = [0.3 if s else 4.0 for _, s in toks]
    r4 = [None] * n
    r3 = [None] * n
    for i in range(n):
        if i + 4 <= n:
            r4[i] = sum(tc[i + k][k] for k in range(4))
        if i + 3 <= n:
            bm = None
            for miss in range(4):
                c = 3.5
                k2 = 0
                for k in range(4):
                    if k == miss:
                        continue
                    c += tc[i + k2][k]
                    k2 += 1
                if bm is None or c < bm[0]:
                    bm = (c, miss)
            r3[i] = bm
    best = [[INF] * (R + 1) for _ in range(n + 1)]
    back = [[None] * (R + 1) for _ in range(n + 1)]
    best[0][0] = 0.0
    for i in range(n):
        bi = best[i]
        for r in range(R + 1):
            b = bi[r]
            if b == INF:
                continue
            c = b + sk[i]
            if c < best[i + 1][r]:
                best[i + 1][r] = c
                back[i + 1][r] = ('skip', i, -1)
            if r < R:
                if r4[i] is not None:
                    c = b + r4[i]
                    if c < best[i + 4][r + 1]:
                        best[i + 4][r + 1] = c
                        back[i + 4][r + 1] = ('row', i, -1)
                if r3[i] is not None:
                    c = b + r3[i][0]
                    if c < best[i + 3][r + 1]:
                        best[i + 3][r + 1] = c
                        back[i + 3][r + 1] = ('row3', i, r3[i][1])
    return best[n], back


def reconstruct(toks, back, n, r):
    rows = []
    j = n
    rr = r
    while j > 0:
        bk = back[j][rr]
        if bk is None:
            break
        i = bk[1]
        if bk[0] == 'skip':
            j = i
            continue
        if bk[0] == 'row':
            rows.append([t for t, _ in toks[i:i + 4]])
        else:
            seg = [t for t, _ in toks[i:i + 3]]
            seg.insert(bk[2], '')
            rows.append(seg)
        j = i
        rr -= 1
    rows.reverse()
    return rows


def items_cands(s):
    out = {}
    if not s:
        return None, out
    ds = to_digits(s.strip())
    if not ds:
        return None, out
    raw = int(ds) if re.match(r'^\d+$', s.strip()) else None
    for cand, c in edits(ds, 0, len(ds), 0, len(ds)):
        if not cand:
            continue
        v = int(cand)
        if 1 <= v <= 80:
            if v not in out or out[v] > c:
                out[v] = c
    if raw is None:
        v = int(ds)
        if 1 <= v <= 80:
            out[v] = 0.5
    return raw, out


def align_rows(state, params):
    doc = state.get('doc', {})
    cols = doc.get('cols', ['CODE', 'QTY', 'UNIT', 'AMOUNT'])
    secs = doc.get('sections', [])
    dps = []
    for sec in secs:
        dps.append(align_dp(sec['tokens'], cols))
    tot = {0: (0.0, [])}
    for costs, _ in dps:
        nt = {}
        for k, (c, ch) in tot.items():
            for r, cr in enumerate(costs):
                if cr == INF:
                    continue
                v = c + cr
                kk = k + r
                if kk not in nt or nt[kk][0] > v:
                    nt[kk] = (v, ch + [r])
        tot = nt
    raw, ic = items_cands(doc.get('items_n'))
    bestk = None
    bests = INF
    for k in sorted(tot):
        c = tot[k][0]
        if raw is not None and k == raw:
            pen = 0.0
        elif k in ic:
            pen = 2.5
        else:
            pen = 6.0
        s = c + pen
        if s < bests - 1e-9:
            bests = s
            bestk = k
    rcounts = [0] * len(secs) if bestk is None else tot[bestk][1]
    out = []
    for si, sec in enumerate(secs):
        rc = rcounts[si] if si < len(rcounts) else 0
        rows = reconstruct(sec['tokens'], dps[si][1], len(sec['tokens']), rc)
        out.append({'rows': rows, 'sub': sec.get('subtotal')})
    state['rows'] = out
    return state


def solve_row(fields, cols):
    d = dict(zip(cols, fields))
    qc = qty_cands(d['QTY'])
    uc = money_cands(d['UNIT'])
    ac = money_cands(d['AMOUNT'])
    q0 = min(sorted(qc), key=lambda v: qc[v]) if qc else 1
    u0 = min(sorted(uc), key=lambda v: uc[v]) if uc else 1
    if qc.get(q0) == 0 and uc.get(u0) == 0 and ac.get(q0 * u0) == 0:
        return [[0.0, q0, u0, q0 * u0]]
    qo = to_digits(re.sub(r'(?i)p\s*c\s*s', '', d['QTY'] or '').strip())
    up = money_parse(d['UNIT'])
    ap = money_parse(d['AMOUNT'])

    def CQ(q):
        v = qc.get(q)
        return v if v is not None else min(4.0, wdist(qo, str(q)))

    def CU(u):
        v = uc.get(u)
        return v if v is not None else min(4.0, mdist(up, u))

    def CA(a):
        v = ac.get(a)
        return v if v is not None else min(4.0, mdist(ap, a))

    cand = {}
    for q, cq in qc.items():
        for u, cu in uc.items():
            s = cq + cu
            if s > 2.2:
                continue
            a = q * u
            ca = ac.get(a)
            if ca is None:
                if s > 1.1:
                    continue
                ca = CA(a)
            tc = s + ca
            key = (q, u)
            if key not in cand or cand[key] > tc:
                cand[key] = tc
    qs1 = [(q, c) for q, c in qc.items() if c <= 1.1]
    us1 = [(u, c) for u, c in uc.items() if c <= 1.1]
    as1 = [(a, c) for a, c in ac.items() if c <= 1.1]
    for q, cq in qs1:
        for a, ca in as1:
            if a % q:
                continue
            u = a // q
            if u <= 0 or (q, u) in cand:
                continue
            cand[(q, u)] = cq + ca + CU(u)
    for u, cu in us1:
        for a, ca in as1:
            if a % u:
                continue
            q = a // u
            if q < 1 or q > 500 or (q, u) in cand:
                continue
            cand[(q, u)] = CQ(q) + cu + ca
    if not cand:
        return [[9.0, q0, u0, q0 * u0]]
    lst = sorted(cand.items(), key=lambda kv: (kv[1], kv[0]))
    bc = lst[0][1]
    res = []
    for (q, u), c in lst:
        if c > bc + 3.0:
            break
        res.append([c, q, u, q * u])
        if len(res) >= 20:
            break
    return res


def decode_rows(state, params):
    t0 = state.get('t0', time.process_time())
    cols = state.get('doc', {}).get('cols', ['CODE', 'QTY', 'UNIT', 'AMOUNT'])
    dec = []
    for sec in state.get('rows', []):
        codes = []
        opts = []
        for r in sec['rows']:
            d = dict(zip(cols, r))
            el = time.process_time() - t0
            try:
                codes.append(fix_code(d['CODE'], allow2=(el < 0.5)))
            except Exception:
                codes.append('AA00000')
            if el > 0.65:
                qc = qty_cands(d['QTY'])
                uc = money_cands(d['UNIT'])
                q = min(sorted(qc), key=lambda v: qc[v])
                u = min(sorted(uc), key=lambda v: uc[v]) if uc else 1
                opts.append([[0.0, q, u, q * u]])
            else:
                try:
                    opts.append(solve_row(r, cols))
                except Exception:
                    opts.append([[9.0, 1, 1, 1]])
        dec.append({'codes': codes, 'opts': opts, 'sub': sec.get('sub')})
    state['dec'] = dec
    return state


def _section_beam(opts, sc, fast):
    MISS = 3.0
    CHG = 0.3
    BOUND = 6.0
    CAP = 2500
    states = {0: (0.0, None)}
    for ro in opts:
        base = ro[0][0]
        alts = []
        lim = 1 if fast else 12
        for oi, o in enumerate(ro[:lim]):
            dc = o[0] - base + (CHG if oi else 0.0)
            if dc <= 4.5:
                alts.append((oi, dc, o[3]))
        new = {}
        for s, (c, ch) in states.items():
            for oi, dc, a in alts:
                nc = c + dc
                if nc > BOUND:
                    continue
                ns = s + a
                e = new.get(ns)
                if e is None or e[0] > nc:
                    new[ns] = (nc, (oi, ch))
        if len(new) > CAP:
            ks = sorted(new.items(), key=lambda kv: (kv[1][0], kv[0]))[:CAP]
            new = dict(ks)
        states = new
    finals = []
    for s, (c, ch) in states.items():
        sub = 0.0 if sc is None else sc.get(s, MISS)
        finals.append((c + sub, s, ch))
    finals.sort(key=lambda x: (x[0], x[1]))
    return finals[:8]


def reconcile(state, params):
    t0 = state.get('t0', time.process_time())
    dec = state.get('dec', [])
    total = state.get('doc', {}).get('total')
    sec_lists = []
    for sec in dec:
        fast = time.process_time() - t0 > 0.8
        sc = money_cands(sec['sub']) if sec.get('sub') else None
        try:
            sec_lists.append(_section_beam(sec['opts'], sc, fast))
        except Exception:
            sec_lists.append([(0.0, sum(o[0][3] for o in sec['opts']), None)])
    picks = [0] * len(sec_lists)
    try:
        tc = money_cands(total) if total else None
        if tc is not None and sec_lists:
            comb = {0: (0.0, [])}
            for fl in sec_lists:
                new = {}
                for s, (c, pk) in comb.items():
                    for idx, f in enumerate(fl):
                        ns = s + f[1]
                        nc = c + f[0]
                        e = new.get(ns)
                        if e is None or e[0] > nc:
                            new[ns] = (nc, pk + [idx])
                if len(new) > 3000:
                    new = dict(sorted(new.items(), key=lambda kv: (kv[1][0], kv[0]))[:3000])
                comb = new
            best = None
            for s in sorted(comb):
                c, pk = comb[s]
                sc2 = c + tc.get(s, 3.0)
                if best is None or sc2 < best[0] - 1e-9:
                    best = (sc2, pk)
            if best is not None:
                picks = best[1]
    except Exception:
        picks = [0] * len(sec_lists)
    items = []
    for si, sec in enumerate(dec):
        n = len(sec['opts'])
        choice = [0] * n
        fl = sec_lists[si] if si < len(sec_lists) else []
        if fl:
            pi = picks[si] if si < len(picks) and picks[si] < len(fl) else 0
            ch = fl[pi][2]
            seq = []
            while ch is not None:
                seq.append(ch[0])
                ch = ch[1]
            seq.reverse()
            if len(seq) == n:
                choice = seq
        for code, opts, ci in zip(sec['codes'], sec['opts'], choice):
            o = opts[ci] if ci < len(opts) else opts[0]
            items.append({'code': code, 'qty': int(o[1]), 'unit_cents': int(o[2])})
    state['output'] = {'items': items}
    return state

import re
import time
import math

LOOK_D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6', 'D': '0', 'Q': '0'}
LOOK_L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G', '4': 'A', '7': 'T', '3': 'E'}
MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63', '6': '50', '7': '12', '8': '30', '9': '43'}
INF = float('inf')


def _rev():
    r = {}
    for o, shown in MIS.items():
        for s in shown:
            r.setdefault(s, []).append(o)
    return r


REV = _rev()


def to_digits(s):
    out = []
    for ch in s:
        if ch.isdigit():
            out.append(ch)
        elif ch in LOOK_D:
            out.append(LOOK_D[ch])
    return ''.join(out)


def wdist(o, c):
    n = len(o)
    m = len(c)
    prev = [j * 1.05 for j in range(m + 1)]
    for i in range(1, n + 1):
        oi = o[i - 1]
        ins = 1.0 if (i >= 2 and o[i - 2] == oi) else 2.5
        cur = [prev[0] + ins] + [0.0] * m
        for j in range(1, m + 1):
            cj = c[j - 1]
            if oi == cj:
                s = prev[j - 1]
            else:
                s = prev[j - 1] + (1.0 if oi in MIS[cj] else 2.5)
            a = cur[j - 1] + 1.05
            if a < s:
                s = a
            b = prev[j] + ins
            if b < s:
                s = b
            cur[j] = s
        prev = cur
    return prev[m]


def money_parse(tok):
    s = ''
    for ch in (tok or '').strip():
        if ch.isdigit() or ch in '.,':
            s += ch
        elif ch in LOOK_D:
            s += LOOK_D[ch]
    m = re.match(r'^(\d*)[.,](\d*)$', s)
    if m:
        return [m.group(1), m.group(2)]
    return [re.sub(r'\D', '', s), None]


def mdist(p, v):
    ip = str(v // 100)
    fp = '%02d' % (v % 100)
    if p[1] is None:
        return wdist(p[0], ip + fp)
    return wdist(p[0], ip) + wdist(p[1], fp)


def code_check(letters, d):
    p1 = ord(letters[0]) - 64
    p2 = ord(letters[1]) - 64
    return (int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p1 + p2) % 10


def code_valid(letters, d):
    return len(d) == 5 and d.isdigit() and code_check(letters, d) == int(d[4])


def _best(res):
    if not res:
        return None
    return max(sorted(res), key=lambda k: res[k])


def _misread_cands(letters, d, res, w=1.0):
    for k in range(len(d)):
        for o in REV.get(d[k], []):
            nd = d[:k] + o + d[k + 1:]
            if code_valid(letters, nd):
                res[nd] = res.get(nd, 0.0) + w / len(MIS[o])
    return res


def _dup_dels(d):
    out = []
    for k in range(1, len(d)):
        if d[k] == d[k - 1]:
            nd = d[:k] + d[k + 1:]
            if nd not in out:
                out.append(nd)
    return out


def _ins_cands(letters, d, res, w=1.0):
    for k in range(len(d) + 1):
        for c in '0123456789':
            nd = d[:k] + c + d[k:]
            if code_valid(letters, nd):
                res[nd] = res.get(nd, 0.0) + w
    return res


def _fallback(letters, d):
    d = (d + '0000')[:4]
    return letters + d + str(code_check(letters, d))


def edits(ds, ins_lo, ins_hi, del_lo, del_hi):
    yield ds, 0.0
    n = len(ds)
    for k in range(n):
        for r in REV.get(ds[k], []):
            yield ds[:k] + r + ds[k + 1:], 1.0 + 0.02 * (len(MIS[r]) - 1)
    for k in range(max(0, del_lo), min(n, del_hi)):
        if (k > 0 and ds[k] == ds[k - 1]) or (k < n - 1 and ds[k] == ds[k + 1]):
            yield ds[:k] + ds[k + 1:], 1.0
    for k in range(max(0, ins_lo), min(n, ins_hi) + 1):
        for c in '0123456789':
            yield ds[:k] + c + ds[k:], 1.05


def parse_code_tok(tok):
    t = re.sub(r'\s+', '', tok or '')
    letters = ''
    i = 0
    while len(letters) < 2 and i < len(t):
        ch = t[i]
        if ch.isalpha():
            letters += ch.upper()
        elif ch in LOOK_L:
            letters += LOOK_L[ch]
        i += 1
    while len(letters) < 2:
        letters += 'A'
    if not ('A' <= letters[0] <= 'Z' and 'A' <= letters[1] <= 'Z'):
        letters = 'AA'
    return letters, to_digits(t[i:])


def fix_code(tok):
    letters, d = parse_code_tok(tok)
    n = len(d)
    if n == 5:
        if code_valid(letters, d):
            return letters + d
        b = _best(_misread_cands(letters, d, {}))
        if b:
            return letters + b
        return _fallback(letters, d)
    if n == 6:
        res = {}
        for nd in _dup_dels(d):
            if code_valid(letters, nd):
                res[nd] = res.get(nd, 0.0) + 1.0
        b = _best(res)
        if b:
            return letters + b
        return _fallback(letters, d[:5])
    if n == 4:
        b = _best(_ins_cands(letters, d, {}))
        if b:
            return letters + b
        return _fallback(letters, d)
    return _fallback(letters, d[:5])


def reach5(d, maxops):
    out = set()
    if len(d) == 5:
        out.add(d)
    frontier = [d]
    seen = {d}
    for step in range(maxops):
        rem = maxops - step - 1
        nf = []

        def add(t):
            if t in seen or abs(len(t) - 5) > rem:
                return
            seen.add(t)
            nf.append(t)
            if len(t) == 5:
                out.add(t)

        for s in frontier:
            L = len(s)
            for k in range(L):
                for r in REV.get(s[k], []):
                    add(s[:k] + r + s[k + 1:])
            if L >= 5:
                for k in range(1, L):
                    if s[k] == s[k - 1]:
                        add(s[:k] + s[k + 1:])
            if L < 5:
                for k in range(L + 1):
                    for c in '0123456789':
                        add(s[:k] + c + s[k:])
        frontier = nf
    return out


def chan_lik(o, s, prof):
    pm, pl, pd = prof
    q0 = max(0.05, 1.0 - pm - pl - pd)
    n = len(o)
    m = len(s)
    f = [[0.0] * (m + 1) for _ in range(n + 1)]
    f[0][0] = 1.0
    for i in range(n):
        oi = o[i]
        mo = MIS[oi]
        fi = f[i]
        fn = f[i + 1]
        for j in range(m + 1):
            v = fi[j]
            if v == 0.0:
                continue
            fn[j] += v * pl
            if j < m:
                sj = s[j]
                if sj == oi:
                    fn[j + 1] += v * q0
                    if j + 1 < m and s[j + 1] == oi:
                        fn[j + 2] += v * pd
                elif sj in mo:
                    fn[j + 1] += v * pm / len(mo)
    return f[n][m]


def repair_code(tok, prof, budget_ok):
    letters, d = parse_code_tok(tok)
    n = len(d)
    if n == 5 and code_valid(letters, d):
        return letters + d
    if n < 2 or n > 8:
        return fix_code(tok)
    off = abs(n - 5)
    maxops = 2 if off <= 1 else min(3, off + 1)
    if not budget_ok:
        maxops = max(1, off)
        if maxops > 2:
            return fix_code(tok)
    cands = reach5(d, maxops)
    best = None
    for c in sorted(cands):
        if not code_valid(letters, c):
            continue
        lk = chan_lik(c, d, prof)
        if lk <= 0:
            continue
        if best is None or lk > best[0] * (1 + 1e-9):
            best = (lk, c)
    if best is None:
        return fix_code(tok)
    return letters + best[1]


def money_cands(tok):
    s = (tok or '').strip()
    s2 = ''
    for ch in s:
        if ch.isdigit() or ch in '.,':
            s2 += ch
        elif ch in LOOK_D:
            s2 += LOOK_D[ch]
    m = re.match(r'^(\d*)[.,](\d*)$', s2)
    if m:
        ip, fp = m.group(1), m.group(2)
        ds = ip + fp
        ni = len(ip)
        if len(fp) == 2:
            il, ih, dl, dh = 0, ni, 0, ni
        elif len(fp) == 1:
            il, ih, dl, dh = ni, len(ds), 0, 0
        elif len(fp) == 3:
            il, ih, dl, dh = 0, -1, ni, len(ds)
        else:
            il, ih, dl, dh = 0, len(ds), 0, len(ds)
    else:
        ds = re.sub(r'\D', '', s2)
        il, ih, dl, dh = 0, len(ds), 0, len(ds)
    out = {}
    for cand, c in edits(ds, il, ih, dl, dh):
        if not cand:
            continue
        v = int(cand)
        if v <= 0:
            continue
        if v not in out or out[v] > c:
            out[v] = c
    return out


def qty_cands(tok):
    s = re.sub(r'(?i)p\s*c\s*s', '', tok or '').strip()
    ds = to_digits(s)
    out = {}
    if not ds:
        for v in range(1, 10):
            out[v] = 1.05
        return out
    for cand, c in edits(ds, 0, len(ds), 0, len(ds)):
        if not cand:
            continue
        v = int(cand)
        if 1 <= v <= 500 and (v not in out or out[v] > c):
            out[v] = c
    if not out:
        out[max(1, min(500, int(ds[:3])))] = 2.0
    return out


def tok_type_cost(tok, col):
    t = tok.strip()
    if col == 'CODE':
        if re.match(r'^[A-Z0-9]{2}[0-9OlSBZGI]{4,6}$', t):
            return 0.0
        if re.match(r'^[A-Za-z0-9]{6,9}$', t):
            return 1.0
        if re.match(r'^[A-Za-z0-9]{4,5}$', t) and re.match(r'^[A-Z]', t):
            return 1.5
        return 3.0
    if col == 'QTY':
        if re.match(r'^[0-9OlSBZG]{0,4}( ?pcs)?$', t):
            return 0.0 if '.' not in t and ',' not in t else 2.0
        return 3.0
    if re.match(r"^[0-9OlSBZG']*[.,][0-9OlSBZG]{1,3}$", t):
        return 0.0
    if re.match(r"^[0-9OlSBZG']{2,}$", t):
        if re.match(r'^[A-Z]{2}', t):
            return 3.0
        return 0.6
    return 3.0


def looks_value(tok):
    t = tok.strip()
    if t == '':
        return True
    t = re.sub(r'\s*pcs$', '', t)
    if t == '':
        return True
    if not re.match(r"^[A-Za-z0-9.,']+$", t):
        return False
    if len(t) > 14:
        return False
    good = sum(1 for ch in t if ch.isdigit() or ch in LOOK_D or ch in ".,'")
    return good >= len(t) - 2 and good >= 1


def split_line(line, sep):
    if sep == '|':
        parts = line.split('|')
    elif sep == ';':
        parts = line.split(';')
    elif sep == '\t':
        parts = line.split('\t')
    else:
        parts = re.split(r' {3}', line.rstrip('\n'))
    parts = [p.strip() for p in parts]
    while parts and parts[-1] == '':
        parts.pop()
    while parts and parts[0] == '':
        parts.pop(0)
    return parts


def parse_doc(state, params):
    state['t0'] = time.process_time()
    text = state.get('input', {}).get('text', '') or ''
    lines = text.split('\n')
    cols = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    sep = ';'
    for ln in lines:
        if 'COLUMNS' in ln:
            body = ln.split('COLUMNS', 1)[1]
            body = body[1:] if body.startswith(':') else body
            pos = []
            for c in ['CODE', 'QTY', 'UNIT', 'AMOUNT']:
                pos.append((body.find(c), c))
            if all(p >= 0 for p, _ in pos):
                cols = [c for _, c in sorted(pos)]
            inner = body.strip()
            if '|' in inner:
                sep = '|'
            elif ';' in inner:
                sep = ';'
            elif '\t' in inner:
                sep = '\t'
            else:
                sep = '   '
            break
    sections = []
    cur = None
    total = None
    items_n = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if re.match(r'^=+\s*SECTION', s):
            cur = {'tokens': [], 'subtotal': None}
            sections.append(cur)
            continue
        if s.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'tokens': [], 'subtotal': None}
                sections.append(cur)
            cur['subtotal'] = s[len('SUBTOTAL'):].strip()
            continue
        if s.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s+(.*?)\s+ITEMS\s*(.*)$', s)
            if m:
                total = m.group(1)
                items_n = m.group(2)
            continue
        parts = split_line(ln.replace('\r', ''), sep)
        if not parts:
            continue
        suspect = not all(looks_value(p) for p in parts)
        if cur is None:
            cur = {'tokens': [], 'subtotal': None}
            sections.append(cur)
        for p in parts:
            cur['tokens'].append([p, bool(suspect or not looks_value(p))])
    state['doc'] = {'cols': cols, 'sections': sections, 'total': total, 'items_n': items_n}
    return state


def align_dp(toks, cols):
    n = len(toks)
    R = n // 3 + 2
    tc = [[tok_type_cost(t, c) for c in cols] for t, _ in toks]
    sk = [0.3 if s else 4.0 for _, s in toks]
    r4 = [None] * n
    r3 = [None] * n
    for i in range(n):
        if i + 4 <= n:
            r4[i] = sum(tc[i + k][k] for k in range(4))
        if i + 3 <= n:
            bm = None
            for miss in range(4):
                c = 3.5
                k2 = 0
                for k in range(4):
                    if k == miss:
                        continue
                    c += tc[i + k2][k]
                    k2 += 1
                if bm is None or c < bm[0]:
                    bm = (c, miss)
            r3[i] = bm
    best = [[INF] * (R + 1) for _ in range(n + 1)]
    back = [[None] * (R + 1) for _ in range(n + 1)]
    best[0][0] = 0.0
    for i in range(n):
        bi = best[i]
        for r in range(R + 1):
            b = bi[r]
            if b == INF:
                continue
            c = b + sk[i]
            if c < best[i + 1][r]:
                best[i + 1][r] = c
                back[i + 1][r] = ('skip', i, -1)
            if r < R:
                if r4[i] is not None:
                    c = b + r4[i]
                    if c < best[i + 4][r + 1]:
                        best[i + 4][r + 1] = c
                        back[i + 4][r + 1] = ('row', i, -1)
                if r3[i] is not None:
                    c = b + r3[i][0]
                    if c < best[i + 3][r + 1]:
                        best[i + 3][r + 1] = c
                        back[i + 3][r + 1] = ('row3', i, r3[i][1])
    return best[n], back


def reconstruct(toks, back, n, r):
    rows = []
    j = n
    rr = r
    while j > 0:
        bk = back[j][rr]
        if bk is None:
            break
        i = bk[1]
        if bk[0] == 'skip':
            j = i
            continue
        if bk[0] == 'row':
            rows.append([t for t, _ in toks[i:i + 4]])
        else:
            seg = [t for t, _ in toks[i:i + 3]]
            seg.insert(bk[2], '')
            rows.append(seg)
        j = i
        rr -= 1
    rows.reverse()
    return rows


def items_cands(s):
    out = {}
    if not s:
        return None, out
    ds = to_digits(s.strip())
    if not ds:
        return None, out
    raw = int(ds) if re.match(r'^\d+$', s.strip()) else None
    for cand, c in edits(ds, 0, len(ds), 0, len(ds)):
        if not cand:
            continue
        v = int(cand)
        if 1 <= v <= 80:
            if v not in out or out[v] > c:
                out[v] = c
    if raw is None:
        v = int(ds)
        if 1 <= v <= 80:
            out[v] = 0.5
    return raw, out


def align_rows(state, params):
    doc = state.get('doc', {})
    cols = doc.get('cols', ['CODE', 'QTY', 'UNIT', 'AMOUNT'])
    secs = doc.get('sections', [])
    dps = []
    for sec in secs:
        dps.append(align_dp(sec['tokens'], cols))
    tot = {0: (0.0, [])}
    for costs, _ in dps:
        nt = {}
        for k, (c, ch) in tot.items():
            for r, cr in enumerate(costs):
                if cr == INF:
                    continue
                v = c + cr
                kk = k + r
                if kk not in nt or nt[kk][0] > v:
                    nt[kk] = (v, ch + [r])
        tot = nt
    raw, ic = items_cands(doc.get('items_n'))
    bestk = None
    bests = INF
    for k in sorted(tot):
        c = tot[k][0]
        if raw is not None and k == raw:
            pen = 0.0
        elif k in ic:
            pen = 2.5
        else:
            pen = 6.0
        s = c + pen
        if s < bests - 1e-9:
            bests = s
            bestk = k
    rcounts = [0] * len(secs) if bestk is None else tot[bestk][1]
    out = []
    for si, sec in enumerate(secs):
        rc = rcounts[si] if si < len(rcounts) else 0
        rows = reconstruct(sec['tokens'], dps[si][1], len(sec['tokens']), rc)
        out.append({'rows': rows, 'sub': sec.get('subtotal')})
    state['rows'] = out
    return state


def solve_row(fields, cols):
    d = dict(zip(cols, fields))
    qc = qty_cands(d['QTY'])
    uc = money_cands(d['UNIT'])
    ac = money_cands(d['AMOUNT'])
    q0 = min(sorted(qc), key=lambda v: qc[v]) if qc else 1
    u0 = min(sorted(uc), key=lambda v: uc[v]) if uc else 1
    if qc.get(q0) == 0 and uc.get(u0) == 0 and ac.get(q0 * u0) == 0:
        return [[0.0, q0, u0, q0 * u0]]
    qo = to_digits(re.sub(r'(?i)p\s*c\s*s', '', d['QTY'] or '').strip())
    up = money_parse(d['UNIT'])
    ap = money_parse(d['AMOUNT'])

    def CQ(q):
        v = qc.get(q)
        return v if v is not None else min(4.0, wdist(qo, str(q)))

    def CU(u):
        v = uc.get(u)
        return v if v is not None else min(4.0, mdist(up, u))

    def CA(a):
        v = ac.get(a)
        return v if v is not None else min(4.0, mdist(ap, a))

    cand = {}
    for q, cq in qc.items():
        for u, cu in uc.items():
            s = cq + cu
            if s > 2.2:
                continue
            a = q * u
            ca = ac.get(a)
            if ca is None:
                if s > 1.1:
                    continue
                ca = CA(a)
            tc = s + ca
            key = (q, u)
            if key not in cand or cand[key] > tc:
                cand[key] = tc
    qs1 = [(q, c) for q, c in qc.items() if c <= 1.1]
    us1 = [(u, c) for u, c in uc.items() if c <= 1.1]
    as1 = [(a, c) for a, c in ac.items() if c <= 1.1]
    for q, cq in qs1:
        for a, ca in as1:
            if a % q:
                continue
            u = a // q
            if u <= 0 or (q, u) in cand:
                continue
            cand[(q, u)] = cq + ca + CU(u)
    for u, cu in us1:
        for a, ca in as1:
            if a % u:
                continue
            q = a // u
            if q < 1 or q > 500 or (q, u) in cand:
                continue
            cand[(q, u)] = CQ(q) + cu + ca
    if not cand:
        return [[9.0, q0, u0, q0 * u0]]
    lst = sorted(cand.items(), key=lambda kv: (kv[1], kv[0]))
    bc = lst[0][1]
    res = []
    for (q, u), c in lst:
        if c > bc + 3.0:
            break
        res.append([c, q, u, q * u])
        if len(res) >= 20:
            break
    return res


def decode_rows(state, params):
    t0 = state.get('t0', time.process_time())
    cols = state.get('doc', {}).get('cols', ['CODE', 'QTY', 'UNIT', 'AMOUNT'])
    dec = []
    for sec in state.get('rows', []):
        ctoks = []
        opts = []
        for r in sec['rows']:
            d = dict(zip(cols, r))
            ctoks.append(d['CODE'])
            el = time.process_time() - t0
            if el > 0.6:
                qc = qty_cands(d['QTY'])
                uc = money_cands(d['UNIT'])
                q = min(sorted(qc), key=lambda v: qc[v])
                u = min(sorted(uc), key=lambda v: uc[v]) if uc else 1
                opts.append([[9.0, q, u, q * u]])
            else:
                try:
                    opts.append(solve_row(r, cols))
                except Exception:
                    opts.append([[9.0, 1, 1, 1]])
        dec.append({'code_toks': ctoks, 'codes': [], 'opts': opts, 'sub': sec.get('sub')})
    state['dec'] = dec
    return state


def _classify(shown, true):
    if shown == true:
        return (0, 0, 0)
    ls = len(shown)
    lt = len(true)
    if ls == lt:
        k = sum(1 for a, b in zip(shown, true) if a != b)
        if k <= 2:
            return (k, 0, 0)
        return None
    if ls == lt + 1:
        for k in range(1, ls):
            if shown[k] == shown[k - 1] and shown[:k] + shown[k + 1:] == true:
                return (0, 0, 1)
        return None
    if ls == lt - 1:
        for k in range(lt):
            if true[:k] + true[k + 1:] == shown:
                return (0, 1, 0)
        return None
    return None


def build_profile(state, params):
    cols = state.get('doc', {}).get('cols', ['CODE', 'QTY', 'UNIT', 'AMOUNT'])
    nm = nl = nd = 0
    N = 0
    try:
        for sec, dsec in zip(state.get('rows', []), state.get('dec', [])):
            for r, ro in zip(sec['rows'], dsec['opts']):
                if not ro or ro[0][0] >= 5.0:
                    continue
                o = ro[0]
                d = dict(zip(cols, r))
                pairs = [
                    (to_digits(re.sub(r'(?i)p\s*c\s*s', '', d['QTY'] or '')), str(o[1])),
                    (to_digits(d['UNIT'] or ''), str(o[2] // 100) + '%02d' % (o[2] % 100)),
                    (to_digits(d['AMOUNT'] or ''), str(o[3] // 100) + '%02d' % (o[3] % 100)),
                ]
                for sh, tr in pairs:
                    if not sh:
                        continue
                    c = _classify(sh, tr)
                    if c is None:
                        continue
                    nm += c[0]
                    nl += c[1]
                    nd += c[2]
                    N += len(tr)
    except Exception:
        pass
    den = N + 8.0
    pm = max(1e-4, (nm + 0.4) / den)
    pl = max(1e-4, (nl + 0.4) / den)
    pd = max(1e-4, (nd + 0.4) / den)
    state['profile'] = [pm, pl, pd]
    return state


def repair_codes(state, params):
    t0 = state.get('t0', time.process_time())
    prof = state.get('profile') or [0.02, 0.02, 0.02]
    for sec in state.get('dec', []):
        codes = []
        for tok in sec.get('code_toks', []):
            el = time.process_time() - t0
            try:
                codes.append(repair_code(tok, prof, el < 0.6))
            except Exception:
                try:
                    codes.append(fix_code(tok))
                except Exception:
                    codes.append('AA00000')
        sec['codes'] = codes
    return state


def _section_beam(opts, sc, fast):
    MISS = 3.0
    CHG = 0.3
    BOUND = 6.0
    CAP = 2500
    states = {0: (0.0, None)}
    for ro in opts:
        base = ro[0][0]
        alts = []
        lim = 1 if fast else 12
        for oi, o in enumerate(ro[:lim]):
            dc = o[0] - base + (CHG if oi else 0.0)
            if dc <= 4.5:
                alts.append((oi, dc, o[3]))
        new = {}
        for s, (c, ch) in states.items():
            for oi, dc, a in alts:
                nc = c + dc
                if nc > BOUND:
                    continue
                ns = s + a
                e = new.get(ns)
                if e is None or e[0] > nc:
                    new[ns] = (nc, (oi, ch))
        if len(new) > CAP:
            ks = sorted(new.items(), key=lambda kv: (kv[1][0], kv[0]))[:CAP]
            new = dict(ks)
        states = new
    finals = []
    for s, (c, ch) in states.items():
        sub = 0.0 if sc is None else sc.get(s, MISS)
        finals.append((c + sub, s, ch))
    finals.sort(key=lambda x: (x[0], x[1]))
    return finals[:8]


def reconcile(state, params):
    t0 = state.get('t0', time.process_time())
    dec = state.get('dec', [])
    total = state.get('doc', {}).get('total')
    sec_lists = []
    for sec in dec:
        fast = time.process_time() - t0 > 0.8
        sc = money_cands(sec['sub']) if sec.get('sub') else None
        try:
            sec_lists.append(_section_beam(sec['opts'], sc, fast))
        except Exception:
            sec_lists.append([(0.0, sum(o[0][3] for o in sec['opts']), None)])
    picks = [0] * len(sec_lists)
    try:
        tc = money_cands(total) if total else None
        if tc is not None and sec_lists:
            comb = {0: (0.0, [])}
            for fl in sec_lists:
                new = {}
                for s, (c, pk) in comb.items():
                    for idx, f in enumerate(fl):
                        ns = s + f[1]
                        nc = c + f[0]
                        e = new.get(ns)
                        if e is None or e[0] > nc:
                            new[ns] = (nc, pk + [idx])
                if len(new) > 3000:
                    new = dict(sorted(new.items(), key=lambda kv: (kv[1][0], kv[0]))[:3000])
                comb = new
            best = None
            for s in sorted(comb):
                c, pk = comb[s]
                sc2 = c + tc.get(s, 3.0)
                if best is None or sc2 < best[0] - 1e-9:
                    best = (sc2, pk)
            if best is not None:
                picks = best[1]
    except Exception:
        picks = [0] * len(sec_lists)
    items = []
    for si, sec in enumerate(dec):
        n = len(sec['opts'])
        choice = [0] * n
        fl = sec_lists[si] if si < len(sec_lists) else []
        if fl:
            pi = picks[si] if si < len(picks) and picks[si] < len(fl) else 0
            ch = fl[pi][2]
            seq = []
            while ch is not None:
                seq.append(ch[0])
                ch = ch[1]
            seq.reverse()
            if len(seq) == n:
                choice = seq
        codes = sec.get('codes') or []
        for idx in range(n):
            opts = sec['opts'][idx]
            ci = choice[idx]
            code = codes[idx] if idx < len(codes) else 'AA00000'
            o = opts[ci] if ci < len(opts) else opts[0]
            items.append({'code': code, 'qty': int(o[1]), 'unit_cents': int(o[2])})
    state['output'] = {'items': items}
    return state

import re
import time
import math

LOOK_D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6', 'D': '0', 'Q': '0'}
LOOK_L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G', '4': 'A', '7': 'T', '3': 'E'}
MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63', '6': '50', '7': '12', '8': '30', '9': '43'}
INF = float('inf')


def _rev():
    r = {}
    for o, shown in MIS.items():
        for s in shown:
            r.setdefault(s, []).append(o)
    return r


REV = _rev()


def to_digits(s):
    out = []
    for ch in s:
        if ch.isdigit():
            out.append(ch)
        elif ch in LOOK_D:
            out.append(LOOK_D[ch])
    return ''.join(out)


def wdist(o, c):
    n = len(o)
    m = len(c)
    prev = [j * 1.05 for j in range(m + 1)]
    for i in range(1, n + 1):
        oi = o[i - 1]
        ins = 1.0 if (i >= 2 and o[i - 2] == oi) else 2.5
        cur = [prev[0] + ins] + [0.0] * m
        for j in range(1, m + 1):
            cj = c[j - 1]
            if oi == cj:
                s = prev[j - 1]
            else:
                s = prev[j - 1] + (1.0 if oi in MIS[cj] else 2.5)
            a = cur[j - 1] + 1.05
            if a < s:
                s = a
            b = prev[j] + ins
            if b < s:
                s = b
            cur[j] = s
        prev = cur
    return prev[m]


def money_parse(tok):
    s = ''
    for ch in (tok or '').strip():
        if ch.isdigit() or ch in '.,':
            s += ch
        elif ch in LOOK_D:
            s += LOOK_D[ch]
    m = re.match(r'^(\d*)[.,](\d*)$', s)
    if m:
        return [m.group(1), m.group(2)]
    return [re.sub(r'\D', '', s), None]


def mdist(p, v):
    ip = str(v // 100)
    fp = '%02d' % (v % 100)
    if p[1] is None:
        return wdist(p[0], ip + fp)
    return wdist(p[0], ip) + wdist(p[1], fp)


def code_check(letters, d):
    p1 = ord(letters[0]) - 64
    p2 = ord(letters[1]) - 64
    return (int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p1 + p2) % 10


def code_valid(letters, d):
    return len(d) == 5 and d.isdigit() and code_check(letters, d) == int(d[4])


def _best(res):
    if not res:
        return None
    return max(sorted(res), key=lambda k: res[k])


def _misread_cands(letters, d, res, w=1.0):
    for k in range(len(d)):
        for o in REV.get(d[k], []):
            nd = d[:k] + o + d[k + 1:]
            if code_valid(letters, nd):
                res[nd] = res.get(nd, 0.0) + w / len(MIS[o])
    return res


def _dup_dels(d):
    out = []
    for k in range(1, len(d)):
        if d[k] == d[k - 1]:
            nd = d[:k] + d[k + 1:]
            if nd not in out:
                out.append(nd)
    return out


def _ins_cands(letters, d, res, w=1.0):
    for k in range(len(d) + 1):
        for c in '0123456789':
            nd = d[:k] + c + d[k:]
            if code_valid(letters, nd):
                res[nd] = res.get(nd, 0.0) + w
    return res


def _fallback(letters, d):
    d = (d + '0000')[:4]
    return letters + d + str(code_check(letters, d))


def edits(ds, ins_lo, ins_hi, del_lo, del_hi):
    yield ds, 0.0
    n = len(ds)
    for k in range(n):
        for r in REV.get(ds[k], []):
            yield ds[:k] + r + ds[k + 1:], 1.0 + 0.02 * (len(MIS[r]) - 1)
    for k in range(max(0, del_lo), min(n, del_hi)):
        if (k > 0 and ds[k] == ds[k - 1]) or (k < n - 1 and ds[k] == ds[k + 1]):
            yield ds[:k] + ds[k + 1:], 1.0
    for k in range(max(0, ins_lo), min(n, ins_hi) + 1):
        for c in '0123456789':
            yield ds[:k] + c + ds[k:], 1.05


def _two_edit(letters, d):
    res = {}
    seen1 = {}
    for e1, c1 in edits(d, 0, len(d), 0, len(d)):
        if e1 in seen1 and seen1[e1] <= c1:
            continue
        seen1[e1] = c1
        if abs(len(e1) - 5) > 1:
            continue
        for e2, c2 in edits(e1, 0, len(e1), 0, len(e1)):
            if len(e2) == 5 and code_valid(letters, e2):
                res[e2] = res.get(e2, 0.0) + math.exp(-3.0 * (c1 + c2))
    return _best(res)


def split_code(tok):
    t = re.sub(r'\s+', '', tok or '')
    letters = ''
    i = 0
    while len(letters) < 2 and i < len(t):
        ch = t[i]
        if ch.isalpha():
            letters += ch.upper()
        elif ch in LOOK_L:
            letters += LOOK_L[ch]
        i += 1
    while len(letters) < 2:
        letters += 'A'
    if not ('A' <= letters[0] <= 'Z' and 'A' <= letters[1] <= 'Z'):
        letters = 'AA'
    return letters, to_digits(t[i:])


def fix_code(tok, allow2=True):
    letters, d = split_code(tok)
    n = len(d)
    if n == 5:
        if code_valid(letters, d):
            return letters + d
        b = _best(_misread_cands(letters, d, {}))
        if b:
            return letters + b
        if allow2:
            b = _two_edit(letters, d)
            if b:
                return letters + b
        return _fallback(letters, d)
    if n == 6:
        res = {}
        for nd in _dup_dels(d):
            if code_valid(letters, nd):
                res[nd] = res.get(nd, 0.0) + 1.0
        b = _best(res)
        if b:
            return letters + b
        res = {}
        for nd in _dup_dels(d):
            _misread_cands(letters, nd, res, 0.3)
        for k in range(6):
            nd = d[:k] + d[k + 1:]
            if code_valid(letters, nd):
                res[nd] = res.get(nd, 0.0) + 0.2
        b = _best(res)
        if b:
            return letters + b
        return _fallback(letters, d[:5])
    if n == 4:
        b = _best(_ins_cands(letters, d, {}))
        if b:
            return letters + b
        return _fallback(letters, d)
    if n == 7:
        res = {}
        for a in _dup_dels(d):
            for nd in _dup_dels(a):
                if code_valid(letters, nd):
                    res[nd] = res.get(nd, 0.0) + 1.0
        b = _best(res)
        if b:
            return letters + b
        return _fallback(letters, d[:5])
    if n == 3:
        res = {}
        for k in range(4):
            for c in '0123456789':
                _ins_cands(letters, d[:k] + c + d[k:], res)
        b = _best(res)
        if b:
            return letters + b
        return _fallback(letters, d)
    if n > 7:
        return _fallback(letters, d[:5])
    return _fallback(letters, d)


def money_cands(tok):
    s = (tok or '').strip()
    s2 = ''
    for ch in s:
        if ch.isdigit() or ch in '.,':
            s2 += ch
        elif ch in LOOK_D:
            s2 += LOOK_D[ch]
    m = re.match(r'^(\d*)[.,](\d*)$', s2)
    if m:
        ip, fp = m.group(1), m.group(2)
        ds = ip + fp
        ni = len(ip)
        if len(fp) == 2:
            il, ih, dl, dh = 0, ni, 0, ni
        elif len(fp) == 1:
            il, ih, dl, dh = ni, len(ds), 0, 0
        elif len(fp) == 3:
            il, ih, dl, dh = 0, -1, ni, len(ds)
        else:
            il, ih, dl, dh = 0, len(ds), 0, len(ds)
    else:
        ds = re.sub(r'\D', '', s2)
        il, ih, dl, dh = 0, len(ds), 0, len(ds)
    out = {}
    for cand, c in edits(ds, il, ih, dl, dh):
        if not cand:
            continue
        v = int(cand)
        if v <= 0:
            continue
        if v not in out or out[v] > c:
            out[v] = c
    return out


def qty_cands(tok):
    s = re.sub(r'(?i)p\s*c\s*s', '', tok or '').strip()
    ds = to_digits(s)
    out = {}
    if not ds:
        for v in range(1, 10):
            out[v] = 1.05
        return out
    for cand, c in edits(ds, 0, len(ds), 0, len(ds)):
        if not cand:
            continue
        v = int(cand)
        if 1 <= v <= 500 and (v not in out or out[v] > c):
            out[v] = c
    if not out:
        out[max(1, min(500, int(ds[:3])))] = 2.0
    return out


def tok_type_cost(tok, col):
    t = tok.strip()
    if col == 'CODE':
        if re.match(r'^[A-Z0-9]{2}[0-9OlSBZGI]{4,6}$', t):
            return 0.0
        if re.match(r'^[A-Za-z0-9]{6,9}$', t):
            return 1.0
        if re.match(r'^[A-Za-z0-9]{4,5}$', t) and re.match(r'^[A-Z]', t):
            return 1.5
        return 3.0
    if col == 'QTY':
        if re.match(r'^[0-9OlSBZG]{0,4}( ?pcs)?$', t):
            return 0.0 if '.' not in t and ',' not in t else 2.0
        return 3.0
    if re.match(r"^[0-9OlSBZG']*[.,][0-9OlSBZG]{1,3}$", t):
        return 0.0
    if re.match(r"^[0-9OlSBZG']{2,}$", t):
        if re.match(r'^[A-Z]{2}', t):
            return 3.0
        return 0.6
    return 3.0


def looks_value(tok):
    t = tok.strip()
    if t == '':
        return True
    t = re.sub(r'\s*pcs$', '', t)
    if t == '':
        return True
    if not re.match(r"^[A-Za-z0-9.,']+$", t):
        return False
    if len(t) > 14:
        return False
    good = sum(1 for ch in t if ch.isdigit() or ch in LOOK_D or ch in ".,'")
    return good >= len(t) - 2 and good >= 1


def split_line(line, sep):
    if sep == '|':
        parts = line.split('|')
    elif sep == ';':
        parts = line.split(';')
    elif sep == '\t':
        parts = line.split('\t')
    else:
        parts = re.split(r' {3}', line.rstrip('\n'))
    parts = [p.strip() for p in parts]
    while parts and parts[-1] == '':
        parts.pop()
    while parts and parts[0] == '':
        parts.pop(0)
    return parts


def parse_doc(state, params):
    state['t0'] = time.process_time()
    text = state.get('input', {}).get('text', '') or ''
    lines = text.split('\n')
    cols = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    sep = ';'
    for ln in lines:
        if 'COLUMNS' in ln:
            body = ln.split('COLUMNS', 1)[1]
            body = body[1:] if body.startswith(':') else body
            pos = []
            for c in ['CODE', 'QTY', 'UNIT', 'AMOUNT']:
                pos.append((body.find(c), c))
            if all(p >= 0 for p, _ in pos):
                cols = [c for _, c in sorted(pos)]
            inner = body.strip()
            if '|' in inner:
                sep = '|'
            elif ';' in inner:
                sep = ';'
            elif '\t' in inner:
                sep = '\t'
            else:
                sep = '   '
            break
    sections = []
    cur = None
    total = None
    items_n = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if re.match(r'^=+\s*SECTION', s):
            cur = {'tokens': [], 'subtotal': None}
            sections.append(cur)
            continue
        if s.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'tokens': [], 'subtotal': None}
                sections.append(cur)
            cur['subtotal'] = s[len('SUBTOTAL'):].strip()
            continue
        if s.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s+(.*?)\s+ITEMS\s*(.*)$', s)
            if m:
                total = m.group(1)
                items_n = m.group(2)
            continue
        parts = split_line(ln.replace('\r', ''), sep)
        if not parts:
            continue
        suspect = not all(looks_value(p) for p in parts)
        if cur is None:
            cur = {'tokens': [], 'subtotal': None}
            sections.append(cur)
        for p in parts:
            cur['tokens'].append([p, bool(suspect or not looks_value(p))])
    state['doc'] = {'cols': cols, 'sections': sections, 'total': total, 'items_n': items_n}
    return state


def align_dp(toks, cols):
    n = len(toks)
    R = n // 3 + 2
    tc = [[tok_type_cost(t, c) for c in cols] for t, _ in toks]
    sk = [0.3 if s else 4.0 for _, s in toks]
    r4 = [None] * n
    r3 = [None] * n
    for i in range(n):
        if i + 4 <= n:
            r4[i] = sum(tc[i + k][k] for k in range(4))
        if i + 3 <= n:
            bm = None
            for miss in range(4):
                c = 3.5
                k2 = 0
                for k in range(4):
                    if k == miss:
                        continue
                    c += tc[i + k2][k]
                    k2 += 1
                if bm is None or c < bm[0]:
                    bm = (c, miss)
            r3[i] = bm
    best = [[INF] * (R + 1) for _ in range(n + 1)]
    back = [[None] * (R + 1) for _ in range(n + 1)]
    best[0][0] = 0.0
    for i in range(n):
        bi = best[i]
        for r in range(R + 1):
            b = bi[r]
            if b == INF:
                continue
            c = b + sk[i]
            if c < best[i + 1][r]:
                best[i + 1][r] = c
                back[i + 1][r] = ('skip', i, -1)
            if r < R:
                if r4[i] is not None:
                    c = b + r4[i]
                    if c < best[i + 4][r + 1]:
                        best[i + 4][r + 1] = c
                        back[i + 4][r + 1] = ('row', i, -1)
                if r3[i] is not None:
                    c = b + r3[i][0]
                    if c < best[i + 3][r + 1]:
                        best[i + 3][r + 1] = c
                        back[i + 3][r + 1] = ('row3', i, r3[i][1])
    return best[n], back


def reconstruct(toks, back, n, r):
    rows = []
    j = n
    rr = r
    while j > 0:
        bk = back[j][rr]
        if bk is None:
            break
        i = bk[1]
        if bk[0] == 'skip':
            j = i
            continue
        if bk[0] == 'row':
            rows.append([t for t, _ in toks[i:i + 4]])
        else:
            seg = [t for t, _ in toks[i:i + 3]]
            seg.insert(bk[2], '')
            rows.append(seg)
        j = i
        rr -= 1
    rows.reverse()
    return rows


def items_cands(s):
    out = {}
    if not s:
        return None, out
    ds = to_digits(s.strip())
    if not ds:
        return None, out
    raw = int(ds) if re.match(r'^\d+$', s.strip()) else None
    for cand, c in edits(ds, 0, len(ds), 0, len(ds)):
        if not cand:
            continue
        v = int(cand)
        if 1 <= v <= 80:
            if v not in out or out[v] > c:
                out[v] = c
    if raw is None:
        v = int(ds)
        if 1 <= v <= 80:
            out[v] = 0.5
    return raw, out


def align_rows(state, params):
    doc = state.get('doc', {})
    cols = doc.get('cols', ['CODE', 'QTY', 'UNIT', 'AMOUNT'])
    secs = doc.get('sections', [])
    dps = []
    for sec in secs:
        dps.append(align_dp(sec['tokens'], cols))
    tot = {0: (0.0, [])}
    for costs, _ in dps:
        nt = {}
        for k, (c, ch) in tot.items():
            for r, cr in enumerate(costs):
                if cr == INF:
                    continue
                v = c + cr
                kk = k + r
                if kk not in nt or nt[kk][0] > v:
                    nt[kk] = (v, ch + [r])
        tot = nt
    raw, ic = items_cands(doc.get('items_n'))
    bestk = None
    bests = INF
    for k in sorted(tot):
        c = tot[k][0]
        if raw is not None and k == raw:
            pen = 0.0
        elif k in ic:
            pen = 2.5
        else:
            pen = 6.0
        s = c + pen
        if s < bests - 1e-9:
            bests = s
            bestk = k
    rcounts = [0] * len(secs) if bestk is None else tot[bestk][1]
    out = []
    for si, sec in enumerate(secs):
        rc = rcounts[si] if si < len(rcounts) else 0
        rows = reconstruct(sec['tokens'], dps[si][1], len(sec['tokens']), rc)
        out.append({'rows': rows, 'sub': sec.get('subtotal')})
    state['rows'] = out
    return state


def solve_row(fields, cols):
    d = dict(zip(cols, fields))
    qc = qty_cands(d['QTY'])
    uc = money_cands(d['UNIT'])
    ac = money_cands(d['AMOUNT'])
    q0 = min(sorted(qc), key=lambda v: qc[v]) if qc else 1
    u0 = min(sorted(uc), key=lambda v: uc[v]) if uc else 1
    if qc.get(q0) == 0 and uc.get(u0) == 0 and ac.get(q0 * u0) == 0:
        return [[0.0, q0, u0, q0 * u0]]
    qo = to_digits(re.sub(r'(?i)p\s*c\s*s', '', d['QTY'] or '').strip())
    up = money_parse(d['UNIT'])
    ap = money_parse(d['AMOUNT'])

    def CQ(q):
        v = qc.get(q)
        return v if v is not None else min(4.0, wdist(qo, str(q)))

    def CU(u):
        v = uc.get(u)
        return v if v is not None else min(4.0, mdist(up, u))

    def CA(a):
        v = ac.get(a)
        return v if v is not None else min(4.0, mdist(ap, a))

    cand = {}
    for q, cq in qc.items():
        for u, cu in uc.items():
            s = cq + cu
            if s > 2.2:
                continue
            a = q * u
            ca = ac.get(a)
            if ca is None:
                if s > 1.1:
                    continue
                ca = CA(a)
            tc = s + ca
            key = (q, u)
            if key not in cand or cand[key] > tc:
                cand[key] = tc
    qs1 = [(q, c) for q, c in qc.items() if c <= 1.1]
    us1 = [(u, c) for u, c in uc.items() if c <= 1.1]
    as1 = [(a, c) for a, c in ac.items() if c <= 1.1]
    for q, cq in qs1:
        for a, ca in as1:
            if a % q:
                continue
            u = a // q
            if u <= 0 or (q, u) in cand:
                continue
            cand[(q, u)] = cq + ca + CU(u)
    for u, cu in us1:
        for a, ca in as1:
            if a % u:
                continue
            q = a // u
            if q < 1 or q > 500 or (q, u) in cand:
                continue
            cand[(q, u)] = CQ(q) + cu + ca
    if not cand:
        return [[9.0, q0, u0, q0 * u0]]
    lst = sorted(cand.items(), key=lambda kv: (kv[1], kv[0]))
    bc = lst[0][1]
    res = []
    for (q, u), c in lst:
        if c > bc + 3.0:
            break
        res.append([c, q, u, q * u])
        if len(res) >= 20:
            break
    return res


def decode_rows(state, params):
    t0 = state.get('t0', time.process_time())
    cols = state.get('doc', {}).get('cols', ['CODE', 'QTY', 'UNIT', 'AMOUNT'])
    dec = []
    for sec in state.get('rows', []):
        ctoks = []
        opts = []
        raws = []
        for r in sec['rows']:
            d = dict(zip(cols, r))
            ctoks.append(d['CODE'])
            raws.append([d['QTY'], d['UNIT'], d['AMOUNT']])
            el = time.process_time() - t0
            if el > 0.6:
                qc = qty_cands(d['QTY'])
                uc = money_cands(d['UNIT'])
                q = min(sorted(qc), key=lambda v: qc[v])
                u = min(sorted(uc), key=lambda v: uc[v]) if uc else 1
                opts.append([[0.0, q, u, q * u]])
            else:
                try:
                    opts.append(solve_row(r, cols))
                except Exception:
                    opts.append([[9.0, 1, 1, 1]])
        dec.append({'ctoks': ctoks, 'raws': raws, 'opts': opts, 'sub': sec.get('sub')})
    state['dec'] = dec
    return state


def _classify(obs, true):
    if obs == true:
        return 'ok'
    lo = len(obs)
    lt = len(true)
    if lo == lt + 1:
        for k in range(lo):
            if obs[:k] + obs[k + 1:] == true:
                if (k > 0 and obs[k] == obs[k - 1]) or (k < lo - 1 and obs[k] == obs[k + 1]):
                    return 'dup'
        return 'other'
    if lo == lt - 1:
        for k in range(lt):
            if true[:k] + true[k + 1:] == obs:
                return 'lost'
        return 'other'
    if lo == lt:
        diff = [k for k in range(lo) if obs[k] != true[k]]
        if len(diff) == 1 and obs[diff[0]] in MIS[true[diff[0]]]:
            return 'mis'
    return 'other'


def estimate_channel(state, params):
    cnt = {'mis': 0, 'lost': 0, 'dup': 0, 'other': 0, 'ok': 0}
    n = 0
    try:
        for sec in state.get('dec', []):
            for raw, opts, ct in zip(sec['raws'], sec['opts'], sec['ctoks']):
                o = opts[0]
                if o[0] >= 9.0:
                    continue
                q, u, a = o[1], o[2], o[3]
                qo = to_digits(re.sub(r'(?i)p\s*c\s*s', '', raw[0] or '').strip())
                pairs = [(qo, str(q)),
                         (to_digits(raw[1] or ''), str(u // 100) + '%02d' % (u % 100)),
                         (to_digits(raw[2] or ''), str(a // 100) + '%02d' % (a % 100))]
                for ob, tr in pairs:
                    if not ob:
                        continue
                    cnt[_classify(ob, tr)] += 1
                    n += 1
                _, cd = split_code(ct)
                n += 1
                if len(cd) == 6:
                    cnt['dup'] += 1
                elif len(cd) == 7:
                    cnt['dup'] += 2
                elif len(cd) == 4:
                    cnt['lost'] += 1
                elif len(cd) == 3:
                    cnt['lost'] += 2
    except Exception:
        pass
    oth = cnt['other'] * 0.3
    rates = {}
    for t in ('mis', 'lost', 'dup'):
        rates[t] = min(0.5, (cnt[t] + oth + 0.1) / (n + 1.0))
    state['rates'] = rates
    return state


def code_posterior(letters, d, rates):
    L = ord(letters[0]) - 64 + ord(letters[1]) - 64
    pm = rates.get('mis', 0.05)
    pl = rates.get('lost', 0.05)
    pd = rates.get('dup', 0.05)

    def valid(s):
        return (int(s[0]) + 2 * int(s[1]) + 3 * int(s[2]) + 4 * int(s[3]) + L) % 10 == int(s[4])

    def step(s, want):
        out = {}
        n = len(s)
        if n in want:
            for k in range(n):
                for o in REV.get(s[k], []):
                    s2 = s[:k] + o + s[k + 1:]
                    out[s2] = out.get(s2, 0.0) + pm / (5.0 * len(MIS[o]))
        if n - 1 in want:
            for k in range(1, n):
                if s[k] == s[k - 1]:
                    s2 = s[:k] + s[k + 1:]
                    out[s2] = out.get(s2, 0.0) + pd / 5.0
        if n + 1 in want:
            seen = set()
            for k in range(n + 1):
                for c in '0123456789':
                    s2 = s[:k] + c + s[k:]
                    if s2 in seen:
                        continue
                    seen.add(s2)
                    out[s2] = out.get(s2, 0.0) + pl / 5.0
        return out

    res = {}
    if len(d) == 5 and valid(d):
        res[d] = 1.0
    l1 = step(d, (4, 5, 6))
    for s1, w1 in l1.items():
        if len(s1) == 5 and valid(s1):
            res[s1] = res.get(s1, 0.0) + w1
        for s2, w2 in step(s1, (5,)).items():
            if len(s2) == 5 and valid(s2):
                res[s2] = res.get(s2, 0.0) + w1 * w2
    return res


def repair_codes(state, params):
    t0 = state.get('t0', time.process_time())
    rates = state.get('rates', {'mis': 0.05, 'lost': 0.05, 'dup': 0.05})
    for sec in state.get('dec', []):
        codes = []
        for tok in sec.get('ctoks', []):
            el = time.process_time() - t0
            try:
                letters, d = split_code(tok)
                if 3 <= len(d) <= 7 and el < 0.8:
                    res = code_posterior(letters, d, rates)
                    b = _best(res)
                    if b:
                        codes.append(letters + b)
                        continue
                codes.append(fix_code(tok, allow2=(el < 0.6)))
            except Exception:
                codes.append('AA00000')
        sec['codes'] = codes
    return state


def _section_beam(opts, sc, fast):
    MISS = 3.0
    CHG = 0.3
    BOUND = 6.0
    CAP = 2500
    states = {0: (0.0, None)}
    for ro in opts:
        base = ro[0][0]
        alts = []
        lim = 1 if fast else 12
        for oi, o in enumerate(ro[:lim]):
            dc = o[0] - base + (CHG if oi else 0.0)
            if dc <= 4.5:
                alts.append((oi, dc, o[3]))
        new = {}
        for s, (c, ch) in states.items():
            for oi, dc, a in alts:
                nc = c + dc
                if nc > BOUND:
                    continue
                ns = s + a
                e = new.get(ns)
                if e is None or e[0] > nc:
                    new[ns] = (nc, (oi, ch))
        if len(new) > CAP:
            ks = sorted(new.items(), key=lambda kv: (kv[1][0], kv[0]))[:CAP]
            new = dict(ks)
        states = new
    finals = []
    for s, (c, ch) in states.items():
        sub = 0.0 if sc is None else sc.get(s, MISS)
        finals.append((c + sub, s, ch))
    finals.sort(key=lambda x: (x[0], x[1]))
    return finals[:8]


def reconcile(state, params):
    t0 = state.get('t0', time.process_time())
    dec = state.get('dec', [])
    total = state.get('doc', {}).get('total')
    sec_lists = []
    for sec in dec:
        fast = time.process_time() - t0 > 0.85
        sc = money_cands(sec['sub']) if sec.get('sub') else None
        try:
            sec_lists.append(_section_beam(sec['opts'], sc, fast))
        except Exception:
            sec_lists.append([(0.0, sum(o[0][3] for o in sec['opts']), None)])
    picks = [0] * len(sec_lists)
    try:
        tc = money_cands(total) if total else None
        if tc is not None and sec_lists:
            comb = {0: (0.0, [])}
            for fl in sec_lists:
                new = {}
                for s, (c, pk) in comb.items():
                    for idx, f in enumerate(fl):
                        ns = s + f[1]
                        nc = c + f[0]
                        e = new.get(ns)
                        if e is None or e[0] > nc:
                            new[ns] = (nc, pk + [idx])
                if len(new) > 3000:
                    new = dict(sorted(new.items(), key=lambda kv: (kv[1][0], kv[0]))[:3000])
                comb = new
            best = None
            for s in sorted(comb):
                c, pk = comb[s]
                sc2 = c + tc.get(s, 3.0)
                if best is None or sc2 < best[0] - 1e-9:
                    best = (sc2, pk)
            if best is not None:
                picks = best[1]
    except Exception:
        picks = [0] * len(sec_lists)
    items = []
    for si, sec in enumerate(dec):
        n = len(sec['opts'])
        choice = [0] * n
        fl = sec_lists[si] if si < len(sec_lists) else []
        if fl:
            pi = picks[si] if si < len(picks) and picks[si] < len(fl) else 0
            ch = fl[pi][2]
            seq = []
            while ch is not None:
                seq.append(ch[0])
                ch = ch[1]
            seq.reverse()
            if len(seq) == n:
                choice = seq
        codes = sec.get('codes') or ['AA00000'] * n
        for code, opts, ci in zip(codes, sec['opts'], choice):
            o = opts[ci] if ci < len(opts) else opts[0]
            items.append({'code': code, 'qty': int(o[1]), 'unit_cents': int(o[2])})
    state['output'] = {'items': items}
    return state

import math
import re
import time

MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63', '6': '50',
       '7': '12', '8': '30', '9': '43'}
CMIS = {d: (2.0 if len(v) == 1 else 2.4) for d, v in MIS.items()}
INVMIS = {}
for _t, _os in MIS.items():
    for _o in _os:
        INVMIS.setdefault(_o, []).append(_t)
CLOST = 2.3
CDUP = 2.3
CMARK = 2.0
CSUB = 6.0
CINS = 6.0
DIGLOOK = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5', 'B': '8',
           'Z': '2', 'z': '2', 'G': '6', 'D': '0', 'Q': '0'}
LETLOOK = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G', 'l': 'I'}


def ed(obs, tru):
    """Min-path channel cost of observing digit string obs when truth is tru."""
    n = len(tru)
    m = len(obs)
    prev = [0.0] * (m + 1)
    for j in range(1, m + 1):
        prev[j] = prev[j - 1] + CINS
    for i in range(1, n + 1):
        t = tru[i - 1]
        cur = [prev[0] + CLOST] + [0.0] * m
        mt = MIS[t]
        cm = CMIS[t]
        for j in range(1, m + 1):
            o = obs[j - 1]
            if o == t:
                best = prev[j - 1]
                v = cur[j - 1] + CDUP
            elif o in mt:
                best = prev[j - 1] + cm
                v = cur[j - 1] + CINS
            else:
                best = prev[j - 1] + CSUB
                v = cur[j - 1] + CINS
            if v < best:
                best = v
            v = prev[j] + CLOST
            if v < best:
                best = v
            cur[j] = best
        prev = cur
    return prev[m]


def fwd(obs, tru):
    """Sum over all edit paths of exp(-cost): full channel likelihood."""
    n = len(tru)
    m = len(obs)
    eI = math.exp(-CINS)
    eL = math.exp(-CLOST)
    eD = math.exp(-CDUP)
    eS = math.exp(-CSUB)
    prev = [1.0] + [0.0] * m
    for j in range(1, m + 1):
        prev[j] = prev[j - 1] * eI
    for i in range(1, n + 1):
        t = tru[i - 1]
        mt = MIS[t]
        em = math.exp(-CMIS[t])
        cur = [prev[0] * eL] + [0.0] * m
        for j in range(1, m + 1):
            o = obs[j - 1]
            if o == t:
                v = prev[j - 1] + cur[j - 1] * eD
            elif o in mt:
                v = prev[j - 1] * em + cur[j - 1] * eI
            else:
                v = prev[j - 1] * eS + cur[j - 1] * eI
            cur[j] = v + prev[j] * eL
        prev = cur
    return prev[m]


def inv(obs, budget, maxins=2, length=None):
    """Channel inversion: truth digit strings with cost(obs|truth) <= budget."""
    res = {}
    m = len(obs)

    def rec(j, out, cost, ins):
        if length is not None and len(out) > length:
            return
        if length is not None and len(out) + (m - j) + (maxins - ins) < length:
            return
        if j == m:
            if length is None or len(out) == length:
                s = ''.join(out)
                if s not in res or res[s] > cost:
                    res[s] = cost
            if ins < maxins and cost + CLOST <= budget and (length is None or len(out) < length):
                for d in '0123456789':
                    out.append(d)
                    rec(j, out, cost + CLOST, ins + 1)
                    out.pop()
            return
        o = obs[j]
        out.append(o)
        rec(j + 1, out, cost, ins)
        out.pop()
        for t in INVMIS.get(o, ()):
            c = cost + CMIS[t]
            if c <= budget:
                out.append(t)
                rec(j + 1, out, c, ins)
                out.pop()
        if out and out[-1] == o and cost + CDUP <= budget:
            rec(j + 1, out, cost + CDUP, ins)
        if ins < maxins and cost + CLOST <= budget:
            for d in '0123456789':
                out.append(d)
                rec(j, out, cost + CLOST, ins + 1)
                out.pop()

    rec(0, [], 0.0, 0)
    return res


def norm_digits(s):
    out = []
    for ch in s:
        if ch.isdigit():
            out.append(ch)
        elif ch in DIGLOOK:
            out.append(DIGLOOK[ch])
    return ''.join(out)


def parse_money(tok):
    s = (tok or '').strip()
    k = max(s.rfind('.'), s.rfind(','))
    if k < 0:
        return (norm_digits(s), None)
    return (norm_digits(s[:k]), norm_digits(s[k + 1:]))


def valid_cents_str(s):
    if len(s) < 3:
        return False
    if len(s) > 3 and s[0] == '0':
        return False
    return True


def mcost(obs, cents, cache):
    key = (obs[0], obs[1], cents)
    v = cache.get(key)
    if v is not None:
        return v
    t = str(cents).zfill(3)
    if obs[1] is None:
        v = CMARK + ed(obs[0], t)
    else:
        v = ed(obs[0], t[:-2]) + ed(obs[1], t[-2:])
    cache[key] = v
    return v


def mlb(obs, cents):
    t = len(str(cents).zfill(3))
    if obs[1] is None:
        return CMARK + 2.3 * abs(len(obs[0]) - t)
    return 2.3 * abs(len(obs[0]) + len(obs[1]) - t)


def money_cands(obs, budget):
    res = {}
    if obs[1] is None:
        for s, c in inv(obs[0], budget - CMARK).items():
            if valid_cents_str(s):
                v = int(s)
                c2 = c + CMARK
                if v > 0 and (v not in res or res[v] > c2):
                    res[v] = c2
    else:
        ints = inv(obs[0], budget, 2)
        fracs = inv(obs[1], budget, 2, 2)
        fl = sorted((c, s) for s, c in fracs.items())
        for si, ci in ints.items():
            if si == '' or (len(si) > 1 and si[0] == '0'):
                continue
            for cf, sf in fl:
                c = ci + cf
                if c > budget:
                    break
                v = int(si + sf)
                if v > 0 and (v not in res or res[v] > c):
                    res[v] = c
    return res


def check_ok(code):
    p1 = ord(code[0]) - 64
    p2 = ord(code[1]) - 64
    d = [int(c) for c in code[2:]]
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p1 + p2) % 10 == d[4]


def decode_code(tok):
    s = re.sub(r'\s', '', tok or '')
    if len(s) < 2:
        s = (s + 'AA')[:2]
    lets = []
    for ch in s[:2]:
        if 'A' <= ch <= 'Z':
            lets.append(ch)
        elif ch in LETLOOK:
            lets.append(LETLOOK[ch])
        elif 'a' <= ch <= 'z':
            lets.append(ch.upper())
        else:
            lets.append('A')
    L = ''.join(lets)
    ds = norm_digits(s[2:])
    if len(ds) == 5 and check_ok(L + ds):
        return L + ds
    for budget in (2.5, 4.9, 7.3):
        cands = inv(ds, budget, 3, 5)
        good = [(c, t) for t, c in cands.items() if check_ok(L + t)]
        if good:
            cmin = min(c for c, t in good)
            best = None
            for c, t in good:
                if c <= cmin + 2.6:
                    key = (-fwd(ds, t), t)
                    if best is None or key < best:
                        best = key
            return L + best[1]
    d = (ds + '00000')[:4]
    dd = [int(c) for c in d]
    ck = (dd[0] + 2 * dd[1] + 3 * dd[2] + 4 * dd[3] + ord(L[0]) - 64 + ord(L[1]) - 64) % 10
    return L + d + str(ck)


# ---------------------------------------------------------------- parsing

def is_value_token(t):
    s = t.strip()
    if s == '':
        return True
    if s.endswith('pcs'):
        s = s[:-3].strip()
    return re.fullmatch(r"[A-Za-z0-9.,']{1,16}", s) is not None and not re.search(r'[a-km-z]', s)


def shape_costs(tok):
    s = tok.strip()
    pcs = s.endswith('pcs')
    if pcs:
        s = s[:-3].strip()
    up = sum(1 for c in s[:2] if 'A' <= c <= 'Z' and c not in 'OSBZG')
    nd = len(norm_digits(s))
    hasmark = ('.' in s) or (',' in s)
    if 5 <= len(s) <= 9 and not hasmark:
        code = 0.0 if up >= 1 else 1.5
    else:
        code = 4.0
    qty = 0.0 if (pcs or (nd <= 3 and not hasmark and up == 0)) else 3.0
    mon = 0.0 if ((hasmark or nd >= 3) and not pcs and up == 0) else 2.5
    return {'CODE': code, 'QTY': qty, 'UNIT': mon, 'AMOUNT': mon}


def align(tokens, cols):
    n = len(tokens)
    if n % 4 == 0:
        ok = True
        for i, t in enumerate(tokens):
            if shape_costs(t)[cols[i % 4]] > 2.0:
                ok = False
                break
        if ok:
            return [tokens[i:i + 4] for i in range(0, n, 4)]
    INF = 1e18
    sc = [shape_costs(t) for t in tokens]
    dp = [[INF] * 4 for _ in range(n + 1)]
    bp = [[None] * 4 for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        for _rep in range(2):
            for p in range(4):
                if dp[i][p] < INF:
                    q = (p + 1) % 4
                    v = dp[i][p] + 3.5
                    if v < dp[i][q]:
                        dp[i][q] = v
                        bp[i][q] = ('miss', i, p)
        if i == n:
            break
        for p in range(4):
            if dp[i][p] >= INF:
                continue
            q = (p + 1) % 4
            v = dp[i][p] + sc[i][cols[p]]
            if v < dp[i + 1][q]:
                dp[i + 1][q] = v
                bp[i + 1][q] = ('tok', i, p)
            v = dp[i][p] + 3.0
            if v < dp[i + 1][p]:
                dp[i + 1][p] = v
                bp[i + 1][p] = ('skip', i, p)
    seq = []
    i, p = n, 0
    guard = 0
    while (i, p) != (0, 0) and guard < 20 * n + 50:
        guard += 1
        b = bp[i][p]
        if b is None:
            break
        kind, pi, pp = b
        if kind == 'tok':
            seq.append(tokens[pi])
        elif kind == 'miss':
            seq.append('')
        i, p = pi, pp
    seq.reverse()
    return [seq[k:k + 4] for k in range(0, len(seq) - len(seq) % 4, 4)]


def parse_doc(state, params):
    text = state.get('input', {}).get('text', '') or ''
    lines = text.replace('\r', '').split('\n')
    sep = None
    cols = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    for ln in lines:
        if ln.startswith('COLUMNS'):
            body = ln.split(':', 1)[1] if ':' in ln else ln[7:]
            body = body.lstrip(' ')
            if ' | ' in body:
                sep = ' | '
            elif ';' in body:
                sep = ';'
            elif '\t' in body:
                sep = '\t'
            elif '   ' in body:
                sep = '   '
            found = []
            for m in re.finditer(r'CODE|QTY|UNIT|AMOUNT', body):
                if m.group(0) not in found:
                    found.append(m.group(0))
            if len(found) == 4:
                cols = found
            break
    if sep is None:
        sep = ';'
    sections = []
    cur = None
    total_tok = None
    items_tok = None
    for ln in lines:
        s = ln.strip(' \t')
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if re.match(r'^\s*==\s*SECTION', ln):
            cur = {'tokens': [], 'sub': None}
            sections.append(cur)
            continue
        if s.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'tokens': [], 'sub': None}
                sections.append(cur)
            cur['sub'] = s[8:].strip()
            continue
        if s.startswith('TOTAL'):
            m = re.match(r'TOTAL\s+(.*?)\s+ITEMS\s*(.*)$', s)
            if m:
                total_tok = m.group(1)
                items_tok = m.group(2)
            else:
                total_tok = s[5:].strip()
            continue
        if ln.strip() == '':
            continue
        parts = ln.split(sep)
        if sep == '   ':
            parts = [x.strip() for x in parts]
        while parts and parts[-1].strip() == '':
            parts.pop()
        while parts and parts[0].strip() == '':
            parts.pop(0)
        if not parts:
            continue
        if not all(is_value_token(x) for x in parts):
            continue
        if cur is None:
            cur = {'tokens': [], 'sub': None}
            sections.append(cur)
        cur['tokens'].extend(x.strip() for x in parts)
    out_secs = []
    for sec in sections:
        rows = align(sec['tokens'], cols)
        if not rows and sec['sub'] is None:
            continue
        recs = []
        for r in rows:
            recs.append({cols[k]: r[k] for k in range(4)})
        out_secs.append({'rows': recs, 'sub': sec['sub']})
    state['parsed'] = {'sections': out_secs, 'total': total_tok, 'items': items_tok}
    return state


# ---------------------------------------------------------------- row hypotheses

def qty_obs(tok):
    s = (tok or '').strip()
    if s.endswith('pcs'):
        s = s[:-3]
    return norm_digits(s)


def as_written(mo):
    if mo[1] is None or len(mo[1]) != 2 or mo[0] == '':
        return None
    if not (mo[0].isdigit() and mo[1].isdigit()):
        return None
    s = mo[0] + mo[1]
    if not valid_cents_str(s):
        return None
    return int(s)


def row_hypotheses(qo, uo, ao, cache, qcache, tight):
    qv = int(qo) if (qo.isdigit() and len(qo) <= 3 and qo[0] != '0') else None
    uv = as_written(uo)
    av = as_written(ao)
    if qv is not None and uv is not None and av is not None and 1 <= qv <= 500 and uv > 0 \
            and qv * uv == av:
        return [(0.0, qv, uv, av)]
    if qo in qcache:
        qlist = qcache[qo]
    else:
        qlist = sorted((ed(qo, str(q)), q) for q in range(1, 501))
        qcache[qo] = qlist
    qcost_of = {}
    for c, q in qlist:
        qcost_of[q] = c
    ub = 2.4 if tight else 4.7
    K = 30 if tight else 80
    U = money_cands(uo, ub)
    A = money_cands(ao, ub)
    Ul = sorted((c, v) for v, c in U.items())[:K]
    Al = sorted((c, v) for v, c in A.items())[:K]
    Qt = qlist[:6] if tight else qlist[:12]
    hyp = {}
    best = [1e9]

    def add(q, u, a, c):
        k = (q, u)
        if k not in hyp or hyp[k][0] > c:
            hyp[k] = (c, q, u, a)
        if c < best[0]:
            best[0] = c

    # UNIT x AMOUNT -> QTY (QTY may be arbitrarily damaged)
    for cu, u in Ul:
        for ca, a in Al:
            base = cu + ca
            if base >= best[0] + 3.0:
                break
            if a % u:
                continue
            q = a // u
            if 1 <= q <= 500:
                add(q, u, a, base + qcost_of[q])
    # QTY x AMOUNT -> UNIT (UNIT may be arbitrarily damaged)
    pairs = sorted((cq + ca, q, a) for cq, q in Qt for ca, a in Al)
    for base, q, a in pairs:
        if base >= best[0] + 3.0:
            break
        if a % q:
            continue
        u = a // q
        cu = U.get(u)
        if cu is None:
            if base + mlb(uo, u) >= best[0] + 3.0:
                continue
            cu = mcost(uo, u, cache)
        add(q, u, a, base + cu)
    # QTY x UNIT -> AMOUNT (AMOUNT may be arbitrarily damaged)
    pairs = sorted((cq + cu, q, u) for cq, q in Qt for cu, u in Ul)
    for base, q, u in pairs:
        if base >= best[0] + 3.0:
            break
        a = q * u
        ca = A.get(a)
        if ca is None:
            if base + mlb(ao, a) >= best[0] + 3.0:
                continue
            ca = mcost(ao, a, cache)
        add(q, u, a, base + ca)
    res = sorted(hyp.values())
    if not res:
        q = qlist[0][1]
        if Ul:
            u = Ul[0][1]
        elif Al:
            u = max(1, Al[0][1] // q)
        else:
            u = 100
        res = [(20.0, q, u, q * u)]
    top = res[0][0]
    return [h for h in res if h[0] <= top + 7.0][:6]


def decode_rows(state, params):
    t0 = time.perf_counter()
    cache = {}
    qcache = {}
    P = state['parsed']
    secs = []
    for sec in P['sections']:
        rows = []
        for r in sec['rows']:
            tight = (time.perf_counter() - t0) > 0.45
            code = decode_code(r.get('CODE', ''))
            qo = qty_obs(r.get('QTY', ''))
            uo = parse_money(r.get('UNIT', ''))
            ao = parse_money(r.get('AMOUNT', ''))
            hy = row_hypotheses(qo, uo, ao, cache, qcache, tight)
            rows.append({'code': code, 'hyp': [[float(h[0]), int(h[1]), int(h[2]), int(h[3])] for h in hy]})
        secs.append({'rows': rows, 'sub': sec['sub']})
    state['decoded'] = {'sections': secs, 'total': P['total']}
    return state


# ---------------------------------------------------------------- global reconciliation

def reconcile(state, params):
    cache = {}
    D = state['decoded']
    sec_opts = []
    W = 300
    for sec in D['sections']:
        beam = {0: (0.0, [])}
        for r in sec['rows']:
            nb = {}
            for s, (c, ch) in beam.items():
                for k, h in enumerate(r['hyp']):
                    c2 = c + h[0]
                    s2 = s + h[3]
                    if s2 not in nb or nb[s2][0] > c2:
                        nb[s2] = (c2, ch + [k])
            if len(nb) > W:
                nb = dict(sorted(nb.items(), key=lambda kv: kv[1][0])[:W])
            beam = nb
        subo = parse_money(sec['sub']) if sec['sub'] is not None else None
        opts = []
        for s, (c, ch) in beam.items():
            cs = min(mcost(subo, s, cache), 9.0) if subo is not None else 0.0
            opts.append((c + cs, c, s, ch))
        opts.sort(key=lambda o: (o[0], o[1], o[2]))
        sec_opts.append(opts[:25])
    totb = {0: (0.0, 0.0, [])}
    for opts in sec_opts:
        if not opts:
            continue
        nb = {}
        for s, (c, rc, ch) in totb.items():
            for k, o in enumerate(opts):
                s2 = s + o[2]
                c2 = c + o[0]
                rc2 = rc + o[1]
                if s2 not in nb or (nb[s2][0], nb[s2][1]) > (c2, rc2):
                    nb[s2] = (c2, rc2, ch + [k])
        if len(nb) > W:
            nb = dict(sorted(nb.items(), key=lambda kv: (kv[1][0], kv[1][1]))[:W])
        totb = nb
    tobs = parse_money(D['total']) if D['total'] else None
    best = None
    for s, (c, rc, ch) in totb.items():
        ct = min(mcost(tobs, s, cache), 9.0) if tobs is not None else 0.0
        key = (c + ct, rc, s)
        if best is None or key < best[0]:
            best = (key, ch)
    choice = best[1] if best else []
    items = []
    ci = 0
    for si, sec in enumerate(D['sections']):
        opts = sec_opts[si]
        if not opts:
            continue
        idx = choice[ci] if ci < len(choice) else 0
        ci += 1
        rowch = opts[idx][3]
        for ri, r in enumerate(sec['rows']):
            k = rowch[ri] if ri < len(rowch) else 0
            h = r['hyp'][k]
            items.append({'code': r['code'], 'qty': int(h[1]), 'unit_cents': int(h[2])})
    state['output'] = {'items': items}
    return state

import re
import time

LOOK = {'O': '0', 'o': '0', 'Q': '0', 'D': '0', 'l': '1', 'I': '1', 'i': '1', '|': '1',
        'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6', 'b': '6'}
LET = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G', 'l': 'I'}
REV = {'6': '05', '8': '03', '7': '12', '4': '19', '9': '34', '1': '47',
       '3': '589', '5': '6', '0': '68', '2': '7'}
DIG = '0123456789'
C_SUB = 1.0
C_DUP = 1.0
C_INS = 1.25
SPLIT_RE = re.compile(r"\s*[|;\t]\s*| {2,}")
CODE_LIKE = re.compile(r"^[A-Z0-9]{2}[0-9OlISBZG]{3,8}$")
NUM_LIKE = re.compile(r"^[0-9OlISBZG.,' ]+(\s*pcs)?$")


def _edits(s):
    out = {}
    n = len(s)
    for i in range(n):
        ch = s[i]
        if ch in REV:
            for t in REV[ch]:
                k = s[:i] + t + s[i + 1:]
                if out.get(k, 9) > C_SUB:
                    out[k] = C_SUB
            if i + 1 < n and s[i + 1] == ch:
                k = s[:i] + s[i + 1:]
                if out.get(k, 9) > C_DUP:
                    out[k] = C_DUP
    for i in range(n + 1):
        a = s[:i]
        b = s[i:]
        for d in DIG:
            k = a + d + b
            if out.get(k, 9) > C_INS:
                out[k] = C_INS
    return out


def _levels(s0, maxlev):
    seen = {s0: 0.0}
    levels = [{s0: 0.0}]
    frontier = {s0: 0.0}
    for _ in range(maxlev):
        nxt = {}
        for s, c in frontier.items():
            for k, ec in _edits(s).items():
                cc = c + ec
                if k in seen and seen[k] <= cc:
                    continue
                if nxt.get(k, 99) > cc:
                    nxt[k] = cc
        for k, c in nxt.items():
            seen[k] = c
        levels.append(nxt)
        frontier = nxt
    return levels


def _norm_num(tok):
    t = tok.strip()
    t = re.sub(r"\s*pcs\s*$", "", t, flags=re.I)
    out = []
    for ch in t:
        if ch.isdigit():
            out.append(ch)
        elif ch in '.,':
            out.append('.')
        elif ch in LOOK:
            out.append(LOOK[ch])
    s = ''.join(out)
    if s.count('.') > 1:
        i = s.rfind('.')
        s = s[:i].replace('.', '') + s[i:]
    return s


def _money_val(s):
    if '.' in s:
        ip, fp = s.split('.', 1)
        if len(fp) != 2 or not ip or not fp.isdigit() or not ip.isdigit():
            return None
        if len(ip) > 1 and ip[0] == '0':
            return None
        return int(ip) * 100 + int(fp)
    if len(s) < 3 or not s.isdigit():
        return None
    ip = s[:-2]
    if len(ip) > 1 and ip[0] == '0':
        return None
    return int(s)


def _qty_val(s):
    if not s or not s.isdigit() or s[0] == '0':
        return None
    v = int(s)
    if 1 <= v <= 500:
        return v
    return None


def _field_dicts(s0, kind, maxlev):
    fn = _money_val if kind == 'm' else _qty_val
    levs = _levels(s0, maxlev)
    res = []
    cum = {}
    for lev in levs:
        for s, c in lev.items():
            v = fn(s)
            if v is None or v <= 0:
                continue
            if cum.get(v, 99) > c:
                cum[v] = c
        res.append(dict(cum))
    return res


def _check_ok(L, d):
    p1 = ord(L[0]) - 64
    p2 = ord(L[1]) - 64
    s = int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p1 + p2
    return s % 10 == int(d[4])


def _fix_code(tok):
    t = re.sub(r"\s+", "", tok)
    if len(t) < 2:
        t = (t + "AA")[:2]
    L = ''
    for ch in t[:2]:
        if ch in LET:
            L += LET[ch]
        elif ch.isalpha():
            L += ch.upper()
        else:
            L += 'A'
    if not ('A' <= L[0] <= 'Z' and 'A' <= L[1] <= 'Z'):
        L = 'AA'
    ds = ''
    for ch in t[2:]:
        if ch.isdigit():
            ds += ch
        elif ch in LOOK:
            ds += LOOK[ch]
    levs = _levels(ds, 2)
    for lev in levs:
        best = None
        for s, c in sorted(lev.items()):
            if len(s) == 5 and _check_ok(L, s):
                if best is None or c < best[0]:
                    best = (c, s)
        if best is not None:
            return L + best[1]
    d = (ds + '00000')[:4]
    p1 = ord(L[0]) - 64
    p2 = ord(L[1]) - 64
    ck = (int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p1 + p2) % 10
    return L + d + str(ck)


def _best_cheap(dicts):
    for dct in dicts:
        if dct:
            return min(dct.items(), key=lambda kv: (kv[1], kv[0]))[0]
    return None


def _solve_row(qtok, utok, atok, deadline):
    qs = _norm_num(qtok)
    us = _norm_num(utok)
    as_ = _norm_num(atok)
    q0 = _qty_val(qs)
    u0 = _money_val(us)
    a0 = _money_val(as_)
    if q0 is not None and u0 is not None and a0 is not None and q0 * u0 == a0:
        return q0, u0
    late = time.perf_counter() > deadline
    Q = _field_dicts(qs, 'q', 1 if late else 2)
    U = _field_dicts(us, 'm', 1 if late else 2)
    A = _field_dicts(as_, 'm', 1 if late else 2)
    best = None  # (total, cq+cu, q, u)

    def consider(q, u, cq, cu, ca):
        nonlocal best
        key = (cq + cu + ca, cq + cu, q, u)
        if best is None or key < best:
            best = key

    Q1, U1, A1 = Q[1], U[1], A[1]
    for q, cq in Q1.items():
        for u, cu in U1.items():
            ca = A1.get(q * u)
            if ca is not None:
                consider(q, u, cq, cu, ca)
    if (best is None or best[0] > 1.5) and not late and len(Q) > 2:
        Q2, U2, A2 = Q[2], U[2], A[2]
        for q, cq in Q1.items():
            for u, cu in U1.items():
                ca = A2.get(q * u)
                if ca is not None and ca > 1.5:
                    consider(q, u, cq, cu, ca)
            for a, ca in A1.items():
                if a % q == 0:
                    u = a // q
                    cu = U2.get(u)
                    if cu is not None and cu > 1.5:
                        consider(q, u, cq, cu, ca)
        for u, cu in U1.items():
            for a, ca in A1.items():
                if a % u == 0:
                    q = a // u
                    cq = Q2.get(q)
                    if cq is not None and cq > 1.5:
                        consider(q, u, cq, cu, ca)
    if best is not None and best[0] < 4.5:
        return best[2], best[3]
    q = q0 if q0 is not None else _best_cheap(Q)
    u = u0 if u0 is not None else _best_cheap(U)
    if q is None:
        q = 1
    if u is None:
        a = a0 if a0 is not None else _best_cheap(A)
        u = (a // q) if a else 0
    return q, u


def _is_code_like(t):
    t = re.sub(r"\s+", "", t)
    if not CODE_LIKE.match(t):
        return False
    return t[0].isalpha() or t[1].isalpha() or len(t) == 7 and '.' not in t


def _is_value_token(t):
    return bool(CODE_LIKE.match(re.sub(r"\s+", "", t))) or bool(NUM_LIKE.match(t))


def _parse_layout(text):
    lines = text.split('\n')
    order = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    sections = []
    cur = None
    for raw in lines:
        line = raw.strip()
        if not line:
            continue
        if line.startswith('COLUMNS'):
            pos = []
            for name in ('CODE', 'QTY', 'UNIT', 'AMOUNT'):
                m = re.search(r"\b" + name + r"\b", line)
                if m:
                    pos.append((m.start(), name))
            if len(pos) == 4:
                order = [n for _, n in sorted(pos)]
            continue
        if line.startswith('MANIFEST'):
            continue
        if 'SECTION' in line and line.startswith('=='):
            cur = []
            sections.append(cur)
            continue
        if line.startswith('SUBTOTAL') or line.startswith('TOTAL'):
            continue
        toks = [t for t in SPLIT_RE.split(line) if t.strip()]
        if not toks:
            continue
        if not all(_is_value_token(t.strip()) for t in toks):
            continue
        if cur is None:
            cur = []
            sections.append(cur)
        cur.extend(t.strip() for t in toks)
    ci = order.index('CODE')
    rows = []
    for toks in sections:
        n = len(toks)
        if n % 4 == 0:
            for k in range(0, n, 4):
                rows.append(toks[k:k + 4])
            continue
        anchors = [i for i, t in enumerate(toks) if _is_code_like(t)]
        used = -1
        for a in anchors:
            st = a - ci
            if st <= used or st < 0 or st + 4 > n:
                continue
            rows.append(toks[st:st + 4])
            used = st + 3
    return order, rows


def solve(state, params):
    t0 = time.perf_counter()
    text = (state.get('input') or {}).get('text', '') or ''
    items = []
    try:
        order, rows = _parse_layout(text)
        idx = {n: i for i, n in enumerate(order)}
        deadline = t0 + 0.6
        for r in rows:
            code = _fix_code(r[idx['CODE']])
            try:
                q, u = _solve_row(r[idx['QTY']], r[idx['UNIT']], r[idx['AMOUNT']], deadline)
            except Exception:
                q, u = 1, 0
            items.append({'code': code, 'qty': int(q), 'unit_cents': int(u)})
    except Exception:
        pass
    state['output'] = {'items': items}
    return state

import re
import time

INF = 1e9
L2D = {'O': '0', 'l': '1', 'S': '5', 'B': '8', 'Z': '2', 'G': '6',
       'o': '0', 'I': '1', 'i': '1', 'z': '2', 's': '5', 'b': '8', 'g': '6', 'D': '0', 'Q': '0'}
L2D_COST = {'O': 0.25, 'l': 0.25, 'S': 0.25, 'B': 0.25, 'Z': 0.25, 'G': 0.25}
D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
MISREAD = {0: [6, 8], 1: [7, 4], 2: [7], 3: [8, 9], 4: [9, 1], 5: [6, 3],
           6: [5, 0], 7: [1, 2], 8: [3, 0], 9: [4, 3]}
INV = {}
for _t, _ss in MISREAD.items():
    for _s in _ss:
        INV.setdefault(str(_s), []).append(str(_t))

SPLIT_RE = re.compile(r'\s*\|\s*|\s*;\s*|\s*\t\s*| {2,}')
PCS_RE = re.compile(r'\s*p\s*c\s*s\.?\s*$', re.I)

C_SUB = 1.0
C_DUP = 1.0
C_INS = 1.4
C_DEC = 1.0
C_DEL_ANY = 2.2
MISMATCH = 3.5
DERIVE = 3.0
START_PEN = 0.4
END_PEN = 0.4
GAP_PEN = 0.05
SKIP_JUNK = 0.2
SKIP_REAL = 7.0


def map_digits(s):
    out = []
    cost = 0.0
    for ch in s:
        if ch.isdigit():
            out.append(ch)
        elif ch in L2D:
            out.append(L2D[ch])
            cost += L2D_COST.get(ch, 1.6)
        else:
            return None
    return ''.join(out), cost


def check_ok(letters, digits):
    p1 = ord(letters[0]) - 64
    p2 = ord(letters[1]) - 64
    d = [int(c) for c in digits]
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p1 + p2) % 10 == d[4]


def code_cands(tok):
    t = tok.strip().replace(' ', '')
    if len(t) < 6 or len(t) > 8:
        return None
    letters = ''
    lc = 0.0
    for ch in t[:2]:
        if 'A' <= ch <= 'Z':
            letters += ch
        elif ch in D2L:
            letters += D2L[ch]
            lc += 1.0
        elif 'a' <= ch <= 'z':
            letters += ch.upper()
            lc += 2.0
        else:
            return None
    md = map_digits(t[2:])
    if md is None:
        return None
    ds, dc = md
    base = lc + dc
    res = {}

    def add(dg, c):
        if len(dg) == 5 and check_ok(letters, dg):
            code = letters + dg
            if c < res.get(code, INF):
                res[code] = c

    n = len(ds)
    if n == 5:
        add(ds, base)
        for i in range(5):
            for r in INV.get(ds[i], []):
                add(ds[:i] + r + ds[i + 1:], base + C_SUB)
        if not res:
            for i in range(5):
                for r in INV.get(ds[i], []):
                    s1 = ds[:i] + r + ds[i + 1:]
                    for j in range(i + 1, 5):
                        for r2 in INV.get(s1[j], []):
                            add(s1[:j] + r2 + s1[j + 1:], base + 2 * C_SUB)
    elif n == 4:
        for i in range(5):
            for d in '0123456789':
                add(ds[:i] + d + ds[i:], base + C_INS)
    elif n == 6:
        for i in range(1, 6):
            if ds[i] == ds[i - 1]:
                add(ds[:i] + ds[i + 1:], base + C_DUP)
        if not res:
            for i in range(6):
                add(ds[:i] + ds[i + 1:], base + C_DEL_ANY)
    if not res:
        if n >= 5:
            dg = ds[:5]
        else:
            dg = (ds + '00000')[:5]
        res[letters + dg] = base + 4.0
    return sorted(res.items(), key=lambda kv: (kv[1], kv[0]))


def int_edits(ds, depth):
    seen = {ds: 0.0}
    frontier = {ds: 0.0}
    for _ in range(depth):
        nf = {}
        for s, c in frontier.items():
            n = len(s)
            for i in range(n):
                for r in INV.get(s[i], []):
                    ns = s[:i] + r + s[i + 1:]
                    nc = c + C_SUB
                    if nc < seen.get(ns, INF) and nc < nf.get(ns, INF):
                        nf[ns] = nc
            for i in range(1, n):
                if s[i] == s[i - 1]:
                    ns = s[:i] + s[i + 1:]
                    nc = c + C_DUP
                    if nc < seen.get(ns, INF) and nc < nf.get(ns, INF):
                        nf[ns] = nc
            if n <= 4:
                for i in range(n + 1):
                    for d in '0123456789':
                        ns = s[:i] + d + s[i:]
                        nc = c + C_INS
                        if nc < seen.get(ns, INF) and nc < nf.get(ns, INF):
                            nf[ns] = nc
        for s, c in nf.items():
            if c < seen.get(s, INF):
                seen[s] = c
        frontier = nf
    return seen


def qty_cands(tok, maxv=500):
    t = tok.strip()
    t = PCS_RE.sub('', t).strip()
    if not t or len(t) > 5:
        return None
    md = map_digits(t)
    if md is None:
        return None
    ds, base = md
    res = {}
    for s, c in int_edits(ds, 2).items():
        if not s or (len(s) > 1 and s[0] == '0'):
            continue
        v = int(s)
        if 1 <= v <= maxv:
            cc = base + c
            if cc < res.get(v, INF):
                res[v] = cc
    return sorted(res.items(), key=lambda kv: (kv[1], kv[0]))


def money_cands(tok):
    t = tok.strip().replace(' ', '')
    if not t or len(t) > 14:
        return None
    digs = []
    marks = []
    base = 0.0
    for ch in t:
        if ch.isdigit():
            digs.append(ch)
        elif ch in '.,':
            marks.append(len(digs))
        elif ch in "'`\u2019":
            continue
        elif ch in L2D:
            digs.append(L2D[ch])
            base += L2D_COST.get(ch, 1.6)
        else:
            return None
    if not digs:
        return None
    s = ''.join(digs)
    if len(marks) > 1:
        base += 2.0
    starts = []
    if marks:
        starts.append((s, len(s) - marks[-1], base))
    else:
        starts.append((s, 2, base + C_DEC))
    res = {}

    def add(st, f, c):
        if f != 2 or len(st) < 3:
            return
        ip = st[:-2]
        if len(ip) > 1 and ip[0] == '0':
            return
        v = int(st)
        if v <= 0:
            return
        if c < res.get(v, INF):
            res[v] = c

    for st, f, c0 in starts:
        n = len(st)
        add(st, f, c0)
        for i in range(n):
            for r in INV.get(st[i], []):
                add(st[:i] + r + st[i + 1:], f, c0 + C_SUB)
        for i in range(1, n):
            if st[i] == st[i - 1]:
                nf = f - 1 if i >= n - f else f
                add(st[:i] + st[i + 1:], nf, c0 + C_DUP)
        for i in range(n + 1):
            nf = f + 1 if i > n - f else f
            if nf != 2:
                continue
            for d in '0123456789':
                add(st[:i] + d + st[i:], nf, c0 + C_INS)
    return sorted(res.items(), key=lambda kv: (kv[1], kv[0]))


def parse_doc(state, params):
    text = state.get('input', {}).get('text', '') or ''
    lines = text.replace('\r', '').split('\n')
    order = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    sections = []
    cur = None
    items_tok = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('COLUMNS'):
            names = re.findall(r'CODE|QTY|UNIT|AMOUNT', s)
            if len(names) == 4 and len(set(names)) == 4:
                order = names
            continue
        if s.startswith('MANIFEST'):
            continue
        if re.match(r'^=+\s*SECTION', s):
            cur = []
            sections.append(cur)
            continue
        if s.startswith('SUBTOTAL'):
            cur = None
            continue
        if s.startswith('TOTAL'):
            m = re.search(r'ITEMS\s*(.*)$', s)
            if m:
                items_tok = m.group(1).strip()
            cur = None
            continue
        if cur is None:
            toks0 = [x for x in SPLIT_RE.split(s) if x.strip()]
            if len(toks0) >= 2:
                cur = []
                sections.append(cur)
            else:
                continue
        toks = [x.strip() for x in SPLIT_RE.split(ln) if x.strip()]
        for j, tk in enumerate(toks):
            cur.append([tk, j == 0, j == len(toks) - 1])
    state['parsed'] = {'order': order, 'sections': sections, 'items_tok': items_tok}
    return state


def segment(state, params):
    P = state['parsed']
    order = P['order']
    sections = P['sections']
    memo = {}

    def fc(kind, tok):
        key = (kind, tok)
        if key in memo:
            return memo[key]
        if kind == 'CODE':
            v = code_cands(tok)
        elif kind == 'QTY':
            v = qty_cands(tok)
        else:
            v = money_cands(tok)
        memo[key] = v
        return v

    row_memo = {}

    def row_cost(toks4):
        key = tuple(toks4)
        if key in row_memo:
            return row_memo[key]
        f = dict(zip(order, toks4))
        cc = fc('CODE', f['CODE'])
        qc = fc('QTY', f['QTY'])
        uc = fc('UNIT', f['UNIT'])
        ac = fc('AMOUNT', f['AMOUNT'])
        if cc is None or qc is None or uc is None or ac is None or not cc or not qc:
            row_memo[key] = (INF, None)
            return row_memo[key]
        code, ccost = cc[0]
        adict = {}
        for a, c in ac:
            if a not in adict:
                adict[a] = c
        best = INF
        bq = bu = None
        for q, cq in qc:
            if cq >= best:
                break
            for u, cu in uc:
                c = cq + cu
                if c >= best:
                    break
                ca = adict.get(q * u)
                tot = c + (ca if ca is not None else MISMATCH)
                if tot < best:
                    best, bq, bu = tot, q, u
        for a, ca in ac:
            if ca + DERIVE >= best:
                break
            for q, cq in qc:
                tot = ca + cq + DERIVE
                if tot >= best:
                    break
                if a % q == 0:
                    best, bq, bu = tot, q, a // q
        for a, ca in ac:
            if ca + DERIVE >= best:
                break
            for u, cu in uc:
                tot = ca + cu + DERIVE
                if tot >= best:
                    break
                if a % u == 0 and 1 <= a // u <= 500:
                    best, bq, bu = tot, a // u, u
        if bq is None:
            if uc:
                bq, bu = qc[0][0], uc[0][0]
                best = qc[0][1] + uc[0][1] + MISMATCH + 2.0
            else:
                row_memo[key] = (INF, None)
                return row_memo[key]
        res = (best + ccost, {'code': code, 'qty': int(bq), 'unit_cents': int(bu)})
        row_memo[key] = res
        return res

    sec_results = []
    for toks in sections:
        T = len(toks)
        junk = []
        for tk, _, _ in toks:
            j = True
            for kind in ('CODE', 'QTY', 'UNIT'):
                if fc(kind, tk) is not None:
                    j = False
                    break
            junk.append(j)
        nn = [T] * (T + 1)
        k = T
        for i in range(T - 1, -1, -1):
            if not junk[i]:
                k = i
            nn[i] = k
        f = [None] * (T + 1)
        f[T] = {0: (0.0, None, None)}
        for i in range(T - 1, -1, -1):
            d = {}
            sc = SKIP_JUNK if junk[i] else SKIP_REAL
            for kk, (c, _, _) in f[i + 1].items():
                if c + sc < d.get(kk, (INF,))[0]:
                    d[kk] = (c + sc, 'skip', None)
            if not junk[i]:
                idx = [i]
                gaps = 0
                p = i
                while len(idx) < 4:
                    q = nn[p + 1] if p + 1 <= T else T
                    if q >= T:
                        break
                    gaps += q - p - 1
                    idx.append(q)
                    p = q
                if len(idx) == 4:
                    rc, row = row_cost([toks[x][0] for x in idx])
                    if rc < INF:
                        c0 = rc + gaps * GAP_PEN
                        if not toks[i][1]:
                            c0 += START_PEN
                        if not toks[idx[3]][2]:
                            c0 += END_PEN
                        for kk, (c, _, _) in f[idx[3] + 1].items():
                            tot = c + c0
                            if tot < d.get(kk + 1, (INF,))[0]:
                                d[kk + 1] = (tot, 'row', [idx[3] + 1, row])
            if len(d) > 12:
                d = dict(sorted(d.items(), key=lambda kv: kv[1][0])[:12])
            f[i] = d

        def backtrack(k0, f=f, T=T):
            rows = []
            i = 0
            k = k0
            while i < T:
                ent = f[i].get(k)
                if ent is None:
                    break
                if ent[1] == 'skip':
                    i += 1
                else:
                    nxi, row = ent[2]
                    rows.append(row)
                    i = nxi
                    k -= 1
            return rows

        opts = {}
        for kk, (c, _, _) in f[0].items():
            opts[kk] = c
        sec_results.append((opts, backtrack))

    comb = {0: (0.0, [])}
    for opts, _ in sec_results:
        nc = {}
        for K, (c, ks) in comb.items():
            for k, c2 in opts.items():
                tot = c + c2
                if tot < nc.get(K + k, (INF,))[0]:
                    nc[K + k] = (tot, ks + [k])
        if len(nc) > 40:
            nc = dict(sorted(nc.items(), key=lambda kv: kv[1][0])[:40])
        comb = nc
    itok = P.get('items_tok')
    icands = {}
    if itok:
        r = qty_cands(itok, maxv=2000)
        if r:
            for v, c in r:
                icands[v] = c
    best = None
    for K, (c, ks) in comb.items():
        pen = icands.get(K, 3.0) if icands else 0.0
        tot = c + pen
        if best is None or tot < best[0]:
            best = (tot, ks)
    items = []
    if best is not None:
        for (opts, bt), k in zip(sec_results, best[1]):
            items.extend(bt(k))
    state['output'] = {'items': items}
    return state


def run(state, params):
    try:
        state = parse_doc(state, params)
        state = segment(state, params)
    except Exception:
        state['output'] = state.get('output') or {'items': []}
    if not isinstance(state.get('output'), dict):
        state['output'] = {'items': []}
    state.pop('parsed', None)
    return state

import re
import time

MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
       '6': '50', '7': '12', '8': '30', '9': '43'}
L2D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5',
       'B': '8', 'Z': '2', 'z': '2', 'G': '6', 'D': '0', 'Q': '0'}
D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
INF = 99.0


def _rev():
    r = {}
    for o, obs in MIS.items():
        for c in obs:
            r.setdefault(c, []).append(o)
    return r


SPLIT_RE = re.compile(r"\s*[|;\t]\s*|\s{2,}")
TOKEN_OK = re.compile(r"^[A-Z0-9l.,']+$")


def _strip_pcs(t):
    t = t.strip()
    m = re.match(r"^(.*?)\s*pcs$", t)
    if m:
        return m.group(1).strip(), True
    return t, False


def _tok_type_cost(tok, col):
    t, _ = _strip_pcs(tok)
    if col == 'CODE':
        if re.match(r"^[A-Z0-9]{2}[0-9A-Zl]{3,7}$", t) and re.search(r"[A-Z]", t[:2]) is not None:
            return 0.0
        if re.match(r"^[A-Z0-9]{2}[0-9A-Zl]{3,7}$", t) and not re.search(r"[.,']", t):
            if all(ch in D2L or ch.isalpha() for ch in t[:2]):
                return 1.0
        return 3.0
    if col == 'QTY':
        if re.match(r"^[0-9OlSBZG]{1,4}$", t):
            return 0.0
        return 3.0
    if re.search(r"[A-Z]", t) and re.search(r"[A-Z]{2}", t[:2]):
        return 3.0
    if re.match(r"^[0-9OlSBZG']+([.,][0-9OlSBZG]{1,3})?$", t):
        return 0.0
    return 3.0


def _segment(tokens, cols):
    """Split a section's token stream into rows of 4 fields in cyclic column order.
    DP over (token position, column slot); junk tokens may be skipped anywhere."""
    m = len(tokens)
    SKIP = 4.0
    BIG = 1e9
    tc = [[_tok_type_cost(tokens[i], c) for c in cols] for i in range(m)]
    dp = [[BIG] * 4 for _ in range(m + 1)]
    bp = [[None] * 4 for _ in range(m + 1)]
    dp[0][0] = 0.0
    for i in range(m):
        for k in range(4):
            c = dp[i][k]
            if c >= BIG:
                continue
            if c + SKIP < dp[i + 1][k]:
                dp[i + 1][k] = c + SKIP
                bp[i + 1][k] = (k, 0)
            nk = (k + 1) % 4
            v = c + tc[i][k]
            if v < dp[i + 1][nk]:
                dp[i + 1][nk] = v
                bp[i + 1][nk] = (k, 1)
    rows = []
    curr = {}
    j, k = m, 0
    seq = []
    while j > 0:
        pk, used = bp[j][k]
        if used:
            seq.append((j - 1, pk))
        j, k = j - 1, pk
    seq.reverse()
    for idx, slot in seq:
        curr[cols[slot]] = tokens[idx]
        if slot == 3:
            rows.append(curr)
            curr = {}
    return rows


def parse_document(state, params):
    inp = state.get("input") or {}
    text = inp.get("text", "") if isinstance(inp, dict) else str(inp)
    text = (text or "").replace('\r', '')
    lines = text.split('\n')
    cols = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    for ln in lines:
        if ln.strip().startswith('COLUMNS'):
            found = re.findall(r"CODE|QTY|UNIT|AMOUNT", ln)
            if sorted(found) == sorted(cols):
                cols = found
            break
    sections = []
    cur = None
    total_s = None
    items_s = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if re.match(r"^==+\s*SECTION\b", s):
            cur = {"tokens": [], "sub": None}
            sections.append(cur)
            continue
        m = re.match(r"^SUBTOTAL\s+(\S+)", s)
        if m:
            if cur is None:
                cur = {"tokens": [], "sub": None}
                sections.append(cur)
            cur["sub"] = m.group(1)
            continue
        m = re.match(r"^TOTAL\s+(\S+)(?:\s+ITEMS\s+(\S+))?", s)
        if m:
            total_s = m.group(1)
            items_s = m.group(2)
            continue
        toks = [t.strip() for t in SPLIT_RE.split(s)]
        toks = [t for t in toks if t]
        if not toks:
            continue
        ok = True
        for t in toks:
            b, _ = _strip_pcs(t)
            if not b or not TOKEN_OK.match(b) or (len(b) >= 4 and not re.search(r"[0-9]", b)):
                ok = False
                break
        if not ok:
            continue
        if cur is None:
            cur = {"tokens": [], "sub": None}
            sections.append(cur)
        cur["tokens"].extend(toks)
    out_secs = []
    for sec in sections:
        rows = _segment(sec["tokens"], cols)
        out_secs.append({"rows": rows, "sub": sec["sub"]})
    state["parsed"] = {"cols": cols, "sections": out_secs, "total": total_s, "items": items_s}
    return state


# ---------------------------------------------------------------- candidates

def _map_digits(t):
    return ''.join(L2D.get(ch, ch) for ch in t)


def _fmt(cents, mark, grp):
    i, f = divmod(int(cents), 100)
    s = str(i)
    if grp:
        g = []
        while len(s) > 3:
            g.insert(0, s[-3:])
            s = s[:-3]
        g.insert(0, s)
        s = "'".join(g)
    return s + mark + '%02d' % f


def _ed(o, c, cap=6.0):
    """Weighted edit cost of observed o given canonical original c."""
    n = len(o)
    m = len(c)
    prev = [0.0] * (m + 1)
    for j in range(1, m + 1):
        prev[j] = prev[j - 1] + (1.0 if c[j - 1] != "'" else 2.0)
    for i in range(1, n + 1):
        oi = o[i - 1]
        ins = 1.0 if (i >= 2 and o[i - 2] == oi and oi.isdigit()) else 2.5
        cur = [prev[0] + ins] + [0.0] * m
        rowmin = cur[0]
        for j in range(1, m + 1):
            cj = c[j - 1]
            if oi == cj:
                best = prev[j - 1]
            else:
                if cj.isdigit() and oi.isdigit():
                    sc = 1.0 if oi in MIS[cj] else 2.5
                else:
                    sc = 3.0
                best = prev[j - 1] + sc
            d = cur[j - 1] + (1.0 if cj != "'" else 2.0)
            if d < best:
                best = d
            d = prev[j] + ins
            if d < best:
                best = d
            cur[j] = best
            if best < rowmin:
                rowmin = best
        prev = cur
        if rowmin >= cap:
            return cap
    return min(prev[m], cap)


def _edits1(s, allow_mark, rev):
    """Single damage-undo operations: misread, doubled digit, lost digit, lost mark."""
    out = []
    n = len(s)
    for i in range(n):
        ch = s[i]
        if ch.isdigit():
            for o in rev.get(ch, ()):
                out.append(s[:i] + o + s[i + 1:])
            if i + 1 < n and s[i + 1] == ch:
                out.append(s[:i] + s[i + 1:])
    for i in range(n + 1):
        pre = s[:i]
        post = s[i:]
        for d in '0123456789':
            out.append(pre + d + post)
        if allow_mark and 0 < i <= n:
            out.append(pre + '.' + post)
    return out


def _money_value(s, grp):
    if s.count('.') != 1:
        return None
    a, b = s.split('.')
    if len(b) != 2 or not b.isdigit():
        return None
    ai = a.replace("'", '')
    if not ai.isdigit() or (len(ai) > 1 and ai[0] == '0'):
        return None
    if "''" in a or a.startswith("'") or a.endswith("'"):
        return None
    cents = int(ai) * 100 + int(b)
    extra = 0.0
    if grp or "'" in a:
        if _fmt(cents, '.', grp) != s:
            extra = 0.5
    return cents, extra


def _money_norm(tok, mark):
    t = _map_digits(tok)
    other = ',' if mark == '.' else '.'
    t = t.replace(mark, '#').replace(other, '#').replace('#', '.')
    t = re.sub(r"[^0-9.']", '', t)
    return t


def _money_cands(norm, grp, rev):
    res = {}
    v = _money_value(norm, grp)
    if v is not None:
        res[v[0]] = v[1]
    allow_mark = '.' not in norm
    for s in _edits1(norm, allow_mark, rev):
        v = _money_value(s, grp)
        if v is not None:
            c = 1.0 + v[1]
            if c < res.get(v[0], INF):
                res[v[0]] = c
    return res


def _qty_norm(tok):
    t, _ = _strip_pcs(tok)
    t = _map_digits(t)
    return re.sub(r"[^0-9]", '', t)


def _qty_cands(norm, rev):
    res = {}
    if norm.isdigit() and norm[0] != '0' and 1 <= int(norm) <= 500:
        res[int(norm)] = 0.0
    for s in _edits1(norm, False, rev):
        if s and s.isdigit() and s[0] != '0':
            q = int(s)
            if 1 <= q <= 500 and 1.0 < res.get(q, INF):
                res[q] = 1.0
    return res


def _check_ok(letters, d):
    if len(d) != 5 or not d.isdigit():
        return False
    p = ord(letters[0]) - 64 + ord(letters[1]) - 64
    s = int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p
    return s % 10 == int(d[4])


def _fix_code(tok, rev):
    t = tok.strip()
    head = t[:2]
    letters = ''
    for ch in head:
        if ch in D2L:
            letters += D2L[ch]
        elif ch == 'l':
            letters += 'I'
        elif 'A' <= ch <= 'Z':
            letters += ch
        else:
            letters += 'A'
    while len(letters) < 2:
        letters += 'A'
    d = re.sub(r"[^0-9]", '', _map_digits(t[2:]))
    if _check_ok(letters, d):
        return letters + d
    level = [d]
    seen = {d}
    for depth in range(3):
        nxt = []
        for s in level:
            for e in _edits1(s, False, rev):
                if e in seen:
                    continue
                seen.add(e)
                if _check_ok(letters, e):
                    return letters + e
                if abs(len(e) - 5) <= 2 - depth:
                    nxt.append(e)
        level = nxt
        if len(seen) > 60000:
            break
    d = (d + '00000')[:5]
    return letters + d


def build_candidates(state, params):
    t0 = time.perf_counter()
    rev = _rev()
    P = state["parsed"]
    dots = commas = 0
    grp = False
    money_toks = []
    for sec in P["sections"]:
        for r in sec["rows"]:
            money_toks.append(r.get('UNIT', ''))
            money_toks.append(r.get('AMOUNT', ''))
        if sec.get("sub"):
            money_toks.append(sec["sub"])
    if P.get("total"):
        money_toks.append(P["total"])
    for t in money_toks:
        t = _map_digits(t)
        if "'" in t:
            grp = True
        if re.search(r"\.[0-9]{2}$", t):
            dots += 1
        elif re.search(r",[0-9]{2}$", t):
            commas += 1
    mark = ',' if commas > dots else '.'
    style = {"mark": mark, "grp": grp}
    sec_out = []
    for sec in P["sections"]:
        rows_out = []
        for r in sec["rows"]:
            fast = (time.perf_counter() - t0) > 0.6
            rows_out.append(_row_cands(r, style, rev, fast))
        sub = _money_norm(sec["sub"], mark) if sec.get("sub") else None
        sec_out.append({"rows": rows_out, "sub": sub})
    tot = _money_norm(P["total"], mark) if P.get("total") else None
    state["cands"] = {"sections": sec_out, "total": tot, "style": style}
    return state


def _row_cands(r, style, rev, fast):
    grp = style["grp"]
    code = _fix_code(r.get('CODE', ''), rev)
    qn = _qty_norm(r.get('QTY', ''))
    un = _money_norm(r.get('UNIT', ''), style["mark"])
    an = _money_norm(r.get('AMOUNT', ''), style["mark"])
    Q = _qty_cands(qn, rev)
    U = _money_cands(un, grp, rev)
    A = _money_cands(an, grp, rev)
    cands = {}

    def add(q, u, a, c):
        k = (q, u)
        if c < cands.get(k, (INF,))[0]:
            cands[k] = (c, a)

    Ql = sorted(Q.items(), key=lambda x: (x[1], x[0]))
    Ul = sorted(U.items(), key=lambda x: (x[1], x[0]))
    for q, cq in Ql:
        for u, cu in Ul:
            if cq + cu > 2.6:
                continue
            a = q * u
            ca = A.get(a)
            if ca is not None:
                add(q, u, a, cq + cu + ca)
    best = min([v[0] for v in cands.values()] + [INF])
    if best >= 1.5 and not fast:
        Al = sorted(A.items(), key=lambda x: (x[1], x[0]))
        for q, cq in Ql:
            if cq > 1.0:
                continue
            for a, ca in Al:
                if cq + ca > 1.6 or a % q:
                    continue
                u = a // q
                if u <= 0 or (q, u) in cands:
                    continue
                cu = _ed(un, _fmt(u, '.', grp), 4.0)
                add(q, u, a, cq + ca + cu)
        for u, cu in Ul:
            if cu > 1.6 or u <= 0:
                continue
            for a, ca in Al:
                if cu + ca > 1.6 or a % u:
                    continue
                q = a // u
                if not (1 <= q <= 500) or (q, u) in cands:
                    continue
                cqq = _ed(qn, str(q), 4.0)
                add(q, u, a, cqq + cu + ca)
        for q, cq in Ql:
            for u, cu in Ul:
                if cq + cu > 1.0:
                    continue
                a = q * u
                if (q, u) in cands:
                    continue
                ca = _ed(an, _fmt(a, '.', grp), 4.0)
                add(q, u, a, cq + cu + ca)
    if not cands:
        q = Ql[0][0] if Ql else 1
        u = Ul[0][0] if Ul else 100
        add(q, u, q * u, 8.0)
    lst = sorted(([v[0], k[0], k[1], v[1]] for k, v in cands.items()), key=lambda x: (x[0], x[1], x[2]))
    b = lst[0][0]
    lst = [x for x in lst if x[0] <= b + 3.5][:12]
    return {"code": code, "cands": lst}


# ---------------------------------------------------------------- beam search

def beam_reconcile(state, params):
    t0 = time.perf_counter()
    C = state["cands"]
    grp = C["style"]["grp"]
    BEAM = 300
    SUBCAP = 3.5
    TOTCAP = 3.5
    KSEC = 12
    sec_opts = []
    for sec in C["sections"]:
        rows = sec["rows"]
        states = {0: (0.0, None)}
        for ri, row in enumerate(rows):
            nxt = {}
            for s, (c, path) in states.items():
                for ci, cand in enumerate(row["cands"]):
                    ns = s + cand[3]
                    nc = c + cand[0]
                    old = nxt.get(ns)
                    if old is None or nc < old[0]:
                        nxt[ns] = (nc, (ci, path))
            if len(nxt) > BEAM:
                items = sorted(nxt.items(), key=lambda kv: (kv[1][0], kv[0]))[:BEAM]
                nxt = dict(items)
            states = nxt
            if time.perf_counter() - t0 > 0.25:
                BEAM = 30
        finals = []
        sub = sec.get("sub")
        for s, (c, path) in states.items():
            sc = _ed(sub, _fmt(s, '.', grp), SUBCAP) if sub else 0.0
            finals.append((c + sc, s, path))
        finals.sort(key=lambda x: (x[0], x[1]))
        opts = []
        for tc, s, path in finals[:KSEC]:
            ch = []
            p = path
            while p is not None:
                ch.append(p[0])
                p = p[1]
            ch.reverse()
            opts.append((tc, s, ch))
        if not opts:
            opts = [(0.0, 0, [])]
        sec_opts.append(opts)
    gstates = {0: (0.0, None)}
    for si, opts in enumerate(sec_opts):
        nxt = {}
        for g, (c, path) in gstates.items():
            for oi, (oc, s, ch) in enumerate(opts):
                ng = g + s
                nc = c + oc
                old = nxt.get(ng)
                if old is None or nc < old[0]:
                    nxt[ng] = (nc, (oi, path))
        if len(nxt) > 400:
            nxt = dict(sorted(nxt.items(), key=lambda kv: (kv[1][0], kv[0]))[:400])
        gstates = nxt
    tot = C.get("total")
    best = None
    for g, (c, path) in gstates.items():
        tc = c + (_ed(tot, _fmt(g, '.', grp), TOTCAP) if tot else 0.0)
        if best is None or (tc, g) < (best[0], best[1]):
            best = (tc, g, path)
    choice = []
    p = best[2] if best else None
    while p is not None:
        choice.append(p[0])
        p = p[1]
    choice.reverse()
    items = []
    for si, sec in enumerate(C["sections"]):
        oi = choice[si] if si < len(choice) else 0
        ch = sec_opts[si][oi][2]
        for ri, row in enumerate(sec["rows"]):
            ci = ch[ri] if ri < len(ch) else 0
            cand = row["cands"][ci]
            items.append({"code": row["code"], "qty": int(cand[1]), "unit_cents": int(cand[2])})
    state["output"] = {"items": items}
    return state

import re
import time
import random

LOOK_D = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5',
          'B': '8', 'Z': '2', 'z': '2', 'G': '6'}
LOOK_L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63', '6': '50',
       '7': '12', '8': '30', '9': '43'}
REV = {}
for _t, _ss in MIS.items():
    for _s in _ss:
        REV.setdefault(_s, []).append(_t)

C_LOOK = 0.2
C_MIS = 3.0
C_LOST = 3.5
C_DUP = 3.3
C_MARK = 1.0
C_BAD = 8.0
P_ROW = 10.0
P_SUB = 10.0
P_TOT = 8.0
P_ITEMS = 6.0
P_LEFT = 12.0
P_SKIP = 10.0
P_CHECK = 12.0
MONEY_RE = re.compile(r'^(0|[1-9]\d*)\.\d\d$')
INT_RE = re.compile(r'^[1-9]\d*$')
NAMES = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
TOKEN_RE = re.compile(r"^[0-9A-Za-z.,']+$")


def check_digit(code):
    p1 = ord(code[0]) - 64
    p2 = ord(code[1]) - 64
    d = [int(c) for c in code[2:6]]
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p1 + p2) % 10


def sub_cost(t, o):
    if t == o:
        return 0.0
    if t.isdigit():
        if LOOK_D.get(o) == t:
            return C_LOOK
        if o in MIS[t]:
            return C_MIS
        return C_BAD
    if t.isalpha():
        if LOOK_L.get(o) == t:
            return C_LOOK
        return C_BAD
    return C_BAD


def edit_cost(t, o):
    n = len(t)
    m = len(o)
    INF = 1e9
    dp = [[INF] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        row = dp[i]
        for j in range(m + 1):
            v = row[j]
            if v >= INF:
                continue
            if j < m:
                w = v + C_BAD
                if w < row[j + 1]:
                    row[j + 1] = w
            if i < n:
                ti = t[i]
                nx = dp[i + 1]
                if j < m:
                    w = v + sub_cost(ti, o[j])
                    if w < nx[j + 1]:
                        nx[j + 1] = w
                    if j + 1 < m and ti.isdigit() and o[j] == ti and o[j + 1] == ti:
                        w = v + C_DUP
                        if w < nx[j + 2]:
                            nx[j + 2] = w
                w = v + (C_MARK if ti == '.' else (C_LOST if ti.isdigit() else C_BAD))
                if w < nx[j]:
                    nx[j] = w
    return dp[n][m]


def norm_money(tok):
    return tok.replace("'", '').replace(' ', '').replace(',', '.')


def norm_int(tok):
    s = re.sub(r'(?i)pcs', '', tok)
    return s.replace(' ', '').replace("'", '')


def render_money(v):
    return '%d.%02d' % (v // 100, v % 100)


def money_value(s):
    if MONEY_RE.match(s):
        return int(s.replace('.', ''))
    return None


def digit_edits(s):
    yield s, 0.0
    n = len(s)
    for i in range(n):
        ch = s[i]
        if ch.isdigit():
            for t in REV.get(ch, ()):
                yield s[:i] + t + s[i + 1:], C_MIS
            if i > 0 and s[i - 1] == ch:
                yield s[:i] + s[i + 1:], C_DUP
    for i in range(n + 1):
        for d in '0123456789':
            yield s[:i] + d + s[i:], C_LOST


def money_cands(tok):
    o = norm_money(tok)
    base = []
    c0 = 0.0
    for ch in o:
        if ch in LOOK_D:
            base.append(LOOK_D[ch])
            c0 += C_LOOK
        else:
            base.append(ch)
    b = ''.join(base)
    if b.count('.') > 1:
        k = b.rfind('.')
        b = b[:k].replace('.', '') + b[k:]
        c0 += C_BAD
    res = {}
    for s, c in digit_edits(b):
        cc = c0 + c
        if '.' not in s:
            if len(s) < 3:
                continue
            s = s[:-2] + '.' + s[-2:]
            cc += C_MARK
        v = money_value(s)
        if v is None:
            continue
        if v in res:
            res[v] = min(res[v], cc) - 0.02
        else:
            res[v] = cc
    return res


def int_cands(tok, lo, hi):
    o = norm_int(tok)
    base = []
    c0 = 0.0
    for ch in o:
        if ch in LOOK_D:
            base.append(LOOK_D[ch])
            c0 += C_LOOK
        else:
            base.append(ch)
    b = ''.join(base)
    res = {}
    for s, c in digit_edits(b):
        if not INT_RE.match(s):
            continue
        v = int(s)
        if v < lo or v > hi:
            continue
        cc = c0 + c
        if v in res:
            res[v] = min(res[v], cc) - 0.02
        else:
            res[v] = cc
    return res


def best_code(tok):
    o = tok.replace(' ', '')
    if len(o) < 2:
        return 'AA00000'
    c0 = 0.0
    letters = []
    for ch in o[:2]:
        if ch in LOOK_L:
            letters.append(LOOK_L[ch])
            c0 += C_LOOK
        else:
            letters.append(ch.upper())
    L = ''.join(letters)
    if not (len(L) == 2 and all('A' <= x <= 'Z' for x in L)):
        L = ''.join(x if 'A' <= x <= 'Z' else 'A' for x in L)
    digs = []
    for ch in o[2:]:
        digs.append(LOOK_D.get(ch, ch))
    D = ''.join(digs)
    best = {}
    frontier = [(D, 0.0)]
    seen = {D: 0.0}
    for level in range(3):
        for s, c in frontier:
            if len(s) == 5 and s.isdigit():
                code = L + s
                ok = check_digit(code) == int(s[4])
                tot = c + (0.0 if ok else P_CHECK)
                if code in best:
                    best[code] = min(best[code], tot) - 0.02
                else:
                    best[code] = tot
        good = [k for k, v in best.items() if v < P_CHECK]
        if good or level == 2:
            break
        nf = []
        for s, c in frontier:
            if len(s) > 8:
                continue
            for s2, c2 in digit_edits(s):
                if c2 == 0.0:
                    continue
                if level == 1 and len(s2) != 5 and abs(len(s2) - 5) >= abs(len(s) - 5):
                    continue
                cc = c + c2
                if s2 not in seen or seen[s2] > cc:
                    seen[s2] = cc
                    nf.append((s2, cc))
        frontier = nf
    if not best:
        s = (D + '00000')[:5]
        s = ''.join(x if x.isdigit() else '0' for x in s)
        return L + s
    return min(best.items(), key=lambda kv: (kv[1], kv[0]))[0]


def detect_sep(lines):
    for ln in lines:
        if 'COLUMNS' in ln:
            body = ln.split('COLUMNS', 1)[1]
            pos = []
            for nm in NAMES:
                k = body.find(nm)
                if k >= 0:
                    pos.append((k, nm))
            pos.sort()
            order = [nm for _, nm in pos]
            sep = 'pipe'
            if len(pos) >= 2:
                mid = body[pos[0][0] + len(pos[0][1]):pos[1][0]]
                if '|' in mid:
                    sep = 'pipe'
                elif ';' in mid:
                    sep = 'semi'
                elif '\t' in mid:
                    sep = 'tab'
                else:
                    sep = 'space'
            if len(order) == 4:
                return sep, order
            return sep, NAMES[:]
    return 'pipe', NAMES[:]


def split_line(ln, sep):
    if sep == 'pipe':
        parts = ln.split('|')
    elif sep == 'semi':
        parts = ln.split(';')
    elif sep == 'tab':
        parts = ln.split('\t')
    else:
        parts = re.split(r' {2,}|\t', ln)
    return [p.strip() for p in parts if p.strip()]


def is_junk_tokens(toks):
    if not toks:
        return True
    for t in toks:
        u = re.sub(r'\s*pcs$', '', t)
        if not u or not TOKEN_RE.match(u) or len(u) > 16:
            return True
        if re.search(r'[a-hj-km-np-rt-y]', u):
            return True
        if not re.search(r'[0-9OlISBZG]', u):
            return True
        if re.search(r'[ACDEFHJKLMNPQRTUVWXY]', u[2:]):
            return True
    return False


def parse_doc(text):
    lines = text.split('\n')
    sep, order = detect_sep(lines)
    sections = []
    total_tok = None
    items_tok = None
    cur = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        m = re.match(r'^==\s*SECTION\b(.*)$', s)
        if m:
            cur = {'lines': [], 'sub': None}
            sections.append(cur)
            continue
        m = re.match(r'^SUBTOTAL\s+(.*)$', s)
        if m:
            if cur is None:
                cur = {'lines': [], 'sub': None}
                sections.append(cur)
            if cur['sub'] is None:
                cur['sub'] = m.group(1).strip()
            cur = None
            continue
        m = re.match(r'^TOTAL\s+(.*?)\s+ITEMS\s+(.*)$', s)
        if m:
            total_tok = m.group(1).strip()
            items_tok = m.group(2).strip()
            continue
        m = re.match(r'^TOTAL\s+(.*)$', s)
        if m:
            total_tok = m.group(1).strip()
            continue
        toks = split_line(ln, sep)
        jk = is_junk_tokens(toks)
        if cur is None:
            if jk:
                continue
            cur = {'lines': [], 'sub': None}
            sections.append(cur)
        cur['lines'].append({'toks': toks, 'skip': jk, 'junk': jk})
    return sep, order, sections, total_tok, items_tok


def make_solver(order):
    idx = {nm: order.index(nm) for nm in NAMES}
    cand_cache = {}
    dp_cache = {}
    sorted_cache = {}

    def cands(kind, tok):
        key = (kind, tok)
        r = cand_cache.get(key)
        if r is None:
            if kind == 'q':
                r = int_cands(tok, 1, 500)
            elif kind == 'n':
                r = int_cands(tok, 1, 100000)
            else:
                r = money_cands(tok)
            cand_cache[key] = r
        return r

    def top(kind, tok, k):
        key = (kind, tok, k)
        r = sorted_cache.get(key)
        if r is None:
            c = cands(kind, tok)
            r = sorted(c.items(), key=lambda kv: (kv[1], kv[0]))[:k]
            sorted_cache[key] = r
        return r

    def cost(kind, tok, v):
        if v is None:
            return 50.0
        c = cands(kind, tok)
        if v in c:
            return c[v]
        key = (kind, tok, v)
        r = dp_cache.get(key)
        if r is None:
            if kind in ('q', 'n'):
                t = str(v)
                o = norm_int(tok)
            else:
                if v < 0:
                    dp_cache[key] = 50.0
                    return 50.0
                t = render_money(v)
                o = norm_money(tok)
            r = min(edit_cost(t, o), 30.0)
            dp_cache[key] = r
        return r

    def base_val(kind, tok):
        t = top(kind, tok, 1)
        return t[0][0] if t else None

    return {'cands': cands, 'top': top, 'cost': cost, 'base': base_val, 'idx': idx}


def build_rows(sec, idx):
    toks = []
    for ln in sec['lines']:
        if not ln['skip']:
            toks.extend(ln['toks'])
    rows = []
    nfull = len(toks) // 4
    for r in range(nfull):
        g = toks[4 * r:4 * r + 4]
        rows.append({'code': g[idx['CODE']], 'qty': g[idx['QTY']],
                     'unit': g[idx['UNIT']], 'amt': g[idx['AMOUNT']]})
    return rows, len(toks) - 4 * nfull


def solve_doc(text, deadline):
    sep, order, sections, total_tok, items_tok = parse_doc(text)
    S = make_solver(order)
    cost = S['cost']
    top = S['top']
    base = S['base']
    idx = S['idx']
    rng = random.Random(1234567)

    def init_section(sec):
        rows, left = build_rows(sec, idx)
        h = {'rows': rows, 'left': left}
        h['q'] = [base('q', r['qty']) or 1 for r in rows]
        h['u'] = [base('m', r['unit']) or 0 for r in rows]
        h['a'] = [base('m', r['amt']) or 0 for r in rows]
        h['S'] = base('m', sec['sub']) if sec['sub'] is not None else None
        return h

    def row_e(h, i):
        r = h['rows'][i]
        q, u, a = h['q'][i], h['u'][i], h['a'][i]
        e = cost('q', r['qty'], q) + cost('m', r['unit'], u) + cost('m', r['amt'], a)
        if q * u != a:
            e += P_ROW
        return e

    def sec_term(h, sm):
        if h['S'] is None:
            return 0.0
        return P_SUB if sm != h['S'] else 0.0

    def subtotal_cost(sec, h):
        if sec['sub'] is None or h['S'] is None:
            return 0.0
        return cost('m', sec['sub'], h['S'])

    def sec_energy(sec, h):
        e = h['left'] * P_LEFT
        for ln in sec['lines']:
            if ln['skip'] and not ln['junk']:
                e += P_SKIP * len(ln['toks'])
        for i in range(len(h['rows'])):
            e += row_e(h, i)
        e += sec_term(h, sum(h['a'])) + subtotal_cost(sec, h)
        return e

    def sec_value(h):
        return h['S'] if h['S'] is not None else sum(h['a'])

    def glob_extra(H, T, N):
        e = 0.0
        if total_tok is not None:
            e += cost('m', total_tok, T)
            if T != sum(sec_value(h) for h in H):
                e += P_TOT
        if items_tok is not None:
            e += cost('n', items_tok, N)
            if N != sum(len(h['rows']) for h in H):
                e += P_ITEMS
        return e

    def glob_energy(H, T, N):
        e = 0.0
        for sec, h in zip(sections, H):
            e += sec_energy(sec, h)
        return e + glob_extra(H, T, N)

    def row_move(h, i):
        r = h['rows'][i]
        tq, tu, ta = r['qty'], r['unit'], r['amt']
        sm_other = sum(h['a']) - h['a'][i]
        cur = row_e(h, i) + sec_term(h, sm_other + h['a'][i])
        Qc = top('q', tq, 10)
        Uc = top('m', tu, 24)
        Ac = top('m', ta, 24)
        Afull = S['cands']('m', ta)
        Ufull = S['cands']('m', tu)
        opts = {}

        def add(q, u, a):
            if q is None or u is None or a is None:
                return
            key = (q, u, a)
            if key in opts:
                return
            e = cost('q', tq, q) + cost('m', tu, u) + cost('m', ta, a)
            if q * u != a:
                e += P_ROW
            e += sec_term(h, sm_other + a)
            opts[key] = e

        cq, cu, ca = h['q'][i], h['u'][i], h['a'][i]
        add(cq, cu, ca)
        q0 = Qc[0][0] if Qc else cq
        u0 = Uc[0][0] if Uc else cu
        a0 = Ac[0][0] if Ac else ca
        add(q0, u0, a0)
        add(cq, cu, cq * cu)
        add(q0, u0, q0 * u0)
        for q, _ in Qc:
            for u, _ in Uc:
                a = q * u
                if a in Afull:
                    add(q, u, a)
        for q, _ in Qc[:6]:
            for a, _ in Ac[:8]:
                if q > 0 and a % q == 0:
                    add(q, a // q, a)
        for u, _ in Uc[:8]:
            if u <= 0:
                continue
            for a, _ in Ac[:8]:
                if a % u == 0 and 1 <= a // u <= 500:
                    add(a // u, u, a)
        if h['S'] is not None:
            need = h['S'] - sm_other
            if need > 0:
                add(q0, u0, need)
                add(cq, cu, need)
                for q, _ in Qc:
                    if need % q == 0:
                        u = need // q
                        if u in Ufull or q == cq or q == q0:
                            add(q, u, need)
                for u, _ in Uc[:8]:
                    if u > 0 and need % u == 0 and 1 <= need // u <= 500:
                        add(need // u, u, need)
        best = min(opts.items(), key=lambda kv: (kv[1], kv[0]))
        if best[1] < cur - 1e-9:
            h['q'][i], h['u'][i], h['a'][i] = best[0]
            return cur - best[1]
        return 0.0

    def sub_move(sec, h, H, T):
        if sec['sub'] is None or h['S'] is None:
            return 0.0
        sm = sum(h['a'])
        others = sum(sec_value(x) for x in H if x is not h)

        def e_of(Sv):
            e = cost('m', sec['sub'], Sv) + (P_SUB if sm != Sv else 0.0)
            if total_tok is not None and T != others + Sv:
                e += P_TOT
            return e
        cur = e_of(h['S'])
        cl = [sm]
        if T is not None:
            cl.append(T - others)
        cl += [v for v, _ in top('m', sec['sub'], 3)]
        best = None
        for v in cl:
            if v is None or v < 0:
                continue
            e = e_of(v)
            if best is None or e < best[0] - 1e-12:
                best = (e, v)
        if best and best[0] < cur - 1e-9:
            h['S'] = best[1]
            return cur - best[0]
        return 0.0

    def climb(H, T, N, cap, only=None, full=True):
        it = 0
        while it < cap:
            it += 1
            gain = 0.0
            for si, (sec, h) in enumerate(zip(sections, H)):
                if only is not None and si not in only:
                    continue
                sec_bad = h['S'] is not None and sum(h['a']) != h['S']
                for i in range(len(h['rows'])):
                    if sec_bad or h['q'][i] * h['u'][i] != h['a'][i] or (it == 1 and full):
                        g = row_move(h, i)
                        if g > 0:
                            gain += g
                            sec_bad = h['S'] is not None and sum(h['a']) != h['S']
                gain += sub_move(sec, h, H, T)
            if total_tok is not None:
                want = sum(sec_value(h) for h in H)
                cur = cost('m', total_tok, T) + (P_TOT if T != want else 0.0)
                new = cost('m', total_tok, want)
                if new < cur - 1e-9:
                    T = want
                    gain += cur - new
            if items_tok is not None:
                want = sum(len(h['rows']) for h in H)
                cur = cost('n', items_tok, N) + (P_ITEMS if N != want else 0.0)
                new = cost('n', items_tok, want)
                if new < cur - 1e-9:
                    N = want
                    gain += cur - new
            if gain <= 1e-9 or time.perf_counter() > deadline:
                break
        return T, N

    H = [init_section(sec) for sec in sections]
    T = base('m', total_tok) if total_tok is not None else None
    N = base('n', items_tok) if items_tok is not None else None
    T, N = climb(H, T, N, 12)

    def sec_broken(sec, h):
        if h['left']:
            return True
        for i in range(len(h['rows'])):
            if row_e(h, i) >= 2 * C_BAD:
                return True
        return False

    for si, sec in enumerate(sections):
        for _round in range(2):
            h = H[si]
            if not sec_broken(sec, h) or time.perf_counter() > deadline:
                break
            best_e = glob_energy(H, T, N)
            best_choice = None
            for li in range(len(sec['lines'])):
                if time.perf_counter() > deadline:
                    break
                ln = sec['lines'][li]
                ln['skip'] = not ln['skip']
                h2 = init_section(sec)
                H2 = H[:si] + [h2] + H[si + 1:]
                T2, N2 = climb(H2, T, N, 6, only=[si])
                e2 = glob_energy(H2, T2, N2)
                ln['skip'] = not ln['skip']
                if e2 < best_e - 1e-9:
                    best_e = e2
                    best_choice = (li, h2, T2, N2)
            if best_choice is None:
                break
            li, h2, T, N = best_choice
            sec['lines'][li]['skip'] = not sec['lines'][li]['skip']
            H[si] = h2

    def snapshot(HH):
        return [{'rows': h['rows'], 'left': h['left'], 'q': h['q'][:], 'u': h['u'][:],
                 'a': h['a'][:], 'S': h['S']} for h in HH]

    best_E = glob_energy(H, T, N)
    best = (snapshot(H), T, N)
    restarts = 0
    while restarts < 16 and time.perf_counter() < deadline:
        Hc, Tc, Nc = best
        bad = []
        for si, h in enumerate(Hc):
            viol = [i for i in range(len(h['rows'])) if h['q'][i] * h['u'][i] != h['a'][i]]
            if viol or (h['S'] is not None and sum(h['a']) != h['S']):
                bad.append((si, viol))
        if not bad:
            break
        restarts += 1
        H2 = snapshot(Hc)
        for si, viol in bad:
            h = H2[si]
            pool = viol if viol else list(range(len(h['rows'])))
            if not pool:
                continue
            k = min(len(pool), rng.randint(1, 2))
            for i in rng.sample(pool, k):
                r = h['rows'][i]
                which = rng.randint(0, 2)
                if which == 0:
                    c = top('q', r['qty'], 6)
                    if c:
                        h['q'][i] = rng.choice(c)[0]
                elif which == 1:
                    c = top('m', r['unit'], 6)
                    if c:
                        h['u'][i] = rng.choice(c)[0]
                else:
                    c = top('m', r['amt'], 6)
                    if c:
                        h['a'][i] = rng.choice(c)[0]
            if h['S'] is not None and rng.random() < 0.3:
                h['S'] = sum(h['a'])
        T2, N2 = climb(H2, Tc, Nc, 8, full=False)
        e2 = glob_energy(H2, T2, N2)
        if e2 < best_E - 1e-9:
            best_E = e2
            best = (snapshot(H2), T2, N2)
    H, T, N = best

    items = []
    for h in H:
        for i, r in enumerate(h['rows']):
            items.append({'code': best_code(r['code']), 'qty': int(h['q'][i]),
                          'unit_cents': int(h['u'][i])})
    return items


def naive_items(text):
    try:
        sep, order, sections, _, _ = parse_doc(text)
        idx = {nm: order.index(nm) for nm in NAMES}
        out = []
        for sec in sections:
            rows, _ = build_rows(sec, idx)
            for r in rows:
                q = int_cands(r['qty'], 1, 500)
                u = money_cands(r['unit'])
                out.append({'code': re.sub(r'\s', '', r['code'])[:7],
                            'qty': min(q, key=q.get) if q else 1,
                            'unit_cents': min(u, key=u.get) if u else 0})
        return out
    except Exception:
        return []


def solve(state, params):
    t0 = time.perf_counter()
    inp = state.get('input') or {}
    text = inp.get('text', '') if isinstance(inp, dict) else ''
    try:
        items = solve_doc(text, t0 + 0.6)
    except Exception:
        items = naive_items(text)
    state['output'] = {'items': items}
    return state

import re
import time
import math

MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
       '6': '50', '7': '12', '8': '30', '9': '43'}
REVM = {}
for _o in sorted(MIS):
    for _c in MIS[_o]:
        REVM.setdefault(_c, []).append(_o)
L2D = {'O': '0', 'o': '0', 'Q': '0', 'D': '0', 'l': '1', 'I': '1', 'i': '1', '|': '1',
       'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6'}
D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G', 'l': 'I'}
LOOKSET = set('OlISBZG')
DIG = '0123456789'
LAM = 2.3
C_MIS = 1.0
C_SUB = 2.5
C_DUP = 1.0
C_DEL = 2.5
C_INS = 1.2
C_MARK = 0.4
INF = 1e9
SPLIT_RE = re.compile(r"\s*[|;\t]\s*|\s{2,}")


# ------------------------------------------------------------ edit model

def _ops(s, anysub):
    out = []
    n = len(s)
    for i in range(n):
        ch = s[i]
        if not ch.isdigit():
            continue
        origs = REVM.get(ch, [])
        for o in origs:
            out.append((s[:i] + o + s[i + 1:], C_MIS))
        if anysub:
            for o in DIG:
                if o != ch and o not in origs:
                    out.append((s[:i] + o + s[i + 1:], C_SUB))
        if i + 1 < n and s[i + 1] == ch:
            out.append((s[:i] + s[i + 1:], C_DUP))
        elif anysub and not (i > 0 and s[i - 1] == ch):
            out.append((s[:i] + s[i + 1:], C_DEL))
    for i in range(n + 1):
        a = s[:i]
        b = s[i:]
        for d in DIG:
            out.append((a + d + b, C_INS))
    return out


def _ed(o, c, cap):
    m = len(c)
    prev = [0.0] * (m + 1)
    for j in range(1, m + 1):
        prev[j] = prev[j - 1] + (C_MARK if c[j - 1] == '.' else C_INS)
    for i in range(1, len(o) + 1):
        oi = o[i - 1]
        if oi == '.':
            ins = 3.0
        elif i >= 2 and o[i - 2] == oi:
            ins = C_DUP
        else:
            ins = C_DEL
        cur = [prev[0] + ins] + [0.0] * m
        rmin = cur[0]
        for j in range(1, m + 1):
            cj = c[j - 1]
            if oi == cj:
                b = prev[j - 1]
            elif oi == '.' or cj == '.' or not oi.isdigit() or not cj.isdigit():
                b = prev[j - 1] + 3.0
            elif oi in MIS[cj]:
                b = prev[j - 1] + C_MIS
            else:
                b = prev[j - 1] + C_SUB
            d = cur[j - 1] + (C_MARK if cj == '.' else C_INS)
            if d < b:
                b = d
            d = prev[j] + ins
            if d < b:
                b = d
            cur[j] = b
            if b < rmin:
                rmin = b
        if rmin >= cap:
            return cap
        prev = cur
    return min(prev[m], cap)


def _fmt(c):
    return '%d.%02d' % (c // 100, c % 100)


def _strip_pcs(t):
    t = t.strip()
    m = re.match(r"^(.*?)\s*pcs$", t)
    if m:
        return m.group(1).strip(), True
    return t, False


def _money_norm(tok):
    t = ''.join(L2D.get(ch, ch) for ch in (tok or ''))
    t = t.replace(',', '.')
    t = re.sub(r"[^0-9.]", '', t)
    if t.count('.') > 1:
        k = t.rfind('.')
        t = t[:k].replace('.', '') + t[k:]
    return t


def _qty_norm(tok):
    b, _ = _strip_pcs(tok or '')
    t = ''.join(L2D.get(ch, ch) for ch in b)
    return re.sub(r"[^0-9]", '', t)


def _money_parse(s):
    if '.' in s:
        if s.count('.') != 1:
            return None
        a, b = s.split('.')
        if len(b) != 2 or not a or not a.isdigit() or not b.isdigit():
            return None
        if len(a) > 1 and a[0] == '0':
            return None
        v = int(a) * 100 + int(b)
        if v <= 0:
            return None
        return v, 0.0
    if len(s) < 3 or not s.isdigit():
        return None
    a = s[:-2]
    if len(a) > 1 and a[0] == '0':
        return None
    v = int(s)
    if v <= 0:
        return None
    return v, C_MARK


def _qty_parse(s):
    if not s or not s.isdigit() or s[0] == '0':
        return None
    v = int(s)
    if 1 <= v <= 500:
        return v, 0.0
    return None


def _cands(s, parse):
    W = {}

    def put(t, c):
        r = parse(t)
        if r is None:
            return
        val, extra = r
        W[val] = W.get(val, 0.0) + math.exp(-LAM * (c + extra))

    put(s, 0.0)
    if s:
        for t, c in _ops(s, False):
            put(t, c)
    else:
        for d in DIG:
            put(d, C_INS)
    out = {}
    for v, w in W.items():
        out[v] = max(0.0, -math.log(w) / LAM)
    return out


# ------------------------------------------------------------ codes

def _code_valid(L, d):
    if len(d) != 5 or not d.isdigit():
        return False
    p = ord(L[0]) - 64 + ord(L[1]) - 64
    return (int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p) % 10 == int(d[4])


def _fix_code(tok):
    t = re.sub(r"\s+", "", tok or '')
    letters = ''
    for ch in t[:2]:
        if 'A' <= ch <= 'Z':
            letters += ch
        elif ch in D2L:
            letters += D2L[ch]
        elif 'a' <= ch <= 'z':
            letters += ch.upper()
        else:
            letters += 'A'
    while len(letters) < 2:
        letters += 'A'
    ds = re.sub(r"[^0-9]", '', ''.join(L2D.get(ch, ch) for ch in t[2:]))
    if _code_valid(letters, ds):
        return letters + ds
    W = {}
    frontier = {ds: 1.0}
    for depth in (1, 2):
        nxt = {}
        for s, w in frontier.items():
            for e, c in _ops(s, True):
                nxt[e] = nxt.get(e, 0.0) + w * math.exp(-LAM * c)
        for e, w in nxt.items():
            if len(e) == 5 and _code_valid(letters, e):
                W[e] = W.get(e, 0.0) + w
        if W:
            break
        items = [(w, e) for e, w in nxt.items() if 3 <= len(e) <= 7]
        items.sort(key=lambda x: (-x[0], x[1]))
        frontier = dict((e, w) for w, e in items[:250])
    if W:
        best = min(W.items(), key=lambda kv: (-round(kv[1], 12), kv[0]))
        return letters + best[0]
    d = (ds + '00000')[:4]
    p = ord(letters[0]) - 64 + ord(letters[1]) - 64
    ck = (int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p) % 10
    return letters + d + str(ck)


# ------------------------------------------------------------ parsing

def _tok_ok(t):
    b, has = _strip_pcs(t)
    if not b:
        return has
    if not re.fullmatch(r"[A-Z0-9l.,']+", b):
        return False
    for ch in b[2:]:
        if 'A' <= ch <= 'Z' and ch not in LOOKSET:
            return False
    return True


def _tc(tok, col, pcs):
    b, has = _strip_pcs(tok)
    if col == 'QTY':
        if not re.fullmatch(r"[0-9OlISBZG]{0,4}", b):
            return 4.0
        c = 0.0
        if pcs and not has:
            c += 2.0
        if not b:
            c += 1.5
        return c
    if has:
        return 6.0
    if col == 'CODE':
        if re.fullmatch(r"[A-Z0-9l]{2}[0-9OlISBZG]{3,7}", b):
            h = b[:2]
            if all('A' <= ch <= 'Z' for ch in h):
                return 0.0
            if all(('A' <= ch <= 'Z') or ch in D2L for ch in h):
                return 0.8
        return 4.0
    if re.fullmatch(r"[0-9OlISBZG']+[.,][0-9OlISBZG]{1,3}", b):
        return 0.0
    if re.fullmatch(r"[0-9OlISBZG']{3,}", b):
        return 0.6
    if re.fullmatch(r"[0-9OlISBZG']{1,2}", b):
        return 2.0
    return 4.0


def _segment(tokens, cols, pcs):
    m = len(tokens)
    if m == 0:
        return []
    BIG = 1e18
    SKIP = 4.0
    tc = [[_tc(t, c, pcs) for c in cols] for t in tokens]
    emp = [2.0 if c == 'QTY' else 4.5 for c in cols]
    dp = [[BIG] * 4 for _ in range(m + 1)]
    bp = [[None] * 4 for _ in range(m + 1)]
    dp[0][0] = 0.0
    for i in range(m + 1):
        for _ in range(2):
            for k in range(4):
                c = dp[i][k]
                if c >= BIG:
                    continue
                nk = (k + 1) % 4
                v = c + emp[k]
                if v < dp[i][nk] - 1e-12:
                    dp[i][nk] = v
                    bp[i][nk] = (i, k, 'e')
        if i == m:
            break
        for k in range(4):
            c = dp[i][k]
            if c >= BIG:
                continue
            v = c + SKIP
            if v < dp[i + 1][k] - 1e-12:
                dp[i + 1][k] = v
                bp[i + 1][k] = (i, k, 's')
            nk = (k + 1) % 4
            v = c + tc[i][k]
            if v < dp[i + 1][nk] - 1e-12:
                dp[i + 1][nk] = v
                bp[i + 1][nk] = (i, k, 'u')
    ops = []
    i, k = m, 0
    guard = 0
    while bp[i][k] is not None and guard < 100000:
        pi, pk, kind = bp[i][k]
        ops.append((pi, pk, kind))
        i, k = pi, pk
        guard += 1
    ops.reverse()
    rows = []
    cur = {}
    for pi, pk, kind in ops:
        if kind == 's':
            continue
        cur[cols[pk]] = tokens[pi] if kind == 'u' else ''
        if pk == 3:
            rows.append(cur)
            cur = {}
    return rows


def _parse(text):
    lines = (text or '').replace('\r', '').split('\n')
    cols = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    for ln in lines:
        if ln.strip().startswith('COLUMNS'):
            found = re.findall(r"CODE|QTY|UNIT|AMOUNT", ln)
            if sorted(found) == sorted(cols):
                cols = found
            break
    secs = []
    cur = None
    total_s = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if re.match(r"^=+\s*SECTION\b", s):
            cur = {'tokens': [], 'sub': None}
            secs.append(cur)
            continue
        if s.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'tokens': [], 'sub': None}
                secs.append(cur)
            cur['sub'] = re.sub(r"\s+", "", s[len('SUBTOTAL'):])
            continue
        if s.startswith('TOTAL'):
            mm = re.match(r"^TOTAL\s*(.*?)(?:\s+ITEMS\b.*)?$", s)
            if mm:
                total_s = re.sub(r"\s+", "", mm.group(1))
            continue
        toks = [t.strip() for t in SPLIT_RE.split(s)]
        toks = [t for t in toks if t]
        if not toks:
            continue
        if not all(_tok_ok(t) for t in toks):
            continue
        if cur is None:
            cur = {'tokens': [], 'sub': None}
            secs.append(cur)
        cur['tokens'].extend(toks)
    pcs = False
    for sec in secs:
        for t in sec['tokens']:
            if t.endswith('pcs'):
                pcs = True
                break
    out = []
    for sec in secs:
        out.append({'rows': _segment(sec['tokens'], cols, pcs), 'sub': sec['sub']})
    return out, total_s


# ------------------------------------------------------------ rows

def _row_cands(r, fast):
    qn = _qty_norm(r.get('QTY', ''))
    un = _money_norm(r.get('UNIT', ''))
    an = _money_norm(r.get('AMOUNT', ''))
    q0 = _qty_parse(qn)
    u0 = _money_parse(un)
    a0 = _money_parse(an)
    if q0 is not None and u0 is not None and a0 is not None and q0[0] * u0[0] == a0[0]:
        return [[u0[1] + a0[1], q0[0], u0[0]]]
    Q = _cands(qn, _qty_parse)
    U = _cands(un, _money_parse)
    A = _cands(an, _money_parse)
    cands = {}

    def add(q, u, c):
        k = (q, u)
        if c < cands.get(k, INF):
            cands[k] = c

    for q, cq in Q.items():
        for u, cu in U.items():
            ca = A.get(q * u)
            if ca is not None:
                add(q, u, cq + cu + ca)
    best = min(cands.values()) if cands else INF
    if best > 1.5 and not fast:
        TH = 1.3
        Ql = sorted([(q, c) for q, c in Q.items() if c <= TH], key=lambda x: (x[1], x[0]))
        Ul = sorted([(u, c) for u, c in U.items() if c <= TH], key=lambda x: (x[1], x[0]))
        Al = sorted([(a, c) for a, c in A.items() if c <= TH], key=lambda x: (x[1], x[0]))
        for q, cq in Ql:
            for u, cu in Ul:
                if cq + cu > TH or (q, u) in cands:
                    continue
                add(q, u, cq + cu + _ed(an, _fmt(q * u), 5.0))
        for q, cq in Ql:
            for a, ca in Al:
                if cq + ca > TH or a % q:
                    continue
                u = a // q
                if u <= 0 or (q, u) in cands:
                    continue
                add(q, u, cq + ca + _ed(un, _fmt(u), 5.0))
        for u, cu in Ul:
            for a, ca in Al:
                if cu + ca > TH or a % u:
                    continue
                q = a // u
                if not (1 <= q <= 500) or (q, u) in cands:
                    continue
                add(q, u, cu + ca + _ed(qn, str(q), 5.0))
    if not cands:
        q = q0[0] if q0 else (min(Q.items(), key=lambda kv: (kv[1], kv[0]))[0] if Q else 1)
        if u0:
            u = u0[0]
        elif U:
            u = min(U.items(), key=lambda kv: (kv[1], kv[0]))[0]
        else:
            a = a0[0] if a0 else (min(A.items(), key=lambda kv: (kv[1], kv[0]))[0] if A else 100)
            u = max(1, a // max(1, q))
        add(q, u, 9.0)
    lst = sorted([[c, k[0], k[1]] for k, c in cands.items()], key=lambda x: (x[0], x[1], x[2]))
    b = lst[0][0]
    return [x for x in lst if x[0] <= b + 3.5][:10]


# ------------------------------------------------------------ reconciliation

def _reconcile(secs, total_s, t0):
    SUBCAP = 3.5
    TOTCAP = 3.5
    KSEC = 12
    sec_opts = []
    for sec in secs:
        beam = 300 if time.perf_counter() - t0 < 0.6 else 40
        states = {0: (0.0, None)}
        for row in sec['rows']:
            nxt = {}
            for s, (c, path) in states.items():
                for ci, cd in enumerate(row['cands']):
                    ns = s + cd[1] * cd[2]
                    nc = c + cd[0]
                    old = nxt.get(ns)
                    if old is None or nc < old[0]:
                        nxt[ns] = (nc, (ci, path))
            if len(nxt) > beam:
                nxt = dict(sorted(nxt.items(), key=lambda kv: (kv[1][0], kv[0]))[:beam])
            states = nxt
        sub = sec.get('subn')
        finals = []
        for s, (c, path) in states.items():
            sc = _ed(sub, _fmt(s), SUBCAP) if sub else 0.0
            finals.append((c + sc, s, path))
        finals.sort(key=lambda x: (x[0], x[1]))
        opts = []
        for tc, s, path in finals[:KSEC]:
            ch = []
            p = path
            while p is not None:
                ch.append(p[0])
                p = p[1]
            ch.reverse()
            opts.append((tc, s, ch))
        if not opts:
            opts = [(0.0, 0, [])]
        sec_opts.append(opts)
    gstates = {0: (0.0, None)}
    for opts in sec_opts:
        nxt = {}
        for g, (c, path) in gstates.items():
            for oi, (oc, s, ch) in enumerate(opts):
                ng = g + s
                nc = c + oc
                old = nxt.get(ng)
                if old is None or nc < old[0]:
                    nxt[ng] = (nc, (oi, path))
        if len(nxt) > 400:
            nxt = dict(sorted(nxt.items(), key=lambda kv: (kv[1][0], kv[0]))[:400])
        gstates = nxt
    best = None
    for g, (c, path) in gstates.items():
        tc = c + (_ed(total_s, _fmt(g), TOTCAP) if total_s else 0.0)
        if best is None or (tc, g) < (best[0], best[1]):
            best = (tc, g, path)
    choice = []
    p = best[2] if best else None
    while p is not None:
        choice.append(p[0])
        p = p[1]
    choice.reverse()
    picks = []
    for si, sec in enumerate(secs):
        oi = choice[si] if si < len(choice) else 0
        ch = sec_opts[si][oi][2]
        picks.append(ch)
    return picks


def solve(state, params):
    t0 = time.perf_counter()
    inp = state.get('input') or {}
    text = inp.get('text', '') if isinstance(inp, dict) else str(inp)
    items = []
    try:
        secs, total_s = _parse(text)
        for sec in secs:
            sec['subn'] = _money_norm(sec['sub']) if sec.get('sub') else None
            rws = []
            for r in sec['rows']:
                fast = (time.perf_counter() - t0) > 0.45
                try:
                    cands = _row_cands(r, fast)
                except Exception:
                    cands = [[9.0, 1, 0]]
                try:
                    code = _fix_code(r.get('CODE', ''))
                except Exception:
                    code = 'AA00000'
                rws.append({'code': code, 'cands': cands})
            sec['rows'] = rws
        tn = _money_norm(total_s) if total_s else None
        try:
            picks = _reconcile(secs, tn, t0)
        except Exception:
            picks = [[] for _ in secs]
        for si, sec in enumerate(secs):
            ch = picks[si] if si < len(picks) else []
            for ri, row in enumerate(sec['rows']):
                ci = ch[ri] if ri < len(ch) else 0
                if ci >= len(row['cands']):
                    ci = 0
                cd = row['cands'][ci]
                items.append({'code': row['code'], 'qty': int(cd[1]), 'unit_cents': int(cd[2])})
    except Exception:
        pass
    state['output'] = {'items': items}
    return state

import re
import time
import math

MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
       '6': '50', '7': '12', '8': '30', '9': '43'}
REVM = {}
for _o in sorted(MIS):
    for _c in MIS[_o]:
        REVM.setdefault(_c, []).append(_o)
L2D = {'O': '0', 'o': '0', 'Q': '0', 'D': '0', 'l': '1', 'I': '1', 'i': '1', '|': '1',
       'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6'}
D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G', 'l': 'I'}
LOOKSET = set('OlISBZG')
DIG = '0123456789'
LAM = 2.3
C_MIS = 1.0
MCOST = {}
for _o in MIS:
    MCOST[_o] = C_MIS + math.log(len(MIS[_o])) / LAM - math.log(2) / LAM
C_SUB = 2.5
C_DUP = 1.0
C_DEL = 2.5
C_INS = 1.2
C_MARK = 0.4
INF = 1e9
GPEN = 3.0
SPLIT_RE = re.compile(r"\s*[|;\t]\s*|\s{2,}")


# ------------------------------------------------------------ edit model

def _ops(s, anysub):
    out = []
    n = len(s)
    for i in range(n):
        ch = s[i]
        if not ch.isdigit():
            continue
        origs = REVM.get(ch, [])
        for o in origs:
            out.append((s[:i] + o + s[i + 1:], MCOST[o]))
        if anysub:
            for o in DIG:
                if o != ch and o not in origs:
                    out.append((s[:i] + o + s[i + 1:], C_SUB))
        if i + 1 < n and s[i + 1] == ch:
            out.append((s[:i] + s[i + 1:], C_DUP))
        elif anysub and not (i > 0 and s[i - 1] == ch):
            out.append((s[:i] + s[i + 1:], C_DEL))
    for i in range(n + 1):
        a = s[:i]
        b = s[i:]
        for d in DIG:
            out.append((a + d + b, C_INS))
    return out


def _ed(o, c, cap):
    m = len(c)
    prev = [0.0] * (m + 1)
    for j in range(1, m + 1):
        prev[j] = prev[j - 1] + (C_MARK if c[j - 1] == '.' else C_INS)
    for i in range(1, len(o) + 1):
        oi = o[i - 1]
        if oi == '.':
            ins = 3.0
        elif i >= 2 and o[i - 2] == oi:
            ins = C_DUP
        else:
            ins = C_DEL
        cur = [prev[0] + ins] + [0.0] * m
        rmin = cur[0]
        for j in range(1, m + 1):
            cj = c[j - 1]
            if oi == cj:
                b = prev[j - 1]
            elif oi == '.' or cj == '.' or not oi.isdigit() or not cj.isdigit():
                b = prev[j - 1] + 3.0
            elif oi in MIS[cj]:
                b = prev[j - 1] + MCOST[cj]
            else:
                b = prev[j - 1] + C_SUB
            d = cur[j - 1] + (C_MARK if cj == '.' else C_INS)
            if d < b:
                b = d
            d = prev[j] + ins
            if d < b:
                b = d
            cur[j] = b
            if b < rmin:
                rmin = b
        if rmin >= cap:
            return cap
        prev = cur
    return min(prev[m], cap)


def _fmt(c):
    return '%d.%02d' % (c // 100, c % 100)


def _gpen(raw, v, grp):
    if not grp or raw is None:
        return 0.0
    has = "'" in raw
    if has == (v >= 100000):
        return 0.0
    return GPEN


def _strip_pcs(t):
    t = t.strip()
    m = re.match(r"^(.*?)\s*pcs$", t)
    if m:
        return m.group(1).strip(), True
    return t, False


def _money_norm(tok):
    t = ''.join(L2D.get(ch, ch) for ch in (tok or ''))
    t = t.replace(',', '.')
    t = re.sub(r"[^0-9.]", '', t)
    if t.count('.') > 1:
        k = t.rfind('.')
        t = t[:k].replace('.', '') + t[k:]
    return t


def _qty_norm(tok):
    b, _ = _strip_pcs(tok or '')
    t = ''.join(L2D.get(ch, ch) for ch in b)
    return re.sub(r"[^0-9]", '', t)


def _money_parse(s):
    if '.' in s:
        if s.count('.') != 1:
            return None
        a, b = s.split('.')
        if len(b) != 2 or not a or not a.isdigit() or not b.isdigit():
            return None
        if len(a) > 1 and a[0] == '0':
            return None
        v = int(a) * 100 + int(b)
        if v <= 0:
            return None
        return v, 0.0
    if len(s) < 3 or not s.isdigit():
        return None
    a = s[:-2]
    if len(a) > 1 and a[0] == '0':
        return None
    v = int(s)
    if v <= 0:
        return None
    return v, C_MARK


def _qty_parse(s):
    if not s or not s.isdigit() or s[0] == '0':
        return None
    v = int(s)
    if 1 <= v <= 500:
        return v, 0.0
    return None


def _cands(s, parse):
    W = {}

    def put(t, c):
        r = parse(t)
        if r is None:
            return
        val, extra = r
        W[val] = W.get(val, 0.0) + math.exp(-LAM * (c + extra))

    put(s, 0.0)
    if s:
        for t, c in _ops(s, False):
            put(t, c)
    else:
        for d in DIG:
            put(d, C_INS)
    out = {}
    for v, w in W.items():
        out[v] = max(0.0, -math.log(w) / LAM)
    return out


# ------------------------------------------------------------ codes

def _code_valid(L, d):
    if len(d) != 5 or not d.isdigit():
        return False
    p = ord(L[0]) - 64 + ord(L[1]) - 64
    return (int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p) % 10 == int(d[4])


def _fix_code(tok):
    t = re.sub(r"\s+", "", tok or '')
    letters = ''
    for ch in t[:2]:
        if 'A' <= ch <= 'Z':
            letters += ch
        elif ch in D2L:
            letters += D2L[ch]
        elif 'a' <= ch <= 'z':
            letters += ch.upper()
        else:
            letters += 'A'
    while len(letters) < 2:
        letters += 'A'
    ds = re.sub(r"[^0-9]", '', ''.join(L2D.get(ch, ch) for ch in t[2:]))
    if _code_valid(letters, ds):
        return letters + ds
    W = {}
    frontier = {ds: 1.0}
    for depth in (1, 2):
        nxt = {}
        for s, w in frontier.items():
            for e, c in _ops(s, True):
                nxt[e] = nxt.get(e, 0.0) + w * math.exp(-LAM * c)
        for e, w in nxt.items():
            if len(e) == 5 and _code_valid(letters, e):
                W[e] = W.get(e, 0.0) + w
        if W:
            break
        items = [(w, e) for e, w in nxt.items() if 3 <= len(e) <= 7]
        items.sort(key=lambda x: (-x[0], x[1]))
        frontier = dict((e, w) for w, e in items[:300])
    if W:
        best = min(W.items(), key=lambda kv: (-round(kv[1], 12), kv[0]))
        return letters + best[0]
    d = (ds + '00000')[:4]
    p = ord(letters[0]) - 64 + ord(letters[1]) - 64
    ck = (int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p) % 10
    return letters + d + str(ck)


# ------------------------------------------------------------ parsing

def _tok_ok(t):
    b, has = _strip_pcs(t)
    if not b:
        return has
    if not re.fullmatch(r"[A-Z0-9l.,']+", b):
        return False
    for ch in b[2:]:
        if 'A' <= ch <= 'Z' and ch not in LOOKSET:
            return False
    return True


def _tc(tok, col, pcs):
    b, has = _strip_pcs(tok)
    if col == 'QTY':
        if not re.fullmatch(r"[0-9OlISBZG]{0,4}", b):
            return 4.0
        c = 0.0
        if pcs and not has:
            c += 2.0
        if not b:
            c += 1.5
        return c
    if has:
        return 6.0
    if col == 'CODE':
        if re.fullmatch(r"[A-Z0-9l]{2}[0-9OlISBZG]{3,7}", b):
            h = b[:2]
            if all('A' <= ch <= 'Z' for ch in h):
                return 0.0
            if all(('A' <= ch <= 'Z') or ch in D2L for ch in h):
                return 0.8
        return 4.0
    if re.fullmatch(r"[0-9OlISBZG']+[.,][0-9OlISBZG]{1,3}", b):
        return 0.0
    if re.fullmatch(r"[0-9OlISBZG']{3,}", b):
        return 0.6
    if re.fullmatch(r"[0-9OlISBZG']{1,2}", b):
        return 2.0
    return 4.0


def _segment(tokens, cols, pcs):
    m = len(tokens)
    if m == 0:
        return []
    BIG = 1e18
    SKIP = 4.0
    tc = [[_tc(t, c, pcs) for c in cols] for t in tokens]
    emp = [2.0 if c == 'QTY' else 4.5 for c in cols]
    dp = [[BIG] * 4 for _ in range(m + 1)]
    bp = [[None] * 4 for _ in range(m + 1)]
    dp[0][0] = 0.0
    for i in range(m + 1):
        for _ in range(2):
            for k in range(4):
                c = dp[i][k]
                if c >= BIG:
                    continue
                nk = (k + 1) % 4
                v = c + emp[k]
                if v < dp[i][nk] - 1e-12:
                    dp[i][nk] = v
                    bp[i][nk] = (i, k, 'e')
        if i == m:
            break
        for k in range(4):
            c = dp[i][k]
            if c >= BIG:
                continue
            v = c + SKIP
            if v < dp[i + 1][k] - 1e-12:
                dp[i + 1][k] = v
                bp[i + 1][k] = (i, k, 's')
            nk = (k + 1) % 4
            v = c + tc[i][k]
            if v < dp[i + 1][nk] - 1e-12:
                dp[i + 1][nk] = v
                bp[i + 1][nk] = (i, k, 'u')
    ops = []
    i, k = m, 0
    guard = 0
    while bp[i][k] is not None and guard < 100000:
        pi, pk, kind = bp[i][k]
        ops.append((pi, pk, kind))
        i, k = pi, pk
        guard += 1
    ops.reverse()
    rows = []
    cur = {}
    for pi, pk, kind in ops:
        if kind == 's':
            continue
        cur[cols[pk]] = tokens[pi] if kind == 'u' else ''
        if pk == 3:
            rows.append(cur)
            cur = {}
    return rows


def _parse(text):
    lines = (text or '').replace('\r', '').split('\n')
    cols = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    for ln in lines:
        if ln.strip().startswith('COLUMNS'):
            found = re.findall(r"CODE|QTY|UNIT|AMOUNT", ln)
            if sorted(found) == sorted(cols):
                cols = found
            break
    secs = []
    cur = None
    total_s = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if re.match(r"^=+\s*SECTION\b", s):
            cur = {'tokens': [], 'sub': None}
            secs.append(cur)
            continue
        if s.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'tokens': [], 'sub': None}
                secs.append(cur)
            cur['sub'] = re.sub(r"\s+", "", s[len('SUBTOTAL'):])
            continue
        if s.startswith('TOTAL'):
            mm = re.match(r"^TOTAL\s*(.*?)(?:\s+ITEMS\b.*)?$", s)
            if mm:
                total_s = re.sub(r"\s+", "", mm.group(1))
            continue
        toks = [t.strip() for t in SPLIT_RE.split(s)]
        toks = [t for t in toks if t]
        if not toks:
            continue
        if not all(_tok_ok(t) for t in toks):
            continue
        if cur is None:
            cur = {'tokens': [], 'sub': None}
            secs.append(cur)
        cur['tokens'].extend(toks)
    pcs = False
    grp = False
    for sec in secs:
        for t in sec['tokens']:
            if t.endswith('pcs'):
                pcs = True
            if re.search(r"[0-9OlSBZG]'[0-9OlSBZG]", t):
                grp = True
        if sec['sub'] and "'" in sec['sub']:
            grp = True
    if total_s and "'" in total_s:
        grp = True
    out = []
    for sec in secs:
        out.append({'rows': _segment(sec['tokens'], cols, pcs), 'sub': sec['sub']})
    return out, total_s, grp


# ------------------------------------------------------------ rows

def _row_cands(r, fast, grp):
    ru = r.get('UNIT', '')
    ra = r.get('AMOUNT', '')
    qn = _qty_norm(r.get('QTY', ''))
    un = _money_norm(ru)
    an = _money_norm(ra)
    q0 = _qty_parse(qn)
    u0 = _money_parse(un)
    a0 = _money_parse(an)
    if (q0 is not None and u0 is not None and a0 is not None and q0[0] * u0[0] == a0[0]
            and _gpen(ru, u0[0], grp) == 0 and _gpen(ra, a0[0], grp) == 0):
        return [[u0[1] + a0[1], q0[0], u0[0]]]
    Q = _cands(qn, _qty_parse)
    U = _cands(un, _money_parse)
    A = _cands(an, _money_parse)
    if grp:
        U = dict((u, c + _gpen(ru, u, grp)) for u, c in U.items())
        A = dict((a, c + _gpen(ra, a, grp)) for a, c in A.items())
    cands = {}

    def add(q, u, c):
        k = (q, u)
        if c < cands.get(k, INF):
            cands[k] = c

    for q, cq in Q.items():
        for u, cu in U.items():
            ca = A.get(q * u)
            if ca is not None:
                add(q, u, cq + cu + ca)
    best = min(cands.values()) if cands else INF
    if best > 1.5 and not fast:
        TH = 1.3
        Ql = sorted([(q, c) for q, c in Q.items() if c <= TH], key=lambda x: (x[1], x[0]))
        Ul = sorted([(u, c) for u, c in U.items() if c <= TH], key=lambda x: (x[1], x[0]))
        Al = sorted([(a, c) for a, c in A.items() if c <= TH], key=lambda x: (x[1], x[0]))
        for q, cq in Ql:
            for u, cu in Ul:
                if cq + cu > TH or (q, u) in cands:
                    continue
                add(q, u, cq + cu + _ed(an, _fmt(q * u), 5.0) + _gpen(ra, q * u, grp))
        for q, cq in Ql:
            for a, ca in Al:
                if cq + ca > TH or a % q:
                    continue
                u = a // q
                if u <= 0 or (q, u) in cands:
                    continue
                add(q, u, cq + ca + _ed(un, _fmt(u), 5.0) + _gpen(ru, u, grp))
        for u, cu in Ul:
            for a, ca in Al:
                if cu + ca > TH or a % u:
                    continue
                q = a // u
                if not (1 <= q <= 500) or (q, u) in cands:
                    continue
                add(q, u, cu + ca + _ed(qn, str(q), 5.0))
    if not cands:
        q = q0[0] if q0 else (min(Q.items(), key=lambda kv: (kv[1], kv[0]))[0] if Q else 1)
        if u0:
            u = u0[0]
        elif U:
            u = min(U.items(), key=lambda kv: (kv[1], kv[0]))[0]
        else:
            a = a0[0] if a0 else (min(A.items(), key=lambda kv: (kv[1], kv[0]))[0] if A else 100)
            u = max(1, a // max(1, q))
        add(q, u, 9.0)
    lst = sorted([[c, k[0], k[1]] for k, c in cands.items()], key=lambda x: (x[0], x[1], x[2]))
    b = lst[0][0]
    return [x for x in lst if x[0] <= b + 3.5][:10]


# ------------------------------------------------------------ reconciliation

def _reconcile(secs, total_s, total_raw, grp, t0):
    SUBCAP = 3.5
    TOTCAP = 3.5
    KSEC = 12
    sec_opts = []
    for sec in secs:
        beam = 300 if time.perf_counter() - t0 < 0.6 else 40
        states = {0: (0.0, None)}
        for row in sec['rows']:
            nxt = {}
            for s, (c, path) in states.items():
                for ci, cd in enumerate(row['cands']):
                    ns = s + cd[1] * cd[2]
                    nc = c + cd[0]
                    old = nxt.get(ns)
                    if old is None or nc < old[0]:
                        nxt[ns] = (nc, (ci, path))
            if len(nxt) > beam:
                nxt = dict(sorted(nxt.items(), key=lambda kv: (kv[1][0], kv[0]))[:beam])
            states = nxt
        sub = sec.get('subn')
        finals = []
        for s, (c, path) in states.items():
            if sub:
                sc = min(SUBCAP, _ed(sub, _fmt(s), SUBCAP) + _gpen(sec.get('sub'), s, grp))
            else:
                sc = 0.0
            finals.append((c + sc, s, path))
        finals.sort(key=lambda x: (x[0], x[1]))
        opts = []
        for tc, s, path in finals[:KSEC]:
            ch = []
            p = path
            while p is not None:
                ch.append(p[0])
                p = p[1]
            ch.reverse()
            opts.append((tc, s, ch))
        if not opts:
            opts = [(0.0, 0, [])]
        sec_opts.append(opts)
    gstates = {0: (0.0, None)}
    for opts in sec_opts:
        nxt = {}
        for g, (c, path) in gstates.items():
            for oi, (oc, s, ch) in enumerate(opts):
                ng = g + s
                nc = c + oc
                old = nxt.get(ng)
                if old is None or nc < old[0]:
                    nxt[ng] = (nc, (oi, path))
        if len(nxt) > 400:
            nxt = dict(sorted(nxt.items(), key=lambda kv: (kv[1][0], kv[0]))[:400])
        gstates = nxt
    best = None
    for g, (c, path) in gstates.items():
        if total_s:
            tcst = min(TOTCAP, _ed(total_s, _fmt(g), TOTCAP) + _gpen(total_raw, g, grp))
        else:
            tcst = 0.0
        tc = c + tcst
        if best is None or (tc, g) < (best[0], best[1]):
            best = (tc, g, path)
    choice = []
    p = best[2] if best else None
    while p is not None:
        choice.append(p[0])
        p = p[1]
    choice.reverse()
    picks = []
    for si, sec in enumerate(secs):
        oi = choice[si] if si < len(choice) else 0
        ch = sec_opts[si][oi][2]
        picks.append(ch)
    return picks


def solve(state, params):
    t0 = time.perf_counter()
    inp = state.get('input') or {}
    text = inp.get('text', '') if isinstance(inp, dict) else str(inp)
    items = []
    try:
        secs, total_s, grp = _parse(text)
        for sec in secs:
            sec['subn'] = _money_norm(sec['sub']) if sec.get('sub') else None
            rws = []
            for r in sec['rows']:
                fast = (time.perf_counter() - t0) > 0.45
                try:
                    cands = _row_cands(r, fast, grp)
                except Exception:
                    cands = [[9.0, 1, 0]]
                try:
                    code = _fix_code(r.get('CODE', ''))
                except Exception:
                    code = 'AA00000'
                rws.append({'code': code, 'cands': cands})
            sec['rows'] = rws
        tn = _money_norm(total_s) if total_s else None
        try:
            picks = _reconcile(secs, tn, total_s, grp, t0)
        except Exception:
            picks = [[] for _ in secs]
        for si, sec in enumerate(secs):
            ch = picks[si] if si < len(picks) else []
            for ri, row in enumerate(sec['rows']):
                ci = ch[ri] if ri < len(ch) else 0
                if ci >= len(row['cands']):
                    ci = 0
                cd = row['cands'][ci]
                items.append({'code': row['code'], 'qty': int(cd[1]), 'unit_cents': int(cd[2])})
    except Exception:
        pass
    state['output'] = {'items': items}
    return state

import re
import time

COLNAMES = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
       '6': '50', '7': '12', '8': '30', '9': '43'}
REV = {}
for _t, _ss in MIS.items():
    for _s in _ss:
        REV[_s] = REV.get(_s, '') + _t
L2D = {'O': '0', 'o': '0', 'Q': '0', 'D': '0', 'l': '1', 'I': '1', 'i': '1', '|': '1',
       'L': '1', 'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6', 'b': '6'}
D2LOOK = {}
for _l, _d in L2D.items():
    D2LOOK[_d] = D2LOOK.get(_d, '') + _l
CODE_D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
LETTER_LOOK = {'O': '0', 'I': '1', 'S': '5', 'B': '8', 'Z': '2', 'G': '6'}
LOOKCH = "0-9OoQDlIi|LSsBZzGb"


# ---------------------------------------------------------------- layout
def split_line(line, sep):
    s = line.strip(' \r\n')
    if sep == 'pipe':
        toks = re.split(r'\s*\|\s*', s.strip())
    elif sep == 'semi':
        toks = re.split(r'\s*;\s*', s.strip())
    elif sep == 'tab':
        toks = [x.strip() for x in s.split('\t')]
    else:
        toks = re.split(r' {3}|\t', s.strip())
    toks = [t.strip() for t in toks]
    while toks and toks[-1] == '':
        toks.pop()
    return toks


def tok_score(tok, typ, pcs):
    if tok is None:
        return 8
    if typ == 'CODE':
        if tok == '':
            return 8
        if re.fullmatch(r'[A-Z]{2}[' + LOOKCH + r']{4,6}', tok):
            return 0
        if re.fullmatch(r'[A-Z0-9]{2}[' + LOOKCH + r']{4,6}', tok):
            return 1
        if re.fullmatch(r'[A-Za-z0-9|]{5,9}', tok):
            return 3
        return 6
    if typ == 'QTY':
        if tok == '':
            return 2
        has = re.search(r'pcs\s*$', tok) is not None
        core = re.sub(r'\s*pcs\s*$', '', tok)
        pen = 0 if has == pcs else 2
        if re.fullmatch(r'[' + LOOKCH + r']{1,4}', core):
            return pen
        return 6
    if tok == '':
        return 8
    if re.search(r'pcs', tok):
        return 6
    if re.fullmatch(r"[" + LOOKCH + r"']+[.,][" + LOOKCH + r"]{1,3}", tok):
        return 0
    if re.fullmatch(r"[" + LOOKCH + r"']{3,10}", tok):
        return 1
    return 6


def align_tokens(toks, cols, pcs):
    n = len(toks)
    INF = 10 ** 9
    SKIP = 6
    EMPTY = 8
    dp = [[INF] * 4 for _ in range(n + 1)]
    bk = [[None] * 4 for _ in range(n + 1)]
    dp[0][0] = 0
    for i in range(n + 1):
        for _ in range(2):
            for j in range(4):
                if dp[i][j] < INF:
                    nj = (j + 1) % 4
                    v = dp[i][j] + EMPTY
                    if v < dp[i][nj]:
                        dp[i][nj] = v
                        bk[i][nj] = ('E', i, j)
        if i == n:
            break
        t = toks[i]
        for j in range(4):
            if dp[i][j] >= INF:
                continue
            v = dp[i][j] + tok_score(t, cols[j], pcs)
            nj = (j + 1) % 4
            if v < dp[i + 1][nj]:
                dp[i + 1][nj] = v
                bk[i + 1][nj] = ('A', i, j)
            v = dp[i][j] + SKIP
            if v < dp[i + 1][j]:
                dp[i + 1][j] = v
                bk[i + 1][j] = ('S', i, j)
    seq = []
    i, j = n, 0
    guard = 0
    while not (i == 0 and j == 0) and guard < 10 * (n + 5):
        guard += 1
        b = bk[i][j]
        if b is None:
            break
        kind, pi, pj = b
        if kind == 'A':
            seq.append((pj, toks[pi]))
        elif kind == 'E':
            seq.append((pj, ''))
        i, j = pi, pj
    seq.reverse()
    rows = []
    cur = {}
    for j, t in seq:
        cur[cols[j]] = t
        if j == 3:
            rows.append(cur)
            cur = {}
    return rows


def parse_layout(state, params):
    text = state.get("input", {}).get("text", "") or ""
    lines = text.replace('\r', '').split('\n')
    cols = list(COLNAMES)
    sep = None
    for ln in lines:
        s = ln.strip()
        if s.startswith('COLUMNS'):
            rest = s[len('COLUMNS'):]
            rest = rest[1:] if rest.startswith(':') else rest
            names = re.findall(r'CODE|QTY|UNIT|AMOUNT', rest)
            if sorted(names) == sorted(COLNAMES):
                cols = names
            m = re.search(r'(?:CODE|QTY|UNIT|AMOUNT)(.*?)(?:CODE|QTY|UNIT|AMOUNT)', rest)
            if m:
                b = m.group(1)
                if '|' in b:
                    sep = 'pipe'
                elif '\t' in b:
                    sep = 'tab'
                elif ';' in b:
                    sep = 'semi'
                else:
                    sep = 'space'
            break
    if sep is None:
        cnt = {'pipe': 0, 'tab': 0, 'semi': 0, 'space': 0}
        for ln in lines:
            cnt['pipe'] += ln.count('|')
            cnt['tab'] += ln.count('\t')
            cnt['semi'] += ln.count(';')
            cnt['space'] += ln.count('   ')
        sep = max(['pipe', 'tab', 'semi', 'space'], key=lambda k: cnt[k])
    groups = [[]]
    alltoks = []
    totvals = []
    tokre = re.compile(r"[A-Za-z0-9.,'|]*(\s*pcs)?")
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if 'SECTION' in s and s.startswith('=='):
            if groups[-1]:
                groups.append([])
            continue
        if s.startswith('SUBTOTAL') or s.startswith('TOTAL'):
            totvals.extend(s.split()[1:2])
            continue
        toks = split_line(ln, sep)
        if not toks:
            continue
        if any(not tokre.fullmatch(t) for t in toks):
            continue
        if all(t == '' for t in toks):
            continue
        groups[-1].append(toks)
        alltoks.extend(toks)
    dot = comma = 0
    for t in alltoks + totvals:
        if re.search(r"\.[" + LOOKCH + r"]{2}$", t):
            dot += 1
        elif re.search(r",[" + LOOKCH + r"]{2}$", t):
            comma += 1
    style = {
        'dm': ',' if comma > dot else '.',
        'grp': any("'" in t for t in alltoks + totvals),
        'pcs': sum(1 for t in alltoks if 'pcs' in t) > 0,
    }
    rows = []
    for g in groups:
        toks = []
        for tl in g:
            toks.extend(tl)
        if toks:
            rows.extend(align_tokens(toks, cols, style['pcs']))
    state['rows'] = rows
    state['style'] = style
    state['cols'] = cols
    return state


# ---------------------------------------------------------------- edit model
def sub_cost(c, s):
    if c == s:
        return 0
    if '0' <= c <= '9':
        if s in D2LOOK.get(c, ''):
            return 1
        if s in MIS[c]:
            return 1
        if '0' <= s <= '9':
            return 3
        return 4
    if c in LETTER_LOOK:
        if s == LETTER_LOOK[c]:
            return 1
        return 4
    if c in '.,' and s in '.,':
        return 2
    return 4


def del_cost(c):
    if '0' <= c <= '9' or c in '.,':
        return 1
    return 3


def ecost(t, r):
    n = len(t)
    m = len(r)
    prev = [4 * j for j in range(m + 1)]
    for i in range(1, n + 1):
        c = t[i - 1]
        isd = '0' <= c <= '9'
        dc = del_cost(c)
        cur = [prev[0] + dc] + [0] * m
        for j in range(1, m + 1):
            v = prev[j - 1] + sub_cost(c, r[j - 1])
            w = prev[j] + dc
            if w < v:
                v = w
            w = cur[j - 1] + 4
            if w < v:
                v = w
            if isd and j >= 2:
                w = prev[j - 2] + 1 + sub_cost(c, r[j - 2]) + sub_cost(c, r[j - 1])
                if w < v:
                    v = w
            cur[j] = v
        prev = cur
    return prev[m]


def edits1(s):
    out = {}
    n = len(s)
    for i in range(n):
        ch = s[i]
        if '0' <= ch <= '9':
            for t in REV.get(ch, ''):
                out[s[:i] + t + s[i + 1:]] = 1
            if i + 1 < n and s[i + 1] == ch:
                out[s[:i] + s[i + 1:]] = 1
    for i in range(n + 1):
        for d in '0123456789':
            out[s[:i] + d + s[i:]] = 1
    out.pop(s, None)
    return list(out)


def levels(base, maxlev):
    seen = {base: 0}
    frontier = [base]
    for lev in range(1, maxlev + 1):
        nf = []
        for x in frontier:
            for y in edits1(x):
                if y not in seen:
                    seen[y] = lev
                    nf.append(y)
        frontier = nf
    return seen


def decode_num(raw, allow_mark):
    cost = 0
    out = []
    marks = 0
    for ch in raw:
        if '0' <= ch <= '9':
            out.append(ch)
        elif ch in L2D:
            out.append(L2D[ch])
            cost += 1
        elif ch in '.,' and allow_mark:
            out.append('.')
            marks += 1
        elif ch in "' \t":
            continue
        else:
            cost += 2
    s = ''.join(out)
    if marks > 1:
        k = s.rfind('.')
        s = s[:k].replace('.', '') + s[k:]
        cost += 2 * (marks - 1)
    return s, cost


def parse_money_str(s):
    if '.' in s:
        ip, fp = s.split('.', 1)
        if len(fp) != 2 or not ip or '.' in fp:
            return None
        if len(ip) > 1 and ip[0] == '0':
            return None
        v = int(ip + fp)
        return (v, 0) if v > 0 else None
    if len(s) < 3:
        return None
    ip = s[:-2]
    if len(ip) > 1 and ip[0] == '0':
        return None
    v = int(s)
    return (v, 1) if v > 0 else None


def money_cands(raw, maxlev):
    base, bc = decode_num(raw or '', True)
    res = {}
    for s, lev in levels(base, maxlev).items():
        p = parse_money_str(s)
        if p is None:
            continue
        v, pen = p
        c = bc + lev + pen
        if v not in res or c < res[v]:
            res[v] = c
    return res


def strip_pcs(raw):
    return re.sub(r'\s*pcs\s*$', '', raw or '')


def qty_cands(raw, maxlev):
    base, bc = decode_num(strip_pcs(raw), False)
    res = {}
    for s, lev in levels(base, maxlev).items():
        if not s or (len(s) > 1 and s[0] == '0') or len(s) > 3:
            continue
        v = int(s)
        if 1 <= v <= 500:
            c = bc + lev
            if v not in res or c < res[v]:
                res[v] = c
    return res


def fmt_money(c, st):
    ip = str(c // 100)
    fp = '%02d' % (c % 100)
    if st.get('grp') and len(ip) > 3:
        parts = []
        while len(ip) > 3:
            parts.insert(0, ip[-3:])
            ip = ip[:-3]
        parts.insert(0, ip)
        ip = "'".join(parts)
    return ip + st.get('dm', '.') + fp


def check_ok(code):
    d = [ord(ch) - 48 for ch in code[2:]]
    p1 = ord(code[0]) - 64
    p2 = ord(code[1]) - 64
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p1 + p2) % 10 == d[4]


def repair_code(raw):
    r = re.sub(r'\s', '', raw or '')
    if len(r) < 2:
        r = (r + 'AA')[:2] + r[2:]
    lc = 0
    letters = ''
    for ch in r[:2]:
        if 'A' <= ch <= 'Z':
            letters += ch
        elif ch in CODE_D2L:
            letters += CODE_D2L[ch]
            lc += 1
        elif 'a' <= ch <= 'z':
            letters += ch.upper()
            lc += 2
        else:
            letters += 'A'
            lc += 5
    digits, dc = decode_num(r[2:], False)
    best = None
    seen = {digits: 0}
    frontier = [digits]
    for lev in range(0, 3):
        if lev > 0:
            nf = []
            for x in frontier:
                for y in edits1(x):
                    if y not in seen:
                        seen[y] = lev
                        nf.append(y)
            frontier = nf
        found = []
        for x in frontier:
            if len(x) == 5 and check_ok(letters + x):
                found.append(letters + x)
        if found:
            if len(found) > 1:
                found.sort(key=lambda c: (ecost(c, r), c))
            best = found[0]
            break
    if best is None:
        x = (digits + '00000')[:4]
        for k in range(10):
            if check_ok(letters + x + str(k)):
                best = letters + x + str(k)
                break
    return best


def solve_row(row, st, deadline):
    rq = row.get('QTY', '') or ''
    ru = row.get('UNIT', '') or ''
    ra = row.get('AMOUNT', '') or ''
    rqs = strip_pcs(rq)
    code = repair_code(row.get('CODE', ''))
    fast = time.process_time() > deadline
    Q0 = qty_cands(rq, 0)
    U0 = money_cands(ru, 0)
    A0 = money_cands(ra, 0)
    for q, cq in Q0.items():
        for u, cu in U0.items():
            if cq + cu == 0 and A0.get(q * u) == 0:
                return code, q, u
    if fast:
        return code, (min(Q0) if Q0 else 1), (min(U0) if U0 else (min(A0) if A0 else 0))
    Q1 = qty_cands(rq, 1)
    U1 = money_cands(ru, 1)
    A1 = money_cands(ra, 1)
    cands = []
    for q, cq in Q1.items():
        for u, cu in U1.items():
            ca = A1.get(q * u)
            if ca is not None:
                cands.append((cq + cu + ca, q, u))
    best = min(c[0] for c in cands) if cands else 99
    if best > 2:
        Q2 = qty_cands(rq, 2)
        for q, cq in Q2.items():
            if q in Q1:
                continue
            for u, cu in U1.items():
                ca = A1.get(q * u)
                if ca is not None:
                    cands.append((cq + cu + ca, q, u))
        dpc = {}

        def mcost(v, raw):
            k = str(v) + '|' + raw
            if k not in dpc:
                dpc[k] = ecost(fmt_money(v, st), raw)
            return dpc[k]
        for q, cq in Q1.items():
            if cq > 1:
                continue
            for a, ca in A1.items():
                if a % q == 0:
                    u = a // q
                    cu = U1.get(u)
                    if cu is None:
                        cu = mcost(u, ru)
                    cands.append((cq + cu + ca, q, u))
        for u, cu in U1.items():
            for a, ca in A1.items():
                if a % u == 0:
                    q = a // u
                    if 1 <= q <= 500:
                        cq = Q1.get(q)
                        if cq is None:
                            cq = ecost(str(q), rqs)
                        cands.append((cq + cu + ca, q, u))
        for q, cq in Q1.items():
            for u, cu in U1.items():
                if cq + cu <= 1 and (q * u) not in A1:
                    cands.append((cq + cu + mcost(q * u, ra), q, u))
    if not cands:
        q = min(Q1, key=lambda v: (Q1[v], v)) if Q1 else 1
        if U1:
            u = min(U1, key=lambda v: (U1[v], v))
        elif A1:
            a = min(A1, key=lambda v: (A1[v], v))
            u = max(1, int(round(a / float(q))))
        else:
            u = 0
        return code, q, u
    best = min(c[0] for c in cands)
    tops = sorted(set((q, u) for c, q, u in cands if c == best))
    if len(tops) > 1:
        def full(qu):
            q, u = qu
            return (ecost(str(q), rqs) + ecost(fmt_money(u, st), ru)
                    + ecost(fmt_money(q * u, st), ra), q, u)
        tops.sort(key=full)
    q, u = tops[0]
    return code, q, u


def repair_rows(state, params):
    t0 = time.process_time()
    deadline = t0 + 0.75
    st = state.get('style') or {'dm': '.', 'grp': False, 'pcs': False}
    items = []
    for row in state.get('rows') or []:
        try:
            code, q, u = solve_row(row, st, deadline)
        except Exception:
            code, q, u = 'AA00000', 1, 0
        items.append({'code': code or 'AA00000', 'qty': int(q), 'unit_cents': int(u)})
    state['output'] = {'items': items}
    return state

import re
import time
import math

MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
       '6': '50', '7': '12', '8': '30', '9': '43'}
REVM = {}
for _o in sorted(MIS):
    for _c in MIS[_o]:
        REVM.setdefault(_c, []).append(_o)
L2D = {'O': '0', 'o': '0', 'Q': '0', 'D': '0', 'l': '1', 'I': '1', 'i': '1', '|': '1',
       'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6'}
D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G', 'l': 'I'}
LOOKSET = set('OlISBZG')
DIG = '0123456789'
LAM = 2.3
C_MIS = 1.0
MCOST = {}
for _o in MIS:
    MCOST[_o] = C_MIS + math.log(len(MIS[_o])) / LAM - math.log(2) / LAM
C_SUB = 2.5
C_DUP = 1.0
C_DEL = 2.5
C_INS = 1.2
C_MARK = 0.4
C_XC = 3.0
INF = 1e9
GPEN = 3.0
SPLIT_RE = re.compile(r"\s*[|;\t]\s*|\s{2,}")


# ------------------------------------------------------------ edit model

def _ops(s, anysub):
    out = []
    n = len(s)
    for i in range(n):
        ch = s[i]
        if not ch.isdigit():
            continue
        origs = REVM.get(ch, [])
        for o in origs:
            out.append((s[:i] + o + s[i + 1:], MCOST[o]))
        if anysub:
            for o in DIG:
                if o != ch and o not in origs:
                    out.append((s[:i] + o + s[i + 1:], C_SUB))
        if i + 1 < n and s[i + 1] == ch:
            out.append((s[:i] + s[i + 1:], C_DUP))
        elif anysub and not (i > 0 and s[i - 1] == ch):
            out.append((s[:i] + s[i + 1:], C_DEL))
    for i in range(n + 1):
        a = s[:i]
        b = s[i:]
        for d in DIG:
            out.append((a + d + b, C_INS))
    return out


def _code_extra(s):
    out = []
    n = len(s)
    for i in range(n):
        ch = s[i]
        origs = REVM.get(ch, [])
        for o in DIG:
            if o != ch and o not in origs:
                out.append((s[:i] + o + s[i + 1:], C_XC))
        if not ((i + 1 < n and s[i + 1] == ch) or (i > 0 and s[i - 1] == ch)):
            out.append((s[:i] + s[i + 1:], C_XC))
    return out


def _ed(o, c, cap):
    m = len(c)
    prev = [0.0] * (m + 1)
    for j in range(1, m + 1):
        prev[j] = prev[j - 1] + (C_MARK if c[j - 1] == '.' else C_INS)
    for i in range(1, len(o) + 1):
        oi = o[i - 1]
        if oi == '.':
            ins = 3.0
        elif i >= 2 and o[i - 2] == oi:
            ins = C_DUP
        else:
            ins = C_DEL
        cur = [prev[0] + ins] + [0.0] * m
        rmin = cur[0]
        for j in range(1, m + 1):
            cj = c[j - 1]
            if oi == cj:
                b = prev[j - 1]
            elif oi == '.' or cj == '.' or not oi.isdigit() or not cj.isdigit():
                b = prev[j - 1] + 3.0
            elif oi in MIS[cj]:
                b = prev[j - 1] + MCOST[cj]
            else:
                b = prev[j - 1] + C_SUB
            d = cur[j - 1] + (C_MARK if cj == '.' else C_INS)
            if d < b:
                b = d
            d = prev[j] + ins
            if d < b:
                b = d
            cur[j] = b
            if b < rmin:
                rmin = b
        if rmin >= cap:
            return cap
        prev = cur
    return min(prev[m], cap)


def _fmt(c):
    return '%d.%02d' % (c // 100, c % 100)


def _gpen(raw, v, grp):
    if not grp or raw is None:
        return 0.0
    has = "'" in raw
    if has == (v >= 100000):
        return 0.0
    return GPEN


def _strip_pcs(t):
    t = t.strip()
    m = re.match(r"^(.*?)\s*pcs$", t)
    if m:
        return m.group(1).strip(), True
    return t, False


def _money_norm(tok):
    t = ''.join(L2D.get(ch, ch) for ch in (tok or ''))
    t = t.replace(',', '.')
    t = re.sub(r"[^0-9.]", '', t)
    if t.count('.') > 1:
        k = t.rfind('.')
        t = t[:k].replace('.', '') + t[k:]
    return t


def _qty_norm(tok):
    b, _ = _strip_pcs(tok or '')
    t = ''.join(L2D.get(ch, ch) for ch in b)
    return re.sub(r"[^0-9]", '', t)


def _money_parse(s):
    if '.' in s:
        if s.count('.') != 1:
            return None
        a, b = s.split('.')
        if len(b) != 2 or not a or not a.isdigit() or not b.isdigit():
            return None
        if len(a) > 1 and a[0] == '0':
            return None
        v = int(a) * 100 + int(b)
        if v <= 0:
            return None
        return v, 0.0
    if len(s) < 3 or not s.isdigit():
        return None
    a = s[:-2]
    if len(a) > 1 and a[0] == '0':
        return None
    v = int(s)
    if v <= 0:
        return None
    return v, C_MARK


def _qty_parse(s):
    if not s or not s.isdigit() or s[0] == '0':
        return None
    v = int(s)
    if 1 <= v <= 500:
        return v, 0.0
    return None


def _cands(s, parse):
    W = {}

    def put(t, c):
        r = parse(t)
        if r is None:
            return
        val, extra = r
        W[val] = W.get(val, 0.0) + math.exp(-LAM * (c + extra))

    put(s, 0.0)
    if s:
        for t, c in _ops(s, False):
            put(t, c)
    else:
        for d in DIG:
            put(d, C_INS)
    out = {}
    for v, w in W.items():
        out[v] = max(0.0, -math.log(w) / LAM)
    return out


# ------------------------------------------------------------ codes

def _code_valid(L, d):
    if len(d) != 5 or not d.isdigit():
        return False
    p = ord(L[0]) - 64 + ord(L[1]) - 64
    return (int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p) % 10 == int(d[4])


def _fix_code(tok, deep):
    t = re.sub(r"\s+", "", tok or '')
    letters = ''
    for ch in t[:2]:
        if 'A' <= ch <= 'Z':
            letters += ch
        elif ch in D2L:
            letters += D2L[ch]
        elif 'a' <= ch <= 'z':
            letters += ch.upper()
        else:
            letters += 'A'
    while len(letters) < 2:
        letters += 'A'
    ds = re.sub(r"[^0-9]", '', ''.join(L2D.get(ch, ch) for ch in t[2:]))
    if _code_valid(letters, ds):
        return letters + ds

    def ok(e):
        return len(e) == 5 and _code_valid(letters, e)

    W = {}
    l1 = {}
    for e, c in _ops(ds, False):
        l1[e] = l1.get(e, 0.0) + math.exp(-LAM * c)
    for e, w in l1.items():
        if ok(e):
            W[e] = W.get(e, 0.0) + w
    for e, c in _code_extra(ds):
        if ok(e):
            W[e] = W.get(e, 0.0) + math.exp(-LAM * c)
    strong = math.exp(-LAM * 1.5)
    if deep and (not W or max(W.values()) < strong):
        l2 = {}
        for e, w in l1.items():
            if not (3 <= len(e) <= 7):
                continue
            for e2, c in _ops(e, False):
                w2 = w * math.exp(-LAM * c)
                l2[e2] = l2.get(e2, 0.0) + w2
            for e2, c in _code_extra(e):
                w2 = w * math.exp(-LAM * c)
                if ok(e2):
                    W[e2] = W.get(e2, 0.0) + w2
        for e2, w2 in l2.items():
            if ok(e2):
                W[e2] = W.get(e2, 0.0) + w2
        if not W:
            items = [(w, e) for e, w in l2.items() if 4 <= len(e) <= 6]
            items.sort(key=lambda x: (-x[0], x[1]))
            for w, e in items[:300]:
                for e3, c in _ops(e, True):
                    if ok(e3):
                        W[e3] = W.get(e3, 0.0) + w * math.exp(-LAM * c)
    if W:
        best = min(W.items(), key=lambda kv: (-round(kv[1], 14), kv[0]))
        return letters + best[0]
    d = (ds + '00000')[:4]
    p = ord(letters[0]) - 64 + ord(letters[1]) - 64
    ck = (int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p) % 10
    return letters + d + str(ck)


# ------------------------------------------------------------ parsing

def _tok_ok(t):
    b, has = _strip_pcs(t)
    if not b:
        return has
    if not re.fullmatch(r"[A-Z0-9l.,']+", b):
        return False
    for ch in b[2:]:
        if 'A' <= ch <= 'Z' and ch not in LOOKSET:
            return False
    return True


def _tc(tok, col, pcs):
    b, has = _strip_pcs(tok)
    if col == 'QTY':
        if not re.fullmatch(r"[0-9OlISBZG]{0,4}", b):
            return 4.0
        c = 0.0
        if pcs and not has:
            c += 2.0
        if not b:
            c += 1.5
        return c
    if has:
        return 6.0
    if col == 'CODE':
        if re.fullmatch(r"[A-Z0-9l]{2}[0-9OlISBZG]{3,7}", b):
            h = b[:2]
            if all('A' <= ch <= 'Z' for ch in h):
                return 0.0
            if all(('A' <= ch <= 'Z') or ch in D2L for ch in h):
                return 0.8
        return 4.0
    if re.fullmatch(r"[0-9OlISBZG']+[.,][0-9OlISBZG]{1,3}", b):
        return 0.0
    if re.fullmatch(r"[0-9OlISBZG']{3,}", b):
        return 0.6
    if re.fullmatch(r"[0-9OlISBZG']{1,2}", b):
        return 2.0
    return 4.0


def _segment(tokens, cols, pcs):
    m = len(tokens)
    if m == 0:
        return []
    BIG = 1e18
    SKIP = 4.0
    tc = [[_tc(t, c, pcs) for c in cols] for t in tokens]
    emp = [2.0 if c == 'QTY' else 4.5 for c in cols]
    dp = [[BIG] * 4 for _ in range(m + 1)]
    bp = [[None] * 4 for _ in range(m + 1)]
    dp[0][0] = 0.0
    for i in range(m + 1):
        for _ in range(2):
            for k in range(4):
                c = dp[i][k]
                if c >= BIG:
                    continue
                nk = (k + 1) % 4
                v = c + emp[k]
                if v < dp[i][nk] - 1e-12:
                    dp[i][nk] = v
                    bp[i][nk] = (i, k, 'e')
        if i == m:
            break
        for k in range(4):
            c = dp[i][k]
            if c >= BIG:
                continue
            v = c + SKIP
            if v < dp[i + 1][k] - 1e-12:
                dp[i + 1][k] = v
                bp[i + 1][k] = (i, k, 's')
            nk = (k + 1) % 4
            v = c + tc[i][k]
            if v < dp[i + 1][nk] - 1e-12:
                dp[i + 1][nk] = v
                bp[i + 1][nk] = (i, k, 'u')
    ops = []
    i, k = m, 0
    guard = 0
    while bp[i][k] is not None and guard < 100000:
        pi, pk, kind = bp[i][k]
        ops.append((pi, pk, kind))
        i, k = pi, pk
        guard += 1
    ops.reverse()
    rows = []
    cur = {}
    for pi, pk, kind in ops:
        if kind == 's':
            continue
        cur[cols[pk]] = tokens[pi] if kind == 'u' else ''
        if pk == 3:
            rows.append(cur)
            cur = {}
    return rows


def _parse(text):
    lines = (text or '').replace('\r', '').split('\n')
    cols = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    for ln in lines:
        if ln.strip().startswith('COLUMNS'):
            found = re.findall(r"CODE|QTY|UNIT|AMOUNT", ln)
            if sorted(found) == sorted(cols):
                cols = found
            break
    secs = []
    cur = None
    total_s = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if re.match(r"^=+\s*SECTION\b", s):
            cur = {'tokens': [], 'sub': None}
            secs.append(cur)
            continue
        if s.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'tokens': [], 'sub': None}
                secs.append(cur)
            cur['sub'] = re.sub(r"\s+", "", s[len('SUBTOTAL'):])
            continue
        if s.startswith('TOTAL'):
            mm = re.match(r"^TOTAL\s*(.*?)(?:\s+ITEMS\b.*)?$", s)
            if mm:
                total_s = re.sub(r"\s+", "", mm.group(1))
            continue
        toks = [t.strip() for t in SPLIT_RE.split(s)]
        toks = [t for t in toks if t]
        if not toks:
            continue
        if not all(_tok_ok(t) for t in toks):
            continue
        if cur is None:
            cur = {'tokens': [], 'sub': None}
            secs.append(cur)
        cur['tokens'].extend(toks)
    pcs = False
    grp = False
    for sec in secs:
        for t in sec['tokens']:
            if t.endswith('pcs'):
                pcs = True
            if re.search(r"[0-9OlSBZG]'[0-9OlSBZG]", t):
                grp = True
        if sec['sub'] and "'" in sec['sub']:
            grp = True
    if total_s and "'" in total_s:
        grp = True
    out = []
    for sec in secs:
        out.append({'rows': _segment(sec['tokens'], cols, pcs), 'sub': sec['sub']})
    return out, total_s, grp


# ------------------------------------------------------------ rows

def _row_cands(r, fast, grp):
    ru = r.get('UNIT', '')
    ra = r.get('AMOUNT', '')
    qn = _qty_norm(r.get('QTY', ''))
    un = _money_norm(ru)
    an = _money_norm(ra)
    q0 = _qty_parse(qn)
    u0 = _money_parse(un)
    a0 = _money_parse(an)
    if (q0 is not None and u0 is not None and a0 is not None and q0[0] * u0[0] == a0[0]
            and _gpen(ru, u0[0], grp) == 0 and _gpen(ra, a0[0], grp) == 0):
        return [[u0[1] + a0[1], q0[0], u0[0]]]
    Q = _cands(qn, _qty_parse)
    U = _cands(un, _money_parse)
    A = _cands(an, _money_parse)
    if grp:
        U = dict((u, c + _gpen(ru, u, grp)) for u, c in U.items())
        A = dict((a, c + _gpen(ra, a, grp)) for a, c in A.items())
    cands = {}

    def add(q, u, c):
        k = (q, u)
        if c < cands.get(k, INF):
            cands[k] = c

    for q, cq in Q.items():
        for u, cu in U.items():
            ca = A.get(q * u)
            if ca is not None:
                add(q, u, cq + cu + ca)
    best = min(cands.values()) if cands else INF
    if best > 1.5 and not fast:
        TH = 1.3
        Ql = sorted([(q, c) for q, c in Q.items() if c <= TH], key=lambda x: (x[1], x[0]))
        Ul = sorted([(u, c) for u, c in U.items() if c <= TH], key=lambda x: (x[1], x[0]))
        Al = sorted([(a, c) for a, c in A.items() if c <= TH], key=lambda x: (x[1], x[0]))
        for q, cq in Ql:
            for u, cu in Ul:
                if cq + cu > TH or (q, u) in cands:
                    continue
                add(q, u, cq + cu + _ed(an, _fmt(q * u), 5.0) + _gpen(ra, q * u, grp))
        for q, cq in Ql:
            for a, ca in Al:
                if cq + ca > TH or a % q:
                    continue
                u = a // q
                if u <= 0 or (q, u) in cands:
                    continue
                add(q, u, cq + ca + _ed(un, _fmt(u), 5.0) + _gpen(ru, u, grp))
        for u, cu in Ul:
            for a, ca in Al:
                if cu + ca > TH or a % u:
                    continue
                q = a // u
                if not (1 <= q <= 500) or (q, u) in cands:
                    continue
                add(q, u, cu + ca + _ed(qn, str(q), 5.0))
    if not cands:
        q = q0[0] if q0 else (min(Q.items(), key=lambda kv: (kv[1], kv[0]))[0] if Q else 1)
        if u0:
            u = u0[0]
        elif U:
            u = min(U.items(), key=lambda kv: (kv[1], kv[0]))[0]
        else:
            a = a0[0] if a0 else (min(A.items(), key=lambda kv: (kv[1], kv[0]))[0] if A else 100)
            u = max(1, a // max(1, q))
        add(q, u, 9.0)
    lst = sorted([[c, k[0], k[1]] for k, c in cands.items()], key=lambda x: (x[0], x[1], x[2]))
    b = lst[0][0]
    return [x for x in lst if x[0] <= b + 3.5][:10]


# ------------------------------------------------------------ reconciliation

def _reconcile(secs, total_s, total_raw, grp, t0):
    SUBCAP = 3.5
    TOTCAP = 3.5
    KSEC = 12
    sec_opts = []
    for sec in secs:
        beam = 300 if time.perf_counter() - t0 < 0.6 else 40
        states = {0: (0.0, None)}
        for row in sec['rows']:
            nxt = {}
            for s, (c, path) in states.items():
                for ci, cd in enumerate(row['cands']):
                    ns = s + cd[1] * cd[2]
                    nc = c + cd[0]
                    old = nxt.get(ns)
                    if old is None or nc < old[0]:
                        nxt[ns] = (nc, (ci, path))
            if len(nxt) > beam:
                nxt = dict(sorted(nxt.items(), key=lambda kv: (kv[1][0], kv[0]))[:beam])
            states = nxt
        sub = sec.get('subn')
        finals = []
        for s, (c, path) in states.items():
            if sub:
                sc = min(SUBCAP, _ed(sub, _fmt(s), SUBCAP) + _gpen(sec.get('sub'), s, grp))
            else:
                sc = 0.0
            finals.append((c + sc, s, path))
        finals.sort(key=lambda x: (x[0], x[1]))
        opts = []
        for tc, s, path in finals[:KSEC]:
            ch = []
            p = path
            while p is not None:
                ch.append(p[0])
                p = p[1]
            ch.reverse()
            opts.append((tc, s, ch))
        if not opts:
            opts = [(0.0, 0, [])]
        sec_opts.append(opts)
    gstates = {0: (0.0, None)}
    for opts in sec_opts:
        nxt = {}
        for g, (c, path) in gstates.items():
            for oi, (oc, s, ch) in enumerate(opts):
                ng = g + s
                nc = c + oc
                old = nxt.get(ng)
                if old is None or nc < old[0]:
                    nxt[ng] = (nc, (oi, path))
        if len(nxt) > 400:
            nxt = dict(sorted(nxt.items(), key=lambda kv: (kv[1][0], kv[0]))[:400])
        gstates = nxt
    best = None
    for g, (c, path) in gstates.items():
        if total_s:
            tcst = min(TOTCAP, _ed(total_s, _fmt(g), TOTCAP) + _gpen(total_raw, g, grp))
        else:
            tcst = 0.0
        tc = c + tcst
        if best is None or (tc, g) < (best[0], best[1]):
            best = (tc, g, path)
    choice = []
    p = best[2] if best else None
    while p is not None:
        choice.append(p[0])
        p = p[1]
    choice.reverse()
    picks = []
    for si, sec in enumerate(secs):
        oi = choice[si] if si < len(choice) else 0
        ch = sec_opts[si][oi][2]
        picks.append(ch)
    return picks


def solve(state, params):
    t0 = time.perf_counter()
    inp = state.get('input') or {}
    text = inp.get('text', '') if isinstance(inp, dict) else str(inp)
    items = []
    try:
        secs, total_s, grp = _parse(text)
        for sec in secs:
            sec['subn'] = _money_norm(sec['sub']) if sec.get('sub') else None
            rws = []
            for r in sec['rows']:
                el = time.perf_counter() - t0
                fast = el > 0.45
                try:
                    cands = _row_cands(r, fast, grp)
                except Exception:
                    cands = [[9.0, 1, 0]]
                try:
                    code = _fix_code(r.get('CODE', ''), (time.perf_counter() - t0) < 0.55)
                except Exception:
                    code = 'AA00000'
                rws.append({'code': code, 'cands': cands})
            sec['rows'] = rws
        tn = _money_norm(total_s) if total_s else None
        try:
            picks = _reconcile(secs, tn, total_s, grp, t0)
        except Exception:
            picks = [[] for _ in secs]
        for si, sec in enumerate(secs):
            ch = picks[si] if si < len(picks) else []
            for ri, row in enumerate(sec['rows']):
                ci = ch[ri] if ri < len(ch) else 0
                if ci >= len(row['cands']):
                    ci = 0
                cd = row['cands'][ci]
                items.append({'code': row['code'], 'qty': int(cd[1]), 'unit_cents': int(cd[2])})
    except Exception:
        pass
    state['output'] = {'items': items}
    return state

import re
import time
import math

MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
       '6': '50', '7': '12', '8': '30', '9': '43'}
REVM = {}
for _o in sorted(MIS):
    for _c in MIS[_o]:
        REVM.setdefault(_c, []).append(_o)
L2D = {'O': '0', 'o': '0', 'Q': '0', 'D': '0', 'l': '1', 'I': '1', 'i': '1', '|': '1',
       'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6'}
D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G', 'l': 'I'}
LOOKSET = set('OlISBZG')
DIG = '0123456789'
LAM = 2.3
COST = {'mis': 1.0, 'dup': 1.0, 'ins': 1.2}
MCOST = {}
C_SUB = 2.5
C_DEL = 2.5
C_MARK = 0.4
C_XC = 3.0
INF = 1e9
GPEN = 3.0
SPLIT_RE = re.compile(r"\s*[|;\t]\s*|\s{2,}")


def _set_costs(dm, dd, dl):
    COST['mis'] = 1.0 + dm
    COST['dup'] = 1.0 + dd
    COST['ins'] = 1.2 + dl
    for o in MIS:
        MCOST[o] = COST['mis'] + math.log(len(MIS[o])) / LAM - math.log(2) / LAM


_set_costs(0.0, 0.0, 0.0)


# ------------------------------------------------------------ edit model

def _ops(s, anysub):
    out = []
    n = len(s)
    cdup = COST['dup']
    cins = COST['ins']
    for i in range(n):
        ch = s[i]
        if not ch.isdigit():
            continue
        origs = REVM.get(ch, [])
        for o in origs:
            out.append((s[:i] + o + s[i + 1:], MCOST[o]))
        if anysub:
            for o in DIG:
                if o != ch and o not in origs:
                    out.append((s[:i] + o + s[i + 1:], C_SUB))
        if i + 1 < n and s[i + 1] == ch:
            out.append((s[:i] + s[i + 1:], cdup))
        elif anysub and not (i > 0 and s[i - 1] == ch):
            out.append((s[:i] + s[i + 1:], C_DEL))
    for i in range(n + 1):
        a = s[:i]
        b = s[i:]
        for d in DIG:
            out.append((a + d + b, cins))
    return out


def _code_extra(s):
    out = []
    n = len(s)
    for i in range(n):
        ch = s[i]
        origs = REVM.get(ch, [])
        for o in DIG:
            if o != ch and o not in origs:
                out.append((s[:i] + o + s[i + 1:], C_XC))
        if not ((i + 1 < n and s[i + 1] == ch) or (i > 0 and s[i - 1] == ch)):
            out.append((s[:i] + s[i + 1:], C_XC))
    return out


def _ed(o, c, cap):
    cins = COST['ins']
    cdup = COST['dup']
    m = len(c)
    prev = [0.0] * (m + 1)
    for j in range(1, m + 1):
        prev[j] = prev[j - 1] + (C_MARK if c[j - 1] == '.' else cins)
    for i in range(1, len(o) + 1):
        oi = o[i - 1]
        if oi == '.':
            ins = 3.0
        elif i >= 2 and o[i - 2] == oi:
            ins = cdup
        else:
            ins = C_DEL
        cur = [prev[0] + ins] + [0.0] * m
        rmin = cur[0]
        for j in range(1, m + 1):
            cj = c[j - 1]
            if oi == cj:
                b = prev[j - 1]
            elif oi == '.' or cj == '.' or not oi.isdigit() or not cj.isdigit():
                b = prev[j - 1] + 3.0
            elif oi in MIS[cj]:
                b = prev[j - 1] + MCOST[cj]
            else:
                b = prev[j - 1] + C_SUB
            d = cur[j - 1] + (C_MARK if cj == '.' else cins)
            if d < b:
                b = d
            d = prev[j] + ins
            if d < b:
                b = d
            cur[j] = b
            if b < rmin:
                rmin = b
        if rmin >= cap:
            return cap
        prev = cur
    return min(prev[m], cap)


def _fmt(c):
    return '%d.%02d' % (c // 100, c % 100)


def _gpen(raw, v, grp):
    if not grp or raw is None:
        return 0.0
    has = "'" in raw
    if has == (v >= 100000):
        return 0.0
    return GPEN


def _strip_pcs(t):
    t = t.strip()
    m = re.match(r"^(.*?)\s*pcs$", t)
    if m:
        return m.group(1).strip(), True
    return t, False


def _money_norm(tok):
    t = ''.join(L2D.get(ch, ch) for ch in (tok or ''))
    t = t.replace(',', '.')
    t = re.sub(r"[^0-9.]", '', t)
    if t.count('.') > 1:
        k = t.rfind('.')
        t = t[:k].replace('.', '') + t[k:]
    return t


def _qty_norm(tok):
    b, _ = _strip_pcs(tok or '')
    t = ''.join(L2D.get(ch, ch) for ch in b)
    return re.sub(r"[^0-9]", '', t)


def _money_parse(s):
    if '.' in s:
        if s.count('.') != 1:
            return None
        a, b = s.split('.')
        if len(b) != 2 or not a or not a.isdigit() or not b.isdigit():
            return None
        if len(a) > 1 and a[0] == '0':
            return None
        v = int(a) * 100 + int(b)
        if v <= 0:
            return None
        return v, 0.0
    if len(s) < 3 or not s.isdigit():
        return None
    a = s[:-2]
    if len(a) > 1 and a[0] == '0':
        return None
    v = int(s)
    if v <= 0:
        return None
    return v, C_MARK


def _qty_parse(s):
    if not s or not s.isdigit() or s[0] == '0':
        return None
    v = int(s)
    if 1 <= v <= 500:
        return v, 0.0
    return None


def _cands(s, parse):
    W = {}

    def put(t, c):
        r = parse(t)
        if r is None:
            return
        val, extra = r
        W[val] = W.get(val, 0.0) + math.exp(-LAM * (c + extra))

    put(s, 0.0)
    if s:
        for t, c in _ops(s, False):
            put(t, c)
    else:
        for d in DIG:
            put(d, COST['ins'])
    out = {}
    for v, w in W.items():
        out[v] = max(0.0, -math.log(w) / LAM)
    return out


# ------------------------------------------------------------ codes

def _code_valid(L, d):
    if len(d) != 5 or not d.isdigit():
        return False
    p = ord(L[0]) - 64 + ord(L[1]) - 64
    return (int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p) % 10 == int(d[4])


def _code_split(tok):
    t = re.sub(r"\s+", "", tok or '')
    letters = ''
    for ch in t[:2]:
        if 'A' <= ch <= 'Z':
            letters += ch
        elif ch in D2L:
            letters += D2L[ch]
        elif 'a' <= ch <= 'z':
            letters += ch.upper()
        else:
            letters += 'A'
    while len(letters) < 2:
        letters += 'A'
    ds = re.sub(r"[^0-9]", '', ''.join(L2D.get(ch, ch) for ch in t[2:]))
    return letters, ds


def _fix_code(tok, deep):
    letters, ds = _code_split(tok)
    if _code_valid(letters, ds):
        return letters + ds

    def ok(e):
        return len(e) == 5 and _code_valid(letters, e)

    W = {}
    l1 = {}
    for e, c in _ops(ds, False):
        l1[e] = l1.get(e, 0.0) + math.exp(-LAM * c)
    for e, w in l1.items():
        if ok(e):
            W[e] = W.get(e, 0.0) + w
    for e, c in _code_extra(ds):
        if ok(e):
            W[e] = W.get(e, 0.0) + math.exp(-LAM * c)
    cmin = min(COST['ins'], COST['dup'], COST['mis'] - math.log(2) / LAM)
    thr = min(1.5, 2 * cmin + 0.05)
    strong = math.exp(-LAM * thr)
    if deep and (not W or max(W.values()) < strong):
        l2 = {}
        for e, w in l1.items():
            if not (3 <= len(e) <= 7):
                continue
            for e2, c in _ops(e, False):
                w2 = w * math.exp(-LAM * c)
                l2[e2] = l2.get(e2, 0.0) + w2
            for e2, c in _code_extra(e):
                w2 = w * math.exp(-LAM * c)
                if ok(e2):
                    W[e2] = W.get(e2, 0.0) + w2
        for e2, w2 in l2.items():
            if ok(e2):
                W[e2] = W.get(e2, 0.0) + w2
        if not W:
            items = [(w, e) for e, w in l2.items() if 4 <= len(e) <= 6]
            items.sort(key=lambda x: (-x[0], x[1]))
            for w, e in items[:300]:
                for e3, c in _ops(e, True):
                    if ok(e3):
                        W[e3] = W.get(e3, 0.0) + w * math.exp(-LAM * c)
    if W:
        best = min(W.items(), key=lambda kv: (-round(kv[1], 14), kv[0]))
        return letters + best[0]
    d = (ds + '00000')[:4]
    p = ord(letters[0]) - 64 + ord(letters[1]) - 64
    ck = (int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p) % 10
    return letters + d + str(ck)


# ------------------------------------------------------------ parsing

def _tok_ok(t):
    b, has = _strip_pcs(t)
    if not b:
        return has
    if not re.fullmatch(r"[A-Z0-9l.,']+", b):
        return False
    for ch in b[2:]:
        if 'A' <= ch <= 'Z' and ch not in LOOKSET:
            return False
    return True


def _tc(tok, col, pcs):
    b, has = _strip_pcs(tok)
    if col == 'QTY':
        if not re.fullmatch(r"[0-9OlISBZG]{0,4}", b):
            return 4.0
        c = 0.0
        if pcs and not has:
            c += 2.0
        if not b:
            c += 1.5
        return c
    if has:
        return 6.0
    if col == 'CODE':
        if re.fullmatch(r"[A-Z0-9l]{2}[0-9OlISBZG]{3,7}", b):
            h = b[:2]
            if all('A' <= ch <= 'Z' for ch in h):
                return 0.0
            if all(('A' <= ch <= 'Z') or ch in D2L for ch in h):
                return 0.8
        return 4.0
    if re.fullmatch(r"[0-9OlISBZG']+[.,][0-9OlISBZG]{1,3}", b):
        return 0.0
    if re.fullmatch(r"[0-9OlISBZG']{3,}", b):
        return 0.6
    if re.fullmatch(r"[0-9OlISBZG']{1,2}", b):
        return 2.0
    return 4.0


def _segment(tokens, cols, pcs):
    m = len(tokens)
    if m == 0:
        return []
    BIG = 1e18
    SKIP = 4.0
    tc = [[_tc(t, c, pcs) for c in cols] for t in tokens]
    emp = [2.0 if c == 'QTY' else 4.5 for c in cols]
    dp = [[BIG] * 4 for _ in range(m + 1)]
    bp = [[None] * 4 for _ in range(m + 1)]
    dp[0][0] = 0.0
    for i in range(m + 1):
        for _ in range(2):
            for k in range(4):
                c = dp[i][k]
                if c >= BIG:
                    continue
                nk = (k + 1) % 4
                v = c + emp[k]
                if v < dp[i][nk] - 1e-12:
                    dp[i][nk] = v
                    bp[i][nk] = (i, k, 'e')
        if i == m:
            break
        for k in range(4):
            c = dp[i][k]
            if c >= BIG:
                continue
            v = c + SKIP
            if v < dp[i + 1][k] - 1e-12:
                dp[i + 1][k] = v
                bp[i + 1][k] = (i, k, 's')
            nk = (k + 1) % 4
            v = c + tc[i][k]
            if v < dp[i + 1][nk] - 1e-12:
                dp[i + 1][nk] = v
                bp[i + 1][nk] = (i, k, 'u')
    ops = []
    i, k = m, 0
    guard = 0
    while bp[i][k] is not None and guard < 100000:
        pi, pk, kind = bp[i][k]
        ops.append((pi, pk, kind))
        i, k = pi, pk
        guard += 1
    ops.reverse()
    rows = []
    cur = {}
    for pi, pk, kind in ops:
        if kind == 's':
            continue
        cur[cols[pk]] = tokens[pi] if kind == 'u' else ''
        if pk == 3:
            rows.append(cur)
            cur = {}
    return rows


def _parse(text):
    lines = (text or '').replace('\r', '').split('\n')
    cols = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    for ln in lines:
        if ln.strip().startswith('COLUMNS'):
            found = re.findall(r"CODE|QTY|UNIT|AMOUNT", ln)
            if sorted(found) == sorted(cols):
                cols = found
            break
    secs = []
    cur = None
    total_s = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if re.match(r"^=+\s*SECTION\b", s):
            cur = {'tokens': [], 'sub': None}
            secs.append(cur)
            continue
        if s.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'tokens': [], 'sub': None}
                secs.append(cur)
            cur['sub'] = re.sub(r"\s+", "", s[len('SUBTOTAL'):])
            continue
        if s.startswith('TOTAL'):
            mm = re.match(r"^TOTAL\s*(.*?)(?:\s+ITEMS\b.*)?$", s)
            if mm:
                total_s = re.sub(r"\s+", "", mm.group(1))
            continue
        toks = [t.strip() for t in SPLIT_RE.split(s)]
        toks = [t for t in toks if t]
        if not toks:
            continue
        if not all(_tok_ok(t) for t in toks):
            continue
        if cur is None:
            cur = {'tokens': [], 'sub': None}
            secs.append(cur)
        cur['tokens'].extend(toks)
    pcs = False
    grp = False
    for sec in secs:
        for t in sec['tokens']:
            if t.endswith('pcs'):
                pcs = True
            if re.search(r"[0-9OlSBZG]'[0-9OlSBZG]", t):
                grp = True
        if sec['sub'] and "'" in sec['sub']:
            grp = True
    if total_s and "'" in total_s:
        grp = True
    out = []
    for sec in secs:
        out.append({'rows': _segment(sec['tokens'], cols, pcs), 'sub': sec['sub']})
    return out, total_s, grp


# ------------------------------------------------------------ damage-mix estimate

def _estimate(secs, total_s):
    L = 0.0
    D = 0.0
    M = 0.0

    def frac(tok):
        t = _money_norm(tok)
        if '.' in t:
            f = len(t) - t.rfind('.') - 1
            if f == 1:
                return 'L'
            if f >= 3:
                return 'D'
        return None

    for sec in secs:
        for r in sec['rows']:
            ct = r.get('CODE', '')
            if ct:
                letters, ds = _code_split(ct)
                n = len(ds)
                if n < 5:
                    L += 5 - n
                elif n > 5:
                    D += n - 5
                elif not _code_valid(letters, ds):
                    M += 1
            anom = False
            for col in ('UNIT', 'AMOUNT'):
                k = frac(r.get(col, ''))
                if k == 'L':
                    L += 1
                    anom = True
                elif k == 'D':
                    D += 1
                    anom = True
            if not anom:
                q = _qty_parse(_qty_norm(r.get('QTY', '')))
                u = _money_parse(_money_norm(r.get('UNIT', '')))
                a = _money_parse(_money_norm(r.get('AMOUNT', '')))
                if q and u and a and q[0] * u[0] != a[0]:
                    M += 0.5
        if sec.get('sub'):
            k = frac(sec['sub'])
            if k == 'L':
                L += 1
            elif k == 'D':
                D += 1
    if total_s:
        k = frac(total_s)
        if k == 'L':
            L += 1
        elif k == 'D':
            D += 1
    tot = L + D + M + 3.0

    def dl(x):
        s = (x + 1.0) / tot
        v = -math.log(3.0 * s) / LAM
        return max(-0.45, min(0.6, v))

    return dl(M), dl(D), dl(L)


# ------------------------------------------------------------ rows

def _row_cands(r, fast, grp):
    ru = r.get('UNIT', '')
    ra = r.get('AMOUNT', '')
    qn = _qty_norm(r.get('QTY', ''))
    un = _money_norm(ru)
    an = _money_norm(ra)
    q0 = _qty_parse(qn)
    u0 = _money_parse(un)
    a0 = _money_parse(an)
    if (q0 is not None and u0 is not None and a0 is not None and q0[0] * u0[0] == a0[0]
            and _gpen(ru, u0[0], grp) == 0 and _gpen(ra, a0[0], grp) == 0):
        return [[u0[1] + a0[1], q0[0], u0[0]]]
    Q = _cands(qn, _qty_parse)
    U = _cands(un, _money_parse)
    A = _cands(an, _money_parse)
    if grp:
        U = dict((u, c + _gpen(ru, u, grp)) for u, c in U.items())
        A = dict((a, c + _gpen(ra, a, grp)) for a, c in A.items())
    cands = {}

    def add(q, u, c):
        k = (q, u)
        if c < cands.get(k, INF):
            cands[k] = c

    for q, cq in Q.items():
        for u, cu in U.items():
            ca = A.get(q * u)
            if ca is not None:
                add(q, u, cq + cu + ca)
    best = min(cands.values()) if cands else INF
    if best > 1.5 and not fast:
        TH = 1.3
        Ql = sorted([(q, c) for q, c in Q.items() if c <= TH], key=lambda x: (x[1], x[0]))
        Ul = sorted([(u, c) for u, c in U.items() if c <= TH], key=lambda x: (x[1], x[0]))
        Al = sorted([(a, c) for a, c in A.items() if c <= TH], key=lambda x: (x[1], x[0]))
        for q, cq in Ql:
            for u, cu in Ul:
                if cq + cu > TH or (q, u) in cands:
                    continue
                add(q, u, cq + cu + _ed(an, _fmt(q * u), 5.0) + _gpen(ra, q * u, grp))
        for q, cq in Ql:
            for a, ca in Al:
                if cq + ca > TH or a % q:
                    continue
                u = a // q
                if u <= 0 or (q, u) in cands:
                    continue
                add(q, u, cq + ca + _ed(un, _fmt(u), 5.0) + _gpen(ru, u, grp))
        for u, cu in Ul:
            for a, ca in Al:
                if cu + ca > TH or a % u:
                    continue
                q = a // u
                if not (1 <= q <= 500) or (q, u) in cands:
                    continue
                add(q, u, cu + ca + _ed(qn, str(q), 5.0))
    if not cands:
        q = q0[0] if q0 else (min(Q.items(), key=lambda kv: (kv[1], kv[0]))[0] if Q else 1)
        if u0:
            u = u0[0]
        elif U:
            u = min(U.items(), key=lambda kv: (kv[1], kv[0]))[0]
        else:
            a = a0[0] if a0 else (min(A.items(), key=lambda kv: (kv[1], kv[0]))[0] if A else 100)
            u = max(1, a // max(1, q))
        add(q, u, 9.0)
    lst = sorted([[c, k[0], k[1]] for k, c in cands.items()], key=lambda x: (x[0], x[1], x[2]))
    b = lst[0][0]
    return [x for x in lst if x[0] <= b + 3.5][:10]


# ------------------------------------------------------------ reconciliation

def _reconcile(secs, total_s, total_raw, grp, t0):
    SUBCAP = 3.5
    TOTCAP = 3.5
    KSEC = 12
    sec_opts = []
    for sec in secs:
        beam = 300 if time.perf_counter() - t0 < 0.6 else 40
        states = {0: (0.0, None)}
        for row in sec['rows']:
            nxt = {}
            for s, (c, path) in states.items():
                for ci, cd in enumerate(row['cands']):
                    ns = s + cd[1] * cd[2]
                    nc = c + cd[0]
                    old = nxt.get(ns)
                    if old is None or nc < old[0]:
                        nxt[ns] = (nc, (ci, path))
            if len(nxt) > beam:
                nxt = dict(sorted(nxt.items(), key=lambda kv: (kv[1][0], kv[0]))[:beam])
            states = nxt
        sub = sec.get('subn')
        finals = []
        for s, (c, path) in states.items():
            if sub:
                sc = min(SUBCAP, _ed(sub, _fmt(s), SUBCAP) + _gpen(sec.get('sub'), s, grp))
            else:
                sc = 0.0
            finals.append((c + sc, s, path))
        finals.sort(key=lambda x: (x[0], x[1]))
        opts = []
        for tc, s, path in finals[:KSEC]:
            ch = []
            p = path
            while p is not None:
                ch.append(p[0])
                p = p[1]
            ch.reverse()
            opts.append((tc, s, ch))
        if not opts:
            opts = [(0.0, 0, [])]
        sec_opts.append(opts)
    gstates = {0: (0.0, None)}
    for opts in sec_opts:
        nxt = {}
        for g, (c, path) in gstates.items():
            for oi, (oc, s, ch) in enumerate(opts):
                ng = g + s
                nc = c + oc
                old = nxt.get(ng)
                if old is None or nc < old[0]:
                    nxt[ng] = (nc, (oi, path))
        if len(nxt) > 400:
            nxt = dict(sorted(nxt.items(), key=lambda kv: (kv[1][0], kv[0]))[:400])
        gstates = nxt
    best = None
    for g, (c, path) in gstates.items():
        if total_s:
            tcst = min(TOTCAP, _ed(total_s, _fmt(g), TOTCAP) + _gpen(total_raw, g, grp))
        else:
            tcst = 0.0
        tc = c + tcst
        if best is None or (tc, g) < (best[0], best[1]):
            best = (tc, g, path)
    choice = []
    p = best[2] if best else None
    while p is not None:
        choice.append(p[0])
        p = p[1]
    choice.reverse()
    picks = []
    for si, sec in enumerate(secs):
        oi = choice[si] if si < len(choice) else 0
        ch = sec_opts[si][oi][2]
        picks.append(ch)
    return picks


def solve(state, params):
    t0 = time.perf_counter()
    _set_costs(0.0, 0.0, 0.0)
    inp = state.get('input') or {}
    text = inp.get('text', '') if isinstance(inp, dict) else str(inp)
    items = []
    try:
        secs, total_s, grp = _parse(text)
        try:
            dm, dd, dl = _estimate(secs, total_s)
            _set_costs(dm, dd, dl)
        except Exception:
            _set_costs(0.0, 0.0, 0.0)
        for sec in secs:
            sec['subn'] = _money_norm(sec['sub']) if sec.get('sub') else None
            rws = []
            for r in sec['rows']:
                el = time.perf_counter() - t0
                fast = el > 0.45
                try:
                    cands = _row_cands(r, fast, grp)
                except Exception:
                    cands = [[9.0, 1, 0]]
                try:
                    code = _fix_code(r.get('CODE', ''), (time.perf_counter() - t0) < 0.55)
                except Exception:
                    code = 'AA00000'
                rws.append({'code': code, 'cands': cands})
            sec['rows'] = rws
        tn = _money_norm(total_s) if total_s else None
        try:
            picks = _reconcile(secs, tn, total_s, grp, t0)
        except Exception:
            picks = [[] for _ in secs]
        for si, sec in enumerate(secs):
            ch = picks[si] if si < len(picks) else []
            for ri, row in enumerate(sec['rows']):
                ci = ch[ri] if ri < len(ch) else 0
                if ci >= len(row['cands']):
                    ci = 0
                cd = row['cands'][ci]
                items.append({'code': row['code'], 'qty': int(cd[1]), 'unit_cents': int(cd[2])})
    except Exception:
        pass
    state['output'] = {'items': items}
    return state

import re
import math
import heapq
import time
import string
from collections import Counter

DIG = '0123456789'
LK_L2D = {'O': '0', 'l': '1', 'S': '5', 'B': '8', 'Z': '2', 'G': '6', 'I': '1', 'o': '0'}
MR = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
      '6': '50', '7': '12', '8': '30', '9': '43'}
CODE_D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
BASE = {'lk': 3.9, 'mr': 4.2, 'del': 4.6, 'dbl': 4.6, 'mk': 4.6}
MONEY_RE = re.compile(r'(0|[1-9][0-9]*)\.[0-9]{2}')
QTY_RE = re.compile(r'[1-9][0-9]{0,2}')
CODE_RE = re.compile(r'[A-Z]{2}[0-9]{5}')
INF = 1e18


def make_costs(raw):
    c = dict(raw)
    mn = min(c.values())
    scale = BASE['lk'] / mn if mn > 0 else 1.0
    for k in list(c.keys()):
        c[k] = c[k] * scale
    mx = max(c.values())
    mn = min(c.values())
    c['oth'] = mx + 5.0
    c['B'] = mx + 0.8 * mn
    return c


def make_tabs(costs):
    opts = {}
    for ch in DIG:
        lst = [(ch, '', 0.0)]
        for t in DIG:
            if ch in MR[t]:
                lst.append((t, 'mr', costs['mr']))
        opts[ch] = lst
    for ch, d in LK_L2D.items():
        opts[ch] = [(d, 'lk', costs['lk'])]
    subc = {}
    for ch, lst in opts.items():
        for t, op, oc in lst:
            k = (t, ch)
            if k not in subc or subc[k] > oc:
                subc[k] = oc
    return {'opts': opts, 'subc': subc, 'costs': costs}


def check_ok(code):
    p1 = ord(code[0]) - 64
    p2 = ord(code[1]) - 64
    d = [int(x) for x in code[2:7]]
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p1 + p2) % 10 == d[4]


def decode_code(obs, T):
    o = re.sub(r'\s+', '', obs or '')
    if CODE_RE.fullmatch(o) and check_ok(o):
        return o, []
    costs = T['costs']
    opts = T['opts']
    subc = T['subc']
    oth = costs['oth']
    dl = costs['del']
    db = costs['dbl']
    lk = costs['lk']
    n = len(o)
    layers = [dict() for _ in range(8)]
    layers[0][(0, 0)] = (0.0, None, '', ())

    def relax(layer, key, c, prev, ch, ops):
        cur = layer.get(key)
        if cur is None or c < cur[0]:
            layer[key] = (c, prev, ch, ops)

    for j in range(7):
        cur = layers[j]
        nxt = layers[j + 1]
        for key, val in list(cur.items()):
            i, s = key
            c = val[0]
            if j < 2:
                if i < n:
                    ch = o[i]
                    cand = []
                    if 'A' <= ch <= 'Z':
                        cand.append((ch, 0.0, ()))
                    if ch in CODE_D2L:
                        cand.append((CODE_D2L[ch], lk, ('lk',)))
                    if not cand:
                        up = ch.upper()
                        if len(up) == 1 and 'A' <= up <= 'Z':
                            cand.append((up, lk, ('lk',)))
                        else:
                            for L in string.ascii_uppercase:
                                cand.append((L, oth, ('oth',)))
                    for L, oc, op in cand:
                        relax(nxt, (i + 1, (s + ord(L) - 64) % 10), c + oc, key, L, op)
            elif j < 6:
                w = j - 1
                if i < n:
                    ch = o[i]
                    lst = opts.get(ch)
                    if lst is None:
                        lst = [(d, 'oth', oth) for d in DIG]
                    for d, op, oc in lst:
                        ns = (s + w * int(d)) % 10
                        ops = (op,) if op else ()
                        relax(nxt, (i + 1, ns), c + oc, key, d, ops)
                        if i + 1 < n and o[i + 1] == ch:
                            relax(nxt, (i + 2, ns), c + oc + db, key, d, ops + ('dbl',))
                for d in DIG:
                    ns = (s + w * int(d)) % 10
                    relax(nxt, (i, ns), c + dl, key, d, ('del',))
            else:
                d = str(s)
                if i < n:
                    ch = o[i]
                    oc = subc.get((d, ch), oth)
                    op = ()
                    if oc > 0:
                        op = ('lk',) if ch in LK_L2D else (('mr',) if ch in DIG else ('oth',))
                    relax(nxt, (i + 1, s), c + oc, key, d, op)
                    if i + 1 < n and o[i + 1] == ch:
                        relax(nxt, (i + 2, s), c + oc + db, key, d, op + ('dbl',))
                relax(nxt, (i, s), c + dl, key, d, ('del',))
    bestkey = None
    bestc = INF
    for key, val in layers[7].items():
        i = key[0]
        if i > n:
            continue
        c = val[0] + oth * (n - i)
        if c < bestc:
            bestc = c
            bestkey = key
    if bestkey is None:
        cleaned = re.sub(r'[^A-Z0-9]', '', o.upper())
        if len(cleaned) < 7:
            cleaned = (cleaned + 'AA00000')[:7]
        return cleaned[:7], []
    chars = []
    ops = []
    key = bestkey
    j = 7
    while j > 0:
        val = layers[j][key]
        chars.append(val[2])
        ops.extend(val[3])
        key = val[1]
        j -= 1
    return ''.join(reversed(chars)), ops


def gen_number(obs, money, T, K=8, maxpop=600):
    costs = T['costs']
    opts = T['opts']
    oth = costs['oth']
    dl = costs['del']
    db = costs['dbl']
    mk = costs['mk']
    B = costs['B']
    n = len(obs)
    heap = [(0.0, 0, '', ())]
    visited = set()
    results = []
    seen = set()
    best = None
    pops = 0
    maxint = n + 2
    while heap and pops < maxpop:
        c, i, out, ops = heapq.heappop(heap)
        pops += 1
        if best is not None and c > best + B:
            break
        key = (i, out)
        if key in visited:
            continue
        visited.add(key)
        dot = out.find('.')
        ph = 1 if dot >= 0 else 0
        fl = len(out) - dot - 1 if ph else -1
        if i == n:
            if money:
                ok = ph == 1 and fl == 2
            else:
                ok = out != '' and int(out) <= 500
            if ok and out not in seen:
                seen.add(out)
                results.append((c, out, ops))
                if best is None:
                    best = c
                if len(results) >= K:
                    break
        if ph == 1 and fl >= 2:
            continue
        if ph == 0:
            allow_digit = out != '0' and (money or len(out) < 3) and len(out) < maxint
            allow_zero = money or out != ''
        else:
            allow_digit = True
            allow_zero = True
        nd = ops.count('del')
        if i < n:
            ch = obs[i]
            if ch == '.':
                if money and ph == 0 and out != '':
                    heapq.heappush(heap, (c, i + 1, out + '.', ops))
                else:
                    heapq.heappush(heap, (c + oth, i + 1, out, ops + ('oth',)))
            else:
                lst = opts.get(ch)
                if lst is None:
                    heapq.heappush(heap, (c + oth, i + 1, out, ops + ('oth',)))
                elif allow_digit:
                    for d, op, oc in lst:
                        if d == '0' and not allow_zero:
                            continue
                        nops = ops + (op,) if op else ops
                        heapq.heappush(heap, (c + oc, i + 1, out + d, nops))
                        if i + 1 < n and obs[i + 1] == ch:
                            heapq.heappush(heap, (c + oc + db, i + 2, out + d, nops + ('dbl',)))
        if allow_digit and nd < 1:
            for d in DIG:
                if d == '0' and not allow_zero:
                    continue
                heapq.heappush(heap, (c + dl, i, out + d, ops + ('del',)))
        if money and ph == 0 and out != '' and (i >= n or obs[i] != '.'):
            heapq.heappush(heap, (c + mk, i, out + '.', ops + ('mk',)))
    return results


def align(obs, tgt, T):
    costs = T['costs']
    subc = T['subc']
    oth = costs['oth']
    dl = costs['del']
    db = costs['dbl']
    mk = costs['mk']
    n = len(obs)
    m = len(tgt)
    D = [[INF] * (m + 1) for _ in range(n + 1)]
    D[0][0] = 0.0
    for i in range(n + 1):
        Di = D[i]
        for j in range(m + 1):
            v = Di[j]
            if v >= INF:
                continue
            if j < m:
                t = tgt[j]
                if t == '.':
                    w = v + mk
                    if w < Di[j + 1]:
                        Di[j + 1] = w
                    if i < n and obs[i] == '.':
                        if v < D[i + 1][j + 1]:
                            D[i + 1][j + 1] = v
                else:
                    w = v + dl
                    if w < Di[j + 1]:
                        Di[j + 1] = w
                    if i < n:
                        ch = obs[i]
                        w = v + subc.get((t, ch), oth)
                        if w < D[i + 1][j + 1]:
                            D[i + 1][j + 1] = w
                        if i + 1 < n and obs[i + 1] == ch:
                            w2 = w + db
                            if w2 < D[i + 2][j + 1]:
                                D[i + 2][j + 1] = w2
            if i < n:
                w = v + oth
                if w < D[i + 1][j]:
                    D[i + 1][j] = w
    return D[n][m]


def fmt(cents):
    return '%d.%02d' % (cents // 100, cents % 100)


def to_cents(s):
    ip, fp = s.split('.')
    return int(ip) * 100 + int(fp)


def norm_money(tok, dec):
    s = (tok or '').replace("'", '').replace(' ', '').replace('\u2019', '')
    if dec == ',':
        s = s.replace(',', '.')
    else:
        s = s.replace(',', '')
    return s


def norm_qty(tok):
    s = re.sub(r'(?i)\s*pcs\.?\s*$', '', (tok or '').strip())
    return s.replace(' ', '')


def decode_row(toks, cols, dec, T, memo):
    f = {}
    for k, name in enumerate(cols):
        f[name] = toks[k] if k < len(toks) else ''
    code, cops = decode_code(f.get('CODE', ''), T)
    qo = norm_qty(f.get('QTY', ''))
    uo = norm_money(f.get('UNIT', ''), dec)
    ao = norm_money(f.get('AMOUNT', ''), dec)
    nch = len(f.get('CODE', '')) + len(qo) + len(uo) + len(ao)
    rec = {'code': code, 'nch': nch, 'fast': False, 'toks': toks}
    if QTY_RE.fullmatch(qo) and MONEY_RE.fullmatch(uo) and MONEY_RE.fullmatch(ao):
        q = int(qo)
        u = to_cents(uo)
        a = to_cents(ao)
        if q <= 500 and q * u == a:
            rec['cands'] = [(0.0, q, u)]
            rec['ops'] = list(cops)
            rec['fast'] = True
            return rec
    B = T['costs']['B']
    Q = gen_number(qo, False, T)
    U = gen_number(uo, True, T)
    A = gen_number(ao, True, T)
    Qd = {}
    for c, s, ops in Q:
        v = int(s)
        if v not in Qd:
            Qd[v] = (c, ops)
    Ud = {}
    for c, s, ops in U:
        v = to_cents(s)
        if v not in Ud:
            Ud[v] = (c, ops)
    Ad = {}
    for c, s, ops in A:
        v = to_cents(s)
        if v not in Ad:
            Ad[v] = (c, ops)
    Ql = sorted(Qd.items(), key=lambda kv: kv[1][0])
    Ul = sorted(Ud.items(), key=lambda kv: kv[1][0])
    Al = sorted(Ad.items(), key=lambda kv: kv[1][0])
    res = {}
    best = [INF]

    def al(obs, tgt):
        key = (obs, tgt)
        v = memo.get(key)
        if v is None:
            v = align(obs, tgt, T)
            memo[key] = v
        return v

    def add(q, u, c, ops):
        cur = res.get((q, u))
        if cur is None or c < cur[0]:
            res[(q, u)] = (c, ops)
        if c < best[0]:
            best[0] = c

    for q, (cq, oq) in Ql:
        if cq >= best[0] + B:
            break
        for u, (cu, ou) in Ul:
            p = cq + cu
            if p >= best[0] + B:
                break
            a = q * u
            if a in Ad:
                ca, oa = Ad[a]
            else:
                ca = al(ao, fmt(a))
                oa = ()
            add(q, u, p + ca, oq + ou + oa)
    for q, (cq, oq) in Ql:
        if cq >= best[0] + B:
            break
        for a, (ca, oa) in Al:
            p = cq + ca
            if p >= best[0] + B:
                break
            if a % q:
                continue
            u = a // q
            if u in Ud:
                cu, ou = Ud[u]
            else:
                cu = al(uo, fmt(u))
                ou = ()
            add(q, u, p + cu, oq + ou + oa)
    for u, (cu, ou) in Ul:
        if cu >= best[0] + B:
            break
        if u <= 0:
            continue
        for a, (ca, oa) in Al:
            p = cu + ca
            if p >= best[0] + B:
                break
            if a % u:
                continue
            q = a // u
            if q < 1 or q > 500:
                continue
            if q in Qd:
                cq, oq = Qd[q]
            else:
                cq = al(qo, str(q))
                oq = ()
            add(q, u, p + cq, oq + ou + oa)
    if not res:
        dq = re.sub(r'[^0-9]', '', qo)
        q = int(dq[:3]) if dq else 1
        if q < 1 or q > 500:
            q = 1
        du = re.sub(r'[^0-9]', '', uo)
        u = int(du[:9]) if du else 0
        if Ul:
            u = Ul[0][0]
        rec['cands'] = [(INF, q, u)]
        rec['ops'] = list(cops)
        return rec
    items = sorted(res.items(), key=lambda kv: kv[1][0])
    rec['cands'] = [(v[0], k[0], k[1]) for k, v in items[:6]]
    rec['ops'] = list(cops) + list(items[0][1][1])
    return rec


def reconcile(rows, sub_obs, dec, T, memo):
    if sub_obs is None or not rows:
        return
    so = norm_money(sub_obs, dec)
    S = gen_number(so, True, T, K=10, maxpop=800)
    Sd = {}
    for c, s, _ in S:
        v = to_cents(s)
        if v not in Sd:
            Sd[v] = c
    S0 = 0
    for r in rows:
        b = r['cands'][0]
        S0 += b[1] * b[2]
    c0 = Sd.get(S0)
    if c0 is None:
        key = (so, fmt(S0))
        c0 = memo.get(key)
        if c0 is None:
            c0 = align(so, fmt(S0), T)
            memo[key] = c0
    bestv = c0
    bestch = None
    alts = []
    for ri, r in enumerate(rows):
        if len(r['cands']) > 1:
            b = r['cands'][0]
            for k in range(1, min(4, len(r['cands']))):
                alt = r['cands'][k]
                d = alt[0] - b[0]
                delta = alt[1] * alt[2] - b[1] * b[2]
                alts.append((ri, k, d, delta))
    for ri, k, d, delta in alts:
        if d >= bestv:
            continue
        cs = Sd.get(S0 + delta)
        if cs is None:
            continue
        v = d + cs
        if v < bestv - 1e-9:
            bestv = v
            bestch = [(ri, k)]
    if len(alts) <= 60:
        for x in range(len(alts)):
            ri1, k1, d1, de1 = alts[x]
            if d1 >= bestv:
                continue
            for y in range(x + 1, len(alts)):
                ri2, k2, d2, de2 = alts[y]
                if ri2 == ri1:
                    continue
                d = d1 + d2
                if d >= bestv:
                    continue
                cs = Sd.get(S0 + de1 + de2)
                if cs is None:
                    continue
                v = d + cs
                if v < bestv - 1e-9:
                    bestv = v
                    bestch = [(ri1, k1), (ri2, k2)]
    if bestch:
        for ri, k in bestch:
            c = rows[ri]['cands']
            chosen = c[k]
            rows[ri]['cands'] = [chosen] + [x for i, x in enumerate(c) if i != k]


def is_junk(s):
    t = s.replace('pcs', '')
    if re.search(r'[a-z]{3,}', t):
        return True
    if re.search(r"[^A-Za-z0-9.,'\s|;\u2019]", s):
        return True
    if re.search(r'(?i)\b(page|continued|copy|scan|fax|note|end)\b', s):
        return True
    return False


def solve(state, params):
    t0 = time.process_time()
    inp = state.get('input') or {}
    text = inp.get('text', '') or ''
    lines = text.replace('\r', '').split('\n')
    cols = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    sep = None
    for ln in lines:
        if 'COLUMNS' in ln:
            rest = ln.split('COLUMNS', 1)[1]
            ms = list(re.finditer(r'CODE|QTY|UNIT|AMOUNT', rest))
            if len(ms) == 4 and len(set(m.group(0) for m in ms)) == 4:
                cols = [m.group(0) for m in ms]
                sep = rest[ms[0].end():ms[1].start()]
            break
    if sep is None:
        for ln in lines:
            s = ln.strip()
            if not s or s.startswith('MANIFEST') or s.startswith('==') or 'TOTAL' in s:
                continue
            if '|' in s:
                sep = ' | '
            elif ';' in s:
                sep = ';'
            elif '\t' in ln:
                sep = '\t'
            else:
                sep = '   '
            break
    if sep is None:
        sep = ' | '
    if '|' in sep:
        kind = 'pipe'
    elif ';' in sep:
        kind = 'semi'
    elif '\t' in sep:
        kind = 'tab'
    else:
        kind = 'space'

    def split(s):
        if kind == 'pipe':
            parts = s.split('|')
        elif kind == 'semi':
            parts = s.split(';')
        elif kind == 'tab':
            parts = s.split('\t')
        else:
            parts = re.split(r'\t| {2,}', s)
        return [p.strip() for p in parts if p.strip()]

    sections = []
    cur = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if s.startswith('==') and 'SECTION' in s:
            cur = {'toks': [], 'sub': None}
            sections.append(cur)
            continue
        if s.startswith('SUBTOTAL'):
            if cur is not None:
                cur['sub'] = s[len('SUBTOTAL'):].strip()
            continue
        if s.startswith('TOTAL'):
            continue
        if is_junk(s):
            continue
        if cur is None:
            cur = {'toks': [], 'sub': None}
            sections.append(cur)
        cur['toks'].extend(split(s))

    sec_rows = []
    for sec in sections:
        toks = sec['toks']
        rows = [toks[k:k + 4] for k in range(0, len(toks), 4)]
        sec_rows.append(rows)

    cnt = Counter()
    for rows in sec_rows:
        for r in rows:
            for k, name in enumerate(cols):
                if name in ('UNIT', 'AMOUNT') and k < len(r):
                    m = re.search(r'([.,])[^.,]{2}$', r[k])
                    if m:
                        cnt[m.group(1)] += 1
    dec = ',' if cnt[','] > cnt['.'] else '.'

    T1 = make_tabs(make_costs(BASE))
    memo1 = {}
    recs = []
    for rows in sec_rows:
        rl = []
        for r in rows:
            rl.append(decode_row(r, cols, dec, T1, memo1))
        recs.append(rl)

    T = T1
    memo = memo1
    if time.process_time() - t0 < 0.45:
        opc = Counter()
        N = 0
        for rl in recs:
            for rec in rl:
                N += rec['nch']
                for op in rec['ops']:
                    if op in BASE:
                        opc[op] += 1
        alpha = 60.0
        raw = {}
        for op, b in BASE.items():
            r0 = math.exp(-b)
            rate = (opc[op] + alpha * r0) / (N + alpha)
            raw[op] = -math.log(max(rate, 1e-9))
        T2 = make_tabs(make_costs(raw))
        memo2 = {}
        complete = True
        for si, rl in enumerate(recs):
            for ri, rec in enumerate(rl):
                if rec['fast']:
                    continue
                if time.process_time() - t0 > 0.8:
                    complete = False
                    break
                rl[ri] = decode_row(rec['toks'], cols, dec, T2, memo2)
            if not complete:
                break
        if complete:
            T = T2
            memo = memo2

    for si, sec in enumerate(sections):
        if time.process_time() - t0 > 0.9:
            break
        reconcile(recs[si], sec['sub'], dec, T, memo)

    items = []
    for rl in recs:
        for rec in rl:
            b = rec['cands'][0]
            items.append({'code': rec['code'], 'qty': int(b[1]), 'unit_cents': int(b[2])})
    state['output'] = {'items': items}
    return state

